RADBRIDGE_ENV = os.getenv('RADBRIDGE_ENV', 'development').strip().lower()


def _validate_production_secrets():
    if RADBRIDGE_ENV != 'production':
        return
    weak = []
    if not app.secret_key or app.secret_key == 'change-me-now':
        weak.append('SECRET_KEY')
    if not ORTHANC_PASSWORD or ORTHANC_PASSWORD == 'ChangeMe_PACS_2026':
        weak.append('ORTHANC_PASSWORD')
    if weak:
        raise RuntimeError(
            'Unsafe production configuration: set strong values for ' + ', '.join(weak)
        )


_validate_production_secrets()

