QA_N8N_BASE_URL=os.getenv('QA_N8N_BASE_URL','').rstrip('/')
QA_N8N_RUN_WEBHOOK=os.getenv('QA_N8N_RUN_WEBHOOK','').strip()
QA_N8N_RETRY_WEBHOOK=os.getenv('QA_N8N_RETRY_WEBHOOK','').strip()
QA_N8N_ENABLE_WEBHOOK=os.getenv('QA_N8N_ENABLE_WEBHOOK','').strip()
QA_N8N_DISABLE_WEBHOOK=os.getenv('QA_N8N_DISABLE_WEBHOOK','').strip()
QA_N8N_STATUS_WEBHOOK=os.getenv('QA_N8N_STATUS_WEBHOOK','').strip()
QA_CALLBACK_TOKEN=os.getenv('QA_CALLBACK_TOKEN','').strip()


def qa_n8n_call(url,payload=None,timeout=15):
    if not url:
        return None,'N8N_WEBHOOK_NOT_CONFIGURED'

    try:
        r=requests.post(
            url,
            json=payload or {},
            timeout=timeout
        )

        if r.status_code >= 400:
            return None,'N8N_HTTP_%s:%s' % (
                r.status_code,
                (r.text or '')[:500]
            )

        try:
            return r.json(),None
        except Exception:
            return {'raw':(r.text or '')[:2000]},None

    except Exception as exc:
        return None,str(exc)


def qa_run_summary(row):
    return {
        'id':row.id,
        'run_type':row.run_type,
        'status':row.status,
        'release_name':row.release_name,
        'environment':row.environment,
        'total_tests':int(row.total_tests or 0),
        'passed_tests':int(row.passed_tests or 0),
        'failed_tests':int(row.failed_tests or 0),
        'critical_tests':int(row.critical_tests or 0),
        'warning_tests':int(row.warning_tests or 0),
        'external_execution_id':row.external_execution_id or '',
        'started_at':row.started_at.isoformat() if row.started_at else None,
        'finished_at':row.finished_at.isoformat() if row.finished_at else None,
    }


