def lang():
    try:
        return current_ui_language()
    except Exception:
        v=session.get('ui_lang') or session.get('lang') or 'en'
        return v if v in ('en','ar') else 'en'
def tr(key):
    return I18N.get(lang(), I18N['en']).get(key,key)



def _active_portal_token(order):
    now=datetime.utcnow()
    row=PortalAccessToken.query.filter_by(order_id=order.id,revoked=False).filter(
        PortalAccessToken.expires_at>now
    ).order_by(PortalAccessToken.id.desc()).first()
    if row:
        return row.token
    token=secrets.token_urlsafe(32)
    db.session.add(PortalAccessToken(
        order_id=order.id,
        token=token,
        expires_at=now+timedelta(days=PATIENT_PORTAL_TOKEN_DAYS),
        revoked=False
    ))
    db.session.flush()
    return token

def _notification_exists(order_id,channel,recipient):
    return NotificationEvent.query.filter_by(
        order_id=order_id,channel=channel,recipient=recipient
    ).first()

def queue_final_delivery(order):
    """Create FINAL-only portal and notification jobs. Safe and idempotent."""
    report=getattr(order,'report',None)
    if not order or (order.status or '').upper()!='FINAL':
        return 0
    if not report or (report.status or '').upper()!='FINAL':
        return 0

    token=_active_portal_token(order)
    portal_url=RIS_PUBLIC_URL + url_for('patient_portal',token=token)
    patient=order.patient
    created=0

    patient_message=(
        f"تم اعتماد التقرير النهائي للفحص {order.accession}. "
        f"يمكنك فتح التقرير من الرابط الآمن التالي: {portal_url}"
    )
    staff_message=(
        f"FINAL report ready | {order.accession} | "
        f"{patient.name if patient else ''}"
    )

    if WHATSAPP_ENABLED and patient and patient.phone:
        if not _notification_exists(order.id,'WHATSAPP',patient.phone):
            db.session.add(NotificationEvent(
                order_id=order.id,channel='WHATSAPP',recipient=patient.phone,
                status='PENDING',attempts=0,last_error=''
            )); created+=1

    if SMTP_ENABLED and patient and getattr(patient,'email',''):
        if not _notification_exists(order.id,'EMAIL',patient.email):
            db.session.add(NotificationEvent(
                order_id=order.id,channel='EMAIL',recipient=patient.email,
                status='PENDING',attempts=0,last_error=''
            )); created+=1

    if TELEGRAM_ENABLED and TELEGRAM_STAFF_CHAT_ID:
        if not _notification_exists(order.id,'TELEGRAM',TELEGRAM_STAFF_CHAT_ID):
            db.session.add(NotificationEvent(
                order_id=order.id,channel='TELEGRAM',recipient=TELEGRAM_STAFF_CHAT_ID,
                status='PENDING',attempts=0,last_error=''
            )); created+=1

    # Store messages in audit, not medical report content in chat.
    audit('FINAL_DELIVERY_QUEUED','order',order.id,
          f'portal={portal_url} jobs={created}')
    db.session.flush()
    return created

def _final_portal_url(order):
    token=_active_portal_token(order)
    return RIS_PUBLIC_URL + url_for('patient_portal',token=token)

def send_notification_job(job):
    """Provider adapter. Failure never changes report FINAL state."""
    order=job.order
    patient=order.patient if order else None
    portal_url=_final_portal_url(order) if order else RIS_PUBLIC_URL
    job.attempts=int(job.attempts or 0)+1
    try:
        if job.channel=='EMAIL':
            if not SMTP_ENABLED:
                raise RuntimeError('SMTP disabled')
            body=(
                f"Your radiology report is ready.\n"
                f"Accession: {order.accession}\n"
                f"Secure report link: {portal_url}\n"
            )
            msg=EmailMessage()
            msg['Subject']='Radiology report ready'
            msg['From']=SMTP_FROM
            msg['To']=job.recipient
            msg.set_content(body)
            with smtplib.SMTP(SMTP_HOST,SMTP_PORT,timeout=20) as smtp:
                if SMTP_TLS: smtp.starttls()
                if SMTP_USER: smtp.login(SMTP_USER,SMTP_PASSWORD)
                smtp.send_message(msg)

        elif job.channel=='TELEGRAM':
            if not TELEGRAM_ENABLED:
                raise RuntimeError('Telegram disabled')
            text=f"FINAL report ready | {order.accession} | {patient.name if patient else ''}"
            r=requests.post(
                f'https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage',
                json={'chat_id':job.recipient,'text':text},
                timeout=15
            )
            r.raise_for_status()

        elif job.channel=='WHATSAPP':
            if not WHATSAPP_ENABLED:
                raise RuntimeError('WhatsApp disabled')
            text=(
                f"تم اعتماد التقرير النهائي للفحص {order.accession}. "
                f"رابط التقرير الآمن: {portal_url}"
            )
            headers={}
            if WHATSAPP_API_KEY:
                headers['apikey']=WHATSAPP_API_KEY
            payload={
                'number':job.recipient,
                'text':text,
                'instance':WHATSAPP_INSTANCE,
                'order_id':order.id
            }
            r=requests.post(WHATSAPP_API_URL,json=payload,headers=headers,timeout=20)
            r.raise_for_status()
        else:
            raise RuntimeError('Unsupported notification channel')

        job.status='SENT'
        job.sent_at=datetime.utcnow()
        job.last_error=''
        audit('NOTIFICATION_SENT','order',order.id,f'{job.channel} {job.recipient}')
        return True
    except Exception as exc:
        job.status='FAILED'
        job.last_error=str(exc)[:1000]
        audit('NOTIFICATION_FAILED','order',order.id,f'{job.channel}: {job.last_error}')
        return False

def process_notification_queue(limit=25):
    jobs=NotificationEvent.query.filter(
        NotificationEvent.status.in_(['PENDING','FAILED']),
        NotificationEvent.attempts<5
    ).order_by(NotificationEvent.id.asc()).limit(limit).all()
    for job in jobs:
        send_notification_job(job)
    db.session.commit()
    return len(jobs)


# Examination workflow is separate from report workflow.
# VERIFIED / SECOND_VERIFIED / FINAL belong to REPORT_WORKFLOW_STATUSES
# and must never be set by the technician exam-status endpoint.
EXAM_STATUS_ORDER=['BOOKED','ORDERED','IN_PROGRESS','EXAM_COMPLETED','REPORTING']

def exam_status_rank(value):
    value=(value or 'ORDERED').upper()
    try:
        return EXAM_STATUS_ORDER.index(value)
    except ValueError:
        return 1

def exam_transition_allowed(current,target):
    current=(current or 'ORDERED').upper()
    target=(target or '').upper()
    return target in EXAM_STATUS_ORDER and exam_status_rank(target)==exam_status_rank(current)+1

def _orthanc_auth():
    return (PACS_ORTHANC_USER,PACS_ORTHANC_PASSWORD) if PACS_ORTHANC_USER else None

def pacs_lookup_order(order):
    accession=str(order.accession or '').strip()
    if not accession:
        return {'count':0,'status':'WAITING','study_id':''}
    try:
        r=requests.post(
            PACS_ORTHANC_URL+'/tools/find',
            auth=_orthanc_auth(),
            json={'Level':'Study','Query':{'AccessionNumber':accession},'Expand':True,'Limit':20},
            timeout=10
        )
        r.raise_for_status()
        studies=r.json() or []
    except Exception:
        order.pacs_status='PACS_OFFLINE'
        return {'count':int(order.pacs_image_count or 0),'status':'PACS_OFFLINE','study_id':order.pacs_study_id or ''}

    if not studies:
        order.pacs_image_count=0
        order.pacs_status='WAITING'
        order.pacs_last_seen_at=datetime.utcnow()
        return {'count':0,'status':'WAITING','study_id':''}

    count=0
    study_id=''
    for st in studies:
        study_id=study_id or st.get('ID','')
        stats=st.get('Statistics') or {}
        c=stats.get('CountInstances')
        if c is None:
            instances=st.get('Instances')
            if instances is not None:
                c=len(instances or [])
            else:
                c=0
                for series_id in (st.get('Series') or []):
                    try:
                        sr=requests.get(
                            PACS_ORTHANC_URL+'/series/'+str(series_id),
                            auth=_orthanc_auth(),
                            timeout=8,
                        )
                        sr.raise_for_status()
                        series_data=sr.json() or {}
                        c += len(series_data.get('Instances') or [])
                    except Exception:
                        continue
        count += int(c or 0)

    now=datetime.utcnow()
    previous=int(order.pacs_image_count or 0)
    if count != previous:
        order.pacs_last_change_at=now

    order.pacs_image_count=count
    order.pacs_last_seen_at=now
    order.pacs_study_id=study_id or order.pacs_study_id or ''

    if count<=0:
        status='WAITING'
    elif (order.exam_status or '').upper()!='EXAM_COMPLETED':
        status='RECEIVING'
    elif order.pacs_last_change_at and (now-order.pacs_last_change_at).total_seconds()>=PACS_IMAGES_STABLE_SECONDS:
        status='IMAGES_COMPLETE'
    else:
        status='RECEIVING'

    order.pacs_status=status
    return {'count':count,'status':status,'study_id':study_id}


FINANCIAL_REPORTS={
 'summary':'Executive Financial Summary',
 'profit_loss':'Profit & Loss',
 'balance_sheet':'Management Balance Sheet',
 'cash_flow':'Cash Flow',
 'revenue_procedure':'Revenue by Procedure / Modality',
 'revenue_payer':'Revenue by Payer / Contract',
 'aging':'Receivables Aging',
 'exam_costing':'Exam Costing / COGS',
 'maintenance':'Medical Equipment Maintenance',
 'payroll_doctor':'Payroll & Doctor Fees',
 'inventory':'Inventory & Consumable Movement',
 'device_profitability':'Device / Modality Profitability',
 'branch_profitability':'Branch Profitability',
 'collections':'Collections by Payment Method'
}
FINANCE_ENTRY_TYPES=['EXPENSE','MAINTENANCE','PAYROLL','DOCTOR_FEE','ASSET','LIABILITY','EQUITY','INVENTORY_PURCHASE']

def _money(v):
    try:return round(float(v or 0),2)
    except:return 0.0

def _finance_filters():
    today=date.today(); start=today.replace(day=1); end=today
    try:
        if request.args.get('start'): start=date.fromisoformat(request.args.get('start'))
    except: pass
    try:
        if request.args.get('end'): end=date.fromisoformat(request.args.get('end'))
    except: pass
    if end<start:start,end=end,start
    return {'start':start,'end':end,'branch_id':request.args.get('branch_id',type=int),
            'contract_id':request.args.get('contract_id',type=int),
            'device_id':request.args.get('device_id',type=int),
            'modality':(request.args.get('modality') or '').upper().strip()}

def _orders_for_finance(f):
    q=Order.query.filter(Order.scheduled>=datetime.combine(f['start'],datetime.min.time()),
                         Order.scheduled<datetime.combine(f['end']+timedelta(days=1),datetime.min.time()))
    if f['branch_id']:q=q.filter(Order.branch_id==f['branch_id'])
    if f['contract_id']:q=q.filter(Order.contract_id==f['contract_id'])
    if f['device_id']:q=q.filter(Order.device_id==f['device_id'])
    if f['modality']:q=q.filter(Order.modality==f['modality'])
    return q.order_by(Order.scheduled.asc()).all()

def _entries_for_finance(f,types=None):
    q=FinancialEntry.query.filter(FinancialEntry.entry_date>=f['start'],FinancialEntry.entry_date<=f['end'],FinancialEntry.status!='VOID')
    if f['branch_id']:q=q.filter(FinancialEntry.branch_id==f['branch_id'])
    if f['device_id']:q=q.filter(FinancialEntry.device_id==f['device_id'])
    if types:q=q.filter(FinancialEntry.entry_type.in_(types))
    return q.order_by(FinancialEntry.entry_date.asc()).all()

def _order_direct_consumable_cost(o):
    nr=NursingConsumableEntry.query.filter_by(order_id=o.id,confirmed=True).all()
    if nr:return sum(_money(n.actual_qty)*_money(n.consumable.unit_cost if n.consumable else 0) for n in nr)
    return sum(_money(x.qty)*_money(x.consumable.unit_cost if x.consumable else 0) for x in OrderConsumable.query.filter_by(order_id=o.id).all())

def _order_revenue(o): return _money(o.contract_price or o.gross_price or 0)

def _financial_dataset(key,f):
    orders=_orders_for_finance(f); entries=_entries_for_finance(f)
    revenue=sum(_order_revenue(o) for o in orders)
    collected=sum(_money(o.paid_amount) for o in orders)
    receivables=sum(max(order_balance(o),0) for o in orders)
    cogs=sum(_order_direct_consumable_cost(o) for o in orders)
    doctor=sum(_money(e.amount) for e in entries if e.entry_type=='DOCTOR_FEE')
    opex=sum(_money(e.amount) for e in entries if e.entry_type in ('EXPENSE','MAINTENANCE','PAYROLL'))
    gross_profit=revenue-cogs-doctor; net_profit=gross_profit-opex
    kpis={'Revenue':revenue,'Collections':collected,'Receivables':receivables,'Consumable COGS':cogs,
          'Doctor Fees':doctor,'Operating Expenses':opex,'Gross Profit':gross_profit,'Net Profit':net_profit,'Cases':len(orders)}
    headers=[];rows=[]

    if key=='summary':
        headers=['Metric','Value'];rows=[[k,v] for k,v in kpis.items()]
    elif key=='profit_loss':
        headers=['Line','Amount'];rows=[['Revenue',revenue],['Less: Consumable COGS',-cogs],['Less: Doctor Fees',-doctor],
        ['Gross Profit',gross_profit],['Less: Operating Expenses',-opex],['Net Profit',net_profit]]
    elif key=='balance_sheet':
        inv=sum(_money(c.stock_qty)*_money(c.unit_cost) for c in Consumable.query.filter_by(active=True).all())
        assets=sum(_money(e.amount) for e in entries if e.entry_type=='ASSET')
        liab=sum(_money(e.amount) for e in entries if e.entry_type=='LIABILITY')
        equity=sum(_money(e.amount) for e in entries if e.entry_type=='EQUITY')
        total=receivables+inv+assets
        headers=['Section','Line','Amount'];rows=[
        ['Assets','Accounts Receivable',receivables],['Assets','Inventory at Cost',inv],['Assets','Registered Assets',assets],
        ['Assets','Total Assets',total],['Liabilities','Registered Liabilities',liab],['Equity','Registered Equity',equity],
        ['Equity','Calculated Net Position',total-liab]]
    elif key=='cash_flow':
        ids=[o.id for o in orders]; recs=Receipt.query.filter(Receipt.order_id.in_(ids)).all() if ids else []
        inflow=sum(_money(r.amount) for r in recs)
        outflow=sum(_money(e.amount) for e in entries if e.entry_type in ('EXPENSE','MAINTENANCE','PAYROLL','DOCTOR_FEE','INVENTORY_PURCHASE'))
        headers=['Cash Flow','Amount'];rows=[['Operating Inflows / Receipts',inflow],['Operating Outflows',-outflow],['Net Cash Flow',inflow-outflow]]
    elif key=='revenue_procedure':
        a={}
        for o in orders:
            k=(o.modality or '',o.proc.name if o.proc else o.procedure);v=a.setdefault(k,[0,0,0,0]);v[0]+=1;v[1]+=_order_revenue(o);v[2]+=_money(o.paid_amount);v[3]+=max(order_balance(o),0)
        headers=['Modality','Procedure','Cases','Revenue','Collected','Outstanding','Revenue/Case']
        rows=[[k[0],k[1],v[0],v[1],v[2],v[3],v[1]/v[0] if v[0] else 0] for k,v in sorted(a.items())]
    elif key=='revenue_payer':
        a={}
        for o in orders:
            k=o.contract.name if o.contract else 'Cash / Private';v=a.setdefault(k,[0,0,0,0,0,0]);v[0]+=1;v[1]+=_order_revenue(o);v[2]+=_money(o.patient_share);v[3]+=_money(o.company_share);v[4]+=_money(o.paid_amount);v[5]+=max(order_balance(o),0)
        headers=['Payer','Cases','Revenue','Patient Share','Company Share','Collected','Outstanding']
        rows=[[k]+v for k,v in sorted(a.items())]
    elif key=='aging':
        today=date.today();buckets={'0-30':0,'31-60':0,'61-90':0,'90+':0}
        headers=['Accession','Patient','Payer','Date','Days','0-30','31-60','61-90','90+','Balance']
        for o in orders:
            bal=max(order_balance(o),0)
            if bal<=0:continue
            days=max((today-o.scheduled.date()).days,0);bn='0-30' if days<=30 else '31-60' if days<=60 else '61-90' if days<=90 else '90+'
            buckets[bn]+=bal;x={k:0 for k in buckets};x[bn]=bal
            rows.append([o.accession,o.patient.name,o.contract.name if o.contract else 'Cash / Private',o.scheduled.date().isoformat(),days,x['0-30'],x['31-60'],x['61-90'],x['90+'],bal])
        kpis.update({f'Aging {k}':v for k,v in buckets.items()})
    elif key=='exam_costing':
        fees={}
        for e in entries:
            if e.entry_type=='DOCTOR_FEE' and e.reference_no:fees[e.reference_no]=fees.get(e.reference_no,0)+_money(e.amount)
        headers=['Accession','Patient','Procedure','Revenue','Consumables','Doctor Fee','Direct Cost','Gross Profit','Margin %']
        for o in orders:
            rev=_order_revenue(o);cons=_order_direct_consumable_cost(o);fee=fees.get(o.accession,0);cost=cons+fee;gp=rev-cost
            rows.append([o.accession,o.patient.name,o.proc.name if o.proc else o.procedure,rev,cons,fee,cost,gp,gp/rev*100 if rev else 0])
    elif key=='maintenance':
        headers=['Date','Branch','Device','Category','Description','Amount','Reference']
        rows=[[e.entry_date.isoformat(),e.branch.name if e.branch else '',e.device.name if e.device else '',e.category,e.description,_money(e.amount),e.reference_no] for e in entries if e.entry_type=='MAINTENANCE']
    elif key=='payroll_doctor':
        headers=['Date','Type','Employee / Doctor','Branch','Description','Amount','Status']
        rows=[[e.entry_date.isoformat(),e.entry_type,e.user.full_name if e.user else '',e.branch.name if e.branch else '',e.description,_money(e.amount),e.status] for e in entries if e.entry_type in ('PAYROLL','DOCTOR_FEE')]
    elif key=='inventory':
        usage={}
        for o in orders:
            for n in NursingConsumableEntry.query.filter_by(order_id=o.id,confirmed=True).all():
                if n.consumable:
                    v=usage.setdefault(n.consumable_id,[0,0]);v[0]+=float(n.actual_qty or 0);v[1]+=_money(n.actual_qty)*_money(n.consumable.unit_cost)
        headers=['Code','Consumable','Unit','Current Stock','Reorder Level','Used Qty','Usage Cost','Stock Value','Status']
        rows=[[c.code,c.name,c.unit,_money(c.stock_qty),_money(c.reorder_level),_money(usage.get(c.id,[0,0])[0]),_money(usage.get(c.id,[0,0])[1]),_money(c.stock_qty)*_money(c.unit_cost),'LOW' if _money(c.stock_qty)<=_money(c.reorder_level) else 'OK'] for c in Consumable.query.order_by(Consumable.name).all()]
    elif key in ('device_profitability','branch_profitability'):
        a={}
        for o in orders:
            name=(o.device.name if o.device else 'Unassigned') if key=='device_profitability' else (o.branch.name if o.branch else 'Unassigned')
            v=a.setdefault(name,[0,0,0,0]);v[0]+=1;v[1]+=_order_revenue(o);v[2]+=_order_direct_consumable_cost(o)
        for e in entries:
            name=(e.device.name if e.device else None) if key=='device_profitability' else (e.branch.name if e.branch else None)
            if name in a and e.entry_type in ('EXPENSE','MAINTENANCE','PAYROLL','DOCTOR_FEE'):a[name][3]+=_money(e.amount)
        headers=['Unit','Cases','Revenue','Consumable Cost','Allocated Expense','Contribution','Revenue/Case']
        rows=[[name,v[0],v[1],v[2],v[3],v[1]-v[2]-v[3],v[1]/v[0] if v[0] else 0] for name,v in sorted(a.items())]
    elif key=='collections':
        ids=[o.id for o in orders];recs=Receipt.query.filter(Receipt.order_id.in_(ids)).all() if ids else [];a={}
        for r in recs:
            m=(r.payment_method or 'OTHER').upper();v=a.setdefault(m,[0,0]);v[0]+=1;v[1]+=_money(r.amount)
        headers=['Payment Method','Transactions','Amount'];rows=[[m,v[0],v[1]] for m,v in sorted(a.items())]

    return {'title':FINANCIAL_REPORTS.get(key,key),'headers':headers,'rows':rows,'kpis':kpis,'filters':f}

def _export_csv(d,name):
    x=io.StringIO();w=csv.writer(x);w.writerow([d['title']]);w.writerow(['Period',d['filters']['start'],d['filters']['end']]);w.writerow([]);w.writerow(d['headers'])
    for row in d['rows']:w.writerow(row)
    return send_file(io.BytesIO(x.getvalue().encode('utf-8-sig')),as_attachment=True,download_name=name+'.csv',mimetype='text/csv; charset=utf-8')

def _export_xlsx(d,name):
    wb=Workbook();ws=wb.active;ws.title='Report';ws['A1']=d['title'];ws['A1'].font=Font(size=16,bold=True);ws['A2']=f"Period: {d['filters']['start']} to {d['filters']['end']}"
    for c,h in enumerate(d['headers'],1):
        x=ws.cell(4,c,h);x.font=Font(bold=True,color='FFFFFF');x.fill=PatternFill('solid',fgColor='1F4E78');x.alignment=Alignment(horizontal='center')
    for rr,row in enumerate(d['rows'],5):
        for cc,v in enumerate(row,1):ws.cell(rr,cc,v)
    for c in range(1,max(len(d['headers']),1)+1):
        vals=[len(str(ws.cell(r,c).value or '')) for r in range(1,ws.max_row+1)];ws.column_dimensions[get_column_letter(c)].width=min(max(max(vals or [10])+2,10),38)
    b=io.BytesIO();wb.save(b);b.seek(0)
    return send_file(b,as_attachment=True,download_name=name+'.xlsx',mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')

def _export_pdf(d,name):
    b=io.BytesIO();doc=SimpleDocTemplate(b,pagesize=A4,rightMargin=20,leftMargin=20,topMargin=25,bottomMargin=25);styles=getSampleStyleSheet()
    story=[Paragraph(d['title'],styles['Title']),Paragraph(f"Period: {d['filters']['start']} to {d['filters']['end']}",styles['Normal']),Spacer(1,10)]
    data=[d['headers']]+[[str(v if v is not None else '') for v in row] for row in d['rows']]
    if not d['headers']:data=[['No data']]
    t=Table(data,repeatRows=1);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#1F4E78')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),7),('GRID',(0,0),(-1,-1),.25,colors.HexColor('#D9E2F3')),('VALIGN',(0,0),(-1,-1),'TOP')]))
    story.append(t);doc.build(story);b.seek(0);return send_file(b,as_attachment=True,download_name=name+'.pdf',mimetype='application/pdf')


