def strict_pacs_demographic_match(tags):
    """
    Safe PACS demographic gate.

    Automatic linking requires:
      - exact Accession
      - exact Patient ID
      - exact DOB

    Any mismatch requires manual review.
    Patient name is informational and is never sufficient for auto-link.
    """
    accession = str(tags.get('accession') or '').strip()
    pacs_pid = str(tags.get('patient_id') or '').strip()
    pacs_dob = str(tags.get('dob') or '').strip()[:8]

    if not accession:
        return None, 'ACCESSION_MISSING', 'REVIEW_REQUIRED'

    order = Order.query.filter_by(accession=accession).first()

    if not order:
        return None, 'ACCESSION_NOT_FOUND', 'REVIEW_REQUIRED'

    patient = Patient.query.get(order.patient_id)

    if not patient:
        return order, 'RIS_PATIENT_NOT_FOUND', 'REVIEW_REQUIRED'

    ris_pid = str(patient.patient_id or '').strip()
    ris_dob = str(patient.dob or '').strip()[:8]

    mismatches = []

    if not pacs_pid or pacs_pid != ris_pid:
        mismatches.append('PATIENT_ID')

    if not pacs_dob or pacs_dob != ris_dob:
        mismatches.append('DOB')

    if mismatches:
        if len(mismatches) > 1:
            reason = 'MULTIPLE_MISMATCH:' + ','.join(mismatches)
        else:
            reason = mismatches[0] + '_MISMATCH'

        return order, reason, 'REVIEW_REQUIRED'

    return order, 'DEMOGRAPHICS_EXACT', 'AUTO_SAFE'



def pacs_demographic_gate(order):
    """
    Central safety gate for PACS/AI/reporting.

    Allowed:
      1. PACS study has an AUTO_SAFE strict demographic match.
      2. PACS study was manually reconciled by an authorized user.

    Blocked:
      - REVIEW_REQUIRED
      - missing/unreconciled PACS study
      - demographic mismatch without authorized reconciliation
    """

    if not order:
        return False, 'ORDER_NOT_FOUND'

    # A study waiting for demographic review always blocks downstream actions.
    review = PacsStudyInbox.query.filter(
        PacsStudyInbox.state == 'REVIEW_REQUIRED',
        PacsStudyInbox.accession == order.accession
    ).order_by(PacsStudyInbox.id.desc()).first()

    if review:
        return False, 'PACS_DEMOGRAPHIC_REVIEW_REQUIRED'

    match = PacsStudyMatch.query.filter_by(
        order_id=order.id
    ).order_by(PacsStudyMatch.id.desc()).first()

    if not match:
        return False, 'PACS_DEMOGRAPHIC_MATCH_NOT_VERIFIED'

    confidence = str(match.confidence or '').upper()
    method = str(match.match_method or '').upper()

    if confidence == 'AUTO_SAFE' and method == 'DEMOGRAPHICS_EXACT':
        return True, 'AUTO_SAFE'

    if method in ('MANUAL_CONFIRMED','OVERRIDE_APPROVED') and confidence in ('CONFIRMED','OVERRIDE_APPROVED'):
        return True, method

    return False, 'PACS_DEMOGRAPHIC_MATCH_NOT_VERIFIED'


def suggest_order_for_study(tags):
    if tags['accession']:
        o=Order.query.filter_by(accession=tags['accession']).first()
        if o:return o,'ACCESSION_EXACT','HIGH'
    if tags['patient_id']:
        patient=Patient.query.filter_by(patient_id=tags['patient_id']).first()
        if patient:
            q=Order.query.filter_by(patient_id=patient.id)
            modality=tags['modality'].split('\\')[0].strip().upper()
            if modality:q=q.filter(Order.modality==modality)
            cand=q.order_by(Order.scheduled.desc()).limit(10).all()
            if len(cand)==1:return cand[0],'PATIENT_ID_UNIQUE','HIGH'
            if cand:return cand[0],'PATIENT_ID_SUGGESTED','MEDIUM'
    return None,'UNMATCHED','LOW'



def _orthanc_study_detail(study_id):
    try:
        r=requests.get(f'{PACS_ORTHANC_URL}/studies/{study_id}',auth=_orthanc_auth(),timeout=15)
        r.raise_for_status()
        return r.json() or {}
    except Exception:
        return {}

def _study_tags_extended(st):
    tags=_study_tags(st)
    mt=st.get('MainDicomTags') or {}
    detail=_orthanc_study_detail(tags['study_id']) if tags.get('study_id') else {}
    dmt=detail.get('MainDicomTags') or {}
    source_ae=''
    if detail:
        for series_id in detail.get('Series',[]):
            series=_orthanc_series_detail(series_id)
            instances=series.get('Instances') or []
            if instances:
                source_ae=_orthanc_instance_remote_aet(instances[0])
                if source_ae:
                    break
    tags.update({
      'study_instance_uid':str(mt.get('StudyInstanceUID') or dmt.get('StudyInstanceUID') or ''),
      'study_description':str(mt.get('StudyDescription') or dmt.get('StudyDescription') or ''),
      # RemoteAET is authoritative for routing. StationName and InstitutionName
      # describe the acquisition device/site and must not select an intake center.
      'source_ae':str(source_ae or mt.get('StationName') or mt.get('InstitutionName') or ''),
    })
    if detail:
        tags['instances']=sum(len((_orthanc_series_detail(x).get('Instances') or [])) for x in detail.get('Series',[]))
    return tags

