    prefix='RC'+today
    last=Receipt.query.filter(Receipt.receipt_no.like(prefix+'%')).order_by(Receipt.id.desc()).first()
    seq=1
    if last:
        try: seq=int(last.receipt_no[-5:])+1
        except: seq=last.id+1
    return f'{prefix}{seq:05d}'

