def _hhmm_minutes(value):
    try:
        h,m=[int(x) for x in value.split(':',1)]
        return h*60+m
    except Exception:
        return 0

def generate_slots(device, proc, day):
    schedule=DeviceSchedule.query.filter_by(device_id=device.id,weekday=day.weekday(),active=True).first()
    if not schedule:
        return []
    duration=max(5,int(proc.duration_min or 20))
    start=_hhmm_minutes(schedule.start_time)
    end=_hhmm_minutes(schedule.end_time)
    break_start=_hhmm_minutes(schedule.break_start) if schedule.break_start else None
    break_end=_hhmm_minutes(schedule.break_end) if schedule.break_end else None
    slots=[]
    cursor=start
    while cursor+duration<=end:
        st=datetime.combine(day,datetime.min.time())+timedelta(minutes=cursor)
        en=st+timedelta(minutes=duration)
        if break_start is not None and break_end is not None and cursor < break_end and cursor+duration > break_start:
            cursor=max(cursor+duration,break_end)
            continue
        blocked=DeviceBlock.query.filter(
            DeviceBlock.device_id==device.id,
            DeviceBlock.start_at < en,
            DeviceBlock.end_at > st
        ).first() is not None
        booked=Appointment.query.filter(
            Appointment.device_id==device.id,
            Appointment.status.in_(['BOOKED','CONFIRMED','ARRIVED']),
            Appointment.scheduled >= st,
            Appointment.scheduled < en
        ).first() is not None
        slots.append({'start':st,'end':en,'label':f'{st:%H:%M} - {en:%H:%M}','available':not blocked and not booked})
        cursor += duration
    return slots


def _safe_token(value):
    value=str(value or '').strip()
