# ============================================================
# OHIF INTEGRATION
# Resolve StudyInstanceUID through DICOMweb using Accession.
# Order.pacs_study_id contains the Orthanc internal study ID,
# not the DICOM StudyInstanceUID.
# ============================================================

OHIF_INTERNAL_URL=os.getenv(
    'OHIF_INTERNAL_URL',
    'http://radbridge-ohif'
).rstrip('/')

OHIF_PUBLIC_URL=os.getenv(
    'OHIF_PUBLIC_URL',
    'http://51.89.248.57:8092'
).rstrip('/')


def ohif_study_uid(order):
    if not order:
        return None

    if order.pacs_study_id:
        try:
            r=requests.get(
                f'{OHIF_INTERNAL_URL}/orthanc-api/studies/{order.pacs_study_id}',
                timeout=5
            )

            r.raise_for_status()
            data=r.json() or {}

            tags=data.get('MainDicomTags') or {}

            uid=(
                tags.get('StudyInstanceUID')
                or data.get('StudyInstanceUID')
            )

            if uid:
                return str(uid).strip()

        except Exception:
            app.logger.exception(
                'Orthanc study lookup failed for order %s study %s',
                getattr(order,'id',None),
                getattr(order,'pacs_study_id','')
            )

    # Fallback to QIDO by Accession where AccessionNumber exists.
    if order.accession:
        try:
            r=requests.get(
                f'{OHIF_INTERNAL_URL}/dicom-web/studies',
                params={'AccessionNumber':order.accession},
                timeout=5
            )

            r.raise_for_status()
            studies=r.json() or []

            if studies:
                tag=studies[0].get('0020000D') or {}
                values=tag.get('Value') or []

                if values:
                    return str(values[0]).strip() or None

        except Exception:
            app.logger.exception(
                'DICOMweb UID lookup failed for order %s accession %s',
                getattr(order,'id',None),
                getattr(order,'accession','')
            )

    return None



# ============================================================
# RadBridge Doctor Identity Bridge
# ============================================================

OHIF_DOCTOR_IDENTITY_MAX_AGE = int(
    os.getenv("OHIF_DOCTOR_IDENTITY_MAX_AGE", "300")
)


def _ohif_identity_serializer():
    from itsdangerous import URLSafeTimedSerializer

    secret = (
        os.getenv("OHIF_DOCTOR_IDENTITY_SECRET", "").strip()
        or app.config.get("SECRET_KEY")
    )

    if not secret:
        raise RuntimeError("OHIF doctor identity secret is not configured")

    return URLSafeTimedSerializer(
        secret_key=secret,
        salt="radbridge-ohif-doctor-identity-v1"
    )


def create_ohif_doctor_identity(user, order):
    if not user or not user.active:
        raise ValueError("ACTIVE_USER_REQUIRED")

    role = (
        user.role.code
        if getattr(user, "role", None)
        else ""
    )

    payload = {
        "purpose": "OHIF_REPORTING",
        "user_id": int(user.id),
        "username": str(user.username or ""),
        "full_name": str(user.full_name or user.username or ""),
        "role": str(role or "").upper(),
        "order_id": int(order.id),
    }

    return _ohif_identity_serializer().dumps(payload)


def verify_ohif_doctor_identity(token, order_id=None):
    from itsdangerous import BadSignature, SignatureExpired

    token = str(token or "").strip()

    if not token:
        return None, "DOCTOR_IDENTITY_REQUIRED"

    try:
        payload = _ohif_identity_serializer().loads(
            token,
            max_age=OHIF_DOCTOR_IDENTITY_MAX_AGE
        )
    except SignatureExpired:
        return None, "DOCTOR_IDENTITY_EXPIRED"
    except BadSignature:
        return None, "DOCTOR_IDENTITY_INVALID"
    except Exception:
        app.logger.exception("Doctor identity verification failed")
        return None, "DOCTOR_IDENTITY_INVALID"

    if payload.get("purpose") != "OHIF_REPORTING":
        return None, "DOCTOR_IDENTITY_INVALID"

    try:
        user_id = int(payload.get("user_id"))
        token_order_id = int(payload.get("order_id"))
    except Exception:
        return None, "DOCTOR_IDENTITY_INVALID"

    if order_id is not None and token_order_id != int(order_id):
        return None, "DOCTOR_IDENTITY_ORDER_MISMATCH"

    user = User.query.get(user_id)

    if not user or not user.active:
        return None, "DOCTOR_IDENTITY_USER_INACTIVE"

    current_role = (
        user.role.code.upper()
        if user.role and user.role.code
        else ""
    )

    token_role = str(payload.get("role") or "").upper()

    if current_role != token_role:
        return None, "DOCTOR_IDENTITY_ROLE_CHANGED"

    linked_order=db.session.get(Order,token_order_id)
    if not doctor_case_access_allowed(user,linked_order):
        return None, "DOCTOR_ASSIGNMENT_REQUIRED"

    return {
        "user": user,
        "payload": payload,
        "role": current_role,
    }, None


def get_ohif_doctor_identity(order_id=None):
    token = (
        request.headers.get("X-RadBridge-Doctor-Identity")
        or request.args.get("radbridgeIdentity")
        or ""
    )

    return verify_ohif_doctor_identity(
        token,
        order_id=order_id
    )



def audit_as_user(user, action, entity='', entity_id='', details=''):
    """Write an audit event explicitly attributed to a verified user."""
    db.session.add(AuditLog(
        user_id=(user.id if user else None),
        username=(user.username if user else 'SYSTEM'),
        action=action,
        entity=entity,
        entity_id=str(entity_id or ''),
        details=str(details or '')[:4000],
        ip=request.headers.get(
            'X-Forwarded-For',
            request.remote_addr or ''
        )[:80]
    ))


def require_ohif_doctor_user(order_id):
    """Require a valid signed RadBridge doctor identity for OHIF writes."""
    identity, error = get_ohif_doctor_identity(order_id=order_id)

    if error or not identity or not identity.get('user'):
        return None, (
            jsonify({
                'ok': False,
                'error': error or 'DOCTOR_IDENTITY_REQUIRED',
                'message': (
                    'Your RadBridge doctor authorization is missing or expired. '
                    'Return to RadBridge RIS and open the case in OHIF again.'
                )
            }),
            403
        )

    return identity['user'], None


def ohif_audit_user(order_id):
    """Resolve the signed RadBridge OHIF identity for audit attribution."""
    identity, error = get_ohif_doctor_identity(order_id=order_id)
    if error or not identity:
        return None
    return identity.get('user')


def ohif_url_for_order(order):
    uid=ohif_study_uid(order)

    if not uid:
        return None

    from urllib.parse import quote

    url = (
        f'{OHIF_PUBLIC_URL}/radbridge'
        f'?StudyInstanceUIDs={quote(uid,safe="")}'
        f'&radbridgeOrderId={order.id}'
    )

    user = current_user()

    if user and user.active:
        role = (
            user.role.code.upper()
            if user.role and user.role.code
            else ''
        )

        if role in (
            'RADIOLOGIST',
            'CONSULTANT',
            'RADIOLOGY_CONSULTANT',
            'SUPER_ADMIN'
        ):
            secret = (
                os.getenv('OHIF_DOCTOR_IDENTITY_SECRET', '').strip()
                or app.config.get('SECRET_KEY')
            )

            if secret:
                token = create_ohif_doctor_identity(
                    user,
                    order
                )

                url += '&radbridgeIdentity=' + quote(token, safe='')

    return url


def case_pacs_url(order):
    """
    Browser-facing image viewer URL.

    RadBridge no longer exposes the legacy
    /pacs/ohif/viewer route. Use the current
    public OHIF /radbridge workflow instead.

    For authenticated radiology users this also
    preserves the signed doctor identity generated
    by ohif_url_for_order().
    """
    return ohif_url_for_order(order)


