def allowed_report_transitions(report):
    s=(report.status or 'DRAFT').upper()
    if s == 'FINAL':
        # FINAL clinical lifecycle is immutable.
        # Addendum is disabled until the dedicated
        # amendment workflow is implemented.
        return []
    if s in ('READY_FORMATTING','FORMATTING'):
        return ['FORMATTING','READY_APPROVAL','DRAFT']
    if s=='READY_APPROVAL':
        return ['DRAFT','VERIFIED','SECOND_VERIFIED','FINAL']
    return ['DRAFT','PARTIAL','READY_FORMATTING','VERIFIED','SECOND_VERIFIED','FINAL']


def report_transition_allowed(report,target):
    return target in allowed_report_transitions(report)


def extract_report_text(path, ext):
    ext=(ext or '').lower()
    try:
        if ext=='.docx':
            with zipfile.ZipFile(path) as z:
                parts=[]
                for name in z.namelist():
                    if name in ('word/document.xml','word/header1.xml','word/header2.xml','word/header3.xml'):
                        xml=z.read(name).decode('utf-8','ignore')
                        parts.append(re.sub(r'<[^>]+>',' ',xml))
                return re.sub(r'\s+',' ',' '.join(parts)).strip()

        if ext=='.odt':
            with zipfile.ZipFile(path) as z:
                xml=z.read('content.xml').decode('utf-8','ignore')
                return re.sub(r'\s+',' ',re.sub(r'<[^>]+>',' ',xml)).strip()

        if ext=='.pdf':
            reader=PdfReader(path)
            text=' '.join((page.extract_text() or '') for page in reader.pages)
            return re.sub(r'\s+',' ',text).strip()

        # Legacy .doc is binary and cannot be reliably parsed here.
        return ''
    except Exception:
        return ''

def _normalize_compare(value):
    return re.sub(r'[^A-Za-z0-9]+','',str(value or '')).upper()

def detect_labeled_value(text, labels):
    if not text:
        return ''
    for label in labels:
        m=re.search(
            rf'{label}\s*[:#\-]?\s*([A-Za-z0-9._/\-]+)',
            text,
            flags=re.I
        )
        if m:
            return m.group(1).strip()
    return ''

def validate_report_patient_file(order, path, ext):
    text=extract_report_text(path,ext)
    expected_pid=str(order.patient.patient_id or '').strip()
    expected_acc=str(order.accession or '').strip()
    expected_name=str(order.patient.name or '').strip()
    expected_worklist=str(getattr(order.patient,'worklist_name','') or '').strip()

    found_pid=detect_labeled_value(text,[r'Patient\s*ID',r'Patient\s*No',r'MRN',r'PID'])
    found_acc=detect_labeled_value(text,[r'Accession(?:\s*No|\s*Number)?',r'Accession'])

    found_name=''
    if text:
        for pattern in [
            r'Patient\s*Name\s*[:#\-]?\s*([A-Za-z\u0600-\u06FF][A-Za-z\u0600-\u06FF ._-]{2,80}?)(?=\s+(?:Patient\s*ID|MRN|PID|Accession|DOB|Sex|Modality|Study)\b|$)',
            r'Name\s*[:#\-]?\s*([A-Za-z\u0600-\u06FF][A-Za-z\u0600-\u06FF ._-]{2,80}?)(?=\s+(?:Patient\s*ID|MRN|PID|Accession|DOB|Sex|Modality|Study)\b|$)'
        ]:
            mm=re.search(pattern,text,flags=re.I)
            if mm:
                found_name=mm.group(1).strip()
                break

    npid=_normalize_compare(expected_pid)
    nacc=_normalize_compare(expected_acc)
    ntext=_normalize_compare(text)
    pid_match=bool(npid and npid in ntext)
    acc_match=bool(nacc and nacc in ntext)

    explicit_pid_mismatch=bool(found_pid and _normalize_compare(found_pid)!=npid)
    explicit_acc_mismatch=bool(found_acc and _normalize_compare(found_acc)!=nacc)

    expected_names={
        normalized_person_name(expected_name),
        normalized_person_name(expected_worklist),
        normalized_person_name(arabic_to_latin_name(expected_name)),
    }
    expected_names={x for x in expected_names if x}
    found_name_norm=normalized_person_name(found_name)
    name_match=(not found_name_norm) or (found_name_norm in expected_names)
    explicit_name_mismatch=bool(found_name_norm and not name_match)

    common={
        'expected_patient_name':expected_name,
        'found_patient_name':found_name,
        'expected_patient_id':expected_pid,
        'found_patient_id':found_pid,
        'expected_accession':expected_acc,
        'found_accession':found_acc,
        'name_match':name_match,
    }

    if explicit_pid_mismatch or explicit_acc_mismatch:
        common.update(result='BLOCKED',reason='Patient ID or Accession does not match the open case.')
        return common

    if explicit_name_mismatch and pid_match and acc_match:
        common.update(result='WARNING',reason='Patient ID and Accession match, but Patient Name differs. Review spelling/transliteration.')
        return common

    if pid_match and acc_match and name_match:
        common.update(result='MATCH',reason='Patient Name, Patient ID and Accession are consistent with the open case.')
        return common

    common.update(result='WARNING',reason='Not enough readable identifiers to confirm Patient Name, Patient ID and Accession.')
    return common



def _csv_values(value):
    return {x.strip().upper() for x in str(value or '').split(',') if x.strip()}


def assignable_doctors():
    # User.role is a relationship, so filtering must use Role.code.
    return (
        User.query.join(Role, User.role_id==Role.id)
        .filter(
            User.active.is_(True),
            Role.code.in_(['RADIOLOGIST','DOCTOR'])
        )
        .order_by(User.full_name.asc(),User.username.asc())
        .all()
    )

def doctor_active_case_count(user_id):
    return Order.query.filter(
        Order.assigned_doctor_id==user_id,
        Order.status.notin_(['FINAL','CANCELLED'])
    ).count()

def eligible_doctors_for_order(order):
    profiles=DoctorAssignmentProfile.query.filter_by(auto_assign=True,available=True).all()
    eligible=[]
    for p in profiles:
        user=p.user
        if not user or not getattr(user,'active',True):
            continue
        modalities=_csv_values(p.modalities)
        branches=_csv_values(p.branches)
        specialties=_csv_values(p.specialties)

        if modalities and str(order.modality or '').upper() not in modalities:
            continue
        if branches and str(order.branch_id or '').upper() not in branches:
            continue

        active_count=doctor_active_case_count(user.id)
        if active_count >= int(p.max_active_cases or 20):
            continue

        eligible.append((p,user,active_count))
    return eligible

def auto_assign_order(order, assigned_by=None):
    eligible=eligible_doctors_for_order(order)
    if not eligible:
        return None

    # Lowest workload first, then higher priority weight.
    eligible.sort(key=lambda x:(x[2], -int(x[0].priority_weight or 100), x[1].id))
    profile,user,active_count=eligible[0]

    from case_assignment_service import assign_case_atomically

    result=assign_case_atomically(
        db=db,
        Order=Order,
        User=User,
        CaseAssignment=CaseAssignment,
        Report=Report,
        AssignmentOffer=AssignmentOffer,
        order_id=order.id,
        doctor_user_id=user.id,
        assigned_by=assigned_by,
        assignment_type='AUTO',
        notes='Legacy automatic assignment',
    )
    audit('CASE_AUTO_ASSIGN','order',order.id,f'doctor={user.username} workload={active_count}')
    return result.doctor

def manual_assign_order(
    order,
    doctor_user_id,
    assigned_by=None,
    notes='',
    assignment_type='MANUAL',
    require_unassigned=False,
):
    from case_assignment_service import assign_case_atomically

    result=assign_case_atomically(
        db=db,
        Order=Order,
        User=User,
        CaseAssignment=CaseAssignment,
        Report=Report,
        AssignmentOffer=AssignmentOffer,
        order_id=order.id,
        doctor_user_id=doctor_user_id,
        assigned_by=assigned_by,
        assignment_type=assignment_type,
        notes=notes,
        require_unassigned=require_unassigned,
    )
    audit(
        'CASE_MANUAL_ASSIGN',
        'order',
        order.id,
        (
            f'doctor={result.doctor.username}; '
            f'type={assignment_type}; '
            f'idempotent={int(result.idempotent)}'
        )
    )
    return result.doctor


ARABIC_NAME_MAP = {
    'ا':'A','أ':'A','إ':'E','آ':'A','ب':'B','ت':'T','ث':'TH','ج':'G','ح':'H','خ':'KH',
    'د':'D','ذ':'Z','ر':'R','ز':'Z','س':'S','ش':'SH','ص':'S','ض':'D','ط':'T','ظ':'Z',
    'ع':'A','غ':'GH','ف':'F','ق':'Q','ك':'K','ل':'L','م':'M','ن':'N','ه':'H','ة':'A',
    'و':'W','ؤ':'O','ي':'Y','ى':'A','ئ':'E','ء':'A'
}
def arabic_to_latin_name(value):
    value=str(value or '').strip()
    out=[]
    for ch in value:
        if ch in ARABIC_NAME_MAP:
            out.append(ARABIC_NAME_MAP[ch])
        elif ch.isascii():
            out.append(ch)
        elif ch.isspace():
            out.append(' ')
    return re.sub(r'\s+',' ',' '.join(''.join(out).split())).strip().upper()

def dicom_person_name(value):
    value=re.sub(r'\s+',' ',str(value or '').strip().upper())
    return '^'.join([x for x in value.split(' ') if x])

def normalized_person_name(value):
    return re.sub(r'[^A-Z0-9\u0600-\u06FF]+','',str(value or '').upper())

def current_user():
    uid = session.get('uid')
    return User.query.get(uid) if uid else None

def has_perm(perm):
    u = current_user()
    if not u or not u.active:
        return False

    if u.role and u.role.code == 'SUPER_ADMIN':
        return True

    perms = u.role.permissions() if u.role else []
    return '*' in perms or perm in perms

def login_required(fn):
    @wraps(fn)
    def w(*a, **kw):
        if not current_user(): return redirect(url_for('login', next=request.path))
        return fn(*a, **kw)
    return w

def require_perm(perm):
    def deco(fn):
        @wraps(fn)
        def w(*a, **kw):
            if not current_user(): return redirect(url_for('login', next=request.path))
            if not has_perm(perm): abort(403)
            return fn(*a, **kw)
        return w
    return deco

def audit(action, entity='', entity_id='', details=''):
    u=current_user()
    db.session.add(AuditLog(user_id=(u.id if u else None), username=(u.username if u else 'SYSTEM'),
        action=action, entity=entity, entity_id=str(entity_id or ''), details=details[:4000],
        ip=request.headers.get('X-Forwarded-For',request.remote_addr or '')[:80]))


def next_patient_id():
    prefix = "P"

    # Serialize every application path that allocates a P-number, including
    # manual registration, booking, PACS intake, and OCR intake.
    if db.engine.dialect.name=='postgresql':
        db.session.execute(text("SELECT pg_advisory_xact_lock(hashtext('PATIENT_ID_SEQUENCE'))"))

    rows = Patient.query.filter(
        Patient.patient_id.like(prefix + "%")
    ).all()

    max_no = 0

    for row in rows:
        pid = str(row.patient_id or "")

        if not pid.startswith(prefix):
            continue

        try:
            n = int(pid[len(prefix):])
            max_no = max(max_no, n)
        except Exception:
            continue

    return f"{prefix}{max_no + 1:08d}"


