# RadBridge v5.45.0 - Unified Registration V2 helpers
# ---------------------------------------------------------------------
def _rb_registration_v2_name_parts(form):
    return [
        (form.get('new_first_name') or '').strip(),
        (form.get('new_middle_name') or '').strip(),
        (form.get('new_third_name') or '').strip(),
        (form.get('new_fourth_name') or '').strip(),
    ]

def _rb_registration_v2_patient_name(form):
    return ' '.join(x for x in _rb_registration_v2_name_parts(form) if x).strip()

def _rb_registration_v2_worklist_name(form):
    return '^'.join(x for x in _rb_registration_v2_name_parts(form) if x).strip('^')

def _rb_registration_v2_dob(form):
    return resolve_patient_dob(form, prefix='new_').dob

def _rb_registration_v2_create_patient(form,audit_action='PATIENT_CREATE_FROM_CALENDAR'):
    parts=_rb_registration_v2_name_parts(form)
    if not parts[0]: raise ValueError('First name is required.')
    if not any(parts[1:]): raise ValueError('Enter at least one additional patient name.')
    name=_rb_registration_v2_patient_name(form)
    dob_resolution=resolve_patient_dob(form, prefix='new_')
    dob=dob_resolution.dob
    phone=(form.get('new_phone') or '').strip()
    national=(form.get('new_national_id') or '').strip()
    duplicates=find_duplicate_patients(name,dob,phone,national)
    if duplicates:
        d=duplicates[0]
        raise ValueError(f'Possible duplicate patient: {d.patient_id} — {d.name}. Use the existing patient or review the duplicate.')
    patient=Patient(
        patient_id='TMP'+secrets.token_hex(8),name=name,dob=dob,
        dob_estimated=dob_resolution.estimated,
        sex=(form.get('new_sex') or '').strip(),phone=phone,national_id=national,
        address=(form.get('new_address') or '').strip(),
        worklist_name=_rb_registration_v2_worklist_name(form))
    db.session.add(patient);db.session.flush()
    try: patient.patient_id=generate_patient_id(patient)
    except Exception: patient.patient_id=next_patient_id()
    audit(audit_action,'patient',patient.id,f'{patient.patient_id} {patient.name}')
    return patient

def _rb_calendar_redirect(scheduled=None,branch_id=None,device_id=None):
    kw={}
    if scheduled is not None: kw['date']=scheduled.date().isoformat()
    if branch_id: kw['branch_id']=branch_id
    if device_id: kw['device_id']=device_id
    return redirect(url_for('schedule_calendar',**kw))

def new_accession():
    # DICOM AccessionNumber is VR SH and must not exceed 16 characters.
    # RB + YYMMDDHH + 6 random hex chars = exactly 16 characters.
    return 'RB' + datetime.now().strftime('%y%m%d%H') + secrets.token_hex(3).upper()

def generate_patient_id(patient):
    return f'P{patient.id:08d}'

def orthanc_ok():
    try: return requests.get(f'{ORTHANC}/system',auth=AUTH,timeout=3).ok
    except Exception: return False

def route_device(branch_id, modality):
    rows=Device.query.filter_by(branch_id=branch_id,modality=modality,active=True).order_by(Device.priority.asc(),Device.id.asc()).all()
    for d in rows:
        if getattr(d,'booking_enabled',True) and (getattr(d,'operational_status','ACTIVE') or 'ACTIVE').upper()=='ACTIVE':
            return d
    return None

def price_order(proc, contract):
    gross=float(proc.base_price or 0)
    if not contract:
        return gross,gross,gross,0.0,0.0
    cp=ContractPrice.query.filter_by(contract_id=contract.id,procedure_id=proc.id).first()
    effective=float(cp.price if cp else gross*(1-(contract.discount_percent or 0)/100.0))
    share_pct=float(cp.patient_share_percent if cp and cp.patient_share_percent is not None else contract.patient_share_percent or 0)
    patient=round(effective*share_pct/100.0,2)
    company=round(effective-patient,2)
    return gross,effective,patient,company,share_pct

def send_mwl(order):
    p=order.patient
    patient_name=(p.worklist_name or p.name or '').replace(' ','^')
    tags={
        'SpecificCharacterSet':'ISO_IR 192',
        'PatientName':patient_name,
        'PatientID':p.patient_id or '',
        'PatientBirthDate':p.dob or '',
        'PatientSex':p.sex or '',
        'AccessionNumber':order.accession or '',
        'RequestedProcedureDescription':order.procedure or '',
        'RequestedProcedureID':order.accession or '',
        'ScheduledProcedureStepSequence':[{
            'ScheduledStationAETitle':order.station_ae or '',
            'Modality':order.modality or '',
            'ScheduledProcedureStepStartDate':order.scheduled.strftime('%Y%m%d'),
            'ScheduledProcedureStepStartTime':order.scheduled.strftime('%H%M%S'),
            'ScheduledProcedureStepDescription':order.procedure or '',
            'ScheduledProcedureStepID':order.accession or ''
        }]
    }
    r=requests.post(f'{ORTHANC}/worklists/create',json={'Tags':tags},auth=AUTH,timeout=15)
    if not r.ok:
        raise RuntimeError(f'Orthanc MWL HTTP {r.status_code}: {r.text[:1000]}')
    try: return r.json()
    except Exception: return {'ok':True,'text':r.text}


def get_report(order):
    if not order.report:
        r=Report(order=order); db.session.add(r); db.session.commit()
    return order.report

def report_history(report):
    return ReportVersion.query.filter_by(report_id=report.id).order_by(ReportVersion.version_no.desc()).all()

def next_version(report):
    last=ReportVersion.query.filter_by(report_id=report.id).order_by(ReportVersion.version_no.desc()).first()
    return (last.version_no+1) if last else 1

def add_version(order,report,action,docx_path=None,pdf_path=None,change_summary=''):
    u=current_user()
    role=(u.role.code if u and u.role else 'SYSTEM')
    path=pdf_path or docx_path or report.pdf_path or report.docx_path or report.source_path
    digest='';size=0
    if path and os.path.exists(path):
        try:
            import hashlib
            h=hashlib.sha256()
            with open(path,'rb') as f:
                for chunk in iter(lambda:f.read(1024*1024),b''):h.update(chunk)
            digest=h.hexdigest();size=os.path.getsize(path)
        except Exception:pass
    db.session.add(ReportVersion(report_id=report.id,accession=order.accession,version_no=next_version(report),
        action=action,findings=report.findings or '',impression=report.impression or '',
        radiologist=report.radiologist or '',docx_path=docx_path,pdf_path=pdf_path,
        created_by=(u.id if u else None),created_role=role,change_summary=change_summary,
        sha256=digest,file_size=size))

def make_docx(order, report=None):
    doc=Document(); doc.add_heading('RADIOLOGY REPORT',0)
    t=doc.add_table(rows=6,cols=2)
    vals=[('Patient',order.patient.name),('Patient ID',order.patient.patient_id),('Accession',order.accession),
          ('Study',f'{order.modality} - {order.procedure}'),('Branch',order.branch.name if order.branch else ''),
          ('Date',order.scheduled.strftime('%Y-%m-%d %H:%M'))]
    for row,(a,b) in zip(t.rows,vals): row.cells[0].text=a; row.cells[1].text=b
    doc.add_paragraph(f'RIS_ACCESSION: {order.accession}')
    doc.add_heading('FINDINGS',level=1); doc.add_paragraph((report.findings if report else '') or '\n\n')
    doc.add_heading('IMPRESSION',level=1); doc.add_paragraph((report.impression if report else '') or '\n\n')
    doc.add_paragraph('\nRadiologist: '+((report.radiologist if report else '') or '____________________'))
    buf=io.BytesIO(); doc.save(buf); buf.seek(0); return buf

def make_pdf(order, report, path):
    c=canvas.Canvas(path,pagesize=A4); w,h=A4; y=h-55
    c.setFont('Helvetica-Bold',16); c.drawString(55,y,'RADIOLOGY REPORT'); y-=35
    c.setFont('Helvetica',10)
    for line in [f'Patient: {order.patient.name}',f'Patient ID: {order.patient.patient_id}',f'Accession: {order.accession}',
                 f'Study: {order.modality} - {order.procedure}',f'Radiologist: {report.radiologist}']:
        c.drawString(55,y,line[:110]); y-=17
    for title,content in [('FINDINGS',report.findings or ''),('IMPRESSION',report.impression or '')]:
        y-=10; c.setFont('Helvetica-Bold',11); c.drawString(55,y,title); y-=18; c.setFont('Helvetica',10)
        for para in content.splitlines() or ['']:
            for i in range(0,max(1,len(para)),95):
                if y<70: c.showPage(); y=h-55; c.setFont('Helvetica',10)
                c.drawString(55,y,para[i:i+95]); y-=14
    c.save()

def extract_docx_sections(path):
    doc=Document(path); lines=[p.text.strip() for p in doc.paragraphs]
    findings=[]; impression=[]; radiologist=''; section=None
    for line in lines:
        up=line.upper()
        if up=='FINDINGS': section='findings'; continue
        if up=='IMPRESSION': section='impression'; continue
        if up.startswith('RIS_ACCESSION:'): continue
        if up.startswith('RADIOLOGIST:'):
            radiologist=line.split(':',1)[1].strip() if ':' in line else ''; section=None; continue
        if section=='findings': findings.append(line)
        elif section=='impression': impression.append(line)
    return '\n'.join(findings).strip(),'\n'.join(impression).strip(),radiologist

