def friendly_404(error):
    return render_template('error.html',
        error_code='404',
        error_id=_error_id(),
        title='Page not found',
        message='The requested page or item could not be found. It may have been moved, removed, or the link may no longer be valid. Use the Error ID below when reporting the problem.'), 404

@app.errorhandler(500)
def friendly_500(error):
    eid=_error_id()

    try:
        db.session.rollback()
    except Exception:
        pass

    app.logger.exception('Internal error %s', eid)

    try:
        return render_template(
            'error.html',
            error_code='500',
            error_id=eid,
            title='Internal Server Error',
            message='An internal error occurred. Use the Error ID below when reporting the problem.'
        ), 500
    except Exception:
        return (
            f'Internal Server Error - Error ID: {eid}',
            500,
            {'Content-Type':'text/plain; charset=utf-8'}
        )


@app.route('/login',methods=['GET','POST'])
def login():
    if request.method=='POST':
        u=User.query.filter_by(username=request.form.get('username','').strip()).first()
        if u and u.active and check_password_hash(u.password_hash,request.form.get('password','')):
            session['uid']=u.id; audit('LOGIN','user',u.id,'Successful login'); db.session.commit()
            return redirect(request.args.get('next') or url_for('dashboard'))
        attempted=(request.form.get('username','').strip()[:80] or 'UNKNOWN')
        db.session.add(AuditLog(
            user_id=(u.id if u else None),username=attempted,
            action='LOGIN_FAILED',entity='user',entity_id=str(u.id if u else ''),
            details='reason=INVALID_CREDENTIALS',
            ip=request.headers.get('X-Forwarded-For',request.remote_addr or '')[:80]
        ))
        db.session.commit()
        flash('Invalid username or password.','danger')
    return render_template('login.html')

@app.route('/logout')
def logout():
    session.clear(); return redirect(url_for('login'))

@app.route('/')
@login_required
def dashboard():
    today = date.today()
    all_orders = Order.query.all()

    def scheduled_today(order):
        return bool(
            order.scheduled
            and order.scheduled.date() == today
        )

    stats = {
        'patients': Patient.query.count(),
        'orders': len(all_orders),
        'today': sum(
            1 for order in all_orders
            if scheduled_today(order)
        ),
        'waiting': sum(
            1 for order in all_orders
            if (order.exam_status or 'ORDERED').upper()
            in ('BOOKED', 'ORDERED')
            and order.status not in ('FINAL', 'CANCELLED')
        ),
        'in_progress': sum(
            1 for order in all_orders
            if (order.exam_status or '').upper() == 'IN_PROGRESS'
        ),
        'completed': sum(
            1 for order in all_orders
            if (order.exam_status or '').upper() == 'EXAM_COMPLETED'
        ),
        'images_received': sum(
            1 for order in all_orders
            if int(order.pacs_image_count or 0) > 0
        ),
        'reporting': sum(
            1 for order in all_orders
            if order.status == 'REPORTING'
        ),
        'final': sum(
            1 for order in all_orders
            if order.status == 'FINAL'
        ),
        'unassigned': sum(
            1 for order in all_orders
            if not order.assigned_doctor_id
            and int(order.pacs_image_count or 0) > 0
            and order.status not in ('FINAL', 'CANCELLED')
        ),
        'mwl_errors': sum(
            1 for order in all_orders
            if order.status in ('MWL_ERROR', 'ROUTING_ERROR')
        ),
        'revenue': round(
            sum(float(order.paid_amount or 0) for order in all_orders),
            2,
        ),
    }

    recent = (
        Order.query
        .order_by(Order.id.desc())
        .limit(12)
        .all()
    )

    return render_template(
        'dashboard.html',
        stats=stats,
        recent=recent,
    )

@app.route('/patients')
@require_perm('patients.view')
def patients():
    q=request.args.get('q','').strip(); query=Patient.query
    if q: query=query.filter(or_(Patient.name.ilike(f'%{q}%'),Patient.patient_id.ilike(f'%{q}%'),Patient.phone.ilike(f'%{q}%'),Patient.national_id.ilike(f'%{q}%')))
    # RB_SMART_BOOKING_V2_PATIENTS_CONTEXT_V1
    return render_template(
        'patients.html',
        patients=query.order_by(Patient.id.desc()).limit(300).all(),
        q=q,
        smart_booking_branches=Branch.query.filter_by(active=True).order_by(Branch.name).all(),
        # RB_SMART_BOOKING_V2_JSON_CONTEXT_V1
        smart_booking_procedures=[
            {
                'id':p.id,
                'code':p.code or '',
                'name':p.name or '',
                'name_ar':p.name_ar or '',
                'modality':p.modality or '',
                'duration_min':int(p.duration_min or 20),
            }
            for p in Procedure.query.filter_by(active=True).order_by(
                Procedure.modality,
                Procedure.name
            ).all()
        ],
        smart_booking_procedure_branches=[
            {
                'branch_id':row.branch_id,
                'procedure_id':row.procedure_id,
                'active':bool(row.active),
            }
            for row in ProcedureBranch.query.filter_by(active=True).all()
        ],
    )

@app.route('/patients/new',methods=['GET','POST'])
@require_perm('patients.create')
def new_patient():
    # v5.46.3: one visible registration entry point.
    if request.method=='GET':
        return redirect(url_for('schedule_calendar',open_registration='1'))

    if request.method=='POST':
        name=request.form['name'].strip()
        try:
            dob_resolution=resolve_patient_dob(request.form, prefix='')
        except ValueError as exc:
            flash(str(exc), 'danger')
            return render_template(
                'patient_form.html',
                duplicates=[],
                form_data=request.form,
            ), 422
        dob=dob_resolution.dob
        phone=request.form.get('phone','').strip()
        national_id=request.form.get('national_id','').strip()
        duplicates=find_duplicate_patients(name,dob,phone,national_id)
        if duplicates and request.form.get('confirm_duplicate')!='1':
            return render_template('patient_form.html',duplicates=duplicates,form_data=request.form),409
        p=Patient(patient_id='TMP'+secrets.token_hex(8),name=name,
                  dob=dob,dob_estimated=dob_resolution.estimated,
                  sex=request.form.get('sex',''),
                  phone=phone,national_id=national_id,
                  address=request.form.get('address','').strip(),
                  email=request.form.get('email','').strip(),
                  worklist_name=(request.form.get('worklist_name','').strip() or arabic_to_latin_name(name)))
        db.session.add(p); db.session.flush(); p.patient_id=generate_patient_id(p)
        audit('PATIENT_CREATE','patient',p.id,f'{p.patient_id} {p.name}'); db.session.commit()
        flash(
            f'PATIENT_CREATED|{p.patient_id}|{p.name}',
            'success'
        )
        return redirect(url_for('new_order',patient=p.id,patient_created=1))
    return render_template('patient_form.html')

@app.route('/orders')
@require_perm('orders.view')
def orders():
    q=request.args.get('q','').strip(); status=request.args.get('status','').strip()
    query=Order.query.join(Patient)
    if q: query=query.filter(or_(Order.accession.ilike(f'%{q}%'),Order.procedure.ilike(f'%{q}%'),Patient.name.ilike(f'%{q}%'),Patient.patient_id.ilike(f'%{q}%')))
    if status: query=query.filter(Order.status==status)
    return render_template('orders.html',orders=query.order_by(Order.id.desc()).limit(400).all(),q=q,status=status)

@app.route('/orders/new',methods=['GET','POST'])
@require_perm('orders.create')
def new_order():
    # v5.46.2: one visible registration workflow.
    if request.method == 'GET':
        kw={'open_registration':'1'}
        patient_arg=request.args.get('patient',type=int)
        intake_arg=request.args.get('intake',type=int)
        if patient_arg: kw['patient']=patient_arg
        if intake_arg: kw['intake']=intake_arg
        return redirect(url_for('schedule_calendar',**kw))

    plist=Patient.query.order_by(Patient.name).all()
    branches=Branch.query.filter_by(active=True).order_by(Branch.name).all()
    procedures=Procedure.query.filter_by(active=True).order_by(Procedure.modality,Procedure.name).all()
    contracts=Contract.query.filter_by(active=True).order_by(Contract.name).all()
    referrers=ReferringDoctor.query.filter_by(active=True).order_by(ReferringDoctor.name).all()
    selected=request.args.get('patient',type=int)
    intake_id=request.args.get('intake',type=int)

    if request.method=='POST':
        patient_mode=(request.form.get('patient_mode') or 'existing').strip()

        if patient_mode=='new':
            name=(request.form.get('new_name') or '').strip()
            phone=(request.form.get('new_phone') or '').strip()
            national_id=(request.form.get('new_national_id') or '').strip()
            nationality=(request.form.get('new_nationality') or '').strip()
            rules=registration_rule_map()
            for key,value in [
                ('patient.name',name),
                ('patient.phone',phone),
                ('patient.national_id',national_id),
                ('patient.nationality',nationality),
                ('patient.email',(request.form.get('new_email') or '').strip()),
                ('patient.address',(request.form.get('new_address') or '').strip())
            ]:
                ok,msg=validate_registration_value(rules.get(key),value)
                if not ok:
                    return registration_validation_error(msg,request.form)
            if not name:
                return registration_validation_error('Patient name is required.',request.form)

            try:
                dob_resolution=resolve_patient_dob(
                    request.form,
                    prefix='new_',
                )
            except ValueError as exc:
                return registration_validation_error(
                    str(exc),
                    request.form,
                )
            dob=dob_resolution.dob
            duplicates=find_duplicate_patients(name,dob,phone,national_id)

            if duplicates and request.form.get('confirm_duplicate')!='1':
                flash(f'Possible duplicate: {duplicates[0].patient_id} — {duplicates[0].name}. Search and use existing patient, or confirm duplicate creation.','warning')
                return render_registration_form(
                    form_data=request.form,
                    selected_patient=None,
                    duplicate_patients=duplicates,
                    status=409
                )

            p=Patient(
                patient_id='TMP'+secrets.token_hex(8),
                name=name,
                dob=dob,
                dob_estimated=dob_resolution.estimated,
                sex=(request.form.get('new_sex') or '').strip(),
                phone=phone,
                national_id=national_id,
                address=(request.form.get('new_address') or '').strip(),
                email=(request.form.get('new_email') or '').strip(),
                worklist_name=((request.form.get('new_worklist_name') or '').strip() or arabic_to_latin_name(name))
            )
            db.session.add(p);db.session.flush()
            extra=PatientDemographicsExtra.query.filter_by(patient_id=p.id).first()
            if not extra:
                extra=PatientDemographicsExtra(patient_id=p.id)
                db.session.add(extra)
            extra.nationality=nationality
            extra.id_type=(request.form.get('new_id_type') or 'NATIONAL_ID').strip().upper()
            extra.other_id=(request.form.get('new_other_id') or '').strip()
            p.patient_id=next_patient_id()
            audit('PATIENT_CREATE_FROM_EASY_REGISTRATION','patient',p.id,p.patient_id)
        else:
            pid=request.form.get('patient',type=int)
            if not pid:
                return registration_validation_error(
                    'Select an existing patient or choose New Patient.',
                    request.form
                )
            p=Patient.query.get_or_404(pid)

        proc_id=request.form.get('procedure_id',type=int)
        branch_id=request.form.get('branch_id',type=int)
        proc=Procedure.query.get(proc_id) if proc_id else None
        branch=Branch.query.get(branch_id) if branch_id else None
        if not branch:
            return registration_validation_error('Select branch.',request.form,rollback=(patient_mode=='new'))
        if not proc:
            return registration_validation_error('Select examination.',request.form,rollback=(patient_mode=='new'))
        contract=Contract.query.get(request.form.get('contract_id',type=int)) if request.form.get('contract_id') else None

        try:
            scheduled=datetime.fromisoformat(request.form['scheduled'])
        except Exception:
            return registration_validation_error(
                'Invalid visit date/time.',
                request.form,
                rollback=(patient_mode=='new')
            )

        if not procedure_available_in_branch(proc.id,branch.id):
            return registration_validation_error(
                'This examination is not available in the selected branch.',
                request.form,
                rollback=(patient_mode=='new')
            )

        device=route_device(branch.id,proc.modality)
        if not device:
            return registration_validation_error(
                'No available device is configured for this examination in the selected branch.',
                request.form,
                rollback=(patient_mode=='new')
            )

        restriction=booking_restriction_reason(branch,proc,device,scheduled,int(proc.duration_min or 20))
        if restriction:
            return registration_validation_error(
                f'Cannot register this examination now: {restriction}',
                request.form,
                rollback=(patient_mode=='new')
            )

        # Insurance approval selection
        approval_required=bool(contract and contract.approval_required)
        approval_method=(request.form.get('approval_method') or '').strip().upper()
        approval_no=(request.form.get('approval_no') or '').strip()

        if approval_required:
            if approval_method not in ('AUTO','MANUAL','ALREADY_APPROVED'):
                approval_method='AUTO'

            if approval_method=='ALREADY_APPROVED' and not approval_no:
                return registration_validation_error(
                    'Approval number is required when approval is already available.',
                    request.form,
                    rollback=(patient_mode=='new')
                )
        else:
            approval_method=''
            approval_no=''

        gross,effective,patient_share,company_share,share_pct=price_order(proc,contract)
        order=Order(
            accession=new_accession(),patient=p,modality=proc.modality,procedure=proc.name,
            procedure_id=proc.id,branch_id=branch.id,device_id=device.id,
            station_ae=device.ae_title,contract_id=(contract.id if contract else None),
            referring_doctor_id=(request.form.get('referring_doctor_id',type=int) or None),
            scheduled=scheduled,status='REGISTERED',gross_price=gross,contract_price=effective,
            patient_share=patient_share,company_share=company_share,
            approval_no=approval_no,
            created_by=current_user().id,
            priority=(request.form.get('priority') or 'ROUTINE').upper()
        )
        db.session.add(order);db.session.flush()

        # Create insurance approval tracking without changing Order.status.
        if approval_required:
            approval_status = (
                'APPROVED'
                if approval_method=='ALREADY_APPROVED'
                else ('PENDING' if approval_method=='AUTO' else 'REQUIRED')
            )

            approval_row=InsuranceApprovalRequest(
                order_id=order.id,
                method=approval_method,
                status=approval_status,
                approval_no=approval_no,
                payer_name=(contract.name if contract else ''),
                requested_at=datetime.utcnow(),
                decided_at=(datetime.utcnow() if approval_status=='APPROVED' else None),
                created_by=current_user().id
            )

            db.session.add(approval_row)
            db.session.flush()

            db.session.add(InsuranceApprovalEvent(
                approval_request_id=approval_row.id,
                event_type='CREATED_FROM_REGISTRATION',
                old_status='',
                new_status=approval_status,
                message=f'method={approval_method}',
                user_id=current_user().id
            ))

            audit(
                'INSURANCE_APPROVAL_CREATE',
                'order',
                order.id,
                f'method={approval_method}; status={approval_status}'
            )

        ensure_journey(order,'REGISTERED')

        # Initial clinical note from registration screen.
        note_text=(request.form.get('clinical_note') or '').strip()
        if note_text:
            db.session.add(ClinicalNote(
                order_id=order.id,author_user_id=current_user().id,
                note_type='RECEPTION',visibility='CLINICAL_TEAM',text=note_text
            ))

        # Default consumables.
        for pc in ProcedureConsumable.query.filter_by(procedure_id=proc.id).all():
            db.session.add(OrderConsumable(
                order_id=order.id,consumable_id=pc.consumable_id,
                qty=pc.qty,source='DEFAULT',created_by=current_user().id
            ))

        # Optional first payment: requires explicit payment permission.
        pay_amount=float(request.form.get('payment_amount') or 0)
        pay_method=(request.form.get('payment_method') or '').strip().upper()
        if pay_amount>0:
            if not has_perm('payments.create'):
                db.session.rollback()
                abort(403)
            if not pay_method:
                return registration_validation_error(
                    'Select payment method.',
                    request.form,
                    rollback=True
                )
            payment=Payment(
                order_id=order.id,amount=pay_amount,method=pay_method,
                reference=(request.form.get('payment_reference') or '').strip(),
                created_by=current_user().id
            )
            db.session.add(payment)
            order.paid_amount=pay_amount
            audit('PAYMENT_CREATE','order',order.id,f'{pay_amount} {pay_method}')

        # Optional MULTI attachments in the same registration screen.
        attachment_files=request.files.getlist('attachment_files')
        attachment_categories=request.form.getlist('attachment_categories')
        attachment_notes=request.form.getlist('attachment_notes')
        saved_attachment_paths=[]
        valid_files=[f for f in attachment_files if f and f.filename]
        if valid_files:
            if not has_perm('attachments.upload'):
                db.session.rollback();abort(403)
            allowed_exts=('.pdf','.jpg','.jpeg','.png','.doc','.docx','.odt','.dcm','.dicom','.zip')
            folder=os.path.join(ATTACHMENT_DIR,str(p.id),str(order.id))
            os.makedirs(folder,exist_ok=True)
            for idx,f in enumerate(attachment_files):
                if not f or not f.filename:
                    continue
                ext=os.path.splitext(f.filename)[1].lower()
                if ext not in allowed_exts:
                    return registration_validation_error(
                        f'Unsupported attachment type: {f.filename}',
                        request.form,
                        rollback=True
                    )
                category=(attachment_categories[idx] if idx<len(attachment_categories) else 'OTHER').upper()
                notes=(attachment_notes[idx] if idx<len(attachment_notes) else '').strip()
                stored_name=generated_attachment_filename(order.id,category,f.filename)
                path=os.path.join(folder,stored_name)
                f.save(path)
                saved_attachment_paths.append(path)
                db.session.add(Attachment(
                    patient_id=p.id,order_id=order.id,
                    category=category,original_name=f.filename,stored_path=path,
                    mime_type=f.mimetype or '',notes=notes,uploaded_by=current_user().id
                ))
                audit('ATTACHMENT_UPLOAD','order',order.id,f'{category}:{f.filename}')

        # Persist the complete RIS transaction before any external side effect.
        # This prevents an MWL/assignment from existing for an order that failed to commit.
        audit('EASY_REGISTRATION_CREATE','order',order.id,
              f'{order.accession} {proc.name} Branch={branch.name} Device={device.name}')
        # RB_WORK_ORDER_GATE_V3
        # Registration must not create an MWL event.
        # MWL is created only by explicit Work Order conversion.
        try:
            db.session.commit()
        except Exception:
            db.session.rollback()
            for saved_path in saved_attachment_paths:
                try:
                    if os.path.isfile(saved_path):
                        os.remove(saved_path)
                except Exception:
                    app.logger.exception('Failed to clean attachment after registration rollback: %s',saved_path)
            raise

        order_id=order.id

        # RB_WORK_ORDER_GATE_V3
        # Registration is complete, but the case intentionally remains
        # REGISTERED until financial clearance and explicit Work Order conversion.
        flash(
            f'Visit {order.accession} registered. Complete financial clearance, then convert to Work Order.',
            'success'
        )

        return redirect(url_for(
            'order_detail',
            order_id=order.id,
            created=1
        ))

    initial_form={}
    if intake_id and selected:
        source_intake=SmartIntakeSession.query.filter_by(
          id=intake_id,patient_id=selected,status='COMPLETED').first()
        if source_intake:
            try: source_summary=json.loads(source_intake.extracted_json or '{}')
            except Exception: source_summary={}
            visit=(source_summary.get('visit_review') or {}) if isinstance(source_summary,dict) else {}
            if source_intake.suggested_procedure_id:
                initial_form['procedure_id']=str(source_intake.suggested_procedure_id)
            if source_intake.suggested_contract_id:
                initial_form['contract_id']=str(source_intake.suggested_contract_id)
            if visit.get('approval_no'):
                initial_form['approval_method']='ALREADY_APPROVED'
                initial_form['approval_no']=str(visit['approval_no'])
            initial_form['smart_intake_id']=str(source_intake.id)

    return render_registration_form(
        form_data=initial_form,
        selected_patient=selected,
        duplicate_patients=[],
        status=200
    )



@login_required
def api_registration_procedures():
    branch_id=request.args.get('branch_id',type=int)
    if not branch_id:
        return jsonify({'ok':False,'error':'branch_id required'}),400
    rows=allowed_procedures_for_branch(branch_id)
    return jsonify({'ok':True,'procedures':[{
        'id':p.id,'code':p.code,'name':p.name,'name_ar':p.name_ar,
        'modality':p.modality,'duration_min':p.duration_min,'base_price':p.base_price
    } for p in rows]})

@login_required
def api_pricing():
    proc=Procedure.query.get(request.args.get('procedure_id',type=int))
    contract=Contract.query.get(request.args.get('contract_id',type=int)) if request.args.get('contract_id') else None
    if not proc: return jsonify({'ok':False}),400
    gross,effective,patient_share,company_share,share_pct=price_order(proc,contract)
    return jsonify({'ok':True,'gross':gross,'contract_price':effective,'patient_share':patient_share,
                    'company_share':company_share,'patient_share_percent':share_pct,
                    'approval_required':bool(contract.approval_required) if contract else False})

@app.route('/profile/password',methods=['GET','POST'])
@login_required
def change_password():
    u=current_user()
    if request.method=='POST':
        if not check_password_hash(u.password_hash,request.form.get('current_password','')):
            flash('Current password is incorrect.','danger')
        elif len(request.form.get('new_password',''))<10:
            flash('New password must be at least 10 characters.','danger')
        elif request.form.get('new_password')!=request.form.get('confirm_password'):
            flash('Password confirmation does not match.','danger')
        else:
            u.password_hash=generate_password_hash(request.form['new_password']); audit('PASSWORD_CHANGE','user',u.id,'')
            db.session.commit(); flash('Password changed.','success'); return redirect(url_for('dashboard'))
    return render_template('change_password.html')



@app.route('/admin/insurance-approvals',methods=['GET','POST'])
@require_perm('contracts.manage')
def admin_insurance_approvals():

    branches=Branch.query.filter_by(active=True).order_by(Branch.name).all()
    contracts=Contract.query.filter_by(active=True).order_by(Contract.name).all()

    if request.method=='POST':

        branch_id=request.form.get('branch_id',type=int)
        payer_name=(request.form.get('payer_name') or '').strip()

        if not branch_id or not payer_name:
            flash('Branch and insurance company are required.','danger')
            return redirect(url_for('admin_insurance_approvals'))

        row=InsurancePortalAccount.query.filter_by(
            branch_id=branch_id,
            payer_name=payer_name
        ).first()

        if not row:
            row=InsurancePortalAccount(
                branch_id=branch_id,
                payer_name=payer_name
            )
            db.session.add(row)

        row.portal_url=(request.form.get('portal_url') or '').strip()
        row.login_url=(request.form.get('login_url') or '').strip()
        row.portal_type=(request.form.get('portal_type') or 'WEB').strip().upper()

        row.username=(request.form.get('username') or '').strip()
        row.credential_ref=(request.form.get('credential_ref') or '').strip()

        row.workflow_mode=(request.form.get('workflow_mode') or 'MANUAL').strip().upper()

        allowed_modes={'MANUAL','BROWSER','API','EMAIL','HYBRID'}
        if row.workflow_mode not in allowed_modes:
            row.workflow_mode='MANUAL'

        row.enabled=request.form.get('enabled')=='1'

        # MANUAL means no automatic portal execution.
        if row.workflow_mode=='MANUAL':
            row.automation_enabled=False
        else:
            row.automation_enabled=request.form.get('automation_enabled')=='1'

        row.telegram_enabled=request.form.get('telegram_enabled')=='1'
        row.email_enabled=request.form.get('email_enabled')=='1'
        row.requires_otp=request.form.get('requires_otp')=='1'

        row.login_notes=(request.form.get('login_notes') or '').strip()
        row.workflow_notes=(request.form.get('workflow_notes') or '').strip()
        row.training_notes=(request.form.get('training_notes') or '').strip()

        row.selectors_json=(request.form.get('selectors_json') or '{}').strip()

        workflow_steps=[]

        step_map=[
            ('step_login','LOGIN'),
            ('step_search_member','SEARCH_MEMBER'),
            ('step_create_request','CREATE_REQUEST'),
            ('step_upload_documents','UPLOAD_DOCUMENTS'),
            ('step_submit','SUBMIT'),
            ('step_check_status','CHECK_STATUS'),
            ('step_download_approval','DOWNLOAD_APPROVAL'),
        ]

        for field_name,step_name in step_map:
            if request.form.get(field_name)=='1':
                workflow_steps.append(step_name)

        config={
            'version':1,
            'workflow_steps':workflow_steps
        }

        # Validate portal configuration before save.
        validation_errors=[]

        effective_url=(row.login_url or row.portal_url or '').strip()

        if row.workflow_mode=='BROWSER' and row.automation_enabled:
            if not effective_url:
                validation_errors.append('Browser Automation requires Portal/Login URL.')

            if not row.username:
                validation_errors.append('Browser Automation requires Username.')

            if not row.credential_ref:
                validation_errors.append('Browser Automation requires Credential Reference.')

            required_steps={'LOGIN','SUBMIT','CHECK_STATUS'}
            missing=sorted(required_steps-set(workflow_steps))

            if missing:
                validation_errors.append(
                    'Browser Automation missing required workflow steps: '
                    + ', '.join(missing)
                )

        elif row.workflow_mode=='API' and row.automation_enabled:
            if not effective_url:
                validation_errors.append('API workflow requires endpoint URL.')

            required_steps={'SUBMIT','CHECK_STATUS'}
            missing=sorted(required_steps-set(workflow_steps))

            if missing:
                validation_errors.append(
                    'API workflow missing required workflow steps: '
                    + ', '.join(missing)
                )

        elif row.workflow_mode=='HYBRID' and row.automation_enabled:
            if not effective_url:
                validation_errors.append('Hybrid workflow requires Portal/API URL.')

            if not workflow_steps:
                validation_errors.append('Hybrid workflow requires at least one workflow step.')

        if validation_errors:
            db.session.rollback()

            for msg in validation_errors:
                flash(msg,'danger')

            return redirect(
                url_for('admin_insurance_approvals')
            )

        row.automation_config_json=json.dumps(
            config,
            ensure_ascii=False
        )

        row.updated_at=datetime.utcnow()

        audit(
            'INSURANCE_PORTAL_SAVE',
            'insurance_portal_account',
            row.id or 0,
            f'branch={branch_id}; payer={payer_name}'
        )

        db.session.commit()

        flash('Insurance portal configuration saved.','success')
        return redirect(
            url_for(
                'admin_insurance_approval_edit',
                portal_id=row.id
            )
        )

    rows=InsurancePortalAccount.query.order_by(
        InsurancePortalAccount.payer_name,
        InsurancePortalAccount.branch_id
    ).all()

    return render_template(
        'admin_insurance_approvals.html',
        rows=rows,
        branches=branches,
        contracts=contracts
    )


