@app.get('/approvals')
@require_perm('orders.view')
def insurance_approvals_dashboard():
    view=(request.args.get('view') or 'pending').strip().lower()

    query=InsuranceApprovalRequest.query.join(
        Order,
        InsuranceApprovalRequest.order_id==Order.id
    ).join(
        Patient,
        Order.patient_id==Patient.id
    )

    if view=='approved':
        query=query.filter(
            InsuranceApprovalRequest.status=='APPROVED'
        )

    elif view=='action':
        query=query.filter(
            InsuranceApprovalRequest.status.in_(
                ['REJECTED','NEED_INFO','ERROR']
            )
        )

    elif view=='all':
        pass

    else:
        view='pending'
        query=query.filter(
            InsuranceApprovalRequest.status.in_(
                ['REQUIRED','SUBMITTED','PENDING']
            )
        )

    rows=query.order_by(
        InsuranceApprovalRequest.updated_at.desc(),
        InsuranceApprovalRequest.id.desc()
    ).limit(500).all()

    counts={
        'pending': InsuranceApprovalRequest.query.filter(
            InsuranceApprovalRequest.status.in_(
                ['REQUIRED','SUBMITTED','PENDING']
            )
        ).count(),

        'approved': InsuranceApprovalRequest.query.filter_by(
            status='APPROVED'
        ).count(),

        'action': InsuranceApprovalRequest.query.filter(
            InsuranceApprovalRequest.status.in_(
                ['REJECTED','NEED_INFO','ERROR']
            )
        ).count(),

        'all': InsuranceApprovalRequest.query.count()
    }

    return render_template(
        'approvals.html',
        rows=rows,
        view=view,
        counts=counts,
        now=datetime.utcnow()
    )


