@app.post('/orders/<int:order_id>/insurance-approval/start')
@require_perm('orders.view')
def insurance_approval_start(order_id):
    order=Order.query.get_or_404(order_id)

    method=(request.form.get('method') or 'MANUAL').strip().upper()

    if method not in ('MANUAL','AUTO'):
        method='MANUAL'

    row=InsuranceApprovalRequest.query.filter_by(
        order_id=order.id
    ).order_by(InsuranceApprovalRequest.id.desc()).first()

    if row and row.status in ('REQUIRED','SUBMITTED','PENDING'):
        flash('يوجد طلب موافقة مفتوح بالفعل لهذه الحالة.','warning')
        return redirect(url_for('order_detail',order_id=order.id))

    payer_name=order.contract.name if order.contract else ''

    row=InsuranceApprovalRequest(
        order_id=order.id,
        method=method,
        status='PENDING' if method=='AUTO' else 'REQUIRED',
        payer_name=payer_name,
        requested_at=datetime.utcnow(),
        created_by=current_user().id
    )

    db.session.add(row)
    db.session.flush()

    db.session.add(InsuranceApprovalEvent(
        approval_request_id=row.id,
        event_type='CREATED',
        old_status='',
        new_status=row.status,
        message='Approval request created',
        user_id=current_user().id
    ))

    audit(
        'INSURANCE_APPROVAL_CREATE',
        'order',
        order.id,
        f'method={method}; status={row.status}'
    )

    db.session.commit()

    if method=='AUTO':
        flash('تم إرسال طلب الموافقة للنظام للمتابعة التلقائية.','success')
    else:
        flash('تم فتح متابعة الموافقة اليدوية.','success')

    return redirect(url_for('order_detail',order_id=order.id))


@app.post('/orders/<int:order_id>/insurance-approval/update')
@require_perm('orders.view')
def insurance_approval_update(order_id):
    order=Order.query.get_or_404(order_id)

    row=InsuranceApprovalRequest.query.filter_by(
        order_id=order.id
    ).order_by(InsuranceApprovalRequest.id.desc()).first_or_404()

    new_status=(request.form.get('status') or '').strip().upper()

    allowed={
        'REQUIRED',
        'SUBMITTED',
        'PENDING',
        'APPROVED',
        'REJECTED',
        'NEED_INFO',
        'ERROR'
    }

    if new_status not in allowed:
        flash('حالة الموافقة غير صحيحة.','danger')
        return redirect(url_for('order_detail',order_id=order.id))

    old_status=row.status or ''

    row.status=new_status
    row.approval_no=(request.form.get('approval_no') or '').strip()
    row.notes=(request.form.get('notes') or '').strip()
    row.updated_at=datetime.utcnow()

    if new_status in ('APPROVED','REJECTED'):
        row.decided_at=datetime.utcnow()

    if new_status=='APPROVED' and row.approval_no:
        # Existing Order field only; does NOT modify workflow status.
        order.approval_no=row.approval_no

    db.session.add(InsuranceApprovalEvent(
        approval_request_id=row.id,
        event_type='STATUS_CHANGE',
        old_status=old_status,
        new_status=new_status,
        message=row.notes,
        user_id=current_user().id
    ))

    audit(
        'INSURANCE_APPROVAL_UPDATE',
        'order',
        order.id,
        f'{old_status}->{new_status}; approval_no={row.approval_no}'
    )

    db.session.commit()

    flash('تم تحديث حالة الموافقة.','success')

    return redirect(url_for('order_detail',order_id=order.id))


# RB_WORK_ORDER_GATE_V4
@app.post('/orders/<int:order_id>/convert-to-work-order')
@require_perm('orders.create')
def convert_to_work_order(order_id):
    order=Order.query.get_or_404(order_id)

    if (order.status or '').upper() != 'REGISTERED':
        flash('Only REGISTERED orders can be converted to Work Orders.','warning')
        return redirect(url_for('order_detail',order_id=order.id))

    if order_balance(order) > 0.01:
        flash('Full financial clearance is required before converting to Work Order.','danger')
        return redirect(url_for('order_detail',order_id=order.id))

    if not order.device_id or not (order.station_ae or '').strip():
        flash('Device and Station AE are required before Work Order conversion.','danger')
        return redirect(url_for('order_detail',order_id=order.id))

    try:
        mwl_event=enqueue_event(
            'ORDER_MWL_CREATE',
            'order',
            order.id,
            {
                'accession':order.accession,
                'device_id':order.device_id
            }
        )
        order.status='MWL_PENDING'
        audit(
            'WORK_ORDER_MWL_PENDING',
            'order',
            order.id,
            f'accession={order.accession}; station_ae={order.station_ae}'
        )
        db.session.commit()
        mwl_event_id=mwl_event.id
    except Exception as exc:
        db.session.rollback()
        app.logger.exception(
            'Work Order preparation failed order=%s',
            order.id
        )
        flash(
            f'Work Order preparation failed: {exc}',
            'danger'
        )
        return redirect(url_for('order_detail',order_id=order.id))

    try:
        order=Order.query.get(order_id)
        send_mwl(order)

        mwl_event=EventOutbox.query.get(mwl_event_id)
        order.status='SCHEDULED'
        order.exam_status='ORDERED'

        if mwl_event:
            mwl_event.status='PROCESSED'
            mwl_event.attempts=int(mwl_event.attempts or 0)+1
            mwl_event.processed_at=datetime.utcnow()
            mwl_event.last_error=''

        audit(
            'WORK_ORDER_CREATED',
            'order',
            order.id,
            f'accession={order.accession}; station_ae={order.station_ae}'
        )
        db.session.commit()
        flash('Work Order created and MWL sent successfully.','success')
    except Exception as exc:
        db.session.rollback()

        order=Order.query.get(order_id)
        mwl_event=EventOutbox.query.get(mwl_event_id)

        if order:
            order.status='MWL_ERROR'

        if mwl_event:
            mwl_event.status='FAILED'
            mwl_event.attempts=int(mwl_event.attempts or 0)+1
            mwl_event.last_error=str(exc)[:2000]

        if order:
            audit(
                'WORK_ORDER_MWL_FAILED',
                'order',
                order.id,
                str(exc)[:500]
            )

        db.session.commit()
        app.logger.exception(
            'Work Order MWL delivery failed order=%s',
            order_id
        )
        flash(
            'Work Order was not activated because MWL delivery failed.',
            'danger'
        )

    return redirect(url_for('order_detail',order_id=order_id))


@app.route('/orders/<int:order_id>/resend-mwl',methods=['POST'])
@require_perm('devices.manage')
def resend_mwl(order_id):
    order=Order.query.get_or_404(order_id)

    # RB_WORK_ORDER_GATE_V3
    # Administrative resend is only for a case that has already passed
    # the Work Order gate. It must never activate a REGISTERED case.
    current_status=(order.status or '').upper()
    if current_status == 'REGISTERED':
        flash('Convert this case to Work Order before sending MWL.','warning')
        return redirect(url_for('order_detail',order_id=order.id))
    if current_status == 'MWL_PENDING':
        flash('MWL delivery is already pending for this Work Order.','warning')
        return redirect(url_for('order_detail',order_id=order.id))

    device=route_device(order.branch_id,order.modality) if order.branch_id else None
    if device: order.device_id=device.id; order.station_ae=device.ae_title
    try:
        if not device: raise ValueError('No active device route')
        send_mwl(order); order.status='SCHEDULED'; flash('MWL sent successfully.','success')
    except Exception as e:
        order.status='MWL_ERROR'; flash(str(e),'danger')
    audit('MWL_RESEND','order',order.id,order.station_ae or ''); db.session.commit()
    return redirect(url_for('order_detail',order_id=order.id))

