@app.route('/nursing')
@require_perm('nursing.worklist')
def nursing_worklist():
    # RB_ROLE_WORKLIST_FILTERS_V1
    q = Order.query.filter(Order.status.notin_(['FINAL', 'CANCELLED']))

    search = (request.args.get('q') or '').strip()
    date_from = (request.args.get('date_from') or '').strip()
    date_to = (request.args.get('date_to') or '').strip()
    priority = (request.args.get('priority') or '').strip().upper()

    if search:
        like = f'%{search}%'
        q = q.join(Patient).filter(db.or_(
            Patient.name.ilike(like),
            Patient.patient_id.ilike(like),
            Patient.phone.ilike(like),
            Patient.national_id.ilike(like),
            Order.accession.ilike(like),
            Order.procedure.ilike(like),
            Order.modality.ilike(like),
        ))

    if priority:
        q = q.filter(Order.priority == priority)

    if date_from:
        try:
            start_day = datetime.strptime(date_from, '%Y-%m-%d')
            q = q.filter(Order.scheduled >= start_day)
        except ValueError:
            pass

    if date_to:
        try:
            end_day = datetime.strptime(date_to, '%Y-%m-%d') + timedelta(days=1)
            q = q.filter(Order.scheduled < end_day)
        except ValueError:
            pass

    orders = (
        q.order_by(Order.scheduled.desc())
        .limit(300)
        .all()
    )

    rows = []

    for order in orders:
        defaults = (
            ProcedureConsumable.query
            .filter_by(procedure_id=order.procedure_id)
            .count()
            if order.procedure_id
            else 0
        )
        confirmed = (
            NursingConsumableEntry.query
            .filter_by(order_id=order.id, confirmed=True)
            .count()
        )
        rows.append((order, defaults, confirmed))

    image_urls = {
        order.id: clinical_image_only_url(order)
        for order in orders
    }

    attachment_counts = {
        order.id: _order_attachment_count(order)
        for order in orders
    }

    return render_template(
        'nursing.html',
        rows=rows,
        image_urls=image_urls,
        attachment_counts=attachment_counts,
        saved_views=_saved_views_for('NURSING'),
        saved_view_page='NURSING',
    )

@app.route('/nursing/<int:order_id>',methods=['GET','POST'])
@require_perm('consumables.use')
def nursing_case(order_id):
    order=Order.query.get_or_404(order_id)
    defaults=ProcedureConsumable.query.filter_by(procedure_id=order.procedure_id).all() if order.procedure_id else []
    if request.method=='POST':
        if NursingConsumableEntry.query.filter_by(order_id=order.id,confirmed=True).first():
            flash('Consumables are already confirmed. Supervisor correction is required for changes.','warning')
            return redirect(url_for('nursing_case',order_id=order.id))
        for pc in defaults:
            qty=max(0,float(request.form.get('qty_'+str(pc.consumable_id)) or 0))
            n=NursingConsumableEntry.query.filter_by(order_id=order.id,consumable_id=pc.consumable_id).first()
            if not n:
                n=NursingConsumableEntry(order_id=order.id,consumable_id=pc.consumable_id); db.session.add(n)
            n.default_qty=pc.qty; n.actual_qty=qty; n.confirmed=True
            n.confirmed_by=current_user().id; n.confirmed_at=datetime.utcnow()
            oc=OrderConsumable.query.filter_by(order_id=order.id,consumable_id=pc.consumable_id).first()
            if not oc:
                oc=OrderConsumable(order_id=order.id,consumable_id=pc.consumable_id,qty=qty,source='NURSING',created_by=current_user().id); db.session.add(oc)
            else: oc.qty=qty; oc.source='NURSING'
            item=Consumable.query.get(pc.consumable_id)
            if item:
                _record_stock_movement(item,-qty,'NURSING_USAGE',reason='Actual nursing usage',
                    reference_type='order',reference_id=order.id,branch_id=order.branch_id,user_id=current_user().id)
        audit('NURSING_CONSUMABLES_CONFIRMED','order',order.id,'Actual quantities confirmed and deducted from stock')
        db.session.commit(); flash('Consumables confirmed and stock updated.','success')
        return redirect(url_for('nursing_worklist'))
    entries={x.consumable_id:x for x in NursingConsumableEntry.query.filter_by(order_id=order.id).all()}
    warehouse=default_warehouse_for_order(order)
    inventory_items=[]
    if warehouse:
        for item in InventoryItem.query.filter_by(active=True).order_by(InventoryItem.name).all():
            inventory_items.append({'id':item.id,'name':item.name,'code':item.code,'unit':item.unit,
                                    'available':inventory_available_qty(warehouse.id,item.id)})
    return render_template(
        'nursing_case.html',
        order=order,
        defaults=defaults,
        entries=entries,
        inv_wh=warehouse,
        inventory_items=inventory_items,
        image_url=clinical_image_only_url(order),
        attachments=(
            Attachment.query
            .filter_by(order_id=order.id)
            .order_by(Attachment.created_at.desc())
            .all()
        ),
        clinical_notes=(
            ClinicalNote.query
            .filter_by(order_id=order.id)
            .order_by(ClinicalNote.created_at.desc())
            .limit(10)
            .all()
        ),
    )

@app.post('/nursing/<int:order_id>/correct')
@require_perm('consumables.correct')
def nursing_consumable_correct(order_id):
    order=Order.query.get_or_404(order_id)
    reason=request.form.get('reason','').strip()
    if len(reason)<5:
        flash('Correction requires a reason.','danger'); return redirect(url_for('nursing_case',order_id=order.id))
    entries=NursingConsumableEntry.query.filter_by(order_id=order.id,confirmed=True).all()
    for n in entries:
        qty=max(0,float(request.form.get('qty_'+str(n.consumable_id)) or n.actual_qty or 0))
        old=float(n.actual_qty or 0); n.actual_qty=qty; n.corrected_by=current_user().id; n.corrected_at=datetime.utcnow(); n.correction_reason=reason
        oc=OrderConsumable.query.filter_by(order_id=order.id,consumable_id=n.consumable_id).first()
        if oc: oc.qty=qty; oc.source='NURSING_CORRECTION'
        item=Consumable.query.get(n.consumable_id)
        if item:
            _record_stock_movement(item,(old-qty),'NURSING_CORRECTION',reason=reason,
                reference_type='order',reference_id=order.id,branch_id=order.branch_id,user_id=current_user().id)
        audit('CONSUMABLE_CORRECTION','order',order.id,f'item={n.consumable_id} {old}->{qty}; stock_delta={old-qty}; reason={reason}')
    db.session.commit(); flash('Consumable correction saved and audited.','success')
    return redirect(url_for('nursing_case',order_id=order.id))

