@app.route('/portal/<token>',methods=['GET','POST'])
def patient_portal(token):
    x=PortalAccessToken.query.filter_by(token=token,revoked=False).first_or_404()
    if x.expires_at<datetime.utcnow(): abort(410)
    o=x.order
    if not o: abort(404)
    verify_key='portal_verified_'+token
    digits=re.sub(r'\D','',o.patient.phone or '')
    needs_verify=PORTAL_REQUIRE_PHONE_VERIFY and len(digits)>=4
    if needs_verify and not session.get(verify_key):
        if request.method=='POST':
            if re.sub(r'\D','',request.form.get('phone_last4',''))==digits[-4:]:
                session[verify_key]=True
                return redirect(url_for('patient_portal',token=token))
            flash('Verification code does not match the registered mobile number.','danger')
        return render_template('patient_portal_verify.html',order=o,portal_token=token)
    report=o.report if o.report and o.report.status=='FINAL' else None
    viewer_url=case_pacs_url(o) if int(o.pacs_image_count or 0)>0 else ''
    return render_template('patient_portal.html',order=o,report=report,portal_token=token,viewer_url=viewer_url)

@app.route('/portal/<token>/report')
def patient_portal_report(token):
    x=PortalAccessToken.query.filter_by(token=token,revoked=False).first_or_404()
    if x.expires_at<datetime.utcnow(): abort(410)
    o=x.order
    if not o or o.status!='FINAL' or not o.report or o.report.status!='FINAL': abort(404)
    path=o.report.pdf_path or o.report.source_path
    if not path or not os.path.exists(path): abort(404)
    return send_file(path,as_attachment=True,download_name=os.path.basename(path))

