@app.post('/technician/<int:order_id>/consume')
@require_perm('consumables.use')
def technician_case_consume(order_id):
    order = Order.query.get_or_404(order_id)

    exam_status = (order.exam_status or 'ORDERED').upper()

    # RB_TECHNICIAN_CONSUME_DURING_EXAM_ONLY_V1
    if exam_status != 'IN_PROGRESS':
        flash(
            'Start the examination before recording consumables.',
            'danger',
        )
        return redirect(url_for(
            'technician_case_workspace',
            order_id=order.id,
        ))

    try:
        item_id = int(request.form.get('item_id') or 0)
        qty = float(request.form.get('qty') or 0)
    except (TypeError, ValueError):
        flash('Invalid consumable or quantity.', 'danger')
        return redirect(url_for(
            'technician_case_workspace',
            order_id=order.id,
        ))

    item = InventoryItem.query.get_or_404(item_id)
    warehouse = default_warehouse_for_order(order)
    reason = (request.form.get('reason') or '').strip()

    try:
        consume_inventory(
            order,
            item,
            qty,
            usage_type='USED',
            source='MANUAL',
            reason=reason,
            warehouse=warehouse,
            user=current_user(),
        )
        audit(
            'TECHNICIAN_CONSUMABLE_USED',
            'order',
            order.id,
            f'item={item.code}; qty={qty:g}; unit={item.unit}',
        )
        db.session.commit()
        flash('Actual consumable usage recorded.', 'success')
    except Exception as exc:
        db.session.rollback()
        flash(str(exc), 'danger')

    return redirect(url_for(
        'technician_case_workspace',
        order_id=order.id,
    ))


@app.route('/technician')
@require_perm('technician.worklist')
def technician_worklist():
    # RB_ROLE_WORKLIST_FILTERS_V1
    q = Order.query.filter(Order.status.in_([
        'SCHEDULED',
        'ARRIVED',
        'IN_PROGRESS',
        'COMPLETED',
        'IMAGES_RECEIVED',
        'REPORTING',
        'MWL_ERROR',
    ]))

    search = (request.args.get('q') or '').strip()
    date_from = (request.args.get('date_from') or '').strip()
    date_to = (request.args.get('date_to') or '').strip()
    priority = (request.args.get('priority') or '').strip().upper()

    if search:
        like = f'%{search}%'
        q = q.join(Patient).filter(db.or_(
            Patient.name.ilike(like),
            Patient.patient_id.ilike(like),
            Patient.phone.ilike(like),
            Patient.national_id.ilike(like),
            Order.accession.ilike(like),
            Order.procedure.ilike(like),
            Order.modality.ilike(like),
        ))

    if priority:
        q = q.filter(Order.priority == priority)

    if date_from:
        try:
            start_day = datetime.strptime(date_from, '%Y-%m-%d')
            q = q.filter(Order.scheduled >= start_day)
        except ValueError:
            pass

    if date_to:
        try:
            end_day = datetime.strptime(date_to, '%Y-%m-%d') + timedelta(days=1)
            q = q.filter(Order.scheduled < end_day)
        except ValueError:
            pass

    rows = (
        q.order_by(Order.scheduled.desc())
        .limit(300)
        .all()
    )

    image_urls = {
        order.id: clinical_image_only_url(order)
        for order in rows
    }

    attachment_counts = {
        order.id: _order_attachment_count(order)
        for order in rows
    }

    return render_template(
        'technician.html',
        orders=rows,
        image_urls=image_urls,
        attachment_counts=attachment_counts,
        saved_views=_saved_views_for('TECHNICIAN'),
        saved_view_page='TECHNICIAN',
    )

