@require_perm('reports.view')
def reports():
    rows=Order.query.order_by(Order.scheduled.desc()).limit(400).all()
    return render_template('reports.html',orders=rows)

@app.post('/reports/<int:order_id>/admin-reopen')
@require_perm('reports.edit')
def admin_report_reopen(order_id):
    u=current_user()

    role=(
        u.role.code.upper()
        if u and u.role and u.role.code
        else ''
    )

    if role not in ('SUPER_ADMIN','ADMIN'):
        abort(403)

    order=Order.query.get_or_404(order_id)
    report=get_report(order)

    audit_as_user(
        u,
        'REPORT_REOPEN_BLOCKED',
        'order',
        order.id,
        (
            'Legacy FINAL->DRAFT reopen disabled. '
            'A dedicated Addendum workflow is required.'
        )
    )

    db.session.commit()

    flash(
        'Reopening a FINAL report is disabled. '
        'A dedicated Addendum workflow must be used.',
        'danger'
    )

    return redirect(
        url_for(
            'report_editor',
            order_id=order.id
        )
    )




@app.post('/reports/<int:order_id>/lease/acquire')
@require_perm('reports.edit')
def report_lease_acquire(order_id):
    import secrets

    order=Order.query.get_or_404(order_id)
    report=get_report(order)
    user=current_user()

    data=request.get_json(silent=True) or {}

    editor_type=str(
        data.get('editor_type') or 'BROWSER'
    ).strip().upper()

    supplied_token=str(
        data.get('lease_token') or
        request.headers.get('X-RadBridge-Report-Lease') or
        ''
    ).strip()

    lease_token=(
        supplied_token
        if supplied_token
        else secrets.token_urlsafe(32)
    )

    try:
        lease=acquire_or_renew_lease(
            db=db,
            order=order,
            report=report,
            user=user,
            editor_type=editor_type,
            lease_token=lease_token,
        )

        audit(
            'REPORT_EDIT_LEASE_ACQUIRED',
            'order',
            order.id,
            f'editor={editor_type}; user={user.id}'
        )

        db.session.commit()

        return jsonify({
            'ok': True,
            'lease_token': lease_token,
            'editor_type': lease.editor_type,
            'expires_at': lease.expires_at.isoformat(),
        })

    except ReportEditControlError as exc:
        db.session.rollback()

        code=getattr(
            exc,
            'code',
            type(exc).__name__
        )

        try:
            audit(
                'REPORT_EDIT_LEASE_DENIED',
                'order',
                order.id,
                f'editor={editor_type}; code={code}; user={user.id}'
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        return jsonify({
            'ok': False,
            'error': code,
        }), 409 if code in (
            'FINAL_REPORT_LOCKED',
            'REPORT_EDIT_LOCKED',
        ) else 403



@app.post('/reports/<int:order_id>/lease/release')
@require_perm('reports.edit')
def report_lease_release(order_id):
    order=Order.query.get_or_404(order_id)
    user=current_user()

    data=request.get_json(silent=True) or {}

    lease_token=str(
        data.get('lease_token') or
        request.headers.get('X-RadBridge-Report-Lease') or
        ''
    ).strip()

    if not lease_token:
        return jsonify({
            'ok': False,
            'error': 'REPORT_LEASE_TOKEN_REQUIRED',
        }), 400

    try:
        released=release_lease(
            db=db,
            order_id=order.id,
            user_id=user.id,
            lease_token=lease_token,
        )

        audit(
            'REPORT_EDIT_LEASE_RELEASED',
            'order',
            order.id,
            f'user={user.id}; released={released}'
        )

        db.session.commit()

        return jsonify({
            'ok': True,
            'released': released,
        })

    except Exception:
        db.session.rollback()
        raise


@app.route('/reports/<int:order_id>',methods=['GET','POST'])
@require_perm('reports.edit')
def report_editor(order_id):
    order=Order.query.get_or_404(order_id)
    if not doctor_case_access_allowed(current_user(),order):
        abort(403)
    report=get_report(order)

    if request.method=='POST':
        target=request.form.get('action','DRAFT').upper().strip()

        user=current_user()

        try:
            assert_not_final(report)
            assert_role_allowed(user,target)

            if target=='DRAFT':
                lease_token=str(
                    request.form.get('lease_token') or
                    request.headers.get('X-RadBridge-Report-Lease') or
                    ''
                ).strip()

                assert_lease_owner(
                    db=db,
                    order=order,
                    report=report,
                    user=user,
                    lease_token=lease_token,
                )

        except ReportEditControlError as exc:
            code=getattr(exc,'code',type(exc).__name__)

            try:
                audit(
                    'REPORT_EDIT_DENIED',
                    'order',
                    order.id,
                    f'action={target}; editor=BROWSER; code={code}; user={user.id}'
                )
                db.session.commit()
            except Exception:
                db.session.rollback()

            flash(
                'Report editing is currently blocked.',
                'danger'
            )

            return redirect(
                url_for('report_editor',order_id=order.id)
            )

        # Browser clinical workflow is intentionally restricted to the
        # unified DRAFT -> VERIFIED -> FINAL state machine.
        if target not in ('DRAFT','VERIFIED','FINAL'):
            flash(
                'This workflow action is not available in the Web editor. '
                'Use Save Draft, Verify, then Finalize.',
                'danger'
            )
            return redirect(
                url_for('report_editor',order_id=order.id)
            )

        if (report.status or '').upper()=='FINAL':
            flash(
                'Final report is locked. '
                'A dedicated Addendum workflow is required.',
                'danger'
            )
            return redirect(
                url_for('report_editor',order_id=order.id)
            )

        user=current_user()

        if not user:
            abort(403)

        submitted_base=request.form.get(
            'base_version_no',
            ''
        ).strip()

        if not submitted_base:
            flash(
                'Report version context is missing. Reload the report.',
                'danger'
            )
            return redirect(
                url_for('report_editor',order_id=order.id)
            )

        try:
            submitted_base=int(submitted_base)
        except Exception:
            flash(
                'Invalid report version context. Reload the report.',
                'danger'
            )
            return redirect(
                url_for('report_editor',order_id=order.id)
            )

        latest=(
            ReportVersion.query
            .filter_by(report_id=report.id)
            .order_by(ReportVersion.version_no.desc())
            .first()
        )

        latest_no=int(latest.version_no) if latest else 0

        if submitted_base != latest_no:
            flash(
                'This report changed after the page was opened. '
                'Reload before continuing.',
                'danger'
            )
            return redirect(
                url_for('report_editor',order_id=order.id)
            )

        username=(
            user.full_name
            or user.username
            or 'Unknown'
        )

        findings=request.form.get(
            'findings',
            ''
        ).strip()

        impression=request.form.get(
            'impression',
            ''
        ).strip()

        radiologist=request.form.get(
            'radiologist',
            ''
        ).strip()

        # VERIFY and FINALIZE are state transitions only.
        # They must never implicitly save edited text.
        if target in ('VERIFIED','FINAL'):
            try:
                assert_no_foreign_active_lease(
                    db=db,
                    order_id=order.id,
                    user=user,
                )
            except ReportEditControlError as exc:
                code=getattr(
                    exc,
                    'code',
                    type(exc).__name__
                )

                audit(
                    'REPORT_EDIT_DENIED',
                    'order',
                    order.id,
                    f'action={target}; editor=BROWSER; code={code}; user={user.id}'
                )
                db.session.commit()

                flash(
                    'This report is currently being edited by another user.',
                    'danger'
                )

                return redirect(
                    url_for(
                        'report_editor',
                        order_id=order.id
                    )
                )

            if (
                findings != str(report.findings or '')
                or impression != str(report.impression or '')
                or radiologist != str(report.radiologist or '')
            ):
                flash(
                    'Unsaved report changes detected. '
                    'Save Draft before Verify or Finalize.',
                    'danger'
                )
                return redirect(
                    url_for('report_editor',order_id=order.id)
                )

        try:
            if target=='DRAFT':
                commit_id=request.form.get(
                    'commit_id',
                    ''
                ).strip()

                if not commit_id:
                    flash(
                        'Commit identity is missing. Reload the report.',
                        'danger'
                    )
                    return redirect(
                        url_for(
                            'report_editor',
                            order_id=order.id
                        )
                    )

                from report_transaction_writer import \
                    commit_report_version

                # Browser reports are text-based. Build a temporary DOCX
                # adapter and send it through the single content writer.
                tmpdir=tempfile.mkdtemp(
                    prefix='ris-browser-draft-'
                )

                try:
                    tmppath=os.path.join(
                        tmpdir,
                        'browser-draft.docx'
                    )

                    class _BrowserDraft:
                        pass

                    draft=_BrowserDraft()
                    draft.findings=findings
                    draft.impression=impression
                    draft.radiologist=radiologist

                    buf=make_docx(order,draft)

                    with open(tmppath,'wb') as fh:
                        fh.write(buf.getvalue())

                    result=commit_report_version(
                        db=db,
                        Report=Report,
                        ReportVersion=ReportVersion,
                        report_root=REPORT_DIR,
                        order=order,
                        patient=order.patient,
                        user=user,
                        editor_type='BROWSER',
                        requested_status='DRAFT',
                        source_file=tmppath,
                        base_version_no=submitted_base,
                        commit_id=commit_id,
                        findings=findings,
                        impression=impression,
                        radiologist=radiologist,
                        change_summary='Browser Save Draft',
                    )

                finally:
                    shutil.rmtree(
                        tmpdir,
                        ignore_errors=True
                    )

                audit(
                    'REPORT_BROWSER_DRAFT',
                    'order',
                    order.id,
                    (
                        f'version={result.get("version_no")}; '
                        f'commit_id={commit_id}'
                    )
                )

                db.session.commit()

                flash(
                    'Draft saved.',
                    'success'
                )

            elif target=='VERIFIED':
                from onlyoffice_report_bridge import \
                    verify_latest_report_version

                version=verify_latest_report_version(
                    db=db,
                    Report=Report,
                    ReportVersion=ReportVersion,
                    order=order,
                    user=user,
                )

                audit(
                    'REPORT_VERIFIED',
                    'order',
                    order.id,
                    (
                        f'version={version.version_no}; '
                        f'by={username}; editor=BROWSER'
                    )
                )

                db.session.commit()

                flash(
                    'Report verified.',
                    'success'
                )

            elif target=='FINAL':
                demographic_ok, demographic_reason = \
                    pacs_demographic_gate(order)

                if not demographic_ok:
                    audit(
                        'REPORT_FINALIZE_BLOCKED_DEMOGRAPHICS',
                        'order',
                        order.id,
                        demographic_reason
                    )

                    db.session.commit()

                    flash(
                        'Report finalization blocked: '
                        'PACS demographics must be verified '
                        'or reconciled first.',
                        'danger'
                    )

                    return redirect(
                        url_for(
                            'report_editor',
                            order_id=order.id
                        )
                    )

                from onlyoffice_report_bridge import \
                    finalize_latest_report_version

                version=finalize_latest_report_version(
                    db=db,
                    Report=Report,
                    ReportVersion=ReportVersion,
                    order=order,
                    user=user,
                )

                audit(
                    'REPORT_FINALIZED',
                    'order',
                    order.id,
                    (
                        f'version={version.version_no}; '
                        f'by={username}; editor=BROWSER'
                    )
                )

                db.session.commit()

                queue_final_delivery(order)

                enqueue_event(
                    'REPORT_FINALIZED',
                    'order',
                    order.id,
                    {
                        'accession':order.accession
                    }
                )

                db.session.commit()

                flash(
                    'Report finalized.',
                    'success'
                )

        except Exception:
            db.session.rollback()

            eid=(
                _error_id()
                if '_error_id' in globals()
                else 'REPORT-ERROR'
            )

            app.logger.exception(
                'Web report workflow failed %s',
                eid
            )

            flash(
                f'Report action failed. Error ID: {eid}',
                'danger'
            )

        return redirect(
            url_for(
                'report_editor',
                order_id=order.id
            )
        )

    history=(
        ReportVersion.query
        .filter_by(report_id=report.id)
        .order_by(ReportVersion.version_no.desc())
        .all()
    )

    latest_version_no=(
        int(history[0].version_no)
        if history
        else 0
    )

    import uuid as _uuid

    web_commit_id=str(_uuid.uuid4())
    upload_commit_id=str(_uuid.uuid4())

    word_templates=DoctorWordTemplate.query.filter(
        DoctorWordTemplate.active.is_(True),
        or_(
            DoctorWordTemplate.owner_user_id==current_user().id,
            DoctorWordTemplate.visibility.in_(
                ['DEPARTMENT','SHARED']
            )
        ),
        or_(
            DoctorWordTemplate.modality=='',
            DoctorWordTemplate.modality==order.modality
        ),
        or_(
            DoctorWordTemplate.procedure_id.is_(None),
            DoctorWordTemplate.procedure_id==order.procedure_id
        )
    ).order_by(
        DoctorWordTemplate.created_at.desc()
    ).all()

    viewer=current_user()

    viewer_role=(
        viewer.role.code.upper()
        if viewer
        and viewer.role
        and viewer.role.code
        else ''
    )

    # Legacy FINAL->DRAFT reopen is intentionally disabled.
    # A future dedicated Addendum workflow must be used.
    can_admin_reopen=False

    return render_template(
        'report_editor.html',
        order=order,
        report=report,
        history=history,
        pacs_url=case_pacs_url(order),
        transitions=allowed_report_transitions(report),
        word_templates=word_templates,
        can_admin_reopen=can_admin_reopen,
        base_version_no=latest_version_no,
        web_commit_id=web_commit_id,
        upload_commit_id=upload_commit_id,
    )


@app.route('/reports/<int:order_id>/word')
@require_perm('reports.view')
def word_template(order_id):
    order=Order.query.get_or_404(order_id)
    report=get_report(order)

    authoritative = _rb_authoritative_docx_download(
        order,
        report,
    )

    if authoritative:
        return send_file(
            authoritative['path'],
            as_attachment=True,
            download_name=build_report_filename(
                order,
                authoritative['version_no'],
                authoritative['status'],
                'docx',
            ),
            mimetype=(
                'application/vnd.openxmlformats-officedocument.'
                'wordprocessingml.document'
            ),
        )

    version_no=_next_report_version(report)

    try:
        doc=Document()
        section=doc.sections[0]
        header=section.header
        table=header.add_table(rows=5,cols=4,width=Inches(7.0))
        table.style='Table Grid'

        p=order.patient
        proc_name=(order.proc.name if order.proc else order.procedure) or ''
        ref_name=(order.referring_doctor.name if getattr(order,'referring_doctor',None) else '')

        values=[
            ('Patient Name',p.name or '','Patient ID',p.patient_id or ''),
            ('DOB',str(p.dob or ''),'Sex',p.sex or ''),
            ('Accession',order.accession or '','Modality',order.modality or ''),
            ('Exam',proc_name,'Study Date',str(order.scheduled or '')),
            ('Referring Doctor',ref_name,'Report Status',report.status or 'DRAFT'),
        ]
        for r,row in enumerate(values):
            for c,val in enumerate(row):
                table.cell(r,c).text=str(val)

        doc.add_heading(proc_name or 'Radiology Report',level=1)
        doc.add_heading('Findings',level=2)
        doc.add_paragraph(report.findings or '')
        doc.add_heading('Impression',level=2)
        doc.add_paragraph(report.impression or '')
        if report.radiologist:
            doc.add_paragraph(f'Radiologist: {report.radiologist}')

        out=io.BytesIO()
        doc.save(out)
        out.seek(0)
        return send_file(
            out,as_attachment=True,
            download_name=build_report_filename(order,version_no,'DRAFT','docx'),
            mimetype='application/vnd.openxmlformats-officedocument.wordprocessingml.document'
        )
    except Exception as exc:
        eid=_error_id()
        app.logger.exception('Word generation failed %s',eid)
        flash(f'Word generation failed. Error ID: {eid}. You can still upload DOCX/ODT/PDF manually.','danger')
        return redirect(url_for('report_editor',order_id=order.id))




RADBRIDGE_REPORTING_TOKEN = os.getenv('RADBRIDGE_REPORTING_TOKEN', '').strip()
REPORTING_CASE_TOKEN_TTL_SECONDS = int(os.getenv('REPORTING_CASE_TOKEN_TTL_SECONDS', '28800') or 28800)


def _reporting_serializer():
    return URLSafeTimedSerializer(app.secret_key, salt='radbridge-reporting-case-v5442')


def reporting_case_token(accession):
    """Create a short-lived, accession-scoped token for the desktop reporting agent."""
    user = current_user()
    if not user or not user.active or not has_perm('reports.view'):
        return ''
    return _reporting_serializer().dumps({
        'accession': str(accession or ''),
        'user_id': user.id,
        'can_edit': bool(has_perm('reports.edit')),
    })


app.jinja_env.globals['reporting_case_token'] = reporting_case_token


def _valid_reporting_case_token(token, accession, write=False):
    if not token:
        return False
    try:
        data = _reporting_serializer().loads(
            token,
            max_age=max(60, REPORTING_CASE_TOKEN_TTL_SECONDS)
        )
    except (BadSignature, SignatureExpired, ValueError, TypeError):
        return False
    if str(data.get('accession') or '') != str(accession or ''):
        return False
    if write and not bool(data.get('can_edit')):
        return False
    return True



def reporting_actor(accession):
    user=current_user()

    if user and user.active:
        return user

    case_token=(
        request.headers.get('X-RadBridge-Case-Token')
        or ''
    ).strip()

    if not case_token:
        return None

    try:
        data=_reporting_serializer().loads(
            case_token,
            max_age=max(
                60,
                REPORTING_CASE_TOKEN_TTL_SECONDS
            )
        )
    except (
        BadSignature,
        SignatureExpired,
        ValueError,
        TypeError,
    ):
        return None

    if (
        str(data.get('accession') or '')
        != str(accession or '')
    ):
        return None

    user_id=data.get('user_id')

    if not user_id:
        return None

    user=db.session.get(User,int(user_id))

    if not user or not user.active:
        return None

    return user


def _reporting_api_authorized(accession, write=False):
    """Allow RIS session, accession-scoped agent token, or dedicated service token."""
    user = current_user()
    if user and user.active:
        return has_perm('reports.edit' if write else 'reports.view')

    case_token = (request.headers.get('X-RadBridge-Case-Token') or '').strip()
    if _valid_reporting_case_token(case_token, accession, write=write):
        return True

    supplied = (request.headers.get('X-RadBridge-Reporting-Token') or '').strip()
    return bool(
        RADBRIDGE_REPORTING_TOKEN
        and supplied
        and hmac.compare_digest(supplied, RADBRIDGE_REPORTING_TOKEN)
    )


def require_reporting_api(write=False):
    def deco(fn):
        @wraps(fn)
        def wrapped(*args, **kwargs):
            accession = kwargs.get('accession')
            if not _reporting_api_authorized(accession, write=write):
                status = 403 if current_user() else 401
                return jsonify({'ok': False, 'error': 'REPORTING_AUTH_REQUIRED'}), status
            return fn(*args, **kwargs)
        return wrapped
    return deco

