@app.post('/api/reporting/cases/<accession>/lease/acquire')
@require_reporting_api(write=True)
def api_reporting_lease_acquire(accession):
    import secrets

    order=Order.query.filter_by(
        accession=accession
    ).first_or_404()

    report=get_report(order)
    user=reporting_actor(accession)

    if not user:
        return jsonify({
            'ok': False,
            'error': 'REPORTING_ACTOR_REQUIRED'
        }), 403

    data=request.get_json(silent=True) or {}

    editor_type=str(
        data.get('editor_type') or 'WORD'
    ).strip().upper()

    supplied_token=str(
        data.get('lease_token') or
        request.headers.get('X-RadBridge-Report-Lease') or
        ''
    ).strip()

    lease_token=(
        supplied_token
        if supplied_token
        else secrets.token_urlsafe(32)
    )

    try:
        lease=acquire_or_renew_lease(
            db=db,
            order=order,
            report=report,
            user=user,
            editor_type=editor_type,
            lease_token=lease_token,
        )

        audit_as_user(user,
            'REPORT_EDIT_LEASE_ACQUIRED',
            'order',
            order.id,
            f'editor={editor_type}; user={user.id}'
        )

        db.session.commit()

        return jsonify({
            'ok': True,
            'lease_token': lease_token,
            'editor_type': lease.editor_type,
            'expires_at': lease.expires_at.isoformat(),
        })

    except ReportEditControlError as exc:
        db.session.rollback()

        code=getattr(
            exc,
            'code',
            type(exc).__name__
        )

        try:
            audit_as_user(user,
                'REPORT_EDIT_LEASE_DENIED',
                'order',
                order.id,
                f'editor={editor_type}; code={code}; user={user.id}'
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        return jsonify({
            'ok': False,
            'error': code,
        }), 409 if code in (
            'FINAL_REPORT_LOCKED',
            'REPORT_EDIT_LOCKED',
        ) else 403



