@app.route('/api/reporting/cases/<accession>/draft',methods=['POST'])
@require_reporting_api(write=True)
def api_reporting_draft(accession):
    import os

    from report_transaction_writer import (
        commit_report_version,
        TransactionalReportCommitError,
    )

    order=Order.query.filter_by(
        accession=accession
    ).first_or_404()

    report=get_report(order)
    user=reporting_actor(accession)

    if not user:
        return jsonify({
            'ok': False,
            'error': 'REPORTING_ACTOR_REQUIRED'
        }), 403

    try:
        assert_not_final(report)
        assert_role_allowed(user,'DRAFT')

        lease_token=str(
            request.form.get('lease_token') or
            request.headers.get('X-RadBridge-Report-Lease') or
            ''
        ).strip()

        assert_lease_owner(
            db=db,
            order=order,
            report=report,
            user=user,
            lease_token=lease_token,
        )

    except ReportEditControlError as exc:
        code=getattr(exc,'code',type(exc).__name__)

        try:
            audit(
                'REPORT_EDIT_DENIED',
                'order',
                order.id,
                f'action=DRAFT; editor=WORD_ADDIN; code={code}; user={user.id}'
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        return jsonify({
            'ok':False,
            'error':code,
        }), 409 if code in (
            'FINAL_REPORT_LOCKED',
            'REPORT_EDIT_LOCKED',
        ) else 403

    document=request.files.get('document')

    if 'base_version_no' not in request.form:
        return jsonify({
            'ok': False,
            'error': 'BASE_VERSION_REQUIRED'
        }), 400

    commit_id=str(
        request.form.get('commit_id')
        or ''
    ).strip()

    if not commit_id:
        return jsonify({
            'ok': False,
            'error': 'COMMIT_ID_REQUIRED'
        }), 400

    tmppath, validation, status_code = \
        _ohif_validate_word_upload(
            order,
            document,
            final=False
        )

    if not tmppath:
        return jsonify(validation), status_code

    owned_artifact=None

    try:
        findings, impression, radiologist = \
            extract_docx_sections(tmppath)

        radiologist=str(
            (
                radiologist
                if radiologist
                and radiologist != '____________________'
                else (
                    getattr(user,'full_name',None)
                    or getattr(user,'username',None)
                    or report.radiologist
                    or ''
                )
            )
        ).strip()

        result=commit_report_version(
            db=db,
            Report=Report,
            ReportVersion=ReportVersion,
            report_root=REPORT_DIR,
            order=order,
            patient=order.patient,
            user=user,
            editor_type='WORD',
            requested_status='DRAFT',
            source_file=tmppath,
            base_version_no=int(
                request.form['base_version_no']
            ),
            commit_id=commit_id,
            findings=findings or '',
            impression=impression or '',
            radiologist=radiologist,
            change_summary='Word Add-in Draft',
        )

        version=result.get('version')

        if (
            version is not None
            and not result.get('retry')
        ):
            owned_artifact=version.docx_path

        if user:
            audit_as_user(
                user,
                (
                    'REPORT_VERSION_RETRY'
                    if result.get('retry')
                    else 'REPORT_VERSION_COMMITTED'
                ),
                'order',
                order.id,
                (
                    f'version={version.version_no}; '
                    'status=DRAFT; '
                    'editor=WORD; '
                    f'commit_id={commit_id}'
                )
            )

        db.session.commit()

        return jsonify({
            'ok': True,
            'status': 'DRAFT',
            'version_no': (
                version.version_no
                if version is not None
                else None
            ),
            'editor_type': 'WORD',
            'retry': bool(result.get('retry')),
        })

    except TransactionalReportCommitError as exc:
        db.session.rollback()

        if owned_artifact:
            try:
                os.unlink(owned_artifact)
            except FileNotFoundError:
                pass

        return jsonify({
            'ok': False,
            'error': getattr(
                exc,
                'code',
                type(exc).__name__
            ),
            'message': str(exc)
        }), 409

    except Exception as exc:
        db.session.rollback()

        if owned_artifact:
            try:
                os.unlink(owned_artifact)
            except FileNotFoundError:
                pass

        return jsonify({
            'ok': False,
            'error': type(exc).__name__,
            'message': str(exc)
        }), 400

    finally:
        if tmppath:
            try:
                os.unlink(tmppath)
            except FileNotFoundError:
                pass

            try:
                os.rmdir(
                    os.path.dirname(tmppath)
                )
            except OSError:
                pass

@app.post('/api/reporting/cases/<accession>/verify')
@require_reporting_api(write=True)
def api_reporting_verify(accession):
    order=Order.query.filter_by(
        accession=accession
    ).first_or_404()

    report=get_report(order)
    user=reporting_actor(accession)

    if not user:
        return jsonify({
            'ok': False,
            'error': 'REPORTING_ACTOR_REQUIRED'
        }), 403

    try:
        assert_not_final(report)
        assert_role_allowed(user,'VERIFY')
        assert_no_foreign_active_lease(
            db=db,
            order_id=order.id,
            user=user,
        )

    except ReportEditControlError as exc:
        code=getattr(exc,'code',type(exc).__name__)

        try:
            audit(
                'REPORT_EDIT_DENIED',
                'order',
                order.id,
                f'action=VERIFY; editor=WORD_ADDIN; code={code}; user={user.id}'
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        return jsonify({
            'ok':False,
            'error':code,
        }), 409 if code in {'FINAL_REPORT_LOCKED','REPORT_EDIT_LOCKED'} else 403

    report=get_report(order)

    if (
        (report.status or '').upper() == 'FINAL'
    ):
        return jsonify({
            'ok': False,
            'error': 'FINAL_REPORT_LOCKED'
        }), 409

    if 'base_version_no' not in request.form:
        return jsonify({
            'ok': False,
            'error': 'BASE_VERSION_REQUIRED'
        }), 400

    latest=_rb_latest_report_version(report)

    if latest is None:
        return jsonify({
            'ok': False,
            'error': 'NO_REPORT_VERSION'
        }), 409

    if str(latest.editor_type or '').upper() != 'WORD':
        return jsonify({
            'ok': False,
            'error': 'LATEST_VERSION_NOT_WORD',
            'version_no': latest.version_no,
            'editor_type': latest.editor_type
        }), 409

    if (latest.status or '').upper() != 'DRAFT':
        return jsonify({
            'ok': False,
            'error': 'REPORT_VERIFY_CONFLICT',
            'message': 'VERSION_ALREADY_VERIFIED'
        }), 409

    demographic_ok, demographic_reason = \
        pacs_demographic_gate(order)

    if not demographic_ok:
        return jsonify({
            'ok': False,
            'error': 'PACS_DEMOGRAPHIC_REVIEW_REQUIRED',
            'reason': demographic_reason
        }), 409

    try:
        from report_commit_core import (
            validate_base_version,
        )

        from onlyoffice_report_bridge import (
            onlyoffice_verify_latest,
        )

        validate_base_version(
            current_version_no=int(latest.version_no),
            base_version_no=int(
                request.form['base_version_no']
            ),
        )

        before_count=(
            ReportVersion.query
            .filter_by(report_id=report.id)
            .count()
        )

        before_id=latest.id
        before_sha=latest.sha256
        before_path=latest.docx_path

        version=onlyoffice_verify_latest(
            db=db,
            Report=Report,
            ReportVersion=ReportVersion,
            order=order,
            user=user,
        )

        after_count=(
            ReportVersion.query
            .filter_by(report_id=report.id)
            .count()
        )

        if after_count != before_count:
            db.session.rollback()
            raise RuntimeError(
                'VERIFY_CREATED_EXTRA_VERSION'
            )

        if version.id != before_id:
            db.session.rollback()
            raise RuntimeError(
                'VERIFY_CHANGED_VERSION_ID'
            )

        if version.sha256 != before_sha:
            db.session.rollback()
            raise RuntimeError(
                'VERIFY_CHANGED_CONTENT_SHA'
            )

        if version.docx_path != before_path:
            db.session.rollback()
            raise RuntimeError(
                'VERIFY_CHANGED_DOCUMENT_PATH'
            )

        if user:
            audit_as_user(
                user,
                'REPORT_VERIFIED',
                'order',
                order.id,
                (
                    f'version={version.version_no}; '
                    'editor=WORD_ADDIN; '
                    'content_immutable=YES'
                )
            )

        db.session.commit()

        return jsonify({
            'ok': True,
            'status': 'VERIFIED',
            'version_no': version.version_no,
            'editor_type': 'WORD',
            'authoritative': True
        })

    except Exception as exc:
        db.session.rollback()

        code=getattr(
            exc,
            'code',
            type(exc).__name__
        )

        conflict_codes={
            'REPORT_VERSION_CONFLICT',
            'REPORT_VERIFY_CONFLICT',
            'VERSION_ALREADY_VERIFIED',
        }

        return jsonify({
            'ok': False,
            'error': code,
            'message': str(exc)
        }), (409 if code in conflict_codes else 400)


