def get_user_profile(user=None):
    user=user or current_user()
    if not user:return None
    row=UserProfile.query.filter_by(user_id=user.id).first()
    if not row:
        row=UserProfile(user_id=user.id,department=(user.role.name if user.role else ''))
        db.session.add(row);db.session.flush()
    return row


def user_profile_settings(profile):
    try:
        data=json.loads(profile.settings_json or '{}')
        return data if isinstance(data,dict) else {}
    except Exception:
        return {}


def user_reporting_preferences(profile):
    settings=user_profile_settings(profile)
    reporting=settings.get('reporting') or {}

    editor=str(
        reporting.get('preferred_editor') or 'ONLYOFFICE'
    ).upper()

    layout=str(
        reporting.get('preferred_layout') or '50_50'
    ).upper()

    allowed_editors={
        'ONLYOFFICE',
        'BROWSER',
        'WORD',
        'LIBREOFFICE',
        'ASK'
    }

    allowed_layouts={
        '50_50',
        '70_30',
        '30_70',
        'FULL_EDITOR',
        'FULL_VIEWER',
        'DUAL_MONITOR'
    }

    if editor not in allowed_editors:
        editor='ONLYOFFICE'

    if layout not in allowed_layouts:
        layout='50_50'

    return {
        'preferred_editor':editor,
        'preferred_layout':layout
    }


def set_user_reporting_preferences(
    profile,
    preferred_editor,
    preferred_layout
):
    settings=user_profile_settings(profile)

    reporting=settings.get('reporting')

    if not isinstance(reporting,dict):
        reporting={}

    editor=str(
        preferred_editor or 'ONLYOFFICE'
    ).upper()

    layout=str(
        preferred_layout or '50_50'
    ).upper()

    allowed_editors={
        'ONLYOFFICE',
        'BROWSER',
        'WORD',
        'LIBREOFFICE',
        'ASK'
    }

    allowed_layouts={
        '50_50',
        '70_30',
        '30_70',
        'FULL_EDITOR',
        'FULL_VIEWER',
        'DUAL_MONITOR'
    }

    if editor not in allowed_editors:
        editor='ONLYOFFICE'

    if layout not in allowed_layouts:
        layout='50_50'

    reporting['preferred_editor']=editor
    reporting['preferred_layout']=layout

    settings['reporting']=reporting

    profile.settings_json=json.dumps(
        settings,
        separators=(',',':')
    )

    return {
        'preferred_editor':editor,
        'preferred_layout':layout
    }


def dictionary_label(key,lang='en',fallback=''):
    row=DictionaryEntry.query.filter_by(key=key,active=True).first()
    if not row:return fallback or key
    return row.label_ar if lang=='ar' and row.label_ar else row.label_en or fallback or key

def seed_dictionary_and_ribbon():
    for key,module,en,ar in DEFAULT_DICTIONARY:
        if not DictionaryEntry.query.filter_by(key=key).first():
            db.session.add(DictionaryEntry(key=key,module=module,label_en=en,label_ar=ar,active=True))
    for key,en,ar,icon,route,perm,ctx,order_no in DEFAULT_RIBBON_ACTIONS:
        if not RibbonAction.query.filter_by(action_key=key).first():
            db.session.add(RibbonAction(action_key=key,label_en=en,label_ar=ar,icon=icon,route_name=route,required_permission=perm,context=ctx,order_no=order_no,active=True))
    db.session.commit()

def booking_control_reason(branch,procedure,device,start_at,end_at):
    rows=BookingBlock.query.filter_by(active=True).filter(
        BookingBlock.start_at < end_at,
        BookingBlock.end_at > start_at
    ).all()
    for b in rows:
        # Staff availability belongs to assignment/worklist scheduling.
        # It must never block creation of the patient's appointment.
        if (b.block_type or '').upper() in ('DOCTOR','TECHNICIAN'):
            continue
        if b.branch_id and b.branch_id!=branch.id:continue
        if b.device_id and b.device_id!=device.id:continue
        if b.procedure_id and b.procedure_id!=procedure.id:continue
        return b.reason_text or b.reason_code
    return ''


def validate_booking_block_scope(
    *,block_type,branch_id=None,device_id=None,procedure_id=None,
    user_id=None,start_at=None,end_at=None
):
    block_type=str(block_type or 'OTHER').strip().upper()
    allowed={'DEVICE','PROCEDURE','BRANCH','DOCTOR','TECHNICIAN','OTHER'}
    if block_type not in allowed:
        return 'Invalid booking block type.'
    if not start_at or not end_at:
        return 'Start and end date/time are required.'
    if end_at<=start_at:
        return 'End date/time must be after start date/time.'
    required={
        'DEVICE':(device_id,'Select a device for a device block.'),
        'PROCEDURE':(procedure_id,'Select a procedure for a procedure block.'),
        'BRANCH':(branch_id,'Select a branch for a branch block.'),
        'DOCTOR':(user_id,'Select a doctor for a doctor availability block.'),
        'TECHNICIAN':(user_id,'Select a technician for a technician availability block.'),
    }
    value_and_message=required.get(block_type)
    if value_and_message and not value_and_message[0]:
        return value_and_message[1]
    if block_type=='OTHER' and not any(
        (branch_id,device_id,procedure_id,user_id)
    ):
        return 'Select at least one scope for an Other block.'
    return ''


def acquire_booking_slot_lock(device_id,start_at):
    """Serialize booking checks for one device/day on PostgreSQL.

    The lock lives only for the current transaction. The second concurrent
    request waits, then repeats the overlap check after the first commits.
    SQLite test runs intentionally use a no-op because they are single-process
    contract tests and do not support PostgreSQL advisory locks.
    """
    if not device_id or not start_at:
        return
    bind=db.session.get_bind()
    if bind.dialect.name!='postgresql':
        return
    lock_name=f'radbridge-booking:{int(device_id)}:{start_at:%Y-%m-%d}'
    db.session.execute(
        text('SELECT pg_advisory_xact_lock(hashtextextended(:name,0))'),
        {'name':lock_name},
    )


