def unread_chat_count(user=None):
    user=user or current_user()
    if not user:return 0
    total=0
    for m in ChatThreadMember.query.filter_by(user_id=user.id,muted=False).all():
        q=ChatMessage.query.filter_by(thread_id=m.thread_id).filter(ChatMessage.sender_id!=user.id,ChatMessage.deleted_at.is_(None))
        if m.last_read_at:q=q.filter(ChatMessage.created_at>m.last_read_at)
        total+=q.count()
    return total

def smart_booking_cards(day,branch_id=None):
    q=Device.query.filter_by(active=True)
    if branch_id:q=q.filter_by(branch_id=branch_id)
    start=datetime.combine(day,datetime.min.time());end=start+timedelta(days=1);out=[]
    for d in q.order_by(Device.modality,Device.name).all():
        appts=Appointment.query.filter(Appointment.device_id==d.id,Appointment.scheduled>=start,Appointment.scheduled<end).order_by(Appointment.scheduled).all()
        blocks=BookingBlock.query.filter(BookingBlock.active.is_(True),BookingBlock.start_at<end,BookingBlock.end_at>start).filter(or_(BookingBlock.device_id==d.id,and_(BookingBlock.device_id.is_(None),BookingBlock.branch_id==d.branch_id))).order_by(BookingBlock.start_at).all()
        out.append({'device':d,'appointments':appts,'blocks':blocks})
    return out


