def normalize_phone(v):
    x=re.sub(r'\D','',v or '')
    if x.startswith('0020'): x=x[2:]
    if x.startswith('20') and len(x)>10: x='0'+x[2:]
    return x

def patient_by_phone(number):
    n=normalize_phone(number)
    if not n: return None
    for p in Patient.query.filter(Patient.phone.isnot(None)).all():
        if normalize_phone(p.phone)==n:
            return p
    return None

def document_timeline(patient):
    events=[]
    for o in Order.query.filter_by(patient_id=patient.id).order_by(Order.id.desc()).all():
        dt=getattr(o,'scheduled',None) or getattr(o,'created_at',None)
        events.append({'kind':'EXAM','date':dt,'title':getattr(o,'procedure','Examination'),'order':o})
    for d in PatientDocument.query.filter_by(patient_id=patient.id).order_by(PatientDocument.created_at.desc()).all():
        label=DOCUMENT_TYPES.get(d.document_type,(d.document_type,d.document_type,'OTHER'))
        events.append({'kind':'DOCUMENT','date':d.created_at,'title':label[1] if current_ui_language()=='ar' else label[0],'document':d})
    events.sort(key=lambda x:x['date'] or datetime.min,reverse=True)
    return events

def extract_document_text_basic(path):
    # Safe local baseline. PDF/image OCR engine can be configured later.
    ext=os.path.splitext(path)[1].lower()
    if ext=='.txt':
        try:
            return open(path,'r',encoding='utf-8',errors='ignore').read()[:100000],'DONE'
        except Exception:
            return '','FAILED'
    return '','OCR_REQUIRED'

def build_document_matches(doc):
    DocumentMatch.query.filter_by(document_id=doc.id).delete()
    text=(doc.extracted_text or '').lower()
    p=doc.patient
    candidates=[
      ('patient_name',p.name or ''),
      ('national_id',getattr(p,'national_id','') or ''),
      ('phone',p.phone or '')
    ]
    if doc.order:
        candidates.append(('examination',getattr(doc.order,'procedure','') or ''))
    for field,value in candidates:
        if not value: continue
        hit=str(value).lower() in text if text else False
        db.session.add(DocumentMatch(document_id=doc.id,field_name=field,extracted_value=(value if hit else ''),ris_value=str(value),confidence=(1.0 if hit else 0.0),match_status=('MATCH' if hit else 'REVIEW')))



