def _collect_patient_file_paths():
    paths=[]
    try:
        for a in Attachment.query.all():
            for attr in ('stored_path','path','file_path'):
                p=getattr(a,attr,None)
                if p and os.path.isfile(p): paths.append(('attachment',p))
    except Exception:
        pass
    try:
        for r in Report.query.all():
            for attr in ('docx_path','pdf_path','source_path','file_path'):
                p=getattr(r,attr,None)
                if p and os.path.isfile(p): paths.append(('report',p))
    except Exception:
        pass
    # stable unique order
    seen=set();out=[]
    for kind,p in paths:
        ap=os.path.abspath(p)
        if ap not in seen:
            seen.add(ap);out.append((kind,ap))
    return out

def create_all_patient_backup():
    stamp=datetime.utcnow().strftime('%Y%m%d-%H%M%S')
    path=os.path.join(admin_backup_dir(),f'all-patients-{stamp}.zip')
    patient_fields=['id','patient_id','name','dob','sex','phone','national_id','address','email','created_at']
    order_fields=['id','accession','patient_id','modality','procedure','scheduled','status','branch_id','contract_id','gross_price','contract_price','patient_share','company_share','paid_amount','created_at']
    with zipfile.ZipFile(path,'w',zipfile.ZIP_DEFLATED,allowZip64=True) as z:
        out=io.StringIO();w=csv.writer(out);w.writerow(patient_fields)
        for p in Patient.query.order_by(Patient.id).yield_per(500):
            w.writerow([getattr(p,f,None) for f in patient_fields])
        z.writestr('patients.csv',out.getvalue())

        out=io.StringIO();w=csv.writer(out);w.writerow(order_fields)
        for o in Order.query.order_by(Order.id).yield_per(500):
            w.writerow([getattr(o,f,None) for f in order_fields])
        z.writestr('orders.csv',out.getvalue())

        manifest={
            'created_at':datetime.utcnow().isoformat()+'Z',
            'patients':Patient.query.count(),
            'orders':Order.query.count(),
            'attachments':Attachment.query.count() if 'Attachment' in globals() else 0,
            'reports':Report.query.count() if 'Report' in globals() else 0,
            'version':APP_VERSION
        }
        z.writestr('manifest.json',json.dumps(manifest,ensure_ascii=False,indent=2))

        for kind,p in _collect_patient_file_paths():
            try:
                z.write(p,f'{kind}s/{safe_export_name(os.path.basename(p))}')
            except Exception:
                pass

    digest=hashlib.sha256()
    with open(path,'rb') as f:
        for chunk in iter(lambda:f.read(1024*1024),b''):
            digest.update(chunk)
    with open(path+'.sha256','w',encoding='utf-8') as f:
        f.write(digest.hexdigest()+'  '+os.path.basename(path)+'\n')
    return path,digest.hexdigest()

def quarantine_patient_files():
    stamp=datetime.utcnow().strftime('%Y%m%d-%H%M%S')
    root=os.path.join(os.getenv('RIS_QUARANTINE_DIR') or '/app/quarantine',f'patient-reset-{stamp}')
    os.makedirs(root,exist_ok=True)
    moved=0
    for kind,p in _collect_patient_file_paths():
        try:
            rel=safe_export_name(os.path.basename(p))
            target=os.path.join(root,kind+'s',rel)
            os.makedirs(os.path.dirname(target),exist_ok=True)
            # avoid collision
            if os.path.exists(target):
                stem,ext=os.path.splitext(target);target=stem+'-'+hashlib.sha1(p.encode()).hexdigest()[:8]+ext
            shutil.move(p,target);moved+=1
        except Exception:
            pass
    return root,moved

def operational_patient_table_order():
    # Discover tables that depend (directly or transitively) on patient/order/appointment.
    meta=db.metadata
    roots={'patient','order','appointment'}
    deps={}
    for name,table in meta.tables.items():
        parents=set()
        for fk in table.foreign_keys:
            parents.add(fk.column.table.name)
        deps[name]=parents

    affected=set(roots)
    changed=True
    while changed:
        changed=False
        for child,parents in deps.items():
            if child=='audit_log':
                continue
            if child not in affected and parents & affected:
                affected.add(child);changed=True

    # Explicitly never delete configuration/security/audit master data.
    protected={'audit_log','user','role','permission','branch','procedure','device','contract',
               'referring_doctor','warehouse','inventory_item','warehouse_stock_policy',
               'procedure_consumable_default','studio_shortcut','printer_profile','registration_default'}
    affected-=protected

    depth={}
    def calc(name,stack=None):
        if name in depth:return depth[name]
        stack=stack or set()
        if name in stack:return 0
        stack=stack|{name}
        ps=[p for p in deps.get(name,set()) if p in affected]
        depth[name]=0 if not ps else max(calc(p,stack)+1 for p in ps)
        return depth[name]
    for name in affected:calc(name)
    return sorted(affected,key=lambda n:depth.get(n,0),reverse=True)

def delete_all_patient_operational_data():
    tables=operational_patient_table_order()
    counts={}
    # Files are quarantined first, never permanently purged by this operation.
    quarantine,moved=quarantine_patient_files()
    for name in tables:
        table=db.metadata.tables.get(name)
        if table is None:continue
        try:
            result=db.session.execute(table.delete())
            counts[name]=getattr(result,'rowcount',None)
        except Exception:
            db.session.rollback()
            raise
    db.session.commit()
    return {'tables':tables,'counts':counts,'quarantine':quarantine,'files_moved':moved}

def admin_storage_paths():
    candidates={
        'Reports':os.getenv('REPORTS_DIR') or os.getenv('REPORT_DIR') or '/app/reports',
        'Attachments':os.getenv('ATTACHMENTS_DIR') or os.getenv('ATTACHMENT_DIR') or '/app/attachments',
        'Uploads':os.getenv('UPLOAD_DIR') or '/app/uploads',
        'Word / Generated Documents':os.getenv('WORD_REPORTS_DIR') or os.getenv('WORD_DIR') or '/app/reports',
        'OCR':os.getenv('OCR_DIR') or '/app/uploads',
        'Backups':os.getenv('RIS_BACKUP_DIR') or os.getenv('BACKUP_DIR') or '/app/backups',
    }
    rows=[]
    for label,path in candidates.items():
        path=os.path.abspath(path)
        exists=os.path.exists(path)
        writable=os.access(path,os.W_OK) if exists else os.access(os.path.dirname(path) or '/',os.W_OK)
        size=0
        if exists:
            try:
                for root,dirs,files in os.walk(path):
                    for f in files:
                        try:size+=os.path.getsize(os.path.join(root,f))
                        except OSError:pass
            except Exception:pass
        rows.append({'label':label,'path':path,'exists':exists,'writable':writable,'size':size})
    return rows

