def related_prior_orders(order,limit=20):
    q=Order.query.filter(Order.patient_id==order.patient_id,Order.id!=order.id)
    if order.modality:
        q=q.filter(Order.modality==order.modality)
    return q.order_by(Order.scheduled.desc(),Order.id.desc()).limit(limit).all()

