def communication_setting(channel):
    return CommunicationChannelSetting.query.filter_by(channel=channel.upper()).first()

def send_patient_communication(row):
    cfg=communication_setting(row.channel)
    if not cfg or not cfg.enabled:
        row.status='FAILED'; row.error_text='Channel disabled'; db.session.commit()
        return False,'Channel disabled'
    try:
        if row.channel=='EMAIL':
            import smtplib
            from email.message import EmailMessage
            secret=os.environ.get(cfg.secret_env_name or 'RIS_SMTP_PASSWORD','')
            msg=EmailMessage()
            msg['Subject']=row.subject or 'RIS Notification'
            msg['From']=cfg.sender or cfg.smtp_user
            msg['To']=row.recipient
            msg.set_content(row.body or '')
            with smtplib.SMTP(cfg.smtp_host,int(cfg.smtp_port or 587),timeout=30) as server:
                if cfg.smtp_tls: server.starttls()
                if cfg.smtp_user: server.login(cfg.smtp_user,secret)
                server.send_message(msg)
            row.status='SENT'; row.sent_at=datetime.utcnow(); row.error_text=''
            db.session.commit(); return True,''
        elif row.channel=='TELEGRAM':
            import requests
            token=os.environ.get(cfg.secret_env_name or 'RIS_TELEGRAM_BOT_TOKEN','')
            if not token: raise RuntimeError('Telegram token missing')
            r=requests.post(
                f'https://api.telegram.org/bot{token}/sendMessage',
                json={'chat_id':row.recipient,'text':row.body},
                timeout=30
            )
            r.raise_for_status()
            data=r.json()
            row.provider_message_id=str((data.get('result') or {}).get('message_id',''))
            row.status='SENT'; row.sent_at=datetime.utcnow(); row.error_text=''
            db.session.commit(); return True,''
        elif row.channel=='WHATSAPP':
            import requests
            token=os.environ.get(cfg.secret_env_name or 'RIS_WHATSAPP_TOKEN','')
            if not cfg.base_url: raise RuntimeError('WhatsApp API URL missing')
            headers={'Content-Type':'application/json'}
            if token: headers['Authorization']='Bearer '+token
            payload={'to':row.recipient,'message':row.body,'sender':cfg.sender}
            r=requests.post(cfg.base_url,json=payload,headers=headers,timeout=30)
            r.raise_for_status()
            try:
                data=r.json()
                row.provider_message_id=str(data.get('id') or data.get('message_id') or '')
            except Exception:
                pass
            row.status='SENT'; row.sent_at=datetime.utcnow(); row.error_text=''
            db.session.commit(); return True,''
        else:
            raise RuntimeError('Unsupported channel')
    except Exception as e:
        row.status='FAILED'; row.error_text=str(e)[:1000]; db.session.commit()
        return False,row.error_text



def imaging_ai_provider_for_modality(modality):
    modality=(modality or '').upper()
    rows=ImagingAIProvider.query.filter_by(enabled=True).order_by(ImagingAIProvider.id).all()
    for row in rows:
        allowed=[x.strip().upper() for x in (row.modalities or '').split(',') if x.strip()]
        if not allowed or modality in allowed:
            return row
    return None


def pacs_study_lookup(order):
    """Return only the study explicitly linked to the RIS order."""
    study_id=str(order.pacs_study_id or '').strip()
    expected_uid=str(order.study_instance_uid or '').strip()
    if not study_id:
        return None,'Order has no authoritative PACS study link'
    try:
        base=(app.config.get('ORTHANC_URL') or os.environ.get('ORTHANC_URL') or '').rstrip('/')
        if not base:
            return None,'PACS URL is not configured'
        import requests
        user=os.environ.get('ORTHANC_USER','');pwd=os.environ.get('ORTHANC_PASSWORD','')
        auth=(user,pwd) if user else None
        response=requests.get(base+'/studies/'+study_id,auth=auth,timeout=30)
        response.raise_for_status();st=response.json()
        tags=st.get('MainDicomTags') or {};pt=st.get('PatientMainDicomTags') or {}
        actual_uid=str(tags.get('StudyInstanceUID') or '').strip()
        if expected_uid and actual_uid != expected_uid:
            return None,'Authoritative PACS StudyInstanceUID mismatch'
        return {
          'orthanc_study_id':st.get('ID',study_id),'study_instance_uid':actual_uid,
          'accession':tags.get('AccessionNumber',''),'study_date':tags.get('StudyDate',''),
          'study_description':tags.get('StudyDescription',''),
          'modality':tags.get('ModalitiesInStudy') or tags.get('Modality',''),
          'patient_name':pt.get('PatientName',''),'patient_id':pt.get('PatientID',''),
          'patient_birth_date':pt.get('PatientBirthDate',''),'patient_sex':pt.get('PatientSex',''),
        },''
    except Exception as exc:
        return None,'PACS lookup failed: %s' % str(exc)


def normalize_person_name(v):
    return re.sub(r'\s+',' ',str(v or '').replace('^',' ').strip().lower())

def normalize_date(v):
    return re.sub(r'\D','',str(v or ''))[:8]

def demographic_verification(order,pacs_meta):
    checks=[]
    score=0.0
    weight_total=0.0

    def add(name,risv,dicomv,weight,normalizer=lambda x:str(x or '').strip()):
        nonlocal score,weight_total
        a=normalizer(risv); b=normalizer(dicomv)
        if not a or not b:
            checks.append({'field':name,'ris':str(risv or ''),'dicom':str(dicomv or ''),'status':'MISSING'})
            return
        weight_total+=weight
        ok=(a==b)
        if ok: score+=weight
        checks.append({'field':name,'ris':str(risv or ''),'dicom':str(dicomv or ''),'status':'MATCH' if ok else 'MISMATCH'})

    add('Patient ID',order.patient.patient_id,pacs_meta.get('patient_id'),0.40,lambda x:str(x or '').strip())
    add('Patient Name',order.patient.name,pacs_meta.get('patient_name'),0.20,normalize_person_name)
    add('DOB',getattr(order.patient,'dob',''),pacs_meta.get('patient_birth_date'),0.20,normalize_date)
    add('Sex',getattr(order.patient,'sex',''),pacs_meta.get('patient_sex'),0.05,lambda x:str(x or '').strip().upper())
    add('Accession',order.accession,pacs_meta.get('accession'),0.15,lambda x:str(x or '').strip().upper())

    pct=(score/weight_total) if weight_total else 0.0
    hard_mismatch=any(x['field'] in ('Patient ID','DOB','Accession') and x['status']=='MISMATCH' for x in checks)
    if hard_mismatch:
        status='BLOCKED'
    elif pct>=0.90:
        status='VERIFIED'
    elif pct>=0.65:
        status='REVIEW_REQUIRED'
    else:
        status='BLOCKED'
    return {'status':status,'score':pct,'checks':checks}

def build_imaging_ai_request(order,pacs_meta,analysis):
    return {
      'request_type':'RADIOLOGY_IMAGE_ANALYSIS',
      'study':{
        'orthanc_study_id':pacs_meta.get('orthanc_study_id'),
        'study_instance_uid':pacs_meta.get('study_instance_uid'),
        'accession':order.accession,
        'modality':order.modality,
        'procedure':order.procedure
      },
      'patient_context':{
        'age_or_dob':str(order.patient.dob or ''),
        'sex':order.patient.sex or '',
      },
      'constraints':{
        'draft_only':True,
        'no_final_diagnosis':True,
        'return_structured_findings':True,
        'include_uncertainty':True
      }
    }

def call_imaging_ai(order,pacs_meta,analysis):
    provider=imaging_ai_provider_for_modality(order.modality)
    if not provider:
        return None,'No Imaging AI provider enabled for modality'
    token=os.environ.get(provider.secret_env_name or 'RIS_IMAGING_AI_TOKEN','')
    headers={'Content-Type':'application/json'}
    if token: headers['Authorization']='Bearer '+token
    payload=build_imaging_ai_request(order,pacs_meta,analysis)
    try:
        import requests
        r=requests.post(provider.base_url.rstrip('/')+'/analyze-study',
            json={'model':provider.model_name,'input':payload},
            headers=headers,timeout=max(30,int(provider.timeout_seconds or 180)))
        r.raise_for_status()
        data=r.json()
        return {
          'structured_findings':data.get('structured_findings') or {},
          'summary':str(data.get('summary') or ''),
          'uncertainty':str(data.get('uncertainty') or ''),
          'raw':data
        },''
    except Exception as e:
        return None,str(e)[:1000]

def latest_verified_imaging_analysis(order):
    return ImagingAIAnalysis.query.filter_by(order_id=order.id,demographic_status='VERIFIED',status='AI_FINDINGS_READY').order_by(ImagingAIAnalysis.completed_at.desc()).first()

def ai_case_context(order):
    # Extend v5.22 context with verified image-derived findings only.
    notes=ClinicalNote.query.filter_by(order_id=order.id).order_by(ClinicalNote.created_at).all()
    imaging=latest_verified_imaging_analysis(order)
    ctx={
      'patient':{'name':order.patient.name,'patient_id':order.patient.patient_id,
                 'dob':str(order.patient.dob or ''),'sex':order.patient.sex or ''},
      'study':{'accession':order.accession,'modality':order.modality,'procedure':order.procedure,
               'scheduled':str(order.scheduled or ''),'priority':order.priority or ''},
      'clinical_notes':[{'type':n.note_type,'text':n.text} for n in notes],
      'selected_priors':selected_prior_context(order)
    }
    if imaging:
        ctx['verified_image_ai']={
          'provider':imaging.provider_key,
          'model':imaging.model_name,
          'structured_findings':json.loads(imaging.structured_findings_json or '{}'),
          'summary':imaging.summary_text,
          'uncertainty':imaging.uncertainty_text
        }
    return ctx



