def doctor_availability(user):
    row=DoctorAvailabilityState.query.filter_by(user_id=user.id).first()
    if not row:
        row=DoctorAvailabilityState(user_id=user.id,state='AVAILABLE',last_seen_at=datetime.utcnow())
        db.session.add(row);db.session.flush()
    if row.busy_until and row.busy_until<=datetime.utcnow() and row.state=='BUSY':
        row.state='AVAILABLE';row.busy_until=None
    return row

def doctor_is_online(user,minutes=5):
    st=doctor_availability(user)
    return bool(st.last_seen_at and st.last_seen_at >= datetime.utcnow()-timedelta(minutes=minutes) and st.state!='OFFLINE')

def assignment_timeout_for(order,policy):
    p=(order.priority or 'ROUTINE').upper()
    if p=='STAT': return max(30,int(policy.stat_timeout_seconds or 60))
    if p=='URGENT': return max(30,int(policy.urgent_timeout_seconds or 120))
    return max(30,int(policy.routine_timeout_seconds or 300))

def assignment_candidate_users(order,policy):
    q=User.query.join(Role).filter(User.active.is_(True))
    external_intake=ExternalIntakeCase.query.filter_by(order_id=order.id).first()
    external_doctor_ids=None
    if external_intake:
        # Fail closed: external work is assignable only after the explicit
        # queue decision and only to this center's active doctor pool.
        if external_intake.status!='QUEUED' or not external_intake.center.assignment_enabled:
            return []
        external_doctor_ids={
            row.doctor_user_id
            for row in ExternalCenterDoctor.query.filter_by(
                center_id=external_intake.center_id,
                active=True
            ).all()
        }
        if not external_doctor_ids:
            return []
    candidates=[]
    for u in q.all():
        role_code=(u.role.code if u.role else '').upper()
        if role_code not in ('RADIOLOGIST','DOCTOR'):
            continue
        if external_doctor_ids is not None and u.id not in external_doctor_ids:
            continue
        prof=DoctorAssignmentProfile.query.filter_by(user_id=u.id).first()
        if prof:
            if not prof.available or not prof.auto_assign:
                continue
            mods=[x.strip().upper() for x in (prof.modalities or '').split(',') if x.strip()]
            if mods and str(order.modality or '').upper() not in mods:
                continue
            branches=[x.strip() for x in (prof.branches or '').split(',') if x.strip()]
            if branches and str(order.branch_id) not in branches:
                continue
        state=doctor_availability(u)
        if state.state in ('BUSY','AWAY','OFFLINE'):
            if policy.mode=='ALL' and state.state!='BUSY':
                pass
            else:
                continue
        online=doctor_is_online(u)
        if policy.mode=='ONLINE_ONLY' and not online:
            continue
        active_cases=CaseAssignment.query.filter_by(doctor_user_id=u.id,active=True).count()
        max_cases=(prof.max_active_cases if prof else 20) or 20
        if active_cases>=max_cases:
            continue
        weight=(prof.priority_weight if prof else 100) or 100
        candidates.append((u,online,active_cases,weight))
    # online first, then lowest load, then highest priority weight
    candidates.sort(key=lambda x:(0 if x[1] else 1,x[2],-x[3],x[0].id))
    return [x[0] for x in candidates]

def assignment_offer_channels(policy):
    return [x.strip().upper() for x in (policy.notification_channels or '').split(',') if x.strip()]

def create_assignment_offer(order,doctor,attempt_no=1,created_by=None,strategy=None):
    policy=assignment_offer_policy()
    if not policy:
        return None

    timeout=assignment_strategy_timeout(
        order,
        strategy,
        policy
    )
    row=AssignmentOffer(
        order_id=order.id,doctor_user_id=doctor.id,attempt_no=attempt_no,
        status='PENDING',offered_at=datetime.utcnow(),
        expires_at=datetime.utcnow()+timedelta(seconds=timeout),
        created_by=created_by
    )
    db.session.add(row);db.session.flush()
    channels=[]
    # In-app is implicit. External channels use existing Communication Hub.
    for ch in assignment_offer_channels(policy):
        if ch=='INAPP':
            channels.append('INAPP')
            continue
        try:
            patient=order.patient
            recipient=''
            if ch=='EMAIL':
                recipient=getattr(doctor,'email','') or ''
            elif ch in ('WHATSAPP','TELEGRAM'):
                recipient=getattr(doctor,'phone','') or ''
            if not recipient:
                continue
            body=(
              f'RIS case offer: {order.accession} | {order.modality} | {order.procedure} | '
              f'Priority: {order.priority}. Please open RIS to Accept / Busy / Reject before {row.expires_at}.'
            )
            msg=PatientCommunication(
              patient_id=patient.id,order_id=order.id,channel=ch,recipient=recipient,
              template_code='ASSIGNMENT_OFFER',subject='RIS Case Assignment Offer',
              body=body,status='PENDING',created_by=created_by
            )
            db.session.add(msg);db.session.flush()
            ok,_=send_patient_communication(msg)
            if ok: channels.append(ch)
        except Exception:
            pass
    row.channel_summary=','.join(channels)
    db.session.add(AssignmentEscalationEvent(
      order_id=order.id,offer_id=row.id,event_type='OFFERED',
      details=f'doctor={doctor.id};attempt={attempt_no};channels={row.channel_summary}',created_by=created_by
    ))
    db.session.commit()
    return row

def case_return_snapshot(order_id):
    # RB_UNIFIED_ASSIGNMENT_DASHBOARD_STATE_V1
    latest_return=(
        CaseWorkflowEvent.query
        .filter_by(order_id=order_id,event_type='RETURNED')
        .order_by(CaseWorkflowEvent.created_at.desc(),CaseWorkflowEvent.id.desc())
        .first()
    )
    if not latest_return:
        return {
            'open':False,
            'return_event':None,
            'resolution_event':None,
            'owner':'',
            'reason':''
        }

    latest_resolution=(
        CaseWorkflowEvent.query
        .filter(
            CaseWorkflowEvent.order_id==order_id,
            CaseWorkflowEvent.event_type.in_(
                ['RESOLVED','READY_FOR_REREVIEW']
            )
        )
        .order_by(
            CaseWorkflowEvent.created_at.desc(),
            CaseWorkflowEvent.id.desc()
        )
        .first()
    )

    resolved=bool(
        latest_resolution and (
            latest_resolution.created_at > latest_return.created_at
            or (
                latest_resolution.created_at == latest_return.created_at
                and latest_resolution.id > latest_return.id
            )
        )
    )

    return {
        'open':not resolved,
        'return_event':latest_return,
        'resolution_event':latest_resolution if resolved else None,
        'owner':latest_return.owner_role or '',
        'reason':latest_return.reason_code or ''
    }


def case_return_is_open(order_id):
    return case_return_snapshot(order_id)['open']


def offer_next_doctor(order,created_by=None):
    """
    RadBridge v5.33 Smart Assignment Engine.

    Readiness:
      BLOCK
      WARN
      ALLOW
      COORDINATOR

    Assignment modes:
      OFFER_ACCEPT
      DIRECT_ASSIGN
      OPEN_POOL
      HYBRID
      MANUAL_ONLY
    """

    # RB_UNIFIED_ASSIGNMENT_GUARD_V1
    order = (
        Order.query
        .filter_by(id=order.id)
        .with_for_update()
        .first()
    )

    if not order:
        return None, 'ORDER_NOT_FOUND'

    if order.assigned_doctor_id:
        return None, 'ALREADY_ASSIGNED'

    if CaseAssignment.query.filter_by(order_id=order.id,active=True).first():
        return None, 'ACTIVE_ASSIGNMENT_EXISTS'

    if case_return_is_open(order.id):
        return None, 'RETURNED_FOR_CORRECTION'

    pending_offer = AssignmentOffer.query.filter_by(
        order_id=order.id,
        status='PENDING'
    ).first()

    if pending_offer:
        return pending_offer, 'PENDING_OFFER_EXISTS'

    decision = assignment_readiness_decision(order)

    strategy = decision.get('strategy')
    action = decision.get('action', 'BLOCK')
    blockers = decision.get('blockers') or []
    warnings = decision.get('warnings') or []
    coordinator = decision.get('coordinator') or []

    strategy_name = strategy.name if strategy else 'LEGACY_POLICY'


    # ------------------------------------------------------
    # Readiness blocked
    # ------------------------------------------------------

    if not decision.get('allowed'):

        reasons = blockers or coordinator or ['CASE_NOT_READY']
        reason_text = ','.join(reasons)

        if action == 'COORDINATOR':

            db.session.add(
                AssignmentEscalationEvent(
                    order_id=order.id,
                    event_type='COORDINATOR_QUEUE',
                    details=f'strategy={strategy_name}; reasons={reason_text}',
                    created_by=created_by
                )
            )

            create_ris_notification(
                order,
                'ASSIGNMENT_COORDINATOR',
                'Case requires coordinator review',
                f'Assignment strategy routed this case to coordinator: {reason_text}',
                'WARNING',
                'COORDINATOR'
            )

            db.session.commit()

            return None, 'COORDINATOR'


        create_ris_notification(
            order,
            'CASE_NOT_READY',
            'Case blocked from smart assignment',
            f'Strategy {strategy_name} blocked assignment: {reason_text}',
            'WARNING',
            'TECHNICIAN'
        )

        db.session.add(
            AssignmentEscalationEvent(
                order_id=order.id,
                event_type='READINESS_BLOCK',
                details=f'strategy={strategy_name}; reasons={reason_text}',
                created_by=created_by
            )
        )

        db.session.commit()

        return None, 'CASE_NOT_READY'


    # ------------------------------------------------------
    # WARN does not block assignment
    # ------------------------------------------------------

    if warnings:

        db.session.add(
            AssignmentEscalationEvent(
                order_id=order.id,
                event_type='READINESS_WARNING',
                details=(
                    f'strategy={strategy_name}; '
                    f'warnings={",".join(warnings)}'
                ),
                created_by=created_by
            )
        )


    policy = assignment_offer_policy()

    if not policy:
        db.session.rollback()
        return None, 'NO_POLICY'


    mode = (
        str(strategy.assignment_mode or 'OFFER_ACCEPT').upper()
        if strategy
        else 'OFFER_ACCEPT'
    )


    # ------------------------------------------------------
    # Manual only
    # ------------------------------------------------------

    if mode == 'MANUAL_ONLY':

        db.session.add(
            AssignmentEscalationEvent(
                order_id=order.id,
                event_type='MANUAL_ONLY',
                details=f'strategy={strategy_name}',
                created_by=created_by
            )
        )

        db.session.commit()

        return None, 'MANUAL_ONLY'


    # ------------------------------------------------------
    # Open Pool
    # ------------------------------------------------------

    if mode == 'OPEN_POOL':

        db.session.add(
            AssignmentEscalationEvent(
                order_id=order.id,
                event_type='OPEN_POOL',
                details=f'strategy={strategy_name}',
                created_by=created_by
            )
        )

        db.session.commit()

        return None, 'OPEN_POOL'


    # ------------------------------------------------------
    # Previous attempts
    # ------------------------------------------------------

    previous = AssignmentOffer.query.filter_by(
        order_id=order.id
    ).order_by(
        AssignmentOffer.attempt_no
    ).all()

    tried = {
        x.doctor_user_id
        for x in previous
    }

    attempt = max(
        [x.attempt_no for x in previous],
        default=0
    ) + 1


    max_attempts = assignment_strategy_max_attempts(
        strategy,
        policy
    )


    # ------------------------------------------------------
    # Maximum attempts reached
    # ------------------------------------------------------

    if attempt > max_attempts:

        fallback = (
            str(strategy.fallback_mode or 'COORDINATOR').upper()
            if strategy
            else 'COORDINATOR'
        )


        if fallback == 'OPEN_POOL':

            db.session.add(
                AssignmentEscalationEvent(
                    order_id=order.id,
                    event_type='OPEN_POOL',
                    details=(
                        f'strategy={strategy_name}; '
                        'reason=MAX_ATTEMPTS'
                    ),
                    created_by=created_by
                )
            )

            db.session.commit()

            return None, 'OPEN_POOL'


        if fallback == 'MANUAL_ONLY':

            db.session.add(
                AssignmentEscalationEvent(
                    order_id=order.id,
                    event_type='MANUAL_ONLY',
                    details=(
                        f'strategy={strategy_name}; '
                        'reason=MAX_ATTEMPTS'
                    ),
                    created_by=created_by
                )
            )

            db.session.commit()

            return None, 'MANUAL_ONLY'


        db.session.add(
            AssignmentEscalationEvent(
                order_id=order.id,
                event_type='ESCALATION_QUEUE',
                details=(
                    f'strategy={strategy_name}; '
                    'reason=MAX_ATTEMPTS'
                ),
                created_by=created_by
            )
        )

        create_ris_notification(
            order,
            'ASSIGNMENT_ESCALATED',
            'Assignment escalated',
            'Maximum doctor offer attempts reached.',
            'WARNING',
            'COORDINATOR'
        )

        db.session.commit()

        return None, 'ESCALATED'


    # ------------------------------------------------------
    # Candidate selection
    # ------------------------------------------------------

    candidates = [
        u
        for u in assignment_candidate_users(order, policy)
        if u.id not in tried
    ]


    if strategy and strategy.require_online:

        candidates = [
            u
            for u in candidates
            if doctor_is_online(u)
        ]


    if not candidates:

        db.session.add(
            AssignmentEscalationEvent(
                order_id=order.id,
                event_type='NO_CANDIDATE',
                details=(
                    f'strategy={strategy_name}; '
                    'reason=NO_ELIGIBLE_DOCTOR'
                ),
                created_by=created_by
            )
        )

        db.session.commit()

        return None, 'NO_CANDIDATE'


    doctor = candidates[0]


    # ------------------------------------------------------
    # DIRECT_ASSIGN
    # ------------------------------------------------------

    if mode == 'DIRECT_ASSIGN':

        row = create_assignment_offer(
            order,
            doctor,
            attempt,
            created_by,
            strategy=strategy
        )

        if not row:
            return None, 'NO_POLICY'


        from case_assignment_service import assign_case_atomically

        now = datetime.utcnow()
        result = assign_case_atomically(
            db=db,
            Order=Order,
            User=User,
            CaseAssignment=CaseAssignment,
            Report=Report,
            AssignmentOffer=AssignmentOffer,
            order_id=order.id,
            doctor_user_id=doctor.id,
            assigned_by=created_by,
            assignment_type='AUTO_DIRECT',
            notes='Direct assignment by smart strategy',
            require_unassigned=True,
            accepted_offer_id=row.id,
            now=now,
        )

        row.status = 'ACCEPTED'
        row.responded_at = now
        row.response_note = 'Direct assignment by smart strategy'


        db.session.add(
            AssignmentEscalationEvent(
                order_id=order.id,
                offer_id=row.id,
                event_type='DIRECT_ASSIGNED',
                details=(
                    f'doctor={result.doctor.id}; '
                    f'strategy={strategy_name}'
                ),
                created_by=created_by
            )
        )

        db.session.commit()

        return row, 'DIRECT_ASSIGNED'


    # ------------------------------------------------------
    # OFFER_ACCEPT / HYBRID
    # ------------------------------------------------------

    offer = create_assignment_offer(
        order,
        doctor,
        attempt,
        created_by,
        strategy=strategy
    )

    if not offer:
        return None, 'NO_POLICY'


    db.session.add(
        AssignmentEscalationEvent(
            order_id=order.id,
            offer_id=offer.id,
            event_type='STRATEGY_SELECTED',
            details=(
                f'strategy={strategy_name}; '
                f'mode={mode}; '
                f'attempt={attempt}'
            ),
            created_by=created_by
        )
    )

    db.session.commit()

    return offer, 'OFFERED'

def coordinate_post_exam_assignment(order,created_by=None,trigger='POST_EXAM_READINESS'):
    # RB_UNIFIED_ASSIGNMENT_COORDINATOR_V1
    if not order:
        return None, 'ORDER_NOT_FOUND'

    order = Order.query.filter_by(id=order.id).with_for_update().first()
    if not order:
        return None, 'ORDER_NOT_FOUND'
    if order.assigned_doctor_id:
        return None, 'ALREADY_ASSIGNED'
    if CaseAssignment.query.filter_by(order_id=order.id,active=True).first():
        return None, 'ACTIVE_ASSIGNMENT_EXISTS'
    if case_return_is_open(order.id):
        return None, 'RETURNED_FOR_CORRECTION'
    if (order.exam_status or '').upper()!='EXAM_COMPLETED':
        return None, 'EXAM_NOT_COMPLETED'
    if (order.pacs_status or '').upper()!='IMAGES_COMPLETE':
        return None, 'IMAGES_NOT_COMPLETE'

    pending = AssignmentOffer.query.filter_by(order_id=order.id,status='PENDING').first()
    if pending:
        return pending, 'PENDING_OFFER_EXISTS'

    offer,status=offer_next_doctor(order,created_by=created_by)
    app.logger.info(
        'Unified assignment coordinator order=%s trigger=%s status=%s',
        order.id,trigger,status
    )
    return offer,status


def expire_assignment_offers():
    now=datetime.utcnow()
    rows=AssignmentOffer.query.filter(
      AssignmentOffer.status=='PENDING',
      AssignmentOffer.expires_at<=now
    ).order_by(AssignmentOffer.expires_at).all()
    touched=[]
    for row in rows:
        row.status='TIMEOUT';row.responded_at=now
        db.session.add(AssignmentEscalationEvent(
          order_id=row.order_id,offer_id=row.id,event_type='TIMEOUT',
          details=f'doctor={row.doctor_user_id};attempt={row.attempt_no}'
        ))
        db.session.flush()
        next_offer,_=offer_next_doctor(row.order,created_by=None)
        touched.append((row.id,next_offer.id if next_offer else None))
    db.session.commit()
    return touched



