def seed_quality_defaults():
    if ProcedureQualityRule.query.count()==0:
        for mod,pat,mn,warn,series in QUALITY_DEFAULTS:
            db.session.add(ProcedureQualityRule(modality=mod,procedure_pattern=pat,min_images=mn,
                warning_images=warn,required_series=series,require_history=True,
                require_attachments=False,require_pacs_study=True,block_auto_assign=True))
    if CaseReturnReason.query.count()==0:
        for code,label,route in [
          ('INCOMPLETE_IMAGES','Incomplete images','TECHNICIAN'),
          ('MISSING_SERIES','Missing series / sequence','TECHNICIAN'),
          ('WRONG_PROTOCOL','Wrong protocol','TECHNICIAN'),
          ('MOTION_ARTIFACT','Motion artifact / poor image quality','TECHNICIAN'),
          ('MISSING_HISTORY','Missing clinical history','RECEPTION'),
          ('MISSING_REFERRAL','Missing referral / attachment','RECEPTION'),
          ('DEMOGRAPHIC_MISMATCH','Patient demographic mismatch','RECEPTION'),
          ('NEED_PRIOR','Need prior/comparison study','RECEPTION'),
          ('OUTSIDE_SPECIALTY','Outside doctor specialty','ASSIGNMENT'),
          ('ADDITIONAL_IMAGING','Additional imaging required','TECHNICIAN'),
          ('OTHER','Other','SUPERVISOR')]:
            db.session.add(CaseReturnReason(code=code,label=label,route_to=route))
    if TATPolicy.query.count()==0:
        for p,total,report in [('STAT',30,15),('URGENT',60,30),('ROUTINE',120,60)]:
            db.session.add(TATPolicy(priority=p,total_tat_min=total,accept_to_final_min=report))
    if NotificationEscalationRule.query.count()==0:
        for ev,role,esc,mins in [
          ('INCOMPLETE_IMAGES','TECHNICIAN','BRANCH_MANAGER',15),
          ('MISSING_HISTORY','RECEPTION','BRANCH_MANAGER',15),
          ('MISSING_ATTACHMENTS','RECEPTION','BRANCH_MANAGER',20),
          ('ASSIGNMENT_TIMEOUT','ASSIGNMENT','BRANCH_MANAGER',10),
          ('STAT_OVERDUE','DOCTOR','BRANCH_MANAGER',5),
          ('RETURNED_TO_TECH','TECHNICIAN','BRANCH_MANAGER',15)]:
            db.session.add(NotificationEscalationRule(event_type=ev,first_role=role,escalate_role=esc,escalate_after_min=mins))
    db.session.commit()

def quality_rule_for(order):
    mod=str(order.modality or '').upper()
    proc=str(order.procedure or '').upper()
    rows=ProcedureQualityRule.query.filter_by(active=True,modality=mod).all()
    exact=[r for r in rows if r.procedure_pattern.upper() in proc]
    return sorted(exact,key=lambda r:len(r.procedure_pattern),reverse=True)[0] if exact else None

def _order_history_present(order):
    try:
        return ClinicalNote.query.filter_by(order_id=order.id).count()>0
    except Exception:
        return False

def _order_attachment_count(order):
    try:
        return PatientDocument.query.filter_by(patient_id=order.patient_id).count()
    except Exception:
        return 0

def pacs_image_count(order):
    count,meta,error,_series=pacs_readiness_evidence(order)
    return count,meta,error

def pacs_readiness_evidence(order):
    meta,error=pacs_study_lookup(order)
    if not meta: return 0,meta,error,[]
    try:
        import requests,os
        base=(app.config.get('ORTHANC_URL') or os.environ.get('ORTHANC_URL') or '').rstrip('/')
        auth=(os.environ.get('ORTHANC_USER',''),os.environ.get('ORTHANC_PASSWORD','')) if os.environ.get('ORTHANC_USER') else None
        sid=meta.get('orthanc_study_id')
        r=requests.get(f'{base}/studies/{sid}',auth=auth,timeout=20);r.raise_for_status()
        study=r.json()
        total=0
        series=[]
        for series_id in study.get('Series',[]):
            sr=requests.get(f'{base}/series/{series_id}',auth=auth,timeout=20);sr.raise_for_status()
            payload=sr.json(); instances=len(payload.get('Instances',[])); total+=instances
            tags=payload.get('MainDicomTags') or {}
            series.append({'series_id':series_id,'description':tags.get('SeriesDescription',''),
              'protocol':tags.get('ProtocolName',''),'modality':tags.get('Modality',''),
              'instance_count':instances})
        return total,meta,'',series
    except Exception as e:
        return 0,meta,str(e)[:500],[]

def evaluate_case_readiness(order):
    from case_readiness_service import evaluate_readiness
    from case_exception_resolution_service import apply_series_aliases
    rule=quality_rule_for(order)
    count,pacs,error,series=pacs_readiness_evidence(order)
    has_history=_order_history_present(order)
    attachments=_order_attachment_count(order)
    missing_pacs=not bool(pacs)
    min_images=(rule.min_images if rule else 0) or 0
    warn_images=(rule.warning_images if rule else 0) or 0
    min_override=CaseReadinessOverride.query.filter_by(
        order_id=order.id,blocker='INCOMPLETE_IMAGES',active=True).first()
    rule_min_images=min_images
    if min_override:
        try: min_images=max(0,int(min_override.override_value))
        except Exception: min_images=rule_min_images
    aliases=(ReadinessSeriesAlias.query.filter_by(rule_id=rule.id,active=True).all()
             if rule else [])
    mapped_series=apply_series_aliases(series,aliases)
    result=evaluate_readiness(image_count=count,min_images=min_images,warning_images=warn_images,
      require_pacs=bool(rule.require_pacs_study) if rule else True,pacs_present=bool(pacs),
      require_history=bool(rule.require_history) if rule else False,history_present=has_history,
      require_attachments=bool(rule.require_attachments) if rule else False,attachment_count=attachments,
      required_series=(rule.required_series if rule else ''),series=mapped_series)
    flags=result['flags']
    row=CaseReadiness.query.filter_by(order_id=order.id).first() or CaseReadiness(order_id=order.id)
    row.status=result['status'];row.score=result['score'];row.image_count=count;row.expected_min_images=min_images
    row.missing_history=flags['missing_history'];row.missing_attachments=flags['missing_attachments']
    row.missing_pacs=flags['missing_pacs'];row.incomplete_images=flags['incomplete_images']
    row.missing_series=flags['missing_series'];row.checked_at=datetime.utcnow();row.series_checked_at=row.checked_at
    result['details'].update({'pacs_error':error,'rule_id':rule.id if rule else None,
      'history':has_history,'attachments':attachments,
      'rule_min_images':rule_min_images,
      'minimum_override_id':min_override.id if min_override else None})
    row.details_json=json.dumps(result['details'],ensure_ascii=False)
    row.series_evidence_json=json.dumps(mapped_series,ensure_ascii=False);row.facts_sha256=result['facts_sha256']
    db.session.add(row);db.session.flush()
    return row

def create_ris_notification(
    order,
    event_type,
    title,
    body,
    severity='WARNING',
    role_code='',
    user_id=None
):
    n=RISNotification(
        order_id=order.id,
        branch_id=order.branch_id,
        severity=severity,
        event_type=event_type,
        title=title,
        body=body,
        role_code=role_code,
        user_id=user_id,
        status='NEW'
    )
    db.session.add(n)
    db.session.commit()
    return n


def assignment_strategy_for_order(order):
    """
    Select the highest-priority enabled AssignmentStrategy
    matching branch / modality / procedure.

    Lower priority number wins.
    A blank scope means wildcard.
    """
    rows = AssignmentStrategy.query.filter_by(
        enabled=True
    ).order_by(
        AssignmentStrategy.priority.asc(),
        AssignmentStrategy.id.asc()
    ).all()

    modality = str(order.modality or '').strip().upper()
    procedure = str(order.procedure or '').strip().upper()

    for row in rows:

        if row.branch_id and row.branch_id != order.branch_id:
            continue

        if row.modality:
            if row.modality.strip().upper() != modality:
                continue

        if row.procedure_pattern:
            pattern = row.procedure_pattern.strip().upper()
            if pattern not in procedure:
                continue

        return row

    return None


def assignment_strategy_timeout(order, strategy, policy=None):
    priority = str(order.priority or 'ROUTINE').upper()

    if strategy:
        if priority == 'STAT':
            return int(strategy.stat_timeout_seconds or 60)

        if priority == 'URGENT':
            return int(strategy.urgent_timeout_seconds or 120)

        return int(strategy.routine_timeout_seconds or 300)

    if policy:
        return assignment_timeout_for(order, policy)

    return 300


def assignment_strategy_max_attempts(strategy, policy=None):
    if strategy and strategy.max_offer_attempts:
        return int(strategy.max_offer_attempts)

    if policy and policy.max_offer_attempts:
        return int(policy.max_offer_attempts)

    return 5



def assignment_readiness_decision(order,refresh_stale=True):
    '''
    Evaluate case readiness using the matching AssignmentStrategy.

    Returns:
      allowed       bool
      action        ALLOW / WARN / BLOCK / COORDINATOR
      blockers      list
      warnings      list
      strategy      AssignmentStrategy or None
      readiness     CaseReadiness
    '''

    row=CaseReadiness.query.filter_by(order_id=order.id).first()

    if refresh_stale and (not row or not row.checked_at or (
        datetime.utcnow()-row.checked_at
    ).total_seconds()>300):
        row=evaluate_case_readiness(order)

    if not row:
        return {
            'allowed':False,'action':'BLOCK','blockers':['READINESS_NOT_CHECKED'],
            'warnings':[],'coordinator':[],'strategy':None,'readiness':None
        }

    strategy=assignment_strategy_for_order(order)

    # Backward-compatible behavior until an admin strategy exists.
    if not strategy:
        return {
            'allowed': row.status=='READY',
            'action': 'ALLOW' if row.status=='READY' else 'BLOCK',
            'blockers': [] if row.status=='READY' else ['LEGACY_READINESS'],
            'warnings': [],
            'strategy': None,
            'readiness': row
        }

    blockers=[]
    warnings=[]
    coordinator=[]

    def apply(rule_action, reason):
        action=str(rule_action or 'WARN').upper()

        if action=='BLOCK':
            blockers.append(reason)

        elif action=='WARN':
            warnings.append(reason)

        elif action=='COORDINATOR':
            coordinator.append(reason)

        # ALLOW / IGNORE intentionally do nothing.

    if row.missing_pacs:
        apply(strategy.pacs_missing_action,'MISSING_PACS')

    if row.incomplete_images:
        apply(strategy.images_incomplete_action,'INCOMPLETE_IMAGES')

    # R8_PHASE3_REQUIRED_SERIES_STRATEGY_V1
    # Missing required acquisitions follow the configured image
    # completeness action. This preserves existing strategy policy
    # while ensuring required Series are never silently ignored.
    if getattr(row,'missing_series',False):
        apply(
            strategy.images_incomplete_action,
            'MISSING_REQUIRED_SERIES'
        )

    if getattr(row,'missing_documents',False):
        apply(strategy.documents_missing_action,'MISSING_DOCUMENTS')

    if getattr(row,'missing_notes',False):
        apply(strategy.notes_missing_action,'MISSING_NOTES')

    if row.missing_attachments:
        apply(strategy.attachments_missing_action,'MISSING_ATTACHMENTS')

    if row.missing_history:
        apply(strategy.history_missing_action,'MISSING_HISTORY')

    if int(order.pacs_image_count or 0) < int(strategy.min_images or 0):
        apply(
            strategy.images_incomplete_action,
            'MIN_IMAGES_NOT_MET'
        )

    if blockers:
        action='BLOCK'
        allowed=False

    elif coordinator:
        action='COORDINATOR'
        allowed=False

    elif warnings:
        action='WARN'
        allowed=True

    else:
        action='ALLOW'
        allowed=True

    return {
        'allowed':allowed,
        'action':action,
        'blockers':blockers,
        'warnings':warnings,
        'coordinator':coordinator,
        'strategy':strategy,
        'readiness':row
    }


def readiness_allows_auto_assign(order):
    '''
    Compatibility wrapper for old callers.
    '''
    return assignment_readiness_decision(order)['allowed']


# RB_TAT_POLICY_RESOLVER_V1
def resolve_tat_policy(priority, modality=None):
    """Resolve active TAT policy by priority + modality, then wildcard."""
    priority_key = str(priority or 'ROUTINE').strip().upper()
    modality_key = str(modality or '').strip().upper()

    if modality_key:
        exact = (
            TATPolicy.query
            .filter_by(
                priority=priority_key,
                modality=modality_key,
                active=True,
            )
            .order_by(TATPolicy.id.asc())
            .first()
        )
        if exact:
            return exact

    return (
        TATPolicy.query
        .filter_by(
            priority=priority_key,
            modality='*',
            active=True,
        )
        .order_by(TATPolicy.id.asc())
        .first()
    )


def case_delay_snapshot(order):
    events=CaseWorkflowEvent.query.filter_by(order_id=order.id).order_by(CaseWorkflowEvent.created_at).all()
    now=datetime.utcnow()
    readiness=CaseReadiness.query.filter_by(order_id=order.id).first()
    assignment=CaseAssignment.query.filter_by(order_id=order.id,active=True).order_by(CaseAssignment.assigned_at.desc()).first()
    final=None
    try:
        final=Report.query.filter_by(order_id=order.id,status='FINAL').order_by(Report.id.desc()).first()
    except Exception: pass
    registered=getattr(order,'created_at',None) or getattr(order,'scheduled',None)
    total_min=int((now-registered).total_seconds()/60) if registered else 0
    policy=resolve_tat_policy(
        order.priority,
        order.modality
    )
    overdue=bool(policy and total_min>policy.total_tat_min and not final)
    if readiness and readiness.status=='BLOCKED':
        owner='TECHNICIAN' if readiness.incomplete_images or readiness.missing_pacs else 'RECEPTION'
        reason='CASE_INCOMPLETE'
    elif not assignment:
        owner='ASSIGNMENT';reason='WAITING_ASSIGNMENT'
    elif not final:
        owner='DOCTOR';reason='WAITING_REPORT'
    else:
        owner='COMPLETE';reason='FINALIZED'
    return {'total_min':total_min,'overdue':overdue,'owner':owner,'reason':reason,
      'readiness':readiness.status if readiness else 'NOT_CHECKED','final':bool(final)}



def advanced_order_query():
    q=Order.query.join(Patient)
    text=(request.args.get('q') or '').strip()
    if text:
        q=q.filter(or_(
          Patient.name.ilike(f'%{text}%'),
          Patient.patient_id.ilike(f'%{text}%'),
          Patient.phone.ilike(f'%{text}%'),
          Patient.national_id.ilike(f'%{text}%'),
          Order.accession.ilike(f'%{text}%'),
          Order.procedure.ilike(f'%{text}%')
        ))
    branch_id=request.args.get('branch_id',type=int)
    modality=(request.args.get('modality') or '').strip().upper()
    procedure=(request.args.get('procedure') or '').strip()
    priority=(request.args.get('priority') or '').strip().upper()
    readiness=(request.args.get('readiness') or '').strip().upper()
    assignment=(request.args.get('assignment') or '').strip().upper()
    report_status=(request.args.get('report_status') or '').strip().upper()
    returned=(request.args.get('returned') or '')=='1'
    overdue=(request.args.get('overdue') or '')=='1'
    missing_history=(request.args.get('missing_history') or '')=='1'
    missing_images=(request.args.get('missing_images') or '')=='1'
    missing_attachments=(request.args.get('missing_attachments') or '')=='1'
    has_priors=(request.args.get('has_priors') or '')=='1'
    has_documents=(request.args.get('has_documents') or '')=='1'
    doctor_id=request.args.get('doctor_id',type=int)
    if branch_id: q=q.filter(Order.branch_id==branch_id)
    if modality: q=q.filter(Order.modality==modality)
    if procedure: q=q.filter(Order.procedure.ilike(f'%{procedure}%'))
    if priority: q=q.filter(Order.priority==priority)
    rows=q.order_by(Order.id.desc()).limit(1000).all()

    def keep(o):
        r=CaseReadiness.query.filter_by(order_id=o.id).first()
        ca=CaseAssignment.query.filter_by(order_id=o.id,active=True).first()
        rp=Report.query.filter_by(order_id=o.id).order_by(Report.id.desc()).first()
        events=CaseWorkflowEvent.query.filter_by(order_id=o.id).all()
        if readiness and (not r or r.status!=readiness): return False
        if assignment=='ASSIGNED' and not ca: return False
        if assignment=='UNASSIGNED' and ca: return False
        if doctor_id and (not ca or ca.doctor_user_id!=doctor_id): return False
        if report_status and (not rp or str(rp.status or '').upper()!=report_status): return False
        if returned and not any(e.event_type=='RETURNED' for e in events): return False
        if missing_history and not (r and r.missing_history): return False
        if missing_images and not (r and r.incomplete_images): return False
        if missing_attachments and not (r and r.missing_attachments): return False
        if has_priors and not (related_prior_orders(o,1) or external_priors_for_order(o)): return False
        if has_documents and PatientDocument.query.filter_by(patient_id=o.patient_id).count()==0: return False
        if overdue and not case_delay_snapshot(o)['overdue']: return False
        return True
    return [o for o in rows if keep(o)]

