def order_visual_state(order):
    report=Report.query.filter_by(order_id=order.id).order_by(Report.id.desc()).first()
    readiness=CaseReadiness.query.filter_by(order_id=order.id).first()
    assignment=CaseAssignment.query.filter_by(order_id=order.id,active=True).first()
    attachments=Attachment.query.filter_by(order_id=order.id).count()

    if getattr(order,'report_delivered',False):
        stage='DELIVERED'
    elif report and report.status=='FINAL':
        stage='FINAL'
    elif report and report.status in ('DRAFT','PRELIMINARY'):
        stage='REPORTING'
    elif assignment:
        stage='ASSIGNED'
    elif readiness and readiness.status=='READY':
        stage='READY_REPORT'
    elif getattr(order,'pacs_status','') in ('PARTIAL','WAITING') and getattr(order,'exam_status','') in ('COMPLETED','DONE'):
        stage='IMAGES_PENDING'
    elif getattr(order,'exam_status','') in ('IN_PROGRESS','STARTED'):
        stage='IN_EXAM'
    else:
        stage='REGISTERED'

    flags=[]
    if getattr(order,'priority','ROUTINE') in ('URGENT','STAT'):
        flags.append(('urgent','URGENT'))
    if readiness:
        missing=[]
        for field,label in [
            ('missing_history','Missing History'),
            ('missing_documents','Missing Documents'),
            ('images_incomplete','Images Incomplete'),
        ]:
            if getattr(readiness,field,False): missing.append(label)
        # Compatible with older readiness schema: use reason/details text if boolean columns do not exist.
        txt=' '.join(str(getattr(readiness,x,'') or '') for x in ('reason','details','notes','blocking_reasons'))
        low=txt.lower()
        if 'history' in low and 'Missing History' not in missing: missing.append('Missing History')
        if ('document' in low or 'attachment' in low) and 'Missing Documents' not in missing: missing.append('Missing Documents')
        if ('image' in low and ('incomplete' in low or 'missing' in low)) and 'Images Incomplete' not in missing: missing.append('Images Incomplete')
        flags.extend(('warning',x) for x in missing)
    if attachments==0:
        flags.append(('info','No Attachments'))
    return {'stage':stage,'flags':flags,'readiness':readiness,'assignment':assignment,'report':report,'attachments':attachments}

def resolve_printer_profile(order,document_type,workstation_code=''):
    q=PrinterProfile.query.filter_by(document_type=document_type.upper(),active=True)
    rows=q.order_by(PrinterProfile.user_id.desc(),PrinterProfile.workstation_code.desc(),PrinterProfile.branch_id.desc()).all()
    uid=current_user().id if current_user() else None
    branch_id=getattr(order,'branch_id',None)
    wc=(workstation_code or '').strip()
    scored=[]
    for p in rows:
        if p.user_id and p.user_id!=uid: continue
        if p.branch_id and p.branch_id!=branch_id: continue
        if p.workstation_code and p.workstation_code!=wc: continue
        score=(8 if p.user_id else 0)+(4 if p.workstation_code else 0)+(2 if p.branch_id else 0)
        scored.append((score,p))
    return sorted(scored,key=lambda x:x[0],reverse=True)[0][1] if scored else None

def generated_attachment_filename(order_id, category, original_name):
    """Generate collision-resistant server filename while preserving original_name in DB/UI."""
    ext=os.path.splitext(original_name or '')[1].lower()
    if not re.fullmatch(r'\.[a-z0-9]{1,10}', ext or ''):
        ext=''
    cat=re.sub(r'[^A-Z0-9_-]','_',str(category or 'OTHER').upper())[:40] or 'OTHER'
    oid=str(order_id or 'GENERAL')
    return f"ATT_{oid}_{cat}_{uuid.uuid4().hex[:12]}{ext}"

