def _rb_v5462_allow_registration():
    if not current_user():
        abort(401)
    if not (has_perm('*') or has_perm('orders.create') or has_perm('appointments.manage')):
        abort(403)

def _rb_v5462_proc_ids(form):
    out=[]
    for raw in form.getlist('procedure_ids'):
        try: pid=int(raw)
        except Exception: continue
        if pid not in out: out.append(pid)
    if not out:
        one=form.get('procedure_id',type=int)
        if one: out=[one]
    return out

def _rb_v5462_patient(form):
    mode=(form.get('patient_mode') or 'new').strip().lower()
    if mode=='existing':
        pid=form.get('patient_id',type=int) or form.get('patient',type=int)
        if not pid:
            raise ValueError('Choose an existing patient.')
        return Patient.query.get_or_404(pid)
    return _rb_registration_v2_create_patient(
        form,
        audit_action='PATIENT_CREATE_FROM_FULL_REGISTRATION'
    )

def _rb_v5462_direct_attachments(patient,order=None,appointment=None):
    files=request.files.getlist('attachment_files')
    cats=request.form.getlist('attachment_categories')
    notes=request.form.getlist('attachment_notes')
    saved=[]
    allowed=('.pdf','.jpg','.jpeg','.png','.webp','.tif','.tiff',
             '.doc','.docx','.odt','.dcm','.dicom','.zip')
    for i,f in enumerate(files):
        if not f or not f.filename: continue
        ext=os.path.splitext(f.filename)[1].lower()
        if ext not in allowed:
            raise ValueError(f'Unsupported attachment type: {f.filename}')
        cat=(cats[i] if i<len(cats) and cats[i] else 'OTHER').upper()
        note=(notes[i] if i<len(notes) else '').strip()
        ref=order.id if order else appointment.id if appointment else 'registration'
        folder=os.path.join(ATTACHMENT_DIR,str(patient.id),str(ref))
        os.makedirs(folder,exist_ok=True)
        stored=generated_attachment_filename(order.id if order else None,cat,f.filename)
        path=os.path.join(folder,stored)
        f.save(path); saved.append(path)
        db.session.add(Attachment(
            patient_id=patient.id,
            order_id=(order.id if order else None),
            appointment_id=(appointment.id if appointment else None),
            category=cat,original_name=f.filename,stored_path=path,
            mime_type=f.mimetype or '',notes=note,uploaded_by=current_user().id
        ))
    return saved

def _rb_v5462_attach_ocr(patient,intake_id,order=None,appointment=None):
    if not intake_id: return
    intake=SmartIntakeSession.query.get(intake_id)
    if not intake: return
    chosen=set()
    for raw in (request.form.get('ocr_document_ids') or '').split(','):
        try: chosen.add(int(raw))
        except Exception: pass
    catmap={
      'IDENTITY':'IDENTITY','INSURANCE_CARD':'INSURANCE_CARD',
      'PRESCRIPTION':'PRESCRIPTION','APPROVAL':'APPROVAL',
      'PREVIOUS_REPORT':'PREVIOUS_REPORT','PREVIOUS_IMAGES':'PREVIOUS_IMAGES',
      'QUESTIONNAIRE':'QUESTIONNAIRE','CONSENT':'CONSENT'
    }
    for doc in SmartIntakeDocument.query.filter_by(intake_id=intake.id).all():
        if chosen and doc.id not in chosen: continue
        if doc.status=='REJECTED': continue
        doc.status='APPROVED'
        doc.reviewed_by=current_user().id
        doc.reviewed_at=datetime.utcnow()
        if not doc.review_notes:
            doc.review_notes='Accepted from unified registration workspace.'
        if not Attachment.query.filter_by(patient_id=patient.id,stored_path=doc.file_path).first():
            db.session.add(Attachment(
                patient_id=patient.id,
                order_id=(order.id if order else None),
                appointment_id=(appointment.id if appointment else None),
                category=catmap.get(doc.document_type,'OTHER'),
                original_name=doc.original_name or f'OCR-{doc.id}',
                stored_path=doc.file_path,mime_type=doc.mime_type or '',
                notes='OCR intake document',uploaded_by=current_user().id
            ))
        if not doc.patient_document_id:
            pd=PatientDocument(
                patient_id=patient.id,
                order_id=(order.id if order else None),
                document_type=doc.document_type or 'OTHER',
                category='SMART_INTAKE',
                file_path=doc.file_path,
                original_name=doc.original_name or '',
                extracted_text=doc.ocr_text or '',
                extraction_status='COMPLETED' if doc.ocr_text else 'NOT_EXTRACTED',
                review_status='APPROVED',
                reviewer_id=current_user().id,
                review_notes=doc.review_notes or '',
                uploaded_by=current_user().id,
                reviewed_at=datetime.utcnow()
            )
            db.session.add(pd); db.session.flush()
            doc.patient_document_id=pd.id
    intake.patient_id=patient.id

def _rb_v5462_insurance(order,contract,form):
    if not contract or not contract.approval_required: return
    method=(form.get('approval_method') or 'AUTO').upper()
    if method not in ('AUTO','MANUAL','ALREADY_APPROVED'): method='AUTO'
    approval_no=(form.get('approval_no') or '').strip()
    if method=='ALREADY_APPROVED' and not approval_no:
        raise ValueError('Approval number is required for an already-approved case.')
    status='APPROVED' if method=='ALREADY_APPROVED' else ('PENDING' if method=='AUTO' else 'REQUIRED')
    row=InsuranceApprovalRequest(
        order_id=order.id,method=method,status=status,
        approval_no=approval_no,payer_name=contract.name,
        member_no=(form.get('member_no') or '').strip(),
        requested_at=datetime.utcnow(),
        decided_at=(datetime.utcnow() if status=='APPROVED' else None),
        created_by=current_user().id
    )
    db.session.add(row); db.session.flush()
    db.session.add(InsuranceApprovalEvent(
        approval_request_id=row.id,event_type='CREATED_FROM_FULL_REGISTRATION',
        old_status='',new_status=status,message=f'method={method}',
        user_id=current_user().id
    ))
    order.approval_no=approval_no

def _rb_v5462_notes(order,form):
    parts=[]
    for label,key in (
        ('History','clinical_history'),
        ('Clinical note','clinical_note'),
        ('Questionnaire','questionnaire_note')
    ):
        value=(form.get(key) or '').strip()
        if value: parts.append(label+':\n'+value)
    if parts:
        db.session.add(ClinicalNote(
            order_id=order.id,author_user_id=current_user().id,
            note_type='RECEPTION',visibility='CLINICAL_TEAM',
            text='\n\n'.join(parts)
        ))

def _rb_v5462_payment(orders,form):
    amount=float(form.get('payment_amount') or 0)
    if amount<=0: return
    if not has_perm('payments.create'): abort(403)
    method=(form.get('payment_method') or '').strip().upper()
    if not method: raise ValueError('Select payment method.')
    total_due=sum(max(0,float(o.patient_share or 0)) for o in orders)
    if amount>total_due+0.01:
        raise ValueError(f'Payment exceeds patient total due ({total_due:.2f}).')
    left=amount
    for o in orders:
        if left<=0: break
        due=max(0,float(o.patient_share or 0))
        part=min(left,due)
        if part<=0: continue
        db.session.add(Payment(
            order_id=o.id,amount=part,method=method,
            reference=(form.get('payment_reference') or '').strip(),
            created_by=current_user().id
        ))
        o.paid_amount=float(o.paid_amount or 0)+part
        left=round(left-part,2)

@app.post('/schedule/ocr-preview')
@login_required
def schedule_ocr_preview():
    _rb_v5462_allow_registration()
    f=request.files.get('file')
    if not f or not f.filename:
        return jsonify({'ok':False,'error':'Choose a document.'}),400

    intake=SmartIntakeSession.query.get(request.form.get('intake_id',type=int)) if request.form.get('intake_id') else None
    if not intake:
        intake=SmartIntakeSession(
            session_key=secrets.token_urlsafe(24),
            created_by=current_user().id,status='UPLOADING'
        )
        db.session.add(intake); db.session.flush()

    dtype=(request.form.get('document_type') or 'OTHER').upper()
    if dtype not in {x[0] for x in SMART_DOCUMENT_TYPES}: dtype='OTHER'
    ext=os.path.splitext(f.filename)[1].lower()
    if ext not in {'.pdf','.png','.jpg','.jpeg','.tif','.tiff','.webp','.bmp','.dcm'}:
        db.session.rollback()
        return jsonify({'ok':False,'error':f'Unsupported file type: {ext or "unknown"}'}),400

    folder=smart_intake_dir(intake.id)
    safe=re.sub(r'[^A-Za-z0-9._-]','_',f.filename)[:180]
    path=os.path.join(folder,f'{uuid.uuid4().hex}_{safe}')
    f.save(path)
    digest=_intake_file_sha256(path)

    doc=SmartIntakeDocument.query.filter_by(intake_id=intake.id,content_sha256=digest).first()
    if doc:
        try: os.remove(path)
        except Exception: pass
    else:
        doc=SmartIntakeDocument(
            intake_id=intake.id,document_type=dtype,original_name=f.filename,
            file_path=path,mime_type=f.mimetype or '',status='UPLOADED',
            content_sha256=digest
        )
        db.session.add(doc); db.session.flush()

    result,error=call_ocr_provider(doc)
    classification={}; fields={}; text_value=''; warning=''
    if result:
        classification=_apply_smart_intake_ocr_result(doc,result)
        fields=dict(result.get('fields') or {})
        text_value=str(result.get('text') or '')
    else:
        warning=error or 'OCR unavailable. Document kept for manual review.'
        doc.status='OCR_FAILED'; doc.ocr_error=warning[:500]

    searchable=(text_value+' '+json.dumps(fields,ensure_ascii=False)).lower()
    matches=[]
    if searchable.strip():
        for p in Procedure.query.filter_by(active=True).all():
            vals=[p.name or '',p.name_ar or '',p.code or '']
            if any(v and v.lower() in searchable for v in vals):
                matches.append({'id':p.id,'name':p.name,'modality':p.modality,'duration':int(p.duration_min or 20)})

    contract_match=None
    if searchable.strip():
        for c in Contract.query.filter_by(active=True).all():
            if c.name and c.name.lower() in searchable:
                contract_match={'id':c.id,'name':c.name,'approval_required':bool(c.approval_required)}
                break

    suggested=classification.get('suggested_type') or classification.get('type') or doc.document_type or 'OTHER'
    db.session.commit()
    return jsonify({
        'ok':True,'intake_id':intake.id,'document_id':doc.id,
        'filename':doc.original_name,'suggested_type':suggested,
        'confidence':float(doc.confidence or 0),'fields':fields,
        'text':text_value[:12000],'procedure_matches':matches,
        'contract_match':contract_match,'warning':warning
    })

@app.post('/schedule/unified-submit')
@login_required
def schedule_unified_submit():
    _rb_v5462_allow_registration()
    action=(request.form.get('registration_action') or 'REGISTER').upper()
    if action not in ('BOOK','REGISTER'): abort(400)

    saved=[]; orders=[]; appts=[]
    try:
        try:
            scheduled=datetime.fromisoformat((request.form.get('scheduled') or '').strip())
        except Exception:
            raise ValueError('Invalid appointment date/time.')

        branch=Branch.query.get_or_404(request.form.get('branch_id',type=int))
        device=Device.query.get_or_404(request.form.get('device_id',type=int))
        if device.branch_id!=branch.id:
            raise ValueError('Selected device does not belong to this branch.')

        procs=[Procedure.query.get_or_404(x) for x in _rb_v5462_proc_ids(request.form)]
        if not procs: raise ValueError('Add at least one examination.')
        for p in procs:
            if (p.modality or '').upper()!=(device.modality or '').upper():
                raise ValueError(f'{p.name} is not compatible with {device.name}.')
            if not procedure_available_in_branch(p.id,branch.id):
                raise ValueError(f'{p.name} is not available in {branch.name}.')

        patient=_rb_v5462_patient(request.form)
        contract=Contract.query.get(request.form.get('contract_id',type=int)) if request.form.get('contract_id') else None
        referrer=request.form.get('referring_doctor_id',type=int)
        priority=(request.form.get('priority') or 'ROUTINE').upper()
        waiting=request.form.get('waiting_list')=='1'
        cursor=scheduled

        if action=='BOOK':
            for p in procs:
                duration=max(5,int(p.duration_min or 20))
                if not waiting:
                    acquire_booking_slot_lock(device.id,cursor)
                    reason=booking_restriction_reason(branch,p,device,cursor,duration)
                    if reason: raise ValueError(f'{p.name}: {reason}')
                dup=Appointment.query.filter_by(
                    patient_id=patient.id,procedure_id=p.id,scheduled=cursor
                ).filter(Appointment.status!='CANCELLED').first()
                if dup: raise ValueError(f'Duplicate booking exists for {p.name} at {cursor.strftime("%H:%M")}.')
                a=Appointment(
                    patient_id=patient.id,branch_id=branch.id,procedure_id=p.id,
                    device_id=device.id,scheduled=cursor,
                    status='WAITING' if waiting else 'BOOKED',
                    source='FULL_REGISTRATION_WORKSPACE',
                    duration_min=duration,priority=priority,waiting_list=waiting,
                    notes=(request.form.get('notes') or '').strip(),
                    created_by=current_user().id
                )
                db.session.add(a); db.session.flush(); appts.append(a)
                cursor+=timedelta(minutes=duration)

            first=appts[0]
            saved+=_rb_v5462_direct_attachments(patient,appointment=first)
            _rb_v5462_attach_ocr(patient,request.form.get('ocr_intake_id',type=int),appointment=first)
            audit('FULL_REGISTRATION_BOOK_ONLY','appointment',first.id,f'patient={patient.id}; exams={len(appts)}')
            db.session.commit()
            flash(f'Booked {len(appts)} examination(s) for {patient.name}.','success')
            return _rb_calendar_redirect(scheduled,branch.id,device.id)

        if not (has_perm('*') or has_perm('orders.create')): abort(403)

        for p in procs:
            duration=max(5,int(p.duration_min or 20))
            acquire_booking_slot_lock(device.id,cursor)
            reason=booking_restriction_reason(branch,p,device,cursor,duration)
            if reason: raise ValueError(f'{p.name}: {reason}')
            gross,effective,patient_share,company_share,_=price_order(p,contract)
            o=Order(
                accession=new_accession(),patient=patient,modality=p.modality,
                procedure=p.name,procedure_id=p.id,branch_id=branch.id,
                device_id=device.id,station_ae=device.ae_title,
                contract_id=(contract.id if contract else None),
                referring_doctor_id=referrer or None,scheduled=cursor,
                status='REGISTERED',gross_price=gross,contract_price=effective,
                patient_share=patient_share,company_share=company_share,
                created_by=current_user().id,priority=priority
            )
            db.session.add(o); db.session.flush()
            a=Appointment(
                patient_id=patient.id,
                branch_id=branch.id,
                procedure_id=p.id,
                device_id=device.id,
                order_id=o.id,
                scheduled=cursor,
                status='REGISTERED',
                source='FULL_REGISTRATION_WORKSPACE',
                duration_min=duration,
                priority=priority,
                waiting_list=False,
                notes=(request.form.get('notes') or '').strip(),
                created_by=current_user().id,
            )
            db.session.add(a); db.session.flush(); appts.append(a)
            _rb_v5462_insurance(o,contract,request.form)
            _rb_v5462_notes(o,request.form)
            ensure_journey(o,'REGISTERED')
            for pc in ProcedureConsumable.query.filter_by(procedure_id=p.id).all():
                db.session.add(OrderConsumable(
                    order_id=o.id,consumable_id=pc.consumable_id,qty=pc.qty,
                    source='DEFAULT',created_by=current_user().id
                ))
            # RB_WORK_ORDER_GATE_V1
            # Registration creates the clinical order only.
            # MWL is created later by explicit Convert to Work Order.
            orders.append(o); cursor+=timedelta(minutes=duration)

        first=orders[0]
        saved+=_rb_v5462_direct_attachments(patient,order=first)
        _rb_v5462_attach_ocr(patient,request.form.get('ocr_intake_id',type=int),order=first)
        _rb_v5462_payment(orders,request.form)
        audit('FULL_REGISTRATION_CREATE','order',first.id,f'patient={patient.id}; exams={len(orders)}')
        db.session.commit()

        # RB_WORK_ORDER_GATE_V1
        # Do not create MWL during registration.
        # Orders remain REGISTERED until an authorized employee
        # explicitly converts them to Work Orders.
        flash(f'Registered {len(orders)} examination(s) for {patient.name}.','success')
        return _rb_calendar_redirect(scheduled,branch.id,device.id)

    except ValueError as exc:
        db.session.rollback()
        for p in saved:
            try:
                if os.path.isfile(p): os.remove(p)
            except Exception: pass
        flash(str(exc),'danger')
        return redirect(url_for('schedule_calendar'))


@app.post('/schedule/book')
@require_perm('appointments.manage')
def schedule_book():
    try: scheduled=datetime.fromisoformat((request.form.get('scheduled') or '').strip())
    except Exception:
        flash('Invalid booking date/time.','danger');return redirect(url_for('schedule_calendar'))
    branch_id=request.form.get('branch_id',type=int);device_id=request.form.get('device_id',type=int)
    if not branch_id or not device_id:
        flash('Branch and device are required.','danger');return _rb_calendar_redirect(scheduled,branch_id,device_id)
    branch=Branch.query.get_or_404(branch_id);device=Device.query.get_or_404(device_id)
    if device.branch_id!=branch.id:
        flash('Selected device does not belong to the selected branch.','danger');return _rb_calendar_redirect(scheduled,branch.id,device.id)
    procedure_ids=[]
    for raw in request.form.getlist('procedure_ids'):
        try: pid=int(raw)
        except Exception: continue
        if pid not in procedure_ids:procedure_ids.append(pid)
    if not procedure_ids:
        one=request.form.get('procedure_id',type=int)
        if one:procedure_ids=[one]
    if not procedure_ids:
        flash('Add at least one examination.','danger');return _rb_calendar_redirect(scheduled,branch.id,device.id)
    procedures=[]
    for pid in procedure_ids:
        proc=Procedure.query.get_or_404(pid)
        if (proc.modality or '').upper()!=(device.modality or '').upper():
            flash(f'{proc.name} is not compatible with {device.name}.','danger');return _rb_calendar_redirect(scheduled,branch.id,device.id)
        if not procedure_available_in_branch(proc.id,branch.id):
            flash(f'{proc.name} is not available in this branch.','danger');return _rb_calendar_redirect(scheduled,branch.id,device.id)
        procedures.append(proc)
    mode=(request.form.get('patient_mode') or 'existing').strip().lower()
    try:
        if mode=='new':patient=_rb_registration_v2_create_patient(request.form,'PATIENT_CREATE_FROM_UNIFIED_BOOKING')
        else:
            patient_id=request.form.get('patient_id',type=int)
            if not patient_id:raise ValueError('Choose an existing patient or select New Patient.')
            patient=Patient.query.get_or_404(patient_id)
    except ValueError as exc:
        db.session.rollback();flash(str(exc),'danger');return _rb_calendar_redirect(scheduled,branch.id,device.id)
    waiting=request.form.get('waiting_list')=='1';priority=(request.form.get('priority') or 'NORMAL').upper();notes=(request.form.get('notes') or '').strip()
    cursor=scheduled;created=[]
    try:
        for proc in procedures:
            duration=max(5,int(proc.duration_min or 20))
            if not waiting:
                acquire_booking_slot_lock(device.id,cursor)
                reason=booking_restriction_reason(branch,proc,device,cursor,duration)
                if reason:raise ValueError(f'{proc.name}: {reason}')
            duplicate=Appointment.query.filter_by(patient_id=patient.id,procedure_id=proc.id,scheduled=cursor).filter(Appointment.status!='CANCELLED').first()
            if duplicate:raise ValueError(f'Duplicate booking exists for {proc.name} at {cursor.strftime("%H:%M")}.')
            appt=Appointment(patient_id=patient.id,branch_id=branch.id,procedure_id=proc.id,device_id=device.id,scheduled=cursor,
                status='WAITING' if waiting else 'BOOKED',source='UNIFIED_CALENDAR',duration_min=duration,priority=priority,waiting_list=waiting,notes=notes,created_by=current_user().id)
            db.session.add(appt);db.session.flush()
            audit('APPOINTMENT_CREATE_UNIFIED','appointment',appt.id,f'{patient.patient_id}; device={device.id}; procedure={proc.id}; {cursor.isoformat()}; duration={duration}')
            created.append(appt);cursor+=timedelta(minutes=duration)
        db.session.commit()
    except Exception as exc:
        db.session.rollback();flash(str(exc),'danger');return _rb_calendar_redirect(scheduled,branch.id,device.id)
    total=sum(int(a.duration_min or 0) for a in created)
    flash(f'Booked {len(created)} examination(s) for {patient.name}. Total duration: {total} min.','success')
    return _rb_calendar_redirect(scheduled,branch.id,device.id)

@app.post('/orders/<int:order_id>/workflow-status')
@login_required
def order_workflow_status(order_id):
    order=Order.query.get_or_404(order_id)
    target=(request.form.get('status') or '').strip().upper().replace(' ','_')
    allowed={'BOOKED','ORDERED','IN_PROGRESS','REPORTING','VERIFIED','FINAL'}
    if target not in allowed:
        abort(400)

    # Preserve current order/report schema. Store workflow state only when a compatible
    # existing field is available; otherwise derive it from existing clinical state.
    if hasattr(order,'workflow_status'):
        order.workflow_status=target
    elif hasattr(order,'status'):
        order.status=target

    # For reporting states, keep report approval logic authoritative.
    if target in {'REPORTING','VERIFIED','FINAL'}:
        report=Report.query.filter_by(order_id=order.id).order_by(Report.id.desc()).first()
        if report and target in {'VERIFIED','FINAL'}:
            # Do not bypass existing approval rules; only mirror if already compatible.
            if target=='VERIFIED' and (report.status or '').upper() in {'VERIFIED','SECOND_VERIFIED','FINAL'}:
                pass
            elif target=='FINAL' and (report.status or '').upper()=='FINAL':
                pass

    db.session.commit()
    flash('Workflow status updated.','success')
    return redirect(request.referrer or url_for('schedule_calendar'))


