@app.route('/appointments/<int:appointment_id>/<action>', methods=['POST'])
@require_perm('appointments.manage')
def appointment_action(appointment_id, action):
    a=Appointment.query.get_or_404(appointment_id)

    if action=='confirm':
        a.status='CONFIRMED'
        a.confirmed_at=datetime.utcnow()
    elif action=='cancel':
        a.status='CANCELLED'
        a.cancelled_at=datetime.utcnow()
    elif action=='noshow':
        a.status='NO_SHOW'
    elif action=='checkin':
        proc=a.procedure
        device=a.device or route_device(a.branch_id,proc.modality)
        if not device:
            flash(f'No active {proc.modality} device is configured for this branch.','danger')
            return redirect(url_for('appointments'))

        # Prevent accidental duplicate order from repeated Check-in.
        existing=Order.query.filter_by(patient_id=a.patient_id,procedure_id=a.procedure_id,scheduled=a.scheduled).first()
        if existing:
            a.status='ARRIVED'
            a.checked_in_at=a.checked_in_at or datetime.utcnow()
            db.session.commit()
            return redirect(url_for('order_detail',order_id=existing.id))

        gross,contract_price,patient_share,company_share,_=price_order(proc,None)
        order=Order(
            accession=new_accession(),
            patient_id=a.patient_id,
            procedure_id=proc.id,
            branch_id=a.branch_id,
            device_id=device.id,
            modality=proc.modality,
            procedure=proc.name,
            station_ae=device.ae_title,
            scheduled=a.scheduled,
            # RB_WORK_ORDER_GATE_V2
            # Check-in creates a registered clinical order only.
            # MWL waits for explicit Work Order conversion.
            status='REGISTERED',
            gross_price=gross,
            contract_price=contract_price,
            patient_share=patient_share,
            company_share=company_share,
            paid_amount=0,
            created_by=current_user().id
        )
        db.session.add(order)
        db.session.flush()

        # RB_WORK_ORDER_GATE_V2
        # Patient arrival is retained on the appointment,
        # while MWL creation is deferred to Convert to Work Order.
        a.status='ARRIVED'
        a.checked_in_at=datetime.utcnow()
        audit('APPOINTMENT_CHECKIN','appointment',a.id,order.accession)
        db.session.commit()
        flash(f'Patient checked in. Accession: {order.accession}','success')
        return redirect(url_for('order_detail',order_id=order.id))
    else:
        abort(400)

    audit('APPOINTMENT_'+action.upper(),'appointment',a.id,a.status)
    db.session.commit()
    flash('Appointment updated successfully.','success')
    return redirect(url_for('appointments'))



@app.post('/appointments/<int:appointment_id>/reschedule')
@require_perm('appointments.manage')
def appointment_reschedule(appointment_id):
    a=Appointment.query.get_or_404(appointment_id)
    if a.status in ('ARRIVED','ORDERED','IN_PROGRESS','EXAM_COMPLETED','REPORTING','VERIFIED','FINAL'):
        return jsonify({'ok':False,'error':'Clinical workflow already started'}),409
    try:new_time=datetime.fromisoformat(request.form.get('scheduled',''))
    except Exception:return jsonify({'ok':False,'error':'Invalid date/time'}),400
    device_id=request.form.get('device_id',type=int) or a.device_id
    device=Device.query.get_or_404(device_id)
    if device.branch_id!=a.branch_id or device.modality.upper()!=a.procedure.modality.upper():
        return jsonify({'ok':False,'error':'Device/branch/modality mismatch'}),400
    acquire_booking_slot_lock(device.id,new_time)
    conflict=appointment_overlap(device.id,new_time,a.duration_min or a.procedure.duration_min,exclude_id=a.id)
    if conflict:return jsonify({'ok':False,'error':f'Conflicts with appointment #{conflict.id}'}),409
    old=a.scheduled
    a.scheduled=new_time;a.device_id=device.id
    audit('APPOINTMENT_RESCHEDULE','appointment',a.id,f'{old}->{new_time}; device={device.id}')
    db.session.commit()
    return jsonify({'ok':True})

