@app.post('/schedule/v2/book')
@require_perm('appointments.manage')
def schedule_v2_book_submit():
    # Legacy-compatible POST path.
    # Keep the central booking safety contract in place even though
    # the visible UI is now unified on /schedule/calendar.
    try:
        scheduled=datetime.fromisoformat(request.form.get('scheduled') or '')
    except Exception:
        flash('Invalid date/time.','danger')
        return redirect(url_for('schedule_calendar'))

    device=Device.query.get_or_404(request.form.get('device_id',type=int))
    proc=Procedure.query.get_or_404(request.form.get('procedure_id',type=int))
    branch=Branch.query.get_or_404(request.form.get('branch_id',type=int))

    duration=max(5,int(proc.duration_min or 20))

    reason=booking_restriction_reason(
        branch,
        proc,
        device,
        scheduled,
        duration
    )
    if reason:
        flash(f'Booking blocked: {reason}','danger')
        return redirect(url_for(
            'schedule_calendar',
            date=scheduled.date().isoformat(),
            branch_id=branch.id,
            device_id=device.id
        ))

    # Reuse the unified booking endpoint instead of maintaining
    # a second registration/booking implementation.
    return schedule_book()

