def operations_dashboard():
    kind=role_dashboard_kind();today=datetime.now().date();start=datetime.combine(today,datetime.min.time());end=start+timedelta(days=1)
    orders=Order.query.filter(Order.scheduled>=start,Order.scheduled<end).all();waiting=[];delayed=[];unreported=[]
    for o in orders:
        snap=journey_snapshot(o);st=snap['stage']
        if st in ('WAITING','NURSING','TECHNICIAN'):waiting.append(o)
        if st in ('EXAM_DONE','PACS_RECEIVED','REPORTING'):unreported.append(o)
        if snap['current'] and (datetime.utcnow()-snap['current'].entered_at).total_seconds()>3600:delayed.append(o)
    cash=refund=0.0
    if kind in ('CASHIER','MANAGEMENT'):
        cash=sum(float(x.amount or 0) for x in Payment.query.filter(Payment.created_at>=start,Payment.created_at<end).all())
        refund=sum(float(x.amount or 0) for x in PaymentRefund.query.filter(PaymentRefund.created_at>=start,PaymentRefund.created_at<end).all())
    return render_template('operations_dashboard.html',kind=kind,today_orders=orders,waiting=waiting,delayed=delayed,unreported=unreported,cash_total=cash,refund_total=refund,unread_chat=unread_chat_count())

