    title=(request.form.get('title') or '').strip();ids=[int(x) for x in request.form.getlist('user_ids') if str(x).isdigit()]
    if not title:return redirect(url_for('chat_home'))
    thread=ChatThread(thread_type='GROUP',title=title,created_by=current_user().id);db.session.add(thread);db.session.flush();ensure_chat_member(thread,current_user().id)
