@app.route('/chat/<int:thread_id>',methods=['GET','POST'])
@login_required
def chat_thread(thread_id):
    thread=ChatThread.query.get_or_404(thread_id);member=ChatThreadMember.query.filter_by(thread_id=thread.id,user_id=current_user().id).first()
    if not member:abort(403)
    if request.method=='POST':
        body=(request.form.get('body') or '').strip();f=request.files.get('attachment');path=name=''
        if f and f.filename:
            ext=os.path.splitext(f.filename)[1].lower()
            if ext not in ('.pdf','.jpg','.jpeg','.png','.doc','.docx','.txt'):abort(400)
            folder=os.path.join(ATTACHMENT_DIR,'chat',str(thread.id));os.makedirs(folder,exist_ok=True);safe=re.sub(r'[^A-Za-z0-9._-]','_',f.filename);path=os.path.join(folder,f'{int(datetime.utcnow().timestamp())}_{safe}');f.save(path);name=f.filename
        if body or path:db.session.add(ChatMessage(thread_id=thread.id,sender_id=current_user().id,body=body or '[Attachment]',attachment_path=path,attachment_name=name));member.last_read_at=datetime.utcnow();db.session.commit()
        return redirect(url_for('chat_thread',thread_id=thread.id))
    member.last_read_at=datetime.utcnow();db.session.commit();msgs=ChatMessage.query.filter_by(thread_id=thread.id).filter(ChatMessage.deleted_at.is_(None)).order_by(ChatMessage.created_at).limit(500).all()
    return render_template('chat_thread.html',thread=thread,messages=msgs)

@app.post('/chat/<int:thread_id>/add-to-clinical-note/<int:message_id>')
@require_perm('orders.view')
def chat_message_to_clinical_note(thread_id,message_id):
    thread=ChatThread.query.get_or_404(thread_id);msg=ChatMessage.query.get_or_404(message_id)
    if thread.thread_type!='CASE' or not thread.order_id:abort(400)
    db.session.add(ClinicalNote(order_id=thread.order_id,author_user_id=current_user().id,note_type='GENERAL',visibility='CLINICAL_TEAM',text=msg.body));audit('CHAT_TO_CLINICAL_NOTE','order',thread.order_id,f'message={msg.id}');db.session.commit();return redirect(url_for('chat_thread',thread_id=thread.id))


@app.route('/patients/<int:patient_id>/documents',methods=['GET','POST'])
@login_required
def patient_documents(patient_id):
    patient=Patient.query.get_or_404(patient_id)
    if request.method=='POST':
        f=request.files.get('file')
        dtype=(request.form.get('document_type') or 'OTHER').upper()
        if dtype not in DOCUMENT_TYPES or not f or not f.filename:
            flash('Document type and file are required.','danger')
            return redirect(url_for('patient_documents',patient_id=patient.id))
        ext=os.path.splitext(f.filename)[1].lower()
        if ext not in ('.pdf','.jpg','.jpeg','.png','.doc','.docx','.txt'):
            flash('Unsupported document type.','danger')
            return redirect(url_for('patient_documents',patient_id=patient.id))
        folder=os.path.join(ATTACHMENT_DIR,'patient-documents',str(patient.id))
        os.makedirs(folder,exist_ok=True)
        stored_name=generated_attachment_filename(intake.id,dtype,f.filename)
        path=os.path.join(folder,stored_name)
        f.save(path)
        order_id=request.form.get('order_id',type=int)
        text,status=extract_document_text_basic(path)
        meta=DOCUMENT_TYPES[dtype]
        doc=PatientDocument(
          patient_id=patient.id,order_id=order_id,document_type=dtype,category=meta[2],
          reference_no=(request.form.get('reference_no') or '').strip(),
          file_path=path,original_name=f.filename,extracted_text=text,
          extraction_status=status,uploaded_by=current_user().id
        )
        db.session.add(doc);db.session.flush()
        build_document_matches(doc)
        audit('PATIENT_DOCUMENT_UPLOAD','patient',patient.id,f'{dtype}:{doc.id}')
        db.session.commit()
        flash('Document uploaded.','success')
        return redirect(url_for('patient_documents',patient_id=patient.id))
    docs=PatientDocument.query.filter_by(patient_id=patient.id).order_by(PatientDocument.created_at.desc()).all()
    orders=Order.query.filter_by(patient_id=patient.id).order_by(Order.id.desc()).all()
    return render_template('patient_documents.html',patient=patient,documents=docs,orders=orders,document_types=DOCUMENT_TYPES)

