def analytics_query():
    q=Order.query
    start=request.args.get('start','').strip()
    end=request.args.get('end','').strip()
    branch_id=request.args.get('branch_id',type=int)
    modality=request.args.get('modality','').strip()
    contract_id=request.args.get('contract_id',type=int)
    if start:
        q=q.filter(Order.scheduled >= datetime.fromisoformat(start))
    if end:
        q=q.filter(Order.scheduled < datetime.fromisoformat(end) + __import__('datetime').timedelta(days=1))
    if branch_id: q=q.filter(Order.branch_id==branch_id)
    if modality: q=q.filter(Order.modality==modality)
    if contract_id: q=q.filter(Order.contract_id==contract_id)
    return q

@require_perm('analytics.view')
def analytics():
    q=analytics_query()
    rows=q.order_by(Order.scheduled.desc()).limit(5000).all()

    total=len(rows)
    gross=sum(float(x.contract_price or x.gross_price or 0) for x in rows)
    patient_share=sum(float(x.patient_share or 0) for x in rows)
    company_share=sum(float(x.company_share or 0) for x in rows)
    paid=sum(float(x.paid_amount or 0) for x in rows)
    outstanding=sum(max(order_balance(x),0) for x in rows)

    by_mod={}
    by_status={}
    by_proc={}
    by_branch={}
    for x in rows:
        mod=x.modality or 'OTHER'
        by_mod[mod]=by_mod.get(mod,0)+1

        status=x.status or 'UNKNOWN'
        by_status[status]=by_status.get(status,0)+1

        key=(x.proc.name if x.proc else x.procedure) or 'Unknown'
        by_proc[key]=by_proc.get(key,0)+1

        branch=(x.branch.name if x.branch else 'No Branch')
        by_branch[branch]=by_branch.get(branch,0)+1

    top_procs=sorted(by_proc.items(), key=lambda z:z[1], reverse=True)[:15]

    # Report turnaround time: scheduled study time -> final report time.
    tats=[]
    for x in rows:
        if x.report and x.report.finalized_at and x.scheduled:
            try:
                hours=(x.report.finalized_at-x.scheduled).total_seconds()/3600.0
                if hours >= 0:
                    tats.append(hours)
            except Exception:
                pass
    avg_tat=(sum(tats)/len(tats)) if tats else 0.0

    # Consumables cost for the currently filtered orders.
    consumable_cost=0.0
    order_ids=[x.id for x in rows]
    if order_ids:
        usages=OrderConsumable.query.filter(OrderConsumable.order_id.in_(order_ids)).all()
        for u in usages:
            try:
                consumable_cost += float(u.qty or 0) * float(u.consumable.unit_cost or 0)
            except Exception:
                pass

    # Appointment statistics honor date / branch filters where applicable.
    aq=Appointment.query
    start=request.args.get('start','').strip()
    end=request.args.get('end','').strip()
    branch_id=request.args.get('branch_id',type=int)

    if start:
        aq=aq.filter(Appointment.scheduled >= datetime.fromisoformat(start))
    if end:
        aq=aq.filter(Appointment.scheduled < datetime.fromisoformat(end) + timedelta(days=1))
    if branch_id:
        aq=aq.filter(Appointment.branch_id == branch_id)

    appointment_stats={}
    for a in aq.all():
        status=a.status or 'UNKNOWN'
        appointment_stats[status]=appointment_stats.get(status,0)+1

    return render_template(
        'analytics.html',
        rows=rows,
        total=total,
        gross=gross,
        patient_share=patient_share,
        company_share=company_share,
        paid=paid,
        outstanding=outstanding,
        avg_tat=avg_tat,
        consumable_cost=consumable_cost,
        appointment_stats=appointment_stats,
        by_mod=sorted(by_mod.items()),
        by_status=sorted(by_status.items()),
        by_branch=sorted(by_branch.items(), key=lambda z:z[1], reverse=True),
        top_procs=top_procs,
        branches=Branch.query.order_by(Branch.name).all(),
        contracts=Contract.query.order_by(Contract.name).all()
    )

@require_perm('export.view')
def analytics_export_csv():
    rows=analytics_query().order_by(Order.scheduled.desc()).all()
    s=io.StringIO(); w=csv.writer(s)
    w.writerow(['Accession','Patient ID','Patient','Scheduled','Branch','Modality','Procedure','Contract','Gross/Contract Price','Patient Share','Company Share','Paid','Status'])
    for x in rows:
        w.writerow([x.accession,x.patient.patient_id,x.patient.name,x.scheduled.isoformat(sep=' '),
            x.branch.name if x.branch else '',x.modality,x.proc.name if x.proc else x.procedure,
            x.contract.name if x.contract else 'Cash / Private',
            x.contract_price or x.gross_price or 0,x.patient_share or 0,x.company_share or 0,x.paid_amount or 0,x.status])
    return send_file(io.BytesIO(s.getvalue().encode('utf-8-sig')),as_attachment=True,
        download_name='ris-analytics.csv',mimetype='text/csv; charset=utf-8')

@app.route('/admin/import-export', methods=['GET','POST'])
@login_required
def admin_import_export():
    if request.method == 'GET':
        if not (
            has_perm('*')
            or has_perm('import.manage')
            or has_perm('export.view')
        ):
            abort(403)

    if request.method=='POST':
        if not has_perm('import.manage'): abort(403)
        entity=request.form.get('entity')
        f=request.files.get('file')
        if not f: flash('Choose a CSV file.','danger'); return redirect(url_for('admin_import_export'))
        text_data=f.stream.read().decode('utf-8-sig',errors='replace')
        reader=csv.DictReader(io.StringIO(text_data))
        inserted=updated=errors=0
        for row in reader:
            try:
                if entity=='procedures':
                    code=(row.get('code') or '').strip().upper()
                    if not code: raise ValueError('code required')
                    p=Procedure.query.filter_by(code=code).first()
                    if not p:
                        p=Procedure(code=code); db.session.add(p); inserted+=1
                    else: updated+=1
                    p.name=(row.get('name') or code).strip()
                    p.name_ar=(row.get('name_ar') or '').strip()
                    p.category=(row.get('category') or '').strip()
                    p.modality=(row.get('modality') or 'OT').strip().upper()
                    p.body_part=(row.get('body_part') or '').strip()
                    p.base_price=float(row.get('base_price') or 0)
                    p.duration_min=int(float(row.get('duration_min') or 20))
                    p.contrast=str(row.get('contrast') or '').strip().lower() in ('1','true','yes','y')
                    p.active=True
                elif entity=='contracts':
                    code=(row.get('code') or '').strip().upper()
                    if not code: raise ValueError('code required')
                    c=Contract.query.filter_by(code=code).first()
                    if not c:
                        c=Contract(code=code); db.session.add(c); inserted+=1
                    else: updated+=1
                    c.name=(row.get('name') or code).strip()
                    c.patient_share_percent=float(row.get('patient_share_percent') or 0)
                    c.discount_percent=float(row.get('discount_percent') or 0)
                    c.approval_required=str(row.get('approval_required') or '').strip().lower() in ('1','true','yes','y')
                    c.active=True
                elif entity=='consumables':
                    code=(row.get('code') or '').strip().upper()
                    if not code: raise ValueError('code required')
                    c=Consumable.query.filter_by(code=code).first()
                    if not c:
                        c=Consumable(code=code); db.session.add(c); inserted+=1
                    else: updated+=1
                    c.name=(row.get('name') or code).strip()
                    c.unit=(row.get('unit') or 'unit').strip()
                    c.stock_qty=float(row.get('stock_qty') or 0)
                    c.reorder_level=float(row.get('reorder_level') or 0)
                    c.unit_cost=float(row.get('unit_cost') or 0)
                    c.active=True
                else:
                    raise ValueError('unsupported entity')
            except Exception:
                errors+=1
        db.session.commit(); audit('IMPORT',entity,'',f'inserted={inserted} updated={updated} errors={errors}')
        db.session.commit(); flash(f'Import complete: {inserted} inserted, {updated} updated, {errors} errors.','success')
        return redirect(url_for('admin_import_export'))
    return render_template('admin_import_export.html')

@app.route('/admin/export/<entity>.csv')
@login_required
def admin_export_entity(entity):
    if not has_perm('export.view') and not has_perm('*'): abort(403)
    s=io.StringIO(); w=csv.writer(s)
    if entity=='procedures':
        w.writerow(['code','name','name_ar','category','modality','body_part','base_price','duration_min','contrast'])
        for p in Procedure.query.order_by(Procedure.modality,Procedure.name):
            w.writerow([p.code,p.name,p.name_ar,p.category,p.modality,p.body_part,p.base_price,p.duration_min,int(bool(p.contrast))])
    elif entity=='contracts':
        w.writerow(['code','name','patient_share_percent','discount_percent','approval_required'])
        for c in Contract.query.order_by(Contract.name):
            w.writerow([c.code,c.name,c.patient_share_percent,c.discount_percent,int(bool(c.approval_required))])
    elif entity=='consumables':
        w.writerow(['code','name','unit','stock_qty','reorder_level','unit_cost'])
        for c in Consumable.query.order_by(Consumable.name):
            w.writerow([c.code,c.name,c.unit,c.stock_qty,c.reorder_level,c.unit_cost])
    elif entity=='devices':
        w.writerow(['branch','name','modality','ae_title','ip','port','room','priority','active'])
        for d in Device.query.order_by(Device.branch_id,Device.modality,Device.priority):
            w.writerow([d.branch.name if d.branch else '',d.name,d.modality,d.ae_title,d.ip,d.port,d.room,d.priority,int(bool(d.active))])
    else:
        abort(404)
    return send_file(io.BytesIO(s.getvalue().encode('utf-8-sig')),as_attachment=True,
        download_name=f'{entity}.csv',mimetype='text/csv; charset=utf-8')

@app.route('/reports/<int:order_id>/upload',methods=['POST'])
@require_perm('reports.edit')
def report_upload(order_id):
    order=Order.query.get_or_404(order_id)
    report=get_report(order)
    user=current_user()

    try:
        assert_not_final(report)
        assert_role_allowed(user,'DRAFT')

        lease_token=str(
            request.form.get('lease_token') or
            request.headers.get('X-RadBridge-Report-Lease') or
            ''
        ).strip()

        assert_lease_owner(
            db=db,
            order=order,
            report=report,
            user=user,
            lease_token=lease_token,
        )

    except ReportEditControlError as exc:
        code=getattr(exc,'code',type(exc).__name__)

        try:
            audit(
                'REPORT_EDIT_DENIED',
                'order',
                order.id,
                f'action=DRAFT; editor=UPLOAD; code={code}; user={user.id}'
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        flash(
            'Report upload is currently blocked.',
            'danger'
        )

        return redirect(
            url_for('report_editor',order_id=order.id)
        )

    if (report.status or '').upper()=='FINAL':
        flash(
            'This report is FINAL. '
            'A dedicated Addendum workflow is required.',
            'danger'
        )
        return redirect(
            url_for('report_editor',order_id=order.id)
        )

    # Upload is content ingestion only.
    # Verification and Finalization are separate explicit actions.
    target=request.form.get(
        'action',
        'DRAFT'
    ).upper().strip()

    if target!='DRAFT':
        flash(
            'Manual upload can create a DRAFT only. '
            'Verify and Finalize separately.',
            'danger'
        )
        return redirect(
            url_for('report_editor',order_id=order.id)
        )

    f=request.files.get('document')

    if not f or not f.filename:
        flash(
            'Choose a report file first.',
            'danger'
        )
        return redirect(
            url_for('report_editor',order_id=order.id)
        )

    # Unified writer is currently validated for DOCX clinical content.
    ext=os.path.splitext(
        f.filename
    )[1].lower()

    if ext!='.docx':
        flash(
            'Manual unified upload currently accepts DOCX only.',
            'danger'
        )
        return redirect(
            url_for('report_editor',order_id=order.id)
        )

    base_raw=request.form.get(
        'base_version_no',
        ''
    ).strip()

    commit_id=request.form.get(
        'commit_id',
        ''
    ).strip()

    if not base_raw or not commit_id:
        flash(
            'Report version context is missing. Reload the report.',
            'danger'
        )
        return redirect(
            url_for('report_editor',order_id=order.id)
        )

    try:
        base_version_no=int(base_raw)
    except Exception:
        flash(
            'Invalid report version context. Reload the report.',
            'danger'
        )
        return redirect(
            url_for('report_editor',order_id=order.id)
        )

    tmpdir=tempfile.mkdtemp(
        prefix='ris-upload-'
    )

    tmppath=os.path.join(
        tmpdir,
        'upload.docx'
    )

    try:
        f.save(tmppath)

        safety=validate_report_patient_file(
            order,
            tmppath,
            ext
        )

        audit(
            'REPORT_PATIENT_SAFETY',
            'order',
            order.id,
            (
                f'{safety["result"]} '
                f'expected_pid={safety["expected_patient_id"]} '
                f'found_pid={safety["found_patient_id"]} '
                f'expected_acc={safety["expected_accession"]} '
                f'found_acc={safety["found_accession"]}'
            )
        )

        db.session.commit()

        if safety['result']=='BLOCKED':
            flash(
                'PATIENT MISMATCH — upload blocked.',
                'danger'
            )
            return redirect(
                url_for(
                    'report_editor',
                    order_id=order.id
                )
            )

        override=(
            request.form.get(
                'safety_override'
            )=='1'
        )

        if (
            safety['result']=='WARNING'
            and not override
        ):
            flash(
                'Patient safety warning — review the '
                'document identifiers and confirm before upload.',
                'warning'
            )
            return redirect(
                url_for(
                    'report_editor',
                    order_id=order.id
                )
            )

        latest=(
            ReportVersion.query
            .filter_by(report_id=report.id)
            .order_by(ReportVersion.version_no.desc())
            .first()
        )

        latest_no=(
            int(latest.version_no)
            if latest
            else 0
        )

        if base_version_no != latest_no:
            flash(
                'This report changed after the page was opened. '
                'Reload before uploading.',
                'danger'
            )
            return redirect(
                url_for(
                    'report_editor',
                    order_id=order.id
                )
            )

        findings,impression,radiologist = \
            extract_docx_sections(tmppath)

        user=current_user()

        if not user:
            abort(403)

        from report_transaction_writer import \
            commit_report_version

        result=commit_report_version(
            db=db,
            Report=Report,
            ReportVersion=ReportVersion,
            report_root=REPORT_DIR,
            order=order,
            patient=order.patient,
            user=user,
            editor_type='UPLOAD',
            requested_status='DRAFT',
            source_file=tmppath,
            base_version_no=base_version_no,
            commit_id=commit_id,
            findings=findings or '',
            impression=impression or '',
            radiologist=(
                radiologist
                or user.full_name
                or user.username
                or 'Unknown'
            ),
            change_summary='Manual DOCX Upload Draft',
        )

        audit(
            'REPORT_UPLOAD_DRAFT',
            'order',
            order.id,
            (
                f'version={result.get("version_no")}; '
                f'patient_safety={safety["result"]}; '
                f'commit_id={commit_id}'
            )
        )

        db.session.commit()

        flash(
            'Report uploaded as DRAFT. '
            'Verify and Finalize separately.',
            'success'
        )

        return redirect(
            url_for(
                'report_editor',
                order_id=order.id
            )
        )

    except Exception:
        db.session.rollback()

        eid=(
            _error_id()
            if '_error_id' in globals()
            else 'UPLOAD-ERROR'
        )

        app.logger.exception(
            'Report upload failed %s',
            eid
        )

        flash(
            f'Report upload failed. Error ID: {eid}',
            'danger'
        )

        return redirect(
            url_for(
                'report_editor',
                order_id=order.id
            )
        )

    finally:
        shutil.rmtree(
            tmpdir,
            ignore_errors=True
        )


@app.route('/reports/<int:order_id>/source')
@require_perm('reports.view')
def report_source(order_id):
    order=Order.query.get_or_404(order_id)
    report=get_report(order)

    # In normal workflow, expose the currently finalized report only.
    path=None
    if report.status=='FINAL':
        path=report.source_path or report.docx_path or report.pdf_path
    else:
        path=report.source_path or report.docx_path or report.pdf_path

    if not path or not os.path.exists(path):
        abort(404)

    ext=os.path.splitext(path)[1].lstrip('.') or 'bin'
    history=ReportVersion.query.filter_by(report_id=report.id).order_by(ReportVersion.version_no.desc()).all()
    version_no=history[0].version_no if history else 1
    filename=report_filename(order,version_no,report.status,ext)
    return send_file(path,as_attachment=True,download_name=filename)


@app.route('/attachments/upload',methods=['POST'])
@require_perm('attachments.upload')
def attachment_upload():
    files=request.files.getlist('files') or request.files.getlist('file')
    files=[f for f in files if f and f.filename]
    if not files:
        flash('Choose one or more files.','danger')
        return redirect(request.referrer or url_for('dashboard'))
    patient_id=request.form.get('patient_id',type=int)
    order_id=request.form.get('order_id',type=int)
    appointment_id=request.form.get('appointment_id',type=int)
    category=(request.form.get('category') or 'OTHER').upper()
    notes=(request.form.get('notes') or '').strip()
    folder=os.path.join(ATTACHMENT_DIR,str(patient_id or 'general'),str(order_id or appointment_id or 'misc'))
    os.makedirs(folder,exist_ok=True)
    allowed_exts=('.pdf','.jpg','.jpeg','.png','.doc','.docx','.odt','.dcm','.dicom','.zip')
    saved=0
    for idx,f in enumerate(files):
        ext=os.path.splitext(f.filename)[1].lower()
        if ext not in allowed_exts:
            flash(f'Unsupported attachment type: {f.filename}','danger')
            continue
        stored_name=generated_attachment_filename(order_id,category,f.filename)
        path=os.path.join(folder,stored_name)
        f.save(path)
        a=Attachment(patient_id=patient_id,order_id=order_id,appointment_id=appointment_id,
            category=category,original_name=f.filename,stored_path=path,
            mime_type=f.mimetype or '',notes=notes,uploaded_by=current_user().id)
        db.session.add(a); audit('ATTACHMENT_UPLOAD','attachment','',f'{category}:{f.filename}')
        saved+=1
    db.session.commit()
    flash(f'{saved} attachment(s) uploaded.','success')
    return redirect(request.referrer or url_for('dashboard'))

