@app.route('/orders/<int:order_id>/sticker')
@require_perm('orders.view')
def order_sticker(order_id):
    order=Order.query.get_or_404(order_id)
    template=get_default_sticker_template();profile=get_company_profile()
    portal_url=_portal_url_for_order(order);db.session.commit()
    from reportlab.lib.units import mm
    from reportlab.lib.utils import ImageReader
    width=float(template.width_mm or 70)*mm;height=float(template.height_mm or 45)*mm
    buf=io.BytesIO();c=canvas.Canvas(buf,pagesize=(width,height));c.setTitle(f"Sticker {order.accession}")
    c.setFont('Helvetica-Bold',8);c.drawString(4*mm,height-6*mm,(profile.name_en or 'RIS')[:38])
    fields=_sticker_fields(template);labels=_sticker_labels(template);top=height-12*mm;line=4.2*mm
    for idx,key in enumerate(fields[:7]):
        y=top-idx*line;c.setFont('Helvetica-Bold',5.5);c.drawString(4*mm,y,(labels.get(key) or {}).get('en',key)+':')
        c.setFont('Helvetica',6.4);c.drawString(22*mm,y,_sticker_value(order,key)[:30])
    if template.show_qr:
        qr=qrcode.QRCode(version=3,box_size=4,border=1);qr.add_data(portal_url);qr.make(fit=True)
        img=qr.make_image(fill_color="black",back_color="white");qbuf=io.BytesIO();img.save(qbuf,format='PNG');qbuf.seek(0)
        size=min(21*mm,height-15*mm);c.drawImage(ImageReader(qbuf),width-size-3*mm,10*mm,size,size,mask='auto')
    if template.show_barcode:
        bc=code128.Code128(order.accession,barHeight=6*mm,barWidth=.22*mm);bc.drawOn(c,4*mm,3*mm)
    c.setFont('Helvetica',5);c.drawRightString(width-3*mm,3*mm,'Scan QR for Results & Images')
    c.showPage();c.save();buf.seek(0)
    return send_file(buf,as_attachment=False,download_name=f'{order.accession}-sticker.pdf',mimetype='application/pdf')

