@app.route('/pacs/reconciliation')
@require_perm('orders.view')
def pacs_reconciliation():
    exceptions=PacsStudyInbox.query.filter_by(
        state='REVIEW_REQUIRED'
    ).order_by(PacsStudyInbox.first_seen_at.desc()).all()

    rows=[]

    for inbox in exceptions:
        candidate=None

        # Candidate 1: exact RIS accession
        if inbox.accession:
            candidate=Order.query.filter_by(
                accession=inbox.accession
            ).first()

        # Candidate 2: unique RIS Patient ID - suggestion only
        if not candidate and inbox.pacs_patient_id:
            patient=Patient.query.filter_by(
                patient_id=inbox.pacs_patient_id
            ).first()

            if patient:
                candidates=Order.query.filter_by(
                    patient_id=patient.id
                ).order_by(Order.id.desc()).limit(10).all()

                if len(candidates)==1:
                    candidate=candidates[0]

        rows.append({
            'inbox':inbox,
            'candidate':candidate,
            'ris_patient':candidate.patient if candidate else None,
        })

    # Exam Linking deliberately remains separate from the authoritative
    # primary PACS match. Only same-patient, editable secondary orders are
    # offered; the service repeats every check under row locks.
    primary_orders=(
        Order.query
        .filter(Order.pacs_study_id.isnot(None))
        .filter(Order.pacs_study_id!='')
        .order_by(Order.id.desc())
        .limit(200)
        .all()
    )

    eligible_exam_pairs=[]

    for primary in primary_orders:
        secondary_orders=(
            Order.query
            .filter(
                Order.patient_id==primary.patient_id,
                Order.id!=primary.id,
                ~Order.status.in_(['FINAL','CANCELLED']),
            )
            .order_by(Order.id.desc())
            .limit(50)
            .all()
        )

        for secondary in secondary_orders:
            latest_report=(
                Report.query
                .filter_by(order_id=secondary.id)
                .order_by(Report.id.desc())
                .first()
            )

            if (
                latest_report
                and str(latest_report.status or '').upper()
                    in ('VERIFIED','FINAL')
            ):
                continue

            eligible_exam_pairs.append({
                'primary':primary,
                'secondary':secondary,
                'patient':primary.patient,
            })

    active_exam_links=[]

    for link in (
        PacsExamLink.query
        .filter_by(active=True)
        .order_by(PacsExamLink.created_at.desc())
        .limit(200)
        .all()
    ):
        secondary=db.session.get(Order,link.order_id)
        primary=(
            Order.query
            .filter_by(pacs_study_id=link.orthanc_study_id)
            .order_by(Order.id)
            .first()
        )

        active_exam_links.append({
            'link':link,
            'primary':primary,
            'secondary':secondary,
        })

    return render_template(
        'pacs_reconciliation.html',
        exceptions=rows,
        eligible_exam_pairs=eligible_exam_pairs,
        active_exam_links=active_exam_links,
        can_exam_link=has_perm('pacs.exam_link'),
        can_reconcile=has_perm('pacs.reconcile'),
    )


@app.post('/pacs/exam-link')
@require_perm('pacs.exam_link')
def pacs_exam_link_create():
    from pacs_resolution_service import atomic_exam_link

    primary_order_id=request.form.get(
        'primary_order_id',type=int
    )
    secondary_order_id=request.form.get(
        'secondary_order_id',type=int
    )
    reason=(request.form.get('reason') or '').strip()

    if not primary_order_id or not secondary_order_id:
        flash('Primary and secondary RIS Orders are required.','danger')
        return redirect(url_for('pacs_reconciliation'))

    primary=Order.query.get_or_404(primary_order_id)

    try:
        result=atomic_exam_link(
            db=db,
            Order=Order,
            Report=Report,
            PacsExamLink=PacsExamLink,
            primary_order_id=primary_order_id,
            secondary_order_id=secondary_order_id,
            orthanc_study_id=primary.pacs_study_id,
            actor_user_id=current_user().id,
            reason=reason,
        )

        link=result['link']

        audit(
            'PACS_EXAM_LINK_CREATED',
            'order',
            secondary_order_id,
            (
                'primary_order=%s; study=%s; action=%s; reason=%s'
                % (
                    primary_order_id,
                    link.orthanc_study_id,
                    result['action'],
                    reason,
                )
            )
        )

        db.session.commit()

        flash(
            'Exam Link saved successfully.'
            if result['action']=='CREATED'
            else 'Exam Link already exists.',
            'success'
        )

    except Exception as exc:
        db.session.rollback()
        code=getattr(exc,'code','') or type(exc).__name__
        flash('Exam Link blocked: %s' % code,'danger')

    return redirect(url_for('pacs_reconciliation'))


