@app.post('/pacs/reconciliation/<study_id>/match')
@require_perm('pacs.reconcile')
def pacs_reconciliation_match(study_id):
    from pacs_resolution_service import atomic_primary_link
    inbox=PacsStudyInbox.query.filter_by(orthanc_study_id=study_id).first_or_404()
    if inbox.state!='REVIEW_REQUIRED':
        flash('Study is not waiting for demographic review.','warning')
        return redirect(url_for('pacs_reconciliation'))
    order_id=request.form.get('order_id',type=int)
    reason=(request.form.get('reason') or '').strip()
    if not order_id or len(reason)<5:
        flash('RIS Order ID and documented reason are required.','danger')
        return redirect(url_for('pacs_reconciliation'))
    order=Order.query.get_or_404(order_id)
    st=next((x for x in _orthanc_recent_studies(300) if x.get('ID')==study_id),None)
    if not st: abort(404)
    tags=_study_tags_extended(st)
    try:
        atomic_primary_link(
            db=db,Order=Order,Report=Report,PacsStudyInbox=PacsStudyInbox,
            PacsStudyMatch=PacsStudyMatch,PacsResolutionEvent=PacsResolutionEvent,
            order_id=order.id,orthanc_study_id=study_id,
            study_instance_uid=tags.get('study_instance_uid') or '',
            image_count=tags.get('instances') or inbox.image_count or 0,
            match_method='MANUAL_CONFIRMED',confidence='CONFIRMED',
            actor_user_id=current_user().id,reason=reason,
            pacs_patient_id=tags.get('patient_id',''),
            pacs_patient_name=tags.get('patient_name',''),
            pacs_accession=tags.get('accession',''),inbox_state='MANUALLY_MATCHED')
        evaluate_case_readiness(order)
        audit('PACS_DEMOGRAPHIC_MANUAL_RECONCILIATION','order',order.id,
              'study=%s reason=%s' % (study_id,reason))
        db.session.commit()
    except Exception as exc:
        db.session.rollback()
        flash(getattr(exc,'code',str(exc)),'danger')
        return redirect(url_for('pacs_reconciliation'))
    try:
        enqueue_auto_routes_for_inbox(inbox);db.session.commit()
    except Exception as exc:
        db.session.rollback();app.logger.warning('Auto routing failed order=%s: %s',order.id,exc)
    flash('PACS exception reviewed and matched successfully.','success')
    return redirect(url_for('pacs_reconciliation'))


@app.post('/pacs/reconciliation/<study_id>/quarantine')
@require_perm('pacs.reconcile')
def pacs_reconciliation_quarantine(study_id):
    inbox=PacsStudyInbox.query.filter_by(
        orthanc_study_id=study_id
    ).first_or_404()

    reason=(request.form.get('reason') or '').strip()

    if len(reason)<5:
        flash('Quarantine reason is required.','danger')
        return redirect(url_for('pacs_reconciliation'))

    old_state=inbox.state

    inbox.order_id=None
    inbox.state='QUARANTINED'
    inbox.match_method='MANUAL_QUARANTINE'
    inbox.error_text=(
        'Quarantined by user_id=%s; reason=%s'
        % (current_user().id,reason)
    )[:2000]

    audit(
        'PACS_DEMOGRAPHIC_QUARANTINE',
        'pacs_study_inbox',
        inbox.id,
        'study=%s old_state=%s reason=%s'
        % (study_id,old_state,reason)
    )

    db.session.commit()

    flash('PACS study moved to quarantine.','warning')
    return redirect(url_for('pacs_reconciliation'))


@app.post('/pacs/reconciliation/auto-safe')
@require_perm('pacs.reconcile')

def pacs_reconciliation_auto_safe():
    from pacs_resolution_service import atomic_primary_link
    matched=0
    try:
        for st in _orthanc_recent_studies(200):
            tags=_study_tags_extended(st);sid=tags.get('study_id')
            existing=PacsStudyMatch.query.filter_by(orthanc_study_id=sid).first()
            if existing: continue
            order,method,decision=strict_pacs_demographic_match(tags)
            if not (order and decision=='AUTO_SAFE'): continue
            inbox=PacsStudyInbox.query.filter_by(orthanc_study_id=sid).first()
            if not inbox:
                inbox=PacsStudyInbox(
                    orthanc_study_id=sid,
                    study_instance_uid=tags.get('study_instance_uid') or None,
                    pacs_patient_id=tags.get('patient_id',''),
                    pacs_patient_name=tags.get('patient_name',''),
                    accession=tags.get('accession',''),modality=tags.get('modality',''),
                    study_description=tags.get('study_description',''),
                    source_ae=tags.get('source_ae',''),
                    image_count=int(tags.get('instances') or 0),state='NEW')
                db.session.add(inbox);db.session.flush()
            atomic_primary_link(
                db=db,Order=Order,Report=Report,PacsStudyInbox=PacsStudyInbox,
                PacsStudyMatch=PacsStudyMatch,PacsResolutionEvent=PacsResolutionEvent,
                order_id=order.id,orthanc_study_id=sid,
                study_instance_uid=tags.get('study_instance_uid') or '',
                image_count=tags.get('instances') or inbox.image_count or 0,
                match_method='DEMOGRAPHICS_EXACT',confidence='AUTO_SAFE',
                actor_user_id=current_user().id,
                reason='Strict match: Accession + Patient ID + DOB',
                pacs_patient_id=tags.get('patient_id',''),
                pacs_patient_name=tags.get('patient_name',''),
                pacs_accession=tags.get('accession',''))
            evaluate_case_readiness(order)
            audit('PACS_DEMOGRAPHIC_AUTO_MATCH','order',order.id,
                  'DEMOGRAPHICS_EXACT study=%s' % sid)
            matched+=1
        db.session.commit()
    except Exception:
        db.session.rollback();raise
    flash(f'Auto-safe matched {matched} study/studies.','success')
    return redirect(url_for('pacs_reconciliation'))


def admin_qa():
    counts={
        'outbox_pending':EventOutbox.query.filter_by(status='PENDING').count(),
        'outbox_failed':EventOutbox.query.filter_by(status='FAILED').count(),
        'users':User.query.count(),
        'orders':Order.query.count(),
        'patients':Patient.query.count(),
    }
    recent=EventOutbox.query.order_by(EventOutbox.id.desc()).limit(100).all()
    return render_template('admin_qa.html',counts=counts,recent=recent)


