# RB_COMMAND_CENTER_CASE_GRAPH_V3
# Read-only per-case workflow contract for the Live Command Center.
@app.get('/api/command-center/case/<int:order_id>/graph-v3')
@require_perm('audit.view')
def api_command_center_case_graph_v3(order_id):
    order = Order.query.get_or_404(order_id)

    def iso(value):
        return value.isoformat() if value else None

    def val(obj, name, default=None):
        return getattr(obj, name, default) if obj is not None else default

    def resolution(code):
        code = str(code or '').upper()

        if code in (
            'MISSING_PACS',
            'INCOMPLETE_IMAGES',
            'MISSING_SERIES',
            'WRONG_PROTOCOL',
            'MOTION_ARTIFACT',
            'ADDITIONAL_IMAGING',
        ):
            return {
                'owner_role': 'TECHNICIAN',
                'url': url_for(
                    'technician_case_workspace',
                    order_id=order.id
                ),
            }

        if code in (
            'REVIEW_REQUIRED',
            'UNMATCHED',
            'DEMOGRAPHIC_MISMATCH',
            'PACS_DEMOGRAPHIC_REVIEW_REQUIRED',
        ):
            return {
                'owner_role': 'RECEPTION',
                'url': url_for('pacs_reconciliation'),
            }

        if code in (
            'MISSING_HISTORY',
            'MISSING_DOCUMENTS',
            'MISSING_ATTACHMENTS',
            'MISSING_REFERRAL',
        ):
            return {
                'owner_role': 'RECEPTION',
                'url': url_for('order_detail', order_id=order.id),
            }

        if code in (
            'NO_CANDIDATE',
            'TIMEOUT',
            'ASSIGNMENT_TIMEOUT',
        ):
            return {
                'owner_role': 'ASSIGNMENT',
                'url': url_for('assignment_dashboard'),
            }

        if code.startswith('REPORT_') or code.startswith('ONLYOFFICE_'):
            return {
                'owner_role': 'DOCTOR',
                'url': url_for('report_editor', order_id=order.id),
            }

        return {
            'owner_role': '',
            'url': url_for('order_detail', order_id=order.id),
        }

    readiness = None
    if 'CaseReadiness' in globals():
        readiness = (
            CaseReadiness.query
            .filter_by(order_id=order.id)
            .order_by(CaseReadiness.id.desc())
            .first()
        )

    pacs_inbox = None
    if 'PacsStudyInbox' in globals():
        q = PacsStudyInbox.query
        if hasattr(PacsStudyInbox, 'order_id'):
            pacs_inbox = (
                q.filter_by(order_id=order.id)
                .order_by(PacsStudyInbox.id.desc())
                .first()
            )

    pacs_match = None
    if 'PacsStudyMatch' in globals():
        q = PacsStudyMatch.query
        if hasattr(PacsStudyMatch, 'order_id'):
            pacs_match = (
                q.filter_by(order_id=order.id)
                .order_by(PacsStudyMatch.id.desc())
                .first()
            )

    assignment = (
        CaseAssignment.query
        .filter_by(order_id=order.id, active=True)
        .order_by(CaseAssignment.id.desc())
        .first()
    )

    doctor = val(assignment, 'doctor')
    doctor_presence = None
    if doctor is not None:
        st = (
            DoctorAvailabilityState.query
            .filter_by(user_id=doctor.id)
            .first()
        )

        effective_state = val(
            st,
            'state',
            'UNKNOWN'
        )

        busy_until = val(
            st,
            'busy_until'
        )

        if (
            effective_state == 'BUSY'
            and busy_until
            and busy_until <= datetime.utcnow()
        ):
            effective_state = 'AVAILABLE'

        last_seen_at = val(
            st,
            'last_seen_at'
        )

        online = bool(
            last_seen_at
            and last_seen_at
                >= datetime.utcnow() - timedelta(minutes=5)
            and effective_state != 'OFFLINE'
        )

        doctor_presence = {
            'user_id': doctor.id,
            'username': val(
                doctor,
                'username',
                ''
            ),
            'full_name': val(
                doctor,
                'full_name',
                ''
            ),
            'state': effective_state,
            'last_seen_at': iso(
                last_seen_at
            ),
            'online': online,
            'online_window_minutes': 5,
        }

    blockers = []

    blocker_fields = (
        ('missing_pacs', 'MISSING_PACS'),
        ('incomplete_images', 'INCOMPLETE_IMAGES'),
        ('missing_series', 'MISSING_SERIES'),
        ('missing_history', 'MISSING_HISTORY'),
        ('missing_attachments', 'MISSING_ATTACHMENTS'),
        ('missing_documents', 'MISSING_DOCUMENTS'),
    )

    for field, code in blocker_fields:
        if bool(val(readiness, field, False)):
            target = resolution(code)
            blockers.append({
                'code': code,
                'owner_role': target['owner_role'],
                'resolution_url': target['url'],
            })

    workflow_events = (
        CaseWorkflowEvent.query
        .filter_by(order_id=order.id)
        .order_by(CaseWorkflowEvent.created_at.asc())
        .all()
    )

    event_rows = []
    for ev in workflow_events:
        code = (
            val(ev, 'reason_code', '')
            or val(ev, 'event_type', '')
        )
        target = resolution(code)

        event_rows.append({
            'id': ev.id,
            'event_type': val(ev, 'event_type', ''),
            'reason_code': val(ev, 'reason_code', ''),
            'owner_role': (
                val(ev, 'owner_role', '')
                or target['owner_role']
            ),
            'note': val(ev, 'note', ''),
            'created_at': iso(val(ev, 'created_at')),
            'resolution_url': target['url'],
        })

    report = val(order, 'report')

    pacs_state = (
        val(pacs_inbox, 'state')
        or val(order, 'pacs_status')
        or 'WAITING'
    )

    match_state = (
        val(pacs_match, 'status')
        or val(pacs_match, 'state')
        or val(pacs_inbox, 'match_method')
        or 'WAITING'
    )

    readiness_state = 'READY'
    if readiness is None:
        readiness_state = 'NOT_CHECKED'
    elif blockers:
        readiness_state = 'BLOCKED'

    assignment_state = (
        'ASSIGNED'
        if assignment is not None
        else 'UNASSIGNED'
    )

    report_state = (
        val(report, 'status', 'UNREPORTED')
        if report is not None
        else 'UNREPORTED'
    )

    nodes = [
        {
            'key': 'ORDER',
            'state': val(order, 'status', 'REGISTERED'),
            'resolution_url': url_for(
                'order_detail',
                order_id=order.id
            ),
        },
        {
            'key': 'MWL',
            'state': (
                'ERROR'
                if str(val(order, 'status', '')).upper()
                in ('MWL_ERROR', 'ROUTING_ERROR')
                else 'REQUESTED'
            ),
            'resolution_url': url_for(
                'order_detail',
                order_id=order.id
            ),
        },
        {
            'key': 'EXAM',
            'state': val(order, 'exam_status', 'WAITING'),
            'resolution_url': url_for(
                'technician_case_workspace',
                order_id=order.id
            ),
        },
        {
            'key': 'PACS',
            'state': pacs_state,
            'details': {
                'image_count': int(
                    val(order, 'pacs_image_count', 0) or 0
                ),
                'study_id': val(order, 'pacs_study_id', ''),
                'last_seen_at': iso(
                    val(order, 'pacs_last_seen_at')
                ),
            },
            'resolution_url': url_for(
                'pacs_case_actions',
                order_id=order.id
            ),
        },
        {
            'key': 'MATCHING',
            'state': match_state,
            'resolution_url': url_for('pacs_reconciliation'),
        },
        {
            'key': 'READINESS',
            'state': readiness_state,
            'blockers': blockers,
            'resolution_url': url_for(
                'case_readiness_dashboard'
            ),
        },
        {
            'key': 'ASSIGNMENT',
            'state': assignment_state,
            'details': {
                'assignment_type': val(
                    assignment,
                    'assignment_type',
                    ''
                ),
                'assigned_at': iso(
                    val(assignment, 'assigned_at')
                ),
                'doctor': doctor_presence,
            },
            'resolution_url': url_for(
                'assignment_dashboard'
            ),
        },
        {
            'key': 'REPORTING',
            'state': report_state,
            'details': {
                'radiologist': val(report, 'radiologist', ''),
                'verified_at': iso(
                    val(report, 'verified_at')
                ),
                'finalized_at': iso(
                    val(report, 'finalized_at')
                ),
            },
            'resolution_url': url_for(
                'report_editor',
                order_id=order.id
            ),
        },
    ]

    return jsonify({
        'schema': 'radbridge.command_center.case_graph.v3',
        'read_only': True,
        'order': {
            'id': order.id,
            'accession': val(order, 'accession', ''),
            'modality': val(order, 'modality', ''),
            'procedure': val(order, 'procedure', ''),
            'status': val(order, 'status', ''),
        },
        'nodes': nodes,
        'blockers': blockers,
        'events': event_rows,
        'assigned_doctor': doctor_presence,
    })



# ============================================================
# RB_COMMAND_CENTER_MONITORING_CONTROL_V1
# Persistent multi-worker runtime control.
#
# OFF:
#   No SSE monitoring loop.
#
# NORMAL:
#   Low-frequency SSE refresh.
#
# LIVE:
#   Real-time SSE refresh.
#
# Storage is intentionally outside the application image.
# A persistent bind mount is required before writes are enabled.
# ============================================================

def _command_center_control_defaults():
    return {
        'schema': 'radbridge.command_center.control.v1',
        'mode': 'LIVE',
        'normal_interval_seconds': 15,
        'live_interval_seconds': 2,
        'updated_at': None,
        'updated_by': '',
        'storage_configured': bool(
            os.environ.get(
                'RADBRIDGE_COMMAND_CENTER_CONTROL_FILE'
            )
        ),
    }


def _command_center_control_path():
    return str(
        os.environ.get(
            'RADBRIDGE_COMMAND_CENTER_CONTROL_FILE'
        )
        or ''
    ).strip()


def command_center_control_state():

    state = _command_center_control_defaults()

    path = _command_center_control_path()

    if not path:
        return state

    try:
        with open(
            path,
            'r',
            encoding='utf-8'
        ) as handle:
            stored = json.load(handle)

        if not isinstance(stored, dict):
            return state

        mode = str(
            stored.get('mode')
            or state['mode']
        ).upper()

        if mode not in (
            'OFF',
            'NORMAL',
            'LIVE'
        ):
            mode = state['mode']

        try:
            normal_interval = int(
                stored.get(
                    'normal_interval_seconds',
                    state['normal_interval_seconds']
                )
            )
        except Exception:
            normal_interval = \
                state['normal_interval_seconds']

        try:
            live_interval = int(
                stored.get(
                    'live_interval_seconds',
                    state['live_interval_seconds']
                )
            )
        except Exception:
            live_interval = \
                state['live_interval_seconds']

        state.update({
            'mode': mode,
            'normal_interval_seconds': max(
                5,
                min(normal_interval, 120)
            ),
            'live_interval_seconds': max(
                1,
                min(live_interval, 10)
            ),
            'updated_at': stored.get(
                'updated_at'
            ),
            'updated_by': str(
                stored.get('updated_by')
                or ''
            ),
            'storage_configured': True,
        })

    except FileNotFoundError:
        pass

    except Exception:
        app.logger.exception(
            'COMMAND_CENTER_CONTROL_READ_FAILED'
        )

    return state


def _command_center_write_control_state(
    mode,
    normal_interval_seconds=None,
    live_interval_seconds=None,
    updated_by=''
):

    path = _command_center_control_path()

    if not path:
        return (
            False,
            'CONTROL_STORAGE_NOT_CONFIGURED'
        )

    mode = str(
        mode or ''
    ).upper()

    if mode not in (
        'OFF',
        'NORMAL',
        'LIVE'
    ):
        return (
            False,
            'INVALID_MONITORING_MODE'
        )

    current = command_center_control_state()

    try:
        normal_interval = int(
            normal_interval_seconds
            if normal_interval_seconds is not None
            else current[
                'normal_interval_seconds'
            ]
        )

        live_interval = int(
            live_interval_seconds
            if live_interval_seconds is not None
            else current[
                'live_interval_seconds'
            ]
        )

    except Exception:
        return (
            False,
            'INVALID_INTERVAL'
        )

    normal_interval = max(
        5,
        min(normal_interval, 120)
    )

    live_interval = max(
        1,
        min(live_interval, 10)
    )

    directory = os.path.dirname(path)

    try:
        if directory:
            os.makedirs(
                directory,
                exist_ok=True
            )

        payload = {
            'schema':
                'radbridge.command_center.control.v1',

            'mode':
                mode,

            'normal_interval_seconds':
                normal_interval,

            'live_interval_seconds':
                live_interval,

            'updated_at':
                datetime.utcnow().isoformat()
                + 'Z',

            'updated_by':
                str(updated_by or ''),
        }

        temp_path = (
            path
            + '.tmp.'
            + str(os.getpid())
        )

        with open(
            temp_path,
            'w',
            encoding='utf-8'
        ) as handle:
            json.dump(
                payload,
                handle,
                ensure_ascii=False,
                sort_keys=True
            )

            handle.flush()
            os.fsync(
                handle.fileno()
            )

        os.replace(
            temp_path,
            path
        )

        return (
            True,
            payload
        )

    except Exception:
        app.logger.exception(
            'COMMAND_CENTER_CONTROL_WRITE_FAILED'
        )

        return (
            False,
            'CONTROL_WRITE_FAILED'
        )


@app.get('/api/command-center/control')
@require_perm('audit.view')
def api_command_center_control_get():

    return jsonify(
        command_center_control_state()
    )


@app.post('/api/command-center/control')
@login_required
def api_command_center_control_set():

    user = current_user()

    role_code = (
        user.role.code.upper()
        if (
            user
            and user.role
            and user.role.code
        )
        else ''
    )

    if role_code not in (
        'SUPER_ADMIN',
        'ADMIN'
    ):
        abort(403)

    data = request.get_json(
        silent=True
    ) or {}

    ok, result = \
        _command_center_write_control_state(
            mode=data.get('mode'),
            normal_interval_seconds=data.get(
                'normal_interval_seconds'
            ),
            live_interval_seconds=data.get(
                'live_interval_seconds'
            ),
            updated_by=(
                user.username
                if user
                else ''
            ),
        )

    if not ok:
        status = (
            503
            if result
            == 'CONTROL_STORAGE_NOT_CONFIGURED'
            else 400
        )

        return jsonify({
            'ok': False,
            'error': result,
        }), status

    audit(
        'COMMAND_CENTER_MODE_CHANGED',
        'system',
        'command-center',
        (
            'mode='
            + str(result.get('mode'))
            + '; normal_interval='
            + str(
                result.get(
                    'normal_interval_seconds'
                )
            )
            + '; live_interval='
            + str(
                result.get(
                    'live_interval_seconds'
                )
            )
        )
    )

    db.session.commit()

    return jsonify({
        'ok': True,
        'control': result,
    })



# ============================================================

# ============================================================
# RB_COMMAND_CENTER_AUTO_PROTECTION_V1
# Protects Command Center monitoring only.
#
# LIVE -> NORMAL when sustained resource pressure is detected.
# Never changes RIS/PACS/DB/clinical workflow behavior.
# ============================================================

def _rb_auto_protection_state_path():
    control_path = _command_center_control_path()

    if not control_path:
        return ''

    return control_path + '.autoprotect.json'


def _rb_auto_protection_defaults():
    return {
        'enabled': True,
        'load_ratio_threshold': 0.80,
        'memory_percent_threshold': 85.0,
        'sustain_seconds': 120,
        'high_since': None,
        'last_triggered_at': None,
        'last_reason': '',
    }


def _rb_auto_protection_read_state():
    state = _rb_auto_protection_defaults()

    path = _rb_auto_protection_state_path()

    if not path:
        return state

    try:
        with open(
            path,
            'r',
            encoding='utf-8'
        ) as handle:
            stored = json.load(handle)

        if isinstance(stored, dict):
            state.update(stored)

    except FileNotFoundError:
        pass

    except Exception:
        app.logger.exception(
            'COMMAND_CENTER_AUTO_PROTECT_READ_FAILED'
        )

    return state


def _rb_auto_protection_write_state(state):
    path = _rb_auto_protection_state_path()

    if not path:
        return False

    directory = os.path.dirname(path)

    try:
        if directory:
            os.makedirs(
                directory,
                exist_ok=True
            )

        temp_path = (
            path
            + '.tmp.'
            + str(os.getpid())
        )

        with open(
            temp_path,
            'w',
            encoding='utf-8'
        ) as handle:
            json.dump(
                state,
                handle,
                ensure_ascii=False,
                sort_keys=True
            )

            handle.flush()
            os.fsync(
                handle.fileno()
            )

        os.replace(
            temp_path,
            path
        )

        return True

    except Exception:
        app.logger.exception(
            'COMMAND_CENTER_AUTO_PROTECT_WRITE_FAILED'
        )

        return False


def _rb_auto_protection_evaluate(
    host_metrics,
    container_metrics
):
    import time as _time

    control = command_center_control_state()
    state = _rb_auto_protection_read_state()

    result = {
        'enabled': bool(
            state.get('enabled', True)
        ),
        'triggered': False,
        'action': None,
        'reason': '',
        'high_since': state.get('high_since'),
        'sustain_seconds': int(
            state.get('sustain_seconds') or 120
        ),
    }

    if not result['enabled']:
        return result

    if str(control.get('mode')).upper() != 'LIVE':
        if state.get('high_since') is not None:
            state['high_since'] = None
            _rb_auto_protection_write_state(state)

        return result

    cpu_count = max(
        1,
        int(host_metrics.get('cpu_count') or 1)
    )

    load1 = host_metrics.get('load1')

    try:
        load_ratio = (
            float(load1) / float(cpu_count)
        )
    except Exception:
        load_ratio = 0.0

    mem_total_kb = (
        host_metrics.get('mem_total_kb')
    )

    mem_available_kb = (
        host_metrics.get('mem_available_kb')
    )

    memory_percent = 0.0

    try:
        if (
            mem_total_kb
            and mem_available_kb is not None
        ):
            memory_percent = (
                (
                    float(mem_total_kb)
                    - float(mem_available_kb)
                )
                / float(mem_total_kb)
            ) * 100.0
    except Exception:
        memory_percent = 0.0

    load_threshold = float(
        state.get(
            'load_ratio_threshold',
            0.80
        )
    )

    memory_threshold = float(
        state.get(
            'memory_percent_threshold',
            85.0
        )
    )

    reasons = []

    if load_ratio >= load_threshold:
        reasons.append(
            'LOAD_RATIO_HIGH'
        )

    if memory_percent >= memory_threshold:
        reasons.append(
            'MEMORY_HIGH'
        )

    now = _time.time()

    if not reasons:
        if state.get('high_since') is not None:
            state['high_since'] = None
            state['last_reason'] = ''
            _rb_auto_protection_write_state(state)

        return result

    if state.get('high_since') is None:
        state['high_since'] = now
        state['last_reason'] = ','.join(reasons)
        _rb_auto_protection_write_state(state)

        result['high_since'] = now
        result['reason'] = state['last_reason']

        return result

    try:
        elapsed = (
            now
            - float(state.get('high_since'))
        )
    except Exception:
        elapsed = 0

    result['high_since'] = state.get('high_since')
    result['reason'] = ','.join(reasons)

    sustain_seconds = int(
        state.get('sustain_seconds') or 120
    )

    if elapsed < sustain_seconds:
        return result

    ok, write_result = \
        _command_center_write_control_state(
            mode='NORMAL',
            updated_by='AUTO_PROTECTION',
        )

    if not ok:
        result['reason'] = (
            result['reason']
            + '; CONTROL_WRITE_FAILED'
        )
        return result

    triggered_at = (
        datetime.utcnow().isoformat()
        + 'Z'
    )

    state['high_since'] = None
    state['last_triggered_at'] = triggered_at
    state['last_reason'] = result['reason']

    _rb_auto_protection_write_state(state)

    result['triggered'] = True
    result['action'] = 'LIVE_TO_NORMAL'

    return result


# RB_COMMAND_CENTER_RESOURCE_MONITOR_V1
# Read-only resource and service health telemetry.
# ============================================================

def _rb_read_text(path):
    try:
        with open(path, 'r', encoding='utf-8') as handle:
            return handle.read().strip()
    except Exception:
        return ''


def _rb_int(value):
    try:
        return int(str(value).strip())
    except Exception:
        return None


def _rb_cgroup_metrics():
    data = {
        'memory_current_bytes': None,
        'memory_max_bytes': None,
        'pids_current': None,
        'cpu_usage_usec': None,
        'cpu_user_usec': None,
        'cpu_system_usec': None,
    }

    memory_current = _rb_read_text(
        '/sys/fs/cgroup/memory.current'
    )
    memory_max = _rb_read_text(
        '/sys/fs/cgroup/memory.max'
    )
    pids_current = _rb_read_text(
        '/sys/fs/cgroup/pids.current'
    )
    cpu_stat = _rb_read_text(
        '/sys/fs/cgroup/cpu.stat'
    )

    data['memory_current_bytes'] = \
        _rb_int(memory_current)

    if memory_max and memory_max != 'max':
        data['memory_max_bytes'] = \
            _rb_int(memory_max)

    data['pids_current'] = \
        _rb_int(pids_current)

    if cpu_stat:
        for line in cpu_stat.splitlines():
            parts = line.split()
            if len(parts) != 2:
                continue

            key, value = parts

            if key == 'usage_usec':
                data['cpu_usage_usec'] = \
                    _rb_int(value)

            elif key == 'user_usec':
                data['cpu_user_usec'] = \
                    _rb_int(value)

            elif key == 'system_usec':
                data['cpu_system_usec'] = \
                    _rb_int(value)

    return data


def _rb_host_metrics():
    import os as _os
    import shutil as _shutil

    result = {
        'cpu_count': _os.cpu_count(),
        'load1': None,
        'load5': None,
        'load15': None,
        'mem_total_kb': None,
        'mem_available_kb': None,
        'disk_total_bytes': None,
        'disk_used_bytes': None,
        'disk_free_bytes': None,
    }

    try:
        load1, load5, load15 = _os.getloadavg()

        result['load1'] = load1
        result['load5'] = load5
        result['load15'] = load15

    except Exception:
        pass

    meminfo = _rb_read_text('/proc/meminfo')

    if meminfo:
        for line in meminfo.splitlines():

            if line.startswith('MemTotal:'):
                parts = line.split()
                if len(parts) >= 2:
                    result['mem_total_kb'] = \
                        _rb_int(parts[1])

            elif line.startswith('MemAvailable:'):
                parts = line.split()
                if len(parts) >= 2:
                    result['mem_available_kb'] = \
                        _rb_int(parts[1])

    try:
        usage = _shutil.disk_usage('/')

        result['disk_total_bytes'] = usage.total
        result['disk_used_bytes'] = usage.used
        result['disk_free_bytes'] = usage.free

    except Exception:
        pass

    return result


def _rb_db_health():
    try:
        value = db.session.execute(
            text('SELECT 1')
        ).scalar()

        return {
            'status':
                'HEALTHY'
                if value == 1
                else 'DEGRADED',
            'detail': str(value),
        }

    except Exception as exc:

        try:
            db.session.rollback()
        except Exception:
            pass

        return {
            'status': 'FAILED',
            'detail': type(exc).__name__,
        }


def _rb_pacs_health():
    try:
        response = requests.get(
            PACS_ORTHANC_URL + '/system',
            auth=_orthanc_auth(),
            timeout=3,
        )

        return {
            'status':
                'ONLINE'
                if response.ok
                else 'DEGRADED',
            'http_status':
                int(response.status_code),
        }

    except Exception as exc:
        return {
            'status': 'OFFLINE',
            'http_status': None,
            'detail': type(exc).__name__,
        }


@app.get('/api/command-center/resources')
@require_perm('audit.view')
def api_command_center_resources():

    control = command_center_control_state()

    host_metrics = _rb_host_metrics()
    container_metrics = _rb_cgroup_metrics()

    auto_protection = _rb_auto_protection_evaluate(
        host_metrics,
        container_metrics,
    )

    return jsonify({
        'schema':
            'radbridge.command_center.resources.v1',

        'read_only':
            True,

        'timestamp':
            datetime.utcnow().isoformat()
            + 'Z',

        'monitoring': {
            'mode':
                control.get('mode'),

            'normal_interval_seconds':
                control.get(
                    'normal_interval_seconds'
                ),

            'live_interval_seconds':
                control.get(
                    'live_interval_seconds'
                ),

            'storage_configured':
                control.get(
                    'storage_configured'
                ),
        },

        'host':
            host_metrics,

        'container':
            container_metrics,

        'auto_protection':
            auto_protection,

        'services': {
            'ris': {
                'status': 'HEALTHY',
            },

            'database':
                _rb_db_health(),

            'pacs':
                _rb_pacs_health(),
        },
    })


# RB_LIVE_COMMAND_CENTER_SSE_V1
# Read-only Server-Sent Events transport for Command Center.
# It reuses the normalized event API and never writes clinical
# workflow state.
# ============================================================

@app.get('/api/command-center/events/stream')
@require_perm('audit.view')
def command_center_events_stream():

    from flask import Response, stream_with_context
    import inspect
    import time

    initial_control = command_center_control_state()

    if initial_control.get('mode') == 'OFF':
        return Response(
            status=204
        )

    @stream_with_context
    def generate():

        last_keys=set()

        while True:

            control = command_center_control_state()

            monitoring_mode = str(
                control.get('mode')
                or 'LIVE'
            ).upper()

            if monitoring_mode == 'OFF':

                yield (
                    'event: monitoring_state\n'
                    'data: {"mode":"OFF"}\n\n'
                )

                return

            interval_seconds = (
                int(
                    control.get(
                        'normal_interval_seconds'
                    )
                    or 15
                )
                if monitoring_mode == 'NORMAL'
                else int(
                    control.get(
                        'live_interval_seconds'
                    )
                    or 2
                )
            )

            view=app.view_functions.get(
                'command_center_events'
            )

            if not view:
                yield (
                    'event: error\n'
                    'data: {"error":"EVENT_API_NOT_FOUND"}\n\n'
                )
                time.sleep(5)
                continue

            raw=inspect.unwrap(view)

            with app.test_request_context(
                '/api/command-center/events?limit=100'
            ):
                rv=raw()
                response=(
                    rv[0]
                    if isinstance(rv,tuple)
                    else rv
                )
                data=response.get_json() or {}

            events=data.get('events') or []

            current_keys=set()

            for event in reversed(events):

                key=str(
                    event.get('event_key') or ''
                )

                if not key:
                    continue

                current_keys.add(key)

                if key in last_keys:
                    continue

                payload=json.dumps(
                    event,
                    ensure_ascii=False,
                    default=str
                )

                yield (
                    f'id: {key}\n'
                    f'event: workflow_event\n'
                    f'data: {payload}\n\n'
                )

            last_keys=current_keys

            heartbeat_payload = json.dumps(
                {
                    'status': 'alive',
                    'mode': monitoring_mode,
                    'interval_seconds':
                        interval_seconds,
                },
                separators=(',', ':')
            )

            yield (
                'event: heartbeat\n'
                f'data: {heartbeat_payload}\n\n'
            )

            time.sleep(
                interval_seconds
            )

    response=Response(
        generate(),
        mimetype='text/event-stream'
    )

    response.headers['Cache-Control']='no-cache'
    response.headers['X-Accel-Buffering']='no'
    response.headers['Connection']='keep-alive'

    return response


@app.route('/operations/live-command-center')
@require_perm('audit.view')
def live_command_center():
    return render_template('live_command_center.html')



# ============================================================
# RadBridge Live Command Center
# Normalized read-only event feed.
# RB_LIVE_COMMAND_CENTER_EVENTS_API_V1
# ============================================================

@app.route('/api/command-center/events')
@require_perm('audit.view')
def command_center_events():

    limit=request.args.get(
        'limit',
        100,
        type=int
    )

    limit=max(1,min(limit or 100,200))

    order_filter=request.args.get(
        'order_id',
        type=int
    )

    events=[]
    order_cache={}

    def timestamp_value(value):
        if not value:
            return ''

        try:
            text=value.isoformat()
            if getattr(value,'tzinfo',None) is None:
                text += 'Z'
            return text
        except Exception:
            return str(value)

    def order_context(order_id):
        try:
            oid=int(order_id)
        except Exception:
            return {
                'order_id':None,
                'accession':'',
                'correlation_id':''
            }

        if oid not in order_cache:
            order_cache[oid]=db.session.get(
                Order,
                oid
            )

        order=order_cache[oid]

        return {
            'order_id':oid,
            'accession':(
                order.accession
                if order else ''
            ) or '',
            'correlation_id':f'order:{oid}'
        }

    def append_event(
        source,
        source_id,
        event_type,
        stage,
        status,
        timestamp,
        order_id=None,
        details='',
        payload=None
    ):
        ctx=order_context(order_id)

        events.append({
            'event_key':f'{source}:{source_id}',
            'source':source,
            'source_id':source_id,
            'event_type':str(
                event_type or ''
            ).upper(),
            'stage':stage,
            'status':status,
            'timestamp':timestamp_value(
                timestamp
            ),
            'order_id':ctx['order_id'],
            'accession':ctx['accession'],
            'correlation_id':ctx[
                'correlation_id'
            ],
            'details':str(
                details or ''
            )[:1000],
            'payload':payload or {}
        })

    def outbox_stage(event_type,payload):
        event_type=str(
            event_type or ''
        ).upper()

        if event_type=='ORDER_MWL_CREATE':
            return 'MWL','SUCCESS'

        if event_type=='ORDER_SMART_ASSIGNMENT':
            return 'ASSIGNMENT','REQUESTED'

        if event_type in (
            'EXAM_STATUS_CHANGED',
            'EXAM_STATUS_OVERRIDE'
        ):
            new_state=str(
                payload.get('to') or ''
            ).upper()

            if new_state=='IN_PROGRESS':
                return 'EXAM','RUNNING'

            if new_state=='EXAM_COMPLETED':
                return 'EXAM','SUCCESS'

            if new_state=='REPORTING':
                return 'REPORTING','RUNNING'

            return 'EXAM','INFO'

        return 'ORDER','INFO'

    def assignment_status(event_type):
        event_type=str(
            event_type or ''
        ).upper()

        mapping={
            'OFFERED':'RUNNING',
            'STRATEGY_SELECTED':'RUNNING',
            'ACCEPTED':'SUCCESS',
            'TIMEOUT':'FAILED',
            'NO_CANDIDATE':'FAILED',
            'READINESS_BLOCK':'BLOCKED',
            'REJECTED':'FAILED',
            'BUSY':'WAITING',
            'CANCELLED':'CANCELLED',
        }

        return mapping.get(
            event_type,
            'INFO'
        )

    def workflow_status(event_type):
        event_type=str(
            event_type or ''
        ).upper()

        if event_type.endswith('_FAILED'):
            return 'FAILED'

        if event_type=='RETURNED':
            return 'BLOCKED'

        if event_type in (
            'RESOLVED',
            'READY_FOR_REREVIEW'
        ):
            return 'SUCCESS'

        return 'INFO'

    # --------------------------------------------------------
    # EventOutbox
    # --------------------------------------------------------

    q=EventOutbox.query.filter(
        EventOutbox.entity_type=='order'
    )

    if order_filter is not None:
        q=q.filter(
            EventOutbox.entity_id==
            str(order_filter)
        )

    outbox_rows=(
        q.order_by(
            EventOutbox.id.desc()
        )
        .limit(limit)
        .all()
    )

    for row in outbox_rows:

        try:
            payload=json.loads(
                row.payload_json or '{}'
            )
        except Exception:
            payload={}

        stage,status=outbox_stage(
            row.event_type,
            payload
        )

        append_event(
            source='OUTBOX',
            source_id=row.id,
            event_type=row.event_type,
            stage=stage,
            status=status,
            timestamp=getattr(
                row,
                'created_at',
                None
            ),
            order_id=row.entity_id,
            details='',
            payload=payload
        )

    # --------------------------------------------------------
    # PACS / DICOM receipt
    # RB_LIVE_COMMAND_CENTER_PACS_MATCHING_EVENTS_V1
    # --------------------------------------------------------

    q=PacsStudyInbox.query

    if order_filter is not None:
        q=q.filter(
            PacsStudyInbox.order_id==order_filter
        )

    inbox_rows=(
        q.order_by(
            PacsStudyInbox.id.desc()
        )
        .limit(limit)
        .all()
    )

    for row in inbox_rows:

        append_event(
            source='PACS_INBOX',
            source_id=f'{row.id}:received',
            event_type='PACS_STUDY_RECEIVED',
            stage='PACS',
            status=(
                'SUCCESS'
                if int(row.image_count or 0)>0
                else 'WAITING'
            ),
            timestamp=(
                row.first_seen_at
                or row.last_seen_at
            ),
            order_id=row.order_id,
            details=(
                f'state={row.state or ""}; '
                f'images={int(row.image_count or 0)}; '
                f'source_ae={row.source_ae or ""}'
            ),
            payload={
                'orthanc_study_id':
                    row.orthanc_study_id or '',
                'study_instance_uid':
                    row.study_instance_uid or '',
                'pacs_accession':
                    row.accession or '',
                'modality':
                    row.modality or '',
                'source_ae':
                    row.source_ae or '',
                'image_count':
                    int(row.image_count or 0),
                'inbox_state':
                    row.state or '',
            }
        )

        inbox_state=str(
            row.state or ''
        ).upper()

        if inbox_state=='REVIEW_REQUIRED':
            append_event(
                source='PACS_INBOX',
                source_id=f'{row.id}:matching',
                event_type='PACS_MATCH_REVIEW_REQUIRED',
                stage='MATCHING',
                status='BLOCKED',
                timestamp=(
                    row.last_seen_at
                    or row.first_seen_at
                ),
                order_id=row.order_id,
                details=(
                    row.error_text
                    or row.match_method
                    or 'PACS matching review required'
                ),
                payload={
                    'orthanc_study_id':
                        row.orthanc_study_id or '',
                    'study_instance_uid':
                        row.study_instance_uid or '',
                    'match_method':
                        row.match_method or '',
                    'inbox_state':
                        row.state or '',
                }
            )

        elif inbox_state=='ERROR':
            append_event(
                source='PACS_INBOX',
                source_id=f'{row.id}:matching',
                event_type='PACS_MATCH_ERROR',
                stage='MATCHING',
                status='FAILED',
                timestamp=(
                    row.last_seen_at
                    or row.first_seen_at
                ),
                order_id=row.order_id,
                details=(
                    row.error_text
                    or 'PACS inbox error'
                ),
                payload={
                    'orthanc_study_id':
                        row.orthanc_study_id or '',
                    'study_instance_uid':
                        row.study_instance_uid or '',
                    'match_method':
                        row.match_method or '',
                    'inbox_state':
                        row.state or '',
                }
            )

    # --------------------------------------------------------
    # Confirmed PACS matches
    # --------------------------------------------------------

    q=PacsStudyMatch.query

    if order_filter is not None:
        q=q.filter(
            PacsStudyMatch.order_id
            ==order_filter
        )

    match_rows=(
        q.order_by(
            PacsStudyMatch.id.desc()
        )
        .limit(limit)
        .all()
    )

    for row in match_rows:

        append_event(
            source='PACS_MATCH',
            source_id=row.id,
            event_type='PACS_MATCH_CONFIRMED',
            stage='MATCHING',
            status='SUCCESS',
            timestamp=row.confirmed_at,
            order_id=row.order_id,
            details=(
                f'method={row.match_method or ""}; '
                f'confidence={row.confidence or ""}; '
                f'current={bool(row.is_current)}'
            ),
            payload={
                'orthanc_study_id':
                    row.orthanc_study_id or '',
                'match_method':
                    row.match_method or '',
                'confidence':
                    row.confidence or '',
                'is_current':
                    bool(row.is_current),
                'pacs_accession':
                    row.pacs_accession or '',
            }
        )

    # --------------------------------------------------------
    # PACS reconciliation / resolution history
    # --------------------------------------------------------

    q=PacsResolutionEvent.query

    if order_filter is not None:
        q=q.filter(
            PacsResolutionEvent.order_id
            ==order_filter
        )

    resolution_rows=(
        q.order_by(
            PacsResolutionEvent.id.desc()
        )
        .limit(limit)
        .all()
    )

    for row in resolution_rows:

        resolution_type=str(
            row.event_type or ''
        ).upper()

        resolution_status=(
            'SUCCESS'
            if resolution_type in (
                'PRIMARY_LINK_CHANGED',
                'MATCH_CONFIRMED',
                'RESOLVED'
            )
            else 'INFO'
        )

        append_event(
            source='PACS_RESOLUTION',
            source_id=row.id,
            event_type=row.event_type,
            stage='MATCHING',
            status=resolution_status,
            timestamp=row.created_at,
            order_id=row.order_id,
            details=row.reason,
            payload={
                'old_orthanc_study_id':
                    row.old_orthanc_study_id or '',
                'new_orthanc_study_id':
                    row.new_orthanc_study_id or '',
                'old_study_instance_uid':
                    row.old_study_instance_uid or '',
                'new_study_instance_uid':
                    row.new_study_instance_uid or '',
            }
        )

    # --------------------------------------------------------
    # Assignment Events
    # --------------------------------------------------------

    q=AssignmentEscalationEvent.query

    if order_filter is not None:
        q=q.filter(
            AssignmentEscalationEvent.order_id
            ==order_filter
        )

    assignment_rows=(
        q.order_by(
            AssignmentEscalationEvent.id.desc()
        )
        .limit(limit)
        .all()
    )

    for row in assignment_rows:

        append_event(
            source='ASSIGNMENT',
            source_id=row.id,
            event_type=row.event_type,
            stage='ASSIGNMENT',
            status=assignment_status(
                row.event_type
            ),
            timestamp=row.created_at,
            order_id=row.order_id,
            details=row.details,
            payload={
                'offer_id':row.offer_id
            }
        )

    # --------------------------------------------------------
    # Case Workflow Events
    # --------------------------------------------------------

    q=CaseWorkflowEvent.query

    if order_filter is not None:
        q=q.filter(
            CaseWorkflowEvent.order_id
            ==order_filter
        )

    workflow_rows=(
        q.order_by(
            CaseWorkflowEvent.id.desc()
        )
        .limit(limit)
        .all()
    )

    for row in workflow_rows:

        append_event(
            source='WORKFLOW',
            source_id=row.id,
            event_type=row.event_type,
            stage='READINESS',
            status=workflow_status(
                row.event_type
            ),
            timestamp=row.created_at,
            order_id=row.order_id,
            details=getattr(
                row,
                'details',
                ''
            )
        )

    # --------------------------------------------------------
    # Order-specific reporting audit
    # --------------------------------------------------------

    reporting_actions=[
        'OHIF_REPORT_OPENED',
        'ONLYOFFICE_EDITOR_OPENED',
        'REPORT_EDIT_LEASE_ACQUIRED',
        'REPORT_EDIT_LEASE_RELEASED',
        'REPORT_FINALIZED',
        'REPORT_VERIFIED',
        'REPORT_SAVED',
    ]

    q=AuditLog.query.filter(
        AuditLog.entity=='order',
        AuditLog.action.in_(
            reporting_actions
        )
    )

    if order_filter is not None:
        q=q.filter(
            AuditLog.entity_id==
            str(order_filter)
        )

    audit_rows=(
        q.order_by(
            AuditLog.id.desc()
        )
        .limit(limit)
        .all()
    )

    for row in audit_rows:

        action=str(
            row.action or ''
        ).upper()

        if 'FINAL' in action:
            status='SUCCESS'
        elif 'OPENED' in action:
            status='RUNNING'
        elif 'ACQUIRED' in action:
            status='RUNNING'
        elif 'RELEASED' in action:
            status='INFO'
        else:
            status='INFO'

        append_event(
            source='AUDIT',
            source_id=row.id,
            event_type=row.action,
            stage='REPORTING',
            status=status,
            timestamp=row.created_at,
            order_id=row.entity_id,
            details=row.details
        )

    # Sort normalized events using real timestamps.
    events.sort(
        key=lambda x:(
            x.get('timestamp') or '',
            x.get('event_key') or ''
        ),
        reverse=True
    )

    events=events[:limit]

    return jsonify({
        'schema':
            'radbridge.command_center.events.v1',
        'generated_at':
            datetime.utcnow().isoformat()+'Z',
        'order_filter':order_filter,
        'count':len(events),
        'events':events
    })


@app.route('/api/command-center/snapshot')
@require_perm('audit.view')
def command_center_snapshot():
    """
    Read-only monitoring snapshot.

    This endpoint must not become part of the clinical workflow.
    It reads existing RadBridge operational state only.
    """

    def grouped_counts(model, column):
        rows = (
            db.session.query(
                column,
                db.func.count(model.id)
            )
            .group_by(column)
            .all()
        )

        return {
            str(value or 'UNKNOWN').upper(): int(count or 0)
            for value, count in rows
        }

    # --------------------------------------------------------
    # Orders / Exam
    # --------------------------------------------------------

    order_status = grouped_counts(
        Order,
        Order.status
    )

    exam_status = grouped_counts(
        Order,
        Order.exam_status
    )

    pacs_status = grouped_counts(
        Order,
        Order.pacs_status
    )

    # --------------------------------------------------------
    # PACS / Matching
    # --------------------------------------------------------

    pacs_inbox_state = grouped_counts(
        PacsStudyInbox,
        PacsStudyInbox.state
    )

    unmatched_studies = (
        PacsStudyInbox.query
        .filter(PacsStudyInbox.order_id.is_(None))
        .count()
    )

    current_matches = (
        PacsStudyMatch.query
        .filter(PacsStudyMatch.is_current.is_(True))
        .count()
    )

    # --------------------------------------------------------
    # Case Readiness
    # --------------------------------------------------------

    readiness_status = grouped_counts(
        CaseReadiness,
        CaseReadiness.status
    )

    readiness_blockers = {
        'MISSING_PACS': (
            CaseReadiness.query
            .filter(CaseReadiness.missing_pacs.is_(True))
            .count()
        ),
        'INCOMPLETE_IMAGES': (
            CaseReadiness.query
            .filter(CaseReadiness.incomplete_images.is_(True))
            .count()
        ),
        'MISSING_SERIES': (
            CaseReadiness.query
            .filter(CaseReadiness.missing_series.is_(True))
            .count()
        ),
        'MISSING_HISTORY': (
            CaseReadiness.query
            .filter(CaseReadiness.missing_history.is_(True))
            .count()
        ),
        'MISSING_ATTACHMENTS': (
            CaseReadiness.query
            .filter(CaseReadiness.missing_attachments.is_(True))
            .count()
        ),
        'MISSING_DOCUMENTS': (
            CaseReadiness.query
            .filter(CaseReadiness.missing_documents.is_(True))
            .count()
        ),
    }

    # --------------------------------------------------------
    # Assignment
    # --------------------------------------------------------

    assignment_offers = grouped_counts(
        AssignmentOffer,
        AssignmentOffer.status
    )

    active_assignments = (
        CaseAssignment.query
        .filter(CaseAssignment.active.is_(True))
        .count()
    )

    ready_unassigned = (
        db.session.query(Order.id)
        .join(
            CaseReadiness,
            CaseReadiness.order_id == Order.id
        )
        .outerjoin(
            CaseAssignment,
            db.and_(
                CaseAssignment.order_id == Order.id,
                CaseAssignment.active.is_(True)
            )
        )
        .filter(
            Order.exam_status == 'EXAM_COMPLETED',
            Order.pacs_status == 'IMAGES_COMPLETE',
            CaseAssignment.id.is_(None)
        )
        .count()
    )

    # --------------------------------------------------------
    # Reporting
    # --------------------------------------------------------

    report_status = grouped_counts(
        Report,
        Report.status
    )

    # --------------------------------------------------------
    # Event / Error visibility
    # --------------------------------------------------------

    outbox_status = grouped_counts(
        EventOutbox,
        EventOutbox.status
    )

    return jsonify({
        'schema': 'radbridge.command_center.snapshot.v1',
        'generated_at': datetime.utcnow().isoformat() + 'Z',

        'orders': {
            'status': order_status,
            'exam_status': exam_status,
        },

        'pacs': {
            'order_pacs_status': pacs_status,
            'inbox_state': pacs_inbox_state,
            'unmatched_studies': int(unmatched_studies),
            'current_matches': int(current_matches),
        },

        'readiness': {
            'status': readiness_status,
            'blockers': readiness_blockers,
        },

        'assignment': {
            'offer_status': assignment_offers,
            'active_assignments': int(active_assignments),
            'ready_unassigned': int(ready_unassigned),
        },

        'reporting': {
            'status': report_status,
        },

        'events': {
            'outbox_status': outbox_status,
        },
    })


