@app.post('/payments/<int:payment_id>/refund')
@require_perm('payments.refund')
def refund_payment(payment_id):
    p=Payment.query.get_or_404(payment_id)
    o=p.order
    amount=float(request.form.get('amount') or 0)
    reason=(request.form.get('reason') or '').strip()
    reference=(request.form.get('reference') or '').strip()

    already=sum(float(x.amount or 0) for x in PaymentRefund.query.filter_by(payment_id=p.id).all())
    refundable=max(0.0,float(p.amount or 0)-already)

    if amount<=0 or amount>refundable+0.001:
        flash(f'Invalid refund amount. Maximum refundable is {refundable:.2f}.','danger')
        return redirect(request.referrer or url_for('cashier_workstation'))
    if not reason:
        flash('Refund reason is required.','danger')
        return redirect(request.referrer or url_for('cashier_workstation'))

    r=PaymentRefund(
        payment_id=p.id,order_id=o.id,amount=amount,reason=reason,
        reference=reference,created_by=current_user().id
    )
    db.session.add(r)
    o.paid_amount=max(0.0,round(float(o.paid_amount or 0)-amount,2))

    if abs(refundable-amount)<0.001:
        p.status='REFUNDED'
    else:
        p.status='PARTIAL_REFUND'

    audit('PAYMENT_REFUND','order',o.id,
          f'payment={p.id}; amount={amount}; reason={reason}; reference={reference}')
    db.session.commit()
    flash(f'Refund {amount:.2f} completed.','success')
    return redirect(request.referrer or url_for('cashier_workstation'))

@app.route('/accounting/reports')
@require_perm('financial.view')
def accounting_reports():
    start=request.args.get('start','').strip()
    end=request.args.get('end','').strip()
    branch_id=request.args.get('branch_id',type=int)
    q=Order.query
    if start: q=q.filter(Order.scheduled>=datetime.fromisoformat(start))
    if end: q=q.filter(Order.scheduled<datetime.fromisoformat(end)+timedelta(days=1))
    if branch_id: q=q.filter(Order.branch_id==branch_id)
    rows=q.order_by(Order.scheduled.desc()).all()
    gross=sum(float(o.contract_price or o.gross_price or 0) for o in rows)
    patient_share=sum(float(o.patient_share or 0) for o in rows)
    company_share=sum(float(o.company_share or 0) for o in rows)
    collected=sum(float(o.paid_amount or 0) for o in rows)
    balance=sum(max(order_balance(o),0) for o in rows)
    cash=visa=wallet=bank=0
    receipts=[]
    ids=[o.id for o in rows]
    if ids:
        receipts=Receipt.query.filter(Receipt.order_id.in_(ids)).all()
    for r in receipts:
        val=float(r.amount or 0)
        m=(r.payment_method or '').upper()
        if m=='CASH': cash+=val
        elif m in ('VISA','MASTERCARD','CARD'): visa+=val
        elif m=='WALLET': wallet+=val
        else: bank+=val
    report_only=sum(1 for o in rows if o.report_delivered and not o.images_delivered)
    images_only=sum(1 for o in rows if o.images_delivered and not o.report_delivered)
    both=sum(1 for o in rows if o.report_delivered and o.images_delivered)
    none=sum(1 for o in rows if not o.report_delivered and not o.images_delivered)
    return render_template('accounting_reports.html',rows=rows,gross=gross,patient_share=patient_share,
        company_share=company_share,collected=collected,balance=balance,cash=cash,visa=visa,wallet=wallet,bank=bank,
        report_only=report_only,images_only=images_only,both=both,none=none,
        branches=Branch.query.order_by(Branch.name).all())

