@app.route('/admin/diagnostics')
@require_perm('users.view')
def admin_diagnostics():
    checks=[]

    try:
        db.session.execute(text('SELECT 1'))
        checks.append(('Database','OK','PostgreSQL connection successful'))
    except Exception as exc:
        checks.append(('Database','ERROR',str(exc)))

    checks.append(('PACS','OK' if orthanc_ok() else 'ERROR',
                   'Orthanc responded' if orthanc_ok() else 'Orthanc is not reachable from RIS'))

    checks.append(('Report Storage','OK' if os.path.isdir(REPORT_DIR) and os.access(REPORT_DIR,os.W_OK) else 'ERROR',REPORT_DIR))
    checks.append(('Attachment Storage','OK' if os.path.isdir(ATTACHMENT_DIR) and os.access(ATTACHMENT_DIR,os.W_OK) else 'ERROR',ATTACHMENT_DIR))

    agent_path=os.path.join(os.path.dirname(__file__),'downloads','RIS-Reporting-Agent-Auto-v2.zip')
    checks.append(('Word Reporting Agent','OK' if os.path.exists(agent_path) else 'WARNING',
                   'Bundled' if os.path.exists(agent_path) else 'Agent package is missing; DOCX download/upload still works'))

    critical_routes=[
        '/api/reporting/health','/doctor','/reports/<int:order_id>',
        '/reports/<int:order_id>/word','/reports/<int:order_id>/upload',
        '/reporting-agent/download','/appointments','/analytics'
    ]
    rules={r.rule for r in app.url_map.iter_rules()}
    for route in critical_routes:
        checks.append((f'Route {route}','OK' if route in rules else 'ERROR',
                       'Registered' if route in rules else 'Missing'))

    return render_template('diagnostics.html',checks=checks,version=APP_VERSION)


def create_reporting_demo_cases():
    specs=[
        ('DEMO001','Ahmed Hassan Demo','M','1985-05-12','CT','CT-BRAIN-NC','DRAFT'),
        ('DEMO002','Mona Ali Demo','F','1992-11-03','MR','MR-LSPINE-NC','PARTIAL'),
        ('DEMO003','Omar Mahmoud Demo','M','1978-02-20','US','US-ABD','VERIFIED'),
        ('DEMO004','Sara Ibrahim Demo','F','1988-08-14','MR','MR-BRAIN-NC','SECOND_VERIFIED'),
        ('DEMO005','Youssef Adel Demo','M','1969-01-05','CT','CT-CHEST-C','FINAL'),
        ('DEMO006','Nour Sameh Demo','F','1995-09-30','DX','XR-CHEST-PA-LAT','ADDENDUM'),
    ]
    branch=Branch.query.first()
    created=[]
    for pid,name,sex,dob,modality,proc_code,status in specs:
        patient=Patient.query.filter_by(patient_id=pid).first()
        if not patient:
            patient=Patient(patient_id=pid,name=name,sex=sex,dob=datetime.strptime(dob,'%Y-%m-%d').date(),
                            phone='01000000000',national_id='DEMO-'+pid,address='Demo Patient')
            db.session.add(patient); db.session.flush()
        proc=Procedure.query.filter_by(code=proc_code).first() or Procedure.query.filter_by(modality=modality).first()
        if not proc:
            continue
        existing=Order.query.filter_by(patient_id=patient.id,procedure_id=proc.id).first()
        if existing:
            created.append(existing); continue
        device=route_device(branch.id,proc.modality) if branch else None
        order=Order(accession='DEMO-'+pid,patient_id=patient.id,procedure_id=proc.id,
                    branch_id=branch.id if branch else None,device_id=device.id if device else None,
                    modality=proc.modality,procedure=proc.name,station_ae=device.ae_title if device else '',
                    scheduled=datetime.utcnow(),status='FINAL' if status=='FINAL' else 'REPORTING',
                    gross_price=float(proc.base_price or 0),contract_price=float(proc.base_price or 0),
                    patient_share=float(proc.base_price or 0),company_share=0,paid_amount=0,
                    created_by=current_user().id if current_user() else None)
        db.session.add(order); db.session.flush()
        report=Report(order_id=order.id,accession=order.accession,status=status,radiologist='Dr. Demo',
                      findings=f'Demo findings for {proc.name}.',impression=f'Demo impression for {proc.name}.')
        if status in ('VERIFIED','SECOND_VERIFIED','FINAL'):
            report.verified_by='Dr. Demo Verifier'; report.verified_at=datetime.utcnow()
        if status in ('SECOND_VERIFIED','FINAL'):
            report.second_verified_by='Dr. Demo Second Verifier'; report.second_verified_at=datetime.utcnow()
        if status=='FINAL':
            report.finalized_by='Dr. Demo Finalizer'; report.finalized_at=datetime.utcnow()
        if status=='ADDENDUM':
            report.addendum_no=1
        db.session.add(report); db.session.flush()
        db.session.add(ReportVersion(report_id=report.id,accession=order.accession,version_no=1,
                                     action='DEMO_'+status,findings=report.findings,
                                     impression=report.impression,radiologist=report.radiologist))
        created.append(order)
    db.session.commit()
    return created

