def _strategy_action(value,default='WARN'):
    value=str(value or default).upper()

    if value not in (
        'BLOCK',
        'WARN',
        'ALLOW',
        'IGNORE',
        'COORDINATOR'
    ):
        return default

    return value


def _strategy_snapshot(row):

    fields=(
        'name',
        'enabled',
        'priority',
        'branch_id',
        'modality',
        'procedure_pattern',
        'assignment_mode',
        'fallback_mode',
        'pacs_missing_action',
        'images_incomplete_action',
        'documents_missing_action',
        'notes_missing_action',
        'attachments_missing_action',
        'history_missing_action',
        'require_modality_match',
        'require_branch_match',
        'require_online',
        'prefer_online',
        'min_images',
        'min_completion_percent',
        'stable_seconds',
        'routine_timeout_seconds',
        'urgent_timeout_seconds',
        'stat_timeout_seconds',
        'busy_snooze_minutes',
        'max_offer_attempts',
        'active_from',
        'active_to',
        'version_no'
    )

    return {
        f:getattr(row,f,None)
        for f in fields
    }

def _strategy_change_summary(before, after):
    changes=[]

    fields=(
        'name',
        'enabled',
        'priority',
        'branch_id',
        'modality',
        'procedure_pattern',
        'assignment_mode',
        'fallback_mode',
        'pacs_missing_action',
        'images_incomplete_action',
        'documents_missing_action',
        'notes_missing_action',
        'attachments_missing_action',
        'history_missing_action',
        'require_modality_match',
        'require_branch_match',
        'require_online',
        'prefer_online',
        'min_images',
        'min_completion_percent',
        'stable_seconds',
        'routine_timeout_seconds',
        'urgent_timeout_seconds',
        'stat_timeout_seconds',
        'busy_snooze_minutes',
        'max_offer_attempts',
        'active_from',
        'active_to'
    )

    for field in fields:
        old=before.get(field)
        new=after.get(field)

        if old!=new:
            changes.append(
                f'{field}: {old} -> {new}'
            )

    if not changes:
        return 'No functional changes'

    return '; '.join(changes)[:1500]





@app.route(
    '/admin/assignment-strategies',
    methods=['GET','POST']
)
@require_perm('assignment.manage')
def admin_assignment_strategies():

    if request.method=='POST':

        sid=request.form.get(
            'strategy_id',
            type=int
        )

        row=(
            AssignmentStrategy.query.get(sid)
            if sid
            else AssignmentStrategy()
        )

        if sid and not row:
            abort(404)

        if not sid:
            db.session.add(row)

        before_snapshot=(
            _strategy_snapshot(row)
            if sid
            else {}
        )

        row.name=(
            request.form.get('name')
            or 'Default Strategy'
        ).strip()

        # Protect the unique strategy name and return a friendly UI
        # message instead of a PostgreSQL IntegrityError.
        with db.session.no_autoflush:
            duplicate=AssignmentStrategy.query.filter(
                AssignmentStrategy.name==row.name
            )

            if sid:
                duplicate=duplicate.filter(
                    AssignmentStrategy.id!=sid
                )

            duplicate=duplicate.first()

        if duplicate:
            db.session.rollback()

            flash(
                f'Strategy name "{row.name}" already exists. '
                'Edit the existing strategy or choose another name.',
                'warning'
            )

            return redirect(
                url_for('admin_assignment_strategies')
            )

        row.enabled=(
            request.form.get('enabled')=='1'
        )

        row.priority=(
            request.form.get(
                'priority',
                type=int
            )
            or 100
        )

        row.branch_id=request.form.get(
            'branch_id',
            type=int
        )

        row.modality=(
            request.form.get('modality')
            or ''
        ).strip().upper()

        row.procedure_pattern=(
            request.form.get(
                'procedure_pattern'
            )
            or ''
        ).strip()

        row.assignment_mode=(
            request.form.get(
                'assignment_mode'
            )
            or 'OFFER_ACCEPT'
        ).upper()

        row.fallback_mode=(
            request.form.get(
                'fallback_mode'
            )
            or 'OPEN_POOL'
        ).upper()

        row.pacs_missing_action=_strategy_action(
            request.form.get(
                'pacs_missing_action'
            ),
            'BLOCK'
        )

        row.images_incomplete_action=_strategy_action(
            request.form.get(
                'images_incomplete_action'
            ),
            'BLOCK'
        )

        row.documents_missing_action=_strategy_action(
            request.form.get(
                'documents_missing_action'
            ),
            'WARN'
        )

        row.notes_missing_action=_strategy_action(
            request.form.get(
                'notes_missing_action'
            ),
            'WARN'
        )

        row.attachments_missing_action=_strategy_action(
            request.form.get(
                'attachments_missing_action'
            ),
            'WARN'
        )

        row.history_missing_action=_strategy_action(
            request.form.get(
                'history_missing_action'
            ),
            'IGNORE'
        )

        row.require_modality_match=(
            request.form.get(
                'require_modality_match'
            )=='1'
        )

        row.require_branch_match=(
            request.form.get(
                'require_branch_match'
            )=='1'
        )

        row.require_online=(
            request.form.get(
                'require_online'
            )=='1'
        )

        row.prefer_online=(
            request.form.get(
                'prefer_online'
            )=='1'
        )

        row.min_images=(
            request.form.get(
                'min_images',
                type=int
            )
            or 0
        )

        row.stable_seconds=(
            request.form.get(
                'stable_seconds',
                type=int
            )
            or 120
        )

        row.routine_timeout_seconds=(
            request.form.get(
                'routine_timeout_seconds',
                type=int
            )
            or 300
        )

        row.urgent_timeout_seconds=(
            request.form.get(
                'urgent_timeout_seconds',
                type=int
            )
            or 120
        )

        row.stat_timeout_seconds=(
            request.form.get(
                'stat_timeout_seconds',
                type=int
            )
            or 60
        )

        row.busy_snooze_minutes=(
            request.form.get(
                'busy_snooze_minutes',
                type=int
            )
            or 30
        )

        row.max_offer_attempts=(
            request.form.get(
                'max_offer_attempts',
                type=int
            )
            or 5
        )

        row.version_no=(
            int(row.version_no or 0)+1
        )

        u=current_user()
        row.updated_by=u.id if u else None

        db.session.flush()

        after_snapshot=_strategy_snapshot(row)

        manual_note=(
            request.form.get('change_note')
            or ''
        ).strip()

        auto_note=_strategy_change_summary(
            before_snapshot,
            after_snapshot
        )

        final_note=manual_note or auto_note

        db.session.add(
            AssignmentStrategyVersion(
                strategy_id=row.id,
                version_no=row.version_no,
                snapshot_json=json.dumps(
                    after_snapshot,
                    ensure_ascii=False,
                    default=str
                ),
                changed_by=current_user().id,
                change_note=final_note
            )
        )

        audit(
            'ASSIGNMENT_STRATEGY_SAVE',
            'assignment_strategy',
            row.id,
            f'{row.name} v{row.version_no}'
        )

        db.session.commit()

        flash(
            'Assignment strategy saved.',
            'success'
        )

        return redirect(
            url_for(
                'admin_assignment_strategies'
            )
        )

    rows=AssignmentStrategy.query.order_by(
        AssignmentStrategy.priority,
        AssignmentStrategy.id
    ).all()

    branches=Branch.query.filter_by(
        active=True
    ).order_by(
        Branch.name
    ).all()

    return render_template(
        'admin_assignment_strategies.html',
        rows=rows,
        branches=branches
    )


def assignment_candidate_diagnostics(order,policy):

    rows=[]

    doctors=User.query.join(
        Role,
        User.role_id==Role.id
    ).filter(
        db.func.upper(Role.code).in_(
            ['RADIOLOGIST','DOCTOR']
        ),
        User.active==True
    ).order_by(
        User.id
    ).all()

    for u in doctors:

        reasons=[]

        profile=DoctorAssignmentProfile.query.filter_by(
            user_id=u.id
        ).first()

        state=doctor_availability(u)
        online=doctor_is_online(u)

        active_cases=CaseAssignment.query.filter_by(
            doctor_user_id=u.id,
            active=True
        ).count()

        max_cases=(
            int(profile.max_active_cases or 20)
            if profile
            else 20
        )

        modality_match=True
        branch_match=True

        if not profile:
            reasons.append('NO_PROFILE')

        else:

            if not profile.auto_assign:
                reasons.append('AUTO_ASSIGN_DISABLED')

            if not profile.available:
                reasons.append('PROFILE_UNAVAILABLE')

            modalities=[
                x.strip().upper()
                for x in (profile.modalities or '').split(',')
                if x.strip()
            ]

            if (
                modalities
                and str(order.modality or '').upper()
                not in modalities
            ):
                modality_match=False
                reasons.append('MODALITY_MISMATCH')

            branches=[
                x.strip()
                for x in (profile.branches or '').split(',')
                if x.strip()
            ]

            if (
                branches
                and str(order.branch_id or '')
                not in branches
            ):
                branch_match=False
                reasons.append('BRANCH_MISMATCH')

        if state.state=='BUSY':
            reasons.append('BUSY')

        elif state.state in ('AWAY','OFFLINE'):

            if policy and policy.mode!='ALL':
                reasons.append(
                    'AVAILABILITY_'+state.state
                )

        if (
            policy
            and policy.mode=='ONLINE_ONLY'
            and not online
        ):
            reasons.append('OFFLINE')

        if active_cases>=max_cases:
            reasons.append(
                'MAX_ACTIVE_CASES_REACHED'
            )

        rows.append({
            'id':u.id,
            'username':u.username,
            'name':u.full_name or u.username,
            'eligible':len(reasons)==0,
            'reasons':reasons,
            'online':bool(online),
            'availability_state':state.state,
            'active_cases':active_cases,
            'max_active_cases':max_cases,
            'modality_match':modality_match,
            'branch_match':branch_match,
            'profile_exists':bool(profile),
            'auto_assign':(
                bool(profile.auto_assign)
                if profile
                else False
            ),
            'available':(
                bool(profile.available)
                if profile
                else False
            )
        })

    return rows


