@app.route('/admin/inventory/export/<fmt>')
@require_perm('inventory.manage')
def admin_inventory_export(fmt):
    items=Consumable.query.order_by(Consumable.code).all()
    if fmt=='csv':
        out=io.StringIO();w=csv.DictWriter(out,fieldnames=INVENTORY_IMPORT_COLUMNS);w.writeheader()
        for c in items:w.writerow(inventory_row(c))
        return send_file(io.BytesIO(out.getvalue().encode('utf-8-sig')),as_attachment=True,download_name='inventory-master.csv',mimetype='text/csv')
    if fmt=='xlsx':
        wb=Workbook();ws=wb.active;ws.title='Inventory Master';ws.append(INVENTORY_IMPORT_COLUMNS)
        for c in items:
            row=inventory_row(c);ws.append([row[x] for x in INVENTORY_IMPORT_COLUMNS])
        for cell in ws[1]:cell.font=Font(bold=True,color='FFFFFF');cell.fill=PatternFill('solid',fgColor='1F4E78')
        for i in range(1,len(INVENTORY_IMPORT_COLUMNS)+1):ws.column_dimensions[get_column_letter(i)].width=20
        buf=io.BytesIO();wb.save(buf);buf.seek(0)
        return send_file(buf,as_attachment=True,download_name='inventory-master.xlsx',
          mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    abort(400)

