@app.route('/admin/audit')
@require_perm('audit.view')
def admin_audit():
    action=(request.args.get('action') or '').strip()[:100]
    username=(request.args.get('username') or '').strip()[:80]
    ip=(request.args.get('ip') or '').strip()[:80]
    entity=(request.args.get('entity') or '').strip()[:80]
    q=AuditLog.query
    if action:q=q.filter(AuditLog.action.ilike(f'%{action}%'))
    if username:q=q.filter(AuditLog.username.ilike(f'%{username}%'))
    if ip:q=q.filter(AuditLog.ip.ilike(f'%{ip}%'))
    if entity:q=q.filter(AuditLog.entity.ilike(f'%{entity}%'))
    rows=q.order_by(AuditLog.id.desc()).limit(1000).all()
    since=datetime.utcnow()-timedelta(hours=24)
    failed_24h=AuditLog.query.filter(AuditLog.action=='LOGIN_FAILED',AuditLog.created_at>=since).count()
    successful_24h=AuditLog.query.filter(AuditLog.action=='LOGIN',AuditLog.created_at>=since).count()
    return render_template('admin_audit.html',rows=rows,action=action,username=username,ip=ip,entity=entity,
        failed_24h=failed_24h,successful_24h=successful_24h,
        cancellation_count=AuditLog.query.filter(AuditLog.action.in_([
            'APPOINTMENT_CANCELLED_ADMIN','ORDER_CANCELLED_ADMIN','ORDER_REFERRAL_REMOVED'])).count())

def cancellation_reason():
    reason=(request.form.get('reason') or '').strip()
    if len(reason)<5:abort(400,'Cancellation reason must contain at least 5 characters.')
    return reason[:1000]

def _cancellation_literal_search_pattern(term):
    # Cancellation Center search values are identifiers/user text, not
    # caller-controlled LIKE patterns. Escape SQL LIKE metacharacters so
    # values such as '%' or '_' cannot broaden candidate selection.
    term=(term or '').strip()[:120]
    escaped=(
        term.replace('\\','\\\\')
            .replace('%','\\%')
            .replace('_','\\_')
    )
    return term,f'%{escaped}%'


def cancellation_search_rows(term):
    term,pattern=_cancellation_literal_search_pattern(term)
    if not term:return [],[]

    orders=(
        Order.query
        .join(Patient,Order.patient_id==Patient.id)
        .filter(db.or_(
            Order.accession.ilike(pattern,escape='\\'),
            Patient.patient_id.ilike(pattern,escape='\\'),
            Patient.name.ilike(pattern,escape='\\'),
            Patient.phone.ilike(pattern,escape='\\'),
        ))
        .order_by(Order.id.desc())
        .limit(50)
        .all()
    )

    appointments=(
        Appointment.query
        .join(Patient,Appointment.patient_id==Patient.id)
        .filter(db.or_(
            Patient.patient_id.ilike(pattern,escape='\\'),
            Patient.name.ilike(pattern,escape='\\'),
            Patient.phone.ilike(pattern,escape='\\'),
        ))
        .order_by(Appointment.id.desc())
        .limit(50)
        .all()
    )

    # Internal Order ID / Appointment ID are exact-only. Numeric patient IDs
    # or phone fragments still participate in the text search above.
    if term.isdigit():
        order=db.session.get(Order,int(term))
        appointment=db.session.get(Appointment,int(term))
        if order and order not in orders:orders.insert(0,order)
        if appointment and appointment not in appointments:appointments.insert(0,appointment)

    return orders[:50],appointments[:50]




# RB_GRANULAR_DELETE_IMAGES_ONLY_V1
def granular_delete_images_only_preflight(
    order,
    typed_accession,
    reason,
    cached_orthanc_response=None,
):
    blockers=[]

    user=current_user()

    if (
        not user
        or not getattr(user, 'role', None)
        or getattr(user.role, 'code', '') != 'SUPER_ADMIN'
    ):
        blockers.append('SUPER_ADMIN_REQUIRED')

    reason=(reason or '').strip()
    typed_accession=(typed_accession or '').strip()
    accession=(order.accession or '').strip()
    study_id=(order.pacs_study_id or '').strip()

    if len(reason) < 5:
        blockers.append('REASON_REQUIRED')

    if not accession:
        blockers.append('ORDER_ACCESSION_MISSING')
    elif typed_accession != accession:
        blockers.append('ACCESSION_CONFIRMATION_MISMATCH')

    if not study_id:
        blockers.append('PACS_STUDY_ID_MISSING')

    patient=db.session.get(Patient, order.patient_id)

    if not patient:
        blockers.append('PATIENT_MISSING')

    same_study_orders=[]

    if study_id:
        same_study_orders=(
            Order.query
            .filter(Order.pacs_study_id == study_id)
            .order_by(Order.id)
            .all()
        )

        others=[
            row
            for row in same_study_orders
            if row.id != order.id
        ]

        if others:
            blockers.append('PACS_STUDY_SHARED_BY_OTHER_ORDER')

    active_transfer_count=0

    if study_id:
        active_transfer_count=(
            PacsTransferJob.query
            .filter(
                PacsTransferJob.order_id == order.id,
                PacsTransferJob.orthanc_study_id == study_id,
                PacsTransferJob.status.in_(
                    ('PENDING','SENDING')
                ),
            )
            .count()
        )

        if active_transfer_count:
            blockers.append('ACTIVE_PACS_TRANSFER_JOB')

    orthanc_status=None
    orthanc_payload=None
    orthanc_error=''

    if study_id:
        try:
            response=(
                cached_orthanc_response
                if cached_orthanc_response is not None
                else requests.get(
                    f'{PACS_ORTHANC_URL}/studies/{study_id}',
                    auth=_orthanc_auth(),
                    timeout=10,
                )
            )

            orthanc_status=response.status_code

            if response.status_code == 200:
                orthanc_payload=response.json()
            else:
                blockers.append('ORTHANC_STUDY_NOT_AVAILABLE')

        except Exception as exc:
            orthanc_error=type(exc).__name__
            blockers.append('ORTHANC_LOOKUP_FAILED')

    if orthanc_payload:
        tags=orthanc_payload.get('MainDicomTags') or {}
        patient_tags=orthanc_payload.get('PatientMainDicomTags') or {}

        orthanc_accession=(tags.get('AccessionNumber') or '').strip()
        orthanc_patient_id=(patient_tags.get('PatientID') or '').strip()
        orthanc_uid=(tags.get('StudyInstanceUID') or '').strip()

        ris_patient_id=(
            (patient.patient_id or '').strip()
            if patient
            else ''
        )

        ris_uid=(
            getattr(order, 'study_instance_uid', '')
            or ''
        ).strip()

        if not orthanc_accession or orthanc_accession != accession:
            blockers.append('ORTHANC_ACCESSION_MISMATCH')

        if (
            orthanc_patient_id
            and ris_patient_id
            and orthanc_patient_id != ris_patient_id
        ):
            blockers.append('ORTHANC_PATIENT_ID_MISMATCH')

        if (
            orthanc_uid
            and ris_uid
            and orthanc_uid != ris_uid
        ):
            blockers.append('ORTHANC_STUDY_UID_MISMATCH')

    return {
        'allowed': not blockers,
        'blockers': blockers,
        'reason': reason,
        'typed_accession': typed_accession,
        'accession': accession,
        'study_id': study_id,
        'patient': patient,
        'orthanc_status': orthanc_status,
        'orthanc_payload': orthanc_payload,
        'orthanc_error': orthanc_error,
        'same_study_order_count': len(same_study_orders),
        'active_transfer_count': active_transfer_count,
    }


def granular_delete_images_only_execute(
    order,
    typed_accession,
    reason,
    preflight=None,
    after_delete=None,
):
    order_id=order.id

    # Phase 2B callers may persist the exact preflight result in the
    # execution ledger before crossing the irreversible DELETE boundary.
    # Legacy/admin callers retain the original self-contained behavior.
    if preflight is None:
        preflight=granular_delete_images_only_preflight(
            order,
            typed_accession,
            reason,
        )

    if not preflight['allowed']:
        audit(
            'PACS_IMAGES_DELETE_BLOCKED_ADMIN',
            'order',
            order.id,
            (
                f"accession={order.accession}; "
                f"study={preflight['study_id']}; "
                f"blockers={','.join(preflight['blockers'])}; "
                f"reason={reason}"
            ),
        )
        db.session.commit()

        return {
            'ok': False,
            'deleted': False,
            'blockers': preflight['blockers'],
        }, 409

    # Final critical revalidation at the irreversible boundary.
    # The earlier preflight is persisted in the correction execution ledger,
    # but PACS/RIS state can change between that check and Orthanc DELETE.
    # Refresh the order and rerun the same safety contract immediately before
    # deletion; never cross the boundary on stale identity/transfer state.
    initial_study_id=(preflight.get('study_id') or '').strip()
    initial_accession=(preflight.get('accession') or '').strip()

    try:
        db.session.refresh(order)
    except Exception as exc:
        audit(
            'PACS_IMAGES_DELETE_BLOCKED_ADMIN',
            'order',
            order.id,
            (
                f"accession={order.accession}; "
                f"study={initial_study_id}; "
                f"stage=FINAL_REVALIDATION_REFRESH; "
                f"error={type(exc).__name__}; "
                f"reason={reason}"
            ),
        )
        db.session.commit()

        return {
            'ok': False,
            'deleted': False,
            'ris_state_updated': False,
            'error': 'FINAL_REVALIDATION_FAILED',
            'blockers': ['ORDER_REFRESH_FAILED'],
        }, 409

    final_preflight=granular_delete_images_only_preflight(
        order,
        typed_accession,
        reason,
    )

    final_blockers=list(final_preflight.get('blockers') or ())
    final_study_id=(final_preflight.get('study_id') or '').strip()
    final_accession=(final_preflight.get('accession') or '').strip()

    if final_study_id != initial_study_id:
        final_blockers.append('PACS_STUDY_CHANGED_AFTER_PREFLIGHT')

    if final_accession != initial_accession:
        final_blockers.append('ACCESSION_CHANGED_AFTER_PREFLIGHT')

    if final_blockers:
        audit(
            'PACS_IMAGES_DELETE_BLOCKED_ADMIN',
            'order',
            order.id,
            (
                f"accession={order.accession}; "
                f"study={final_study_id}; "
                f"stage=FINAL_REVALIDATION; "
                f"blockers={','.join(final_blockers)}; "
                f"reason={reason}"
            ),
        )
        db.session.commit()

        return {
            'ok': False,
            'deleted': False,
            'ris_state_updated': False,
            'error': 'FINAL_REVALIDATION_BLOCKED',
            'blockers': final_blockers,
        }, 409

    study_id=final_study_id
    image_count_before=order.pacs_image_count or 0
    study_uid=(
        getattr(order, 'study_instance_uid', '')
        or ''
    )

    audit(
        'PACS_IMAGES_DELETE_REQUESTED_ADMIN',
        'order',
        order.id,
        (
            f"accession={order.accession}; "
            f"patient_id={order.patient.patient_id if order.patient else ''}; "
            f"study={study_id}; "
            f"study_uid={study_uid}; "
            f"image_count_before={image_count_before}; "
            f"reason={reason}"
        ),
    )
    db.session.commit()

    try:
        response=requests.delete(
            f'{PACS_ORTHANC_URL}/studies/{study_id}',
            auth=_orthanc_auth(),
            timeout=20,
        )
    except Exception as exc:
        audit(
            'PACS_IMAGES_DELETE_FAILED_ADMIN',
            'order',
            order.id,
            (
                f"accession={order.accession}; "
                f"study={study_id}; "
                f"stage=ORTHANC_DELETE_EXCEPTION; "
                f"error={type(exc).__name__}; "
                f"reason={reason}"
            ),
        )
        db.session.commit()

        return {
            'ok': False,
            'deleted': False,
            'error': 'ORTHANC_DELETE_FAILED',
        }, 502

    if response.status_code != 200:
        audit(
            'PACS_IMAGES_DELETE_FAILED_ADMIN',
            'order',
            order.id,
            (
                f"accession={order.accession}; "
                f"study={study_id}; "
                f"stage=ORTHANC_DELETE_HTTP; "
                f"http={response.status_code}; "
                f"reason={reason}"
            ),
        )
        db.session.commit()

        return {
            'ok': False,
            'deleted': False,
            'error': 'ORTHANC_DELETE_REJECTED',
            'http_status': response.status_code,
        }, 502

    # Orthanc accepted the DELETE. Persist VERIFYING before the
    # post-delete absence check or any RIS PACS-state mutation.
    if after_delete is not None:
        after_delete()

    try:
        verify=requests.get(
            f'{PACS_ORTHANC_URL}/studies/{study_id}',
            auth=_orthanc_auth(),
            timeout=10,
        )
    except Exception as exc:
        audit(
            'PACS_IMAGES_DELETE_FAILED_ADMIN',
            'order',
            order.id,
            (
                f"accession={order.accession}; "
                f"study={study_id}; "
                f"stage=ORTHANC_VERIFY_EXCEPTION; "
                f"error={type(exc).__name__}; "
                f"reason={reason}"
            ),
        )
        db.session.commit()

        return {
            'ok': False,
            'deleted': True,
            'ris_state_updated': False,
            'error': 'ORTHANC_DELETE_VERIFICATION_FAILED',
        }, 502

    if verify.status_code != 404:
        audit(
            'PACS_IMAGES_DELETE_FAILED_ADMIN',
            'order',
            order.id,
            (
                f"accession={order.accession}; "
                f"study={study_id}; "
                f"stage=ORTHANC_VERIFY_PRESENT; "
                f"http={verify.status_code}; "
                f"reason={reason}"
            ),
        )
        db.session.commit()

        return {
            'ok': False,
            'deleted': True,
            'ris_state_updated': False,
            'error': 'ORTHANC_STUDY_STILL_PRESENT',
        }, 502

    try:
        order.pacs_image_count=0
        order.pacs_status='IMAGES_DELETED'
        order.pacs_last_seen_at=datetime.utcnow()
        order.pacs_last_change_at=datetime.utcnow()

        audit(
            'PACS_IMAGES_DELETED_ADMIN',
            'order',
            order.id,
            (
                f"accession={order.accession}; "
                f"patient_id={order.patient.patient_id if order.patient else ''}; "
                f"study={study_id}; "
                f"study_uid={study_uid}; "
                f"image_count_before={image_count_before}; "
                f"image_count_after=0; "
                f"orthanc_verified_absent=yes; "
                f"reason={reason}"
            ),
        )

        db.session.commit()

    except Exception as exc:
        db.session.rollback()

        try:
            audit(
                'PACS_IMAGES_DELETE_FAILED_ADMIN',
                'order',
                order.id,
                (
                    f"accession={order.accession}; "
                    f"study={study_id}; "
                    f"stage=RIS_STATE_UPDATE_AFTER_PACS_DELETE; "
                    f"error={type(exc).__name__}; "
                    f"reason={reason}"
                ),
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        return {
            'ok': False,
            'deleted': True,
            'ris_state_updated': False,
            'error': 'RIS_STATE_UPDATE_FAILED_AFTER_PACS_DELETE',
        }, 500

    return {
        'ok': True,
        'deleted': True,
        'ris_state_updated': True,
        'order_id': order.id,
        'accession': order.accession,
        'pacs_study_id': study_id,
        'pacs_status': order.pacs_status,
        'pacs_image_count': order.pacs_image_count,
    }, 200


@app.post(
    '/admin/cancellation-center/order/<int:order_id>/delete-images'
)
@require_perm('data.cancel.case')
def granular_delete_order_images_only(order_id):
    order=Order.query.get_or_404(order_id)

    reason=(request.form.get('reason') or '').strip()
    typed_accession=(
        request.form.get('confirm_accession')
        or ''
    ).strip()

    return granular_delete_images_only_execute(
        order,
        typed_accession,
        reason,
    )


# RB_DELETE_REPORTS_ONLY_PREVIEW_V1
def granular_delete_reports_only_preview_snapshot(order, patient, reports):
    """Read-only dependency preflight for Delete Reports Only."""
    from datetime import datetime as _preview_datetime
    from pathlib import Path as _PreviewPath
    from sqlalchemy import inspect as _sa_inspect, text as _sa_text

    report_ids=[int(row.id) for row in reports]
    version_rows=[]
    coordinator_rows=[]
    artifacts=[]
    blockers=[]
    warnings=[]

    if report_ids:
        version_rows=(
            ReportVersion.query
            .filter(ReportVersion.report_id.in_(report_ids))
            .order_by(ReportVersion.report_id,ReportVersion.version_no)
            .all()
        )
        coordinator_rows=(
            CoordinatorTask.query
            .filter(CoordinatorTask.report_id.in_(report_ids))
            .order_by(CoordinatorTask.id)
            .all()
        )

    report_identity_mismatch=False
    version_identity_mismatch=False

    for report in reports:
        if int(getattr(report,'order_id',0) or 0) != int(order.id):
            report_identity_mismatch=True

    expected_accession=str(getattr(order,'accession','') or '').strip()
    for version in version_rows:
        version_accession=str(getattr(version,'accession','') or '').strip()
        if expected_accession and version_accession != expected_accession:
            version_identity_mismatch=True

    if report_identity_mismatch:
        blockers.append('Report/order identity mismatch.')
    if version_identity_mismatch:
        blockers.append('ReportVersion accession does not match the selected Order.')
    if coordinator_rows:
        blockers.append('CoordinatorTask references the report; Reports Only deletion is blocked.')

    lease_rows=[]
    lease_table_present=False
    try:
        inspector=_sa_inspect(db.engine)
        lease_table_present=inspector.has_table('report_edit_lease')
        if lease_table_present and report_ids:
            placeholders=','.join(str(int(value)) for value in report_ids)
            lease_rows=db.session.execute(
                _sa_text(
                    'SELECT id,order_id,report_id,user_id,editor_type,expires_at '
                    'FROM report_edit_lease '
                    'WHERE order_id = :order_id OR report_id IN ('+placeholders+')'
                ),
                {'order_id':int(order.id)},
            ).mappings().all()
    except Exception as exc:
        blockers.append('Report edit lease state could not be verified.')
        warnings.append(type(exc).__name__)

    now=_preview_datetime.utcnow()
    active_lease_count=0
    expired_lease_count=0
    lease_preview=[]
    for row in lease_rows:
        expires_at=row.get('expires_at')
        compare_expiry=expires_at

        # Raw SQL returns native datetimes on PostgreSQL, but SQLite-backed
        # isolated tests may return DATETIME values as ISO strings. Normalize
        # both forms without mutating lease state. Fail closed when an expiry
        # cannot be interpreted safely.
        if isinstance(compare_expiry,str):
            raw_expiry=compare_expiry.strip()
            if raw_expiry.endswith('Z'):
                raw_expiry=raw_expiry[:-1] + '+00:00'
            try:
                compare_expiry=_preview_datetime.fromisoformat(raw_expiry)
            except ValueError:
                compare_expiry=None
                blockers.append('Report edit lease expiry could not be interpreted.')

        if compare_expiry is not None and getattr(compare_expiry,'tzinfo',None) is not None:
            compare_expiry=compare_expiry.astimezone(
                __import__('datetime').timezone.utc
            ).replace(tzinfo=None)

        active=bool(compare_expiry is not None and compare_expiry > now)
        if active:
            active_lease_count += 1
        elif compare_expiry is not None:
            expired_lease_count += 1
        lease_preview.append({
            'id':row.get('id'),
            'order_id':row.get('order_id'),
            'report_id':row.get('report_id'),
            'user_id':row.get('user_id'),
            'editor_type':row.get('editor_type'),
            'expires_at':expires_at,
            'active':active,
        })

    if active_lease_count:
        blockers.append('Active report edit lease exists.')
    if expired_lease_count:
        warnings.append('Expired report edit lease requires cleanup during execution preflight.')

    if report_ids and not lease_table_present:
        blockers.append('report_edit_lease table is unavailable; lease safety cannot be verified.')

    case_root=None
    case_root_error=None
    try:
        from report_storage_safety import canonical_case_paths
        case_root=_PreviewPath(
            canonical_case_paths(REPORT_DIR,patient,order)['case_root']
        ).resolve()
    except Exception as exc:
        case_root_error=type(exc).__name__
        blockers.append('Canonical report case root could not be resolved.')

    seen_paths=set()
    path_sources=[]
    for report in reports:
        for field in ('source_path','docx_path','pdf_path'):
            value=str(getattr(report,field,None) or '').strip()
            if value:
                path_sources.append(('REPORT',report.id,None,field,value))
    for version in version_rows:
        for field in ('source_path','docx_path','pdf_path'):
            value=str(getattr(version,field,None) or '').strip()
            if value:
                path_sources.append(('REPORT_VERSION',version.report_id,version.id,field,value))

    unsafe_path_count=0
    missing_artifact_count=0
    for owner_type,report_id,version_id,field,value in path_sources:
        try:
            resolved=_PreviewPath(value).expanduser().resolve()
            path_key=str(resolved)
        except Exception:
            resolved=None
            path_key=value

        if path_key in seen_paths:
            continue
        seen_paths.add(path_key)

        inside_case_root=False
        if resolved is not None and case_root is not None:
            try:
                resolved.relative_to(case_root)
                inside_case_root=True
            except ValueError:
                inside_case_root=False

        exists=bool(resolved is not None and resolved.exists())
        if not inside_case_root:
            unsafe_path_count += 1
        if not exists:
            missing_artifact_count += 1

        artifacts.append({
            'path':path_key,
            'owner_type':owner_type,
            'report_id':report_id,
            'version_id':version_id,
            'field':field,
            'exists':exists,
            'inside_case_root':inside_case_root,
        })

    if unsafe_path_count:
        blockers.append('One or more report artifact paths are outside the canonical case root.')
    if missing_artifact_count:
        warnings.append('One or more referenced report artifacts are missing on disk.')

    if not reports:
        blockers.append('No Report row exists for this Order.')

    blocker_codes=[]
    if report_identity_mismatch:
        blocker_codes.append('REPORT_ORDER_IDENTITY_MISMATCH')
    if version_identity_mismatch:
        blocker_codes.append('REPORT_VERSION_ACCESSION_MISMATCH')
    if coordinator_rows:
        blocker_codes.append('COORDINATOR_TASK_PRESENT')
    if active_lease_count:
        blocker_codes.append('ACTIVE_REPORT_EDIT_LEASE')
    if 'Report edit lease expiry could not be interpreted.' in blockers:
        blocker_codes.append('LEASE_EXPIRY_UNPARSEABLE')
    if report_ids and not lease_table_present:
        blocker_codes.append('LEASE_STATE_UNAVAILABLE')
    if case_root_error:
        blocker_codes.append('REPORT_CASE_ROOT_UNAVAILABLE')
    if unsafe_path_count:
        blocker_codes.append('REPORT_ARTIFACT_OUTSIDE_CASE_ROOT')
    if not reports:
        blocker_codes.append('NO_REPORT')

    return {
        'report_count':len(reports),
        'report_ids':report_ids,
        'version_count':len(version_rows),
        'versions':[
            {
                'id':row.id,
                'report_id':row.report_id,
                'version_no':row.version_no,
                'accession':row.accession,
                'status':getattr(row,'status',None),
                'source_type':getattr(row,'source_type',None),
            }
            for row in version_rows
        ],
        'coordinator_task_count':len(coordinator_rows),
        'coordinator_tasks':[
            {
                'id':row.id,
                'report_id':row.report_id,
                'status':row.status,
                'assigned_to':row.assigned_to,
            }
            for row in coordinator_rows
        ],
        'lease':{
            'table_present':lease_table_present,
            'active_count':active_lease_count,
            'expired_count':expired_lease_count,
            'rows':lease_preview,
        },
        'storage':{
            'report_root':str(_PreviewPath(REPORT_DIR).resolve()),
            'case_root':str(case_root) if case_root is not None else None,
            'case_root_error':case_root_error,
            'artifact_count':len(artifacts),
            'unsafe_path_count':unsafe_path_count,
            'missing_artifact_count':missing_artifact_count,
            'artifacts':artifacts,
        },
        'blocker_codes':blocker_codes,
        'blockers':blockers,
        'warnings':warnings,
        'can_delete_reports_only':bool(reports) and not blocker_codes,
        'readonly':True,
    }


# RB_DELETE_REPORTS_ONLY_EXECUTION_V1
def _delete_reports_only_is_super_admin(user):
    return bool(
        user
        and getattr(user, 'role', None)
        and str(getattr(user.role, 'code', '') or '').strip().upper() == 'SUPER_ADMIN'
    )


def _delete_reports_only_quarantine_target(patient, order, operation_id):
    """Return a same-filesystem quarantine target under REPORT_DIR."""
    from pathlib import Path as _DeletePath
    from report_storage_safety import canonical_case_paths, safe_token

    paths=canonical_case_paths(REPORT_DIR,patient,order)
    report_root=_DeletePath(REPORT_DIR).resolve()
    quarantine_root=(report_root/'.quarantine'/'reports-only').resolve()
    quarantine_target=(
        quarantine_root
        / safe_token(str(operation_id))
        / safe_token(getattr(patient,'patient_id','PATIENT'))
        / safe_token(getattr(order,'accession','ORDER'))
    ).resolve()

    try:
        quarantine_target.relative_to(report_root)
    except ValueError as exc:
        raise RuntimeError('QUARANTINE_PATH_OUTSIDE_REPORT_ROOT') from exc

    return paths['case_root'].resolve(),quarantine_target


def _delete_reports_only_blocked_response(order, reason, code, blockers, status=409):
    try:
        audit(
            'REPORTS_ONLY_DELETE_BLOCKED_ADMIN',
            'order',
            order.id,
            (
                f"accession={getattr(order,'accession','')}; "
                f"code={code}; "
                f"blockers={','.join(str(x) for x in (blockers or []))}; "
                f"reason={reason}"
            ),
        )
        db.session.commit()
    except Exception:
        db.session.rollback()

    return {
        'ok':False,
        'deleted':False,
        'error':code,
        'blockers':list(blockers or []),
    },status


def granular_delete_reports_only_execute(order, typed_accession, reason):
    """Dependency-safe Delete Reports Only execution.

    Invariants:
      * SUPER_ADMIN only.
      * exact typed Accession and mandatory reason.
      * Report/ReportVersion only; Order/Patient/PACS/Audit are preserved.
      * CoordinatorTask or active edit lease blocks execution.
      * report case directory is moved to same-filesystem quarantine first.
      * database deletion is revalidated under row locks and verified before commit.
      * any database failure attempts to restore quarantined files.
    """
    from pathlib import Path as _DeletePath
    from sqlalchemy import inspect as _delete_inspect, text as _delete_text

    user=current_user()
    reason=str(reason or '').strip()
    typed_accession=str(typed_accession or '').strip()
    expected_accession=str(getattr(order,'accession','') or '').strip()

    if not _delete_reports_only_is_super_admin(user):
        abort(403)

    if len(reason) < 5:
        return _delete_reports_only_blocked_response(
            order,reason,'REASON_REQUIRED',['REASON_REQUIRED'],400
        )

    if not typed_accession or typed_accession != expected_accession:
        return _delete_reports_only_blocked_response(
            order,reason,'ACCESSION_CONFIRMATION_MISMATCH',
            ['ACCESSION_CONFIRMATION_MISMATCH'],409
        )

    patient=getattr(order,'patient',None)
    if patient is None:
        return _delete_reports_only_blocked_response(
            order,reason,'PATIENT_NOT_FOUND',['PATIENT_NOT_FOUND'],409
        )

    initial_reports=(
        Report.query
        .filter_by(order_id=order.id)
        .order_by(Report.id)
        .all()
    )
    initial_preview=granular_delete_reports_only_preview_snapshot(
        order,patient,initial_reports
    )

    if not initial_preview.get('can_delete_reports_only'):
        return _delete_reports_only_blocked_response(
            order,reason,'REPORTS_ONLY_PREFLIGHT_BLOCKED',
            initial_preview.get('blocker_codes') or ['PREFLIGHT_BLOCKED'],409
        )

    initial_report_ids=tuple(initial_preview.get('report_ids') or ())
    initial_version_ids=tuple(
        int(row.get('id')) for row in (initial_preview.get('versions') or [])
    )
    initial_artifact_paths=tuple(sorted(
        str(row.get('path') or '')
        for row in initial_preview.get('storage',{}).get('artifacts',[])
    ))
    pacs_before={
        'pacs_study_id':getattr(order,'pacs_study_id',None),
        'pacs_image_count':getattr(order,'pacs_image_count',None),
        'pacs_status':getattr(order,'pacs_status',None),
        'study_instance_uid':getattr(order,'study_instance_uid',None),
    }

    operation_id=(
        datetime.utcnow().strftime('%Y%m%d-%H%M%S')
        +'-'+secrets.token_hex(6)
    )
    case_root=None
    quarantine_target=None
    quarantined=False

    try:
        locked_order=(
            Order.query
            .filter_by(id=order.id)
            .with_for_update()
            .first()
        )
        if locked_order is None:
            raise RuntimeError('ORDER_NOT_FOUND_AFTER_LOCK')

        locked_patient=db.session.get(Patient,locked_order.patient_id)
        if locked_patient is None:
            raise RuntimeError('PATIENT_NOT_FOUND_AFTER_LOCK')

        locked_reports=(
            Report.query
            .filter_by(order_id=locked_order.id)
            .order_by(Report.id)
            .with_for_update()
            .all()
        )

        final_preview=granular_delete_reports_only_preview_snapshot(
            locked_order,locked_patient,locked_reports
        )
        final_blockers=list(final_preview.get('blocker_codes') or ())

        if tuple(final_preview.get('report_ids') or ()) != initial_report_ids:
            final_blockers.append('REPORT_SET_CHANGED_AFTER_PREFLIGHT')
        if tuple(
            int(row.get('id')) for row in (final_preview.get('versions') or [])
        ) != initial_version_ids:
            final_blockers.append('REPORT_VERSION_SET_CHANGED_AFTER_PREFLIGHT')
        if tuple(sorted(
            str(row.get('path') or '')
            for row in final_preview.get('storage',{}).get('artifacts',[])
        )) != initial_artifact_paths:
            final_blockers.append('REPORT_ARTIFACT_SET_CHANGED_AFTER_PREFLIGHT')
        if str(getattr(locked_order,'accession','') or '').strip() != expected_accession:
            final_blockers.append('ACCESSION_CHANGED_AFTER_PREFLIGHT')

        if final_blockers:
            db.session.rollback()
            return _delete_reports_only_blocked_response(
                order,reason,'FINAL_REVALIDATION_BLOCKED',final_blockers,409
            )

        case_root,quarantine_target=_delete_reports_only_quarantine_target(
            locked_patient,locked_order,operation_id
        )
        report_root=_DeletePath(REPORT_DIR).resolve()
        case_root=_DeletePath(case_root).resolve()
        quarantine_target=_DeletePath(quarantine_target).resolve()
        case_root.relative_to(report_root)
        quarantine_target.relative_to(report_root)

        # Move the complete case report tree (versions + working files) before
        # DB deletion. os.replace is same-filesystem and does not silently copy.
        if case_root.exists():
            quarantine_target.parent.mkdir(parents=True,exist_ok=True)
            if quarantine_target.exists():
                raise RuntimeError('QUARANTINE_TARGET_EXISTS')
            os.replace(str(case_root),str(quarantine_target))
            quarantined=True

        report_ids=[int(row.id) for row in locked_reports]
        version_count_before=int(final_preview.get('version_count') or 0)
        expired_lease_count=int(final_preview.get('lease',{}).get('expired_count') or 0)

        inspector=_delete_inspect(db.engine)
        if report_ids and inspector.has_table('report_edit_lease'):
            placeholders=','.join(str(int(value)) for value in report_ids)
            db.session.execute(
                _delete_text(
                    'DELETE FROM report_edit_lease '
                    'WHERE (order_id = :order_id OR report_id IN ('+placeholders+')) '
                    'AND expires_at <= :now'
                ),
                {'order_id':int(locked_order.id),'now':datetime.utcnow()},
            )

        if report_ids:
            ReportVersion.query.filter(
                ReportVersion.report_id.in_(report_ids)
            ).delete(synchronize_session=False)
            for row in locked_reports:
                db.session.delete(row)

        db.session.flush()

        remaining_reports=Report.query.filter_by(order_id=locked_order.id).count()
        remaining_versions=(
            ReportVersion.query
            .filter(ReportVersion.report_id.in_(report_ids))
            .count()
            if report_ids else 0
        )
        order_still_present=db.session.get(Order,locked_order.id) is not None
        patient_still_present=db.session.get(Patient,locked_patient.id) is not None

        if remaining_reports or remaining_versions:
            raise RuntimeError('REPORT_DELETE_POSTCHECK_FAILED')
        if not order_still_present or not patient_still_present:
            raise RuntimeError('CORE_CASE_PRESERVATION_FAILED')

        for key,value in pacs_before.items():
            if getattr(locked_order,key,None) != value:
                raise RuntimeError('PACS_STATE_CHANGED_DURING_REPORT_DELETE')

        audit(
            'REPORTS_ONLY_DELETED_ADMIN',
            'order',
            locked_order.id,
            (
                f"accession={expected_accession}; "
                f"report_ids={','.join(str(x) for x in report_ids)}; "
                f"report_count={len(report_ids)}; "
                f"version_count={version_count_before}; "
                f"expired_leases_removed={expired_lease_count}; "
                f"quarantined={'yes' if quarantined else 'no'}; "
                f"quarantine={str(quarantine_target) if quarantined else ''}; "
                f"operation_id={operation_id}; "
                f"reason={reason}"
            ),
        )
        db.session.commit()

        return {
            'ok':True,
            'deleted':True,
            'order_id':locked_order.id,
            'accession':expected_accession,
            'report_count_deleted':len(report_ids),
            'version_count_deleted':version_count_before,
            'expired_leases_removed':expired_lease_count,
            'quarantined':quarantined,
            'quarantine_path':str(quarantine_target) if quarantined else None,
            'operation_id':operation_id,
            'post_delete':{
                'report_count':0,
                'version_count':0,
                'order_preserved':True,
                'patient_preserved':True,
                'pacs_state_preserved':True,
            },
        },200

    except Exception as exc:
        db.session.rollback()
        restored=False
        restore_error=None

        if quarantined and quarantine_target is not None and case_root is not None:
            try:
                case_root.parent.mkdir(parents=True,exist_ok=True)
                if case_root.exists():
                    raise RuntimeError('RESTORE_TARGET_ALREADY_EXISTS')
                os.replace(str(quarantine_target),str(case_root))
                restored=True
            except Exception as restore_exc:
                restore_error=type(restore_exc).__name__

        try:
            audit(
                'REPORTS_ONLY_DELETE_FAILED_ADMIN',
                'order',
                getattr(order,'id',''),
                (
                    f"accession={expected_accession}; "
                    f"operation_id={operation_id}; "
                    f"error={type(exc).__name__}; "
                    f"quarantined={'yes' if quarantined else 'no'}; "
                    f"restored={'yes' if restored else 'no'}; "
                    f"restore_error={restore_error or ''}; "
                    f"reason={reason}"
                ),
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        return {
            'ok':False,
            'deleted':False,
            'error':'REPORTS_ONLY_DELETE_FAILED',
            'failure_type':type(exc).__name__,
            'quarantined':quarantined,
            'restored':restored,
            'restore_error':restore_error,
        },500


