def seed_master_data():
    if Branch.query.count()==0:
        db.session.add(Branch(code='MAIN',name='Main Branch',active=True)); db.session.commit()
    for code,perms in ROLE_PERMS.items():
        r=Role.query.filter_by(code=code).first()
        if not r:
            db.session.add(Role(code=code,name=code.replace('_',' ').title(),permissions_json=json.dumps(perms)))
    db.session.commit()

    # RB_CORRECTION_PERMISSION_DEFAULTS_V1
    # Append only the new correction permissions to standard roles. Existing
    # custom permissions remain untouched and execution is never granted here.
    correction_defaults={
        'RECEPTION': {'correction.request'},
        'TECHNICIAN': {'correction.request'},
        'BRANCH_MANAGER': {'correction.request'},
        'CASE_COORDINATOR': {'correction.request','correction.review'},
    }
    for code,required in correction_defaults.items():
        role=Role.query.filter_by(code=code).first()
        if not role:
            continue
        current=set(role.permissions())
        missing=required-current
        if missing:
            role.permissions_json=json.dumps(sorted(current|required))
    db.session.commit()
    if User.query.count()==0:
        admin_role=Role.query.filter_by(code='SUPER_ADMIN').first()
        admin_password=(os.getenv('RIS_ADMIN_PASSWORD') or '').strip()
        if not admin_password:
            raise RuntimeError('RIS_ADMIN_PASSWORD is required when creating the initial administrator')
        db.session.add(User(username='admin',full_name='System Administrator',
            password_hash=generate_password_hash(admin_password),
            role_id=admin_role.id,branch_id=Branch.query.first().id,active=True))
        db.session.commit()
    if Contract.query.count()==0:
        db.session.add(Contract(code='CASH',name='Cash / Private',patient_share_percent=100,discount_percent=0,approval_required=False,active=True))
        db.session.commit()
    storage_defaults()

    # Comprehensive bilingual procedure catalog.
    # Upsert by code so existing customer prices are preserved.
    for code,name_en,name_ar,modality,body,price,duration,contrast,category in PROCEDURE_CATALOG:
        p=Procedure.query.filter_by(code=code).first()
        if not p:
            db.session.add(Procedure(code=code,name=name_en,name_ar=name_ar,category=category,modality=modality,
                body_part=body,base_price=price,duration_min=duration,contrast=contrast,active=True))
        else:
            # Keep existing configured prices, but enrich names/catalog metadata.
            p.name=name_en
            p.name_ar=name_ar
            p.category=category
            if not p.body_part: p.body_part=body
            if not p.modality: p.modality=modality
            if not p.duration_min: p.duration_min=duration
    db.session.commit()

    # starter consumables and automatic mapping for contrast studies
    starters=[
      ('CANNULA20','IV Cannula 20G','unit',100,20,8),
      ('SYR20','Syringe 20 ml','unit',100,20,5),
      ('SALINE500','Normal Saline 500 ml','bag',50,10,25),
      ('CTCONTRAST100','Non-ionic CT Contrast 100 ml','vial',20,5,650),
      ('GAD10','Gadolinium 10 ml','vial',20,5,900),
    ]
    for code,name,unit,stock,reorder,cost in starters:
        if not Consumable.query.filter_by(code=code).first():
            db.session.add(Consumable(code=code,name=name,unit=unit,stock_qty=stock,reorder_level=reorder,unit_cost=cost,active=True))
    db.session.commit()
    cann=Consumable.query.filter_by(code='CANNULA20').first()
    syr=Consumable.query.filter_by(code='SYR20').first()
    sal=Consumable.query.filter_by(code='SALINE500').first()
    ct=Consumable.query.filter_by(code='CTCONTRAST100').first()
    gad=Consumable.query.filter_by(code='GAD10').first()
    for p in Procedure.query.filter_by(contrast=True).all():
        default=[(cann,1),(syr,1),(sal,1),(gad if p.modality=='MR' else ct,1)]
        for c,q in default:
            if c and not ProcedureConsumable.query.filter_by(procedure_id=p.id,consumable_id=c.id).first():
                db.session.add(ProcedureConsumable(procedure_id=p.id,consumable_id=c.id,qty=q))
    db.session.commit()


