@app.get('/reports/<int:order_id>/word-template/<int:template_id>')
@require_perm('reports.view')
def report_word_from_doctor_template(order_id,template_id):
    order=Order.query.get_or_404(order_id)
    tpl=DoctorWordTemplate.query.get_or_404(template_id)
    if not tpl.active: abort(404)
    if tpl.visibility=='PERSONAL' and tpl.owner_user_id!=current_user().id and not has_perm('*'):
        abort(403)
    if tpl.procedure_id and tpl.procedure_id!=order.procedure_id:
        abort(400)
    if tpl.modality and tpl.modality.upper()!=str(order.modality or '').upper():
        abort(400)
    report=get_report(order)

    authoritative = _rb_authoritative_docx_download(
        order,
        report,
    )

    if authoritative:
        return send_file(
            authoritative['path'],
            as_attachment=True,
            download_name=build_report_filename(
                order,
                authoritative['version_no'],
                authoritative['status'],
                'docx',
            ),
            mimetype=(
                'application/vnd.openxmlformats-officedocument.'
                'wordprocessingml.document'
            ),
        )

    doc=Document(tpl.file_path)
    values={
      'PATIENT_NAME':order.patient.name,
      'PATIENT_ID':order.patient.patient_id,
      'DOB':order.patient.dob or '',
      'SEX':order.patient.sex or '',
      'ACCESSION':order.accession,
      'MODALITY':order.modality,
      'EXAM':order.procedure,
      'STUDY_DATE':order.scheduled or '',
      'REFERRING_DOCTOR':order.referring_doctor.name if getattr(order,'referring_doctor',None) else '',
      'RADIOLOGIST':report.radiologist or '',
      'FINDINGS':report.findings or '',
      'IMPRESSION':report.impression or ''
    }
    replace_docx_placeholders(doc,values)
    out=io.BytesIO(); doc.save(out); out.seek(0)
    return send_file(out,as_attachment=True,
      download_name=build_report_filename(order,_next_report_version(report),'DRAFT','docx'),
      mimetype='application/vnd.openxmlformats-officedocument.wordprocessingml.document')


