@app.route('/patients/<int:patient_id>/external-priors',methods=['GET','POST'])
@login_required
def patient_external_priors(patient_id):
    patient=Patient.query.get_or_404(patient_id)
    if request.method=='POST':
        f=request.files.get('file')
        if not f or not f.filename: abort(400)
        ext=os.path.splitext(f.filename)[1].lower()
        if ext not in ('.dcm','.dicom','.zip','.jpg','.jpeg','.png','.pdf'): abort(400)
        folder=os.path.join(ATTACHMENT_DIR,'external-priors',str(patient.id));os.makedirs(folder,exist_ok=True)
        safe=re.sub(r'[^A-Za-z0-9._-]','_',f.filename);path=os.path.join(folder,f'{int(datetime.utcnow().timestamp())}_{safe}');f.save(path)
        source='DICOM' if ext in ('.dcm','.dicom') else ('ZIP' if ext=='.zip' else ('PDF' if ext=='.pdf' else 'IMAGE'))
        meta=safe_dicom_metadata(path) if source=='DICOM' else {}
        score,status=score_prior_match(patient,meta)
        study_date=None
        if meta.get('study_date'):
            try: study_date=datetime.strptime(meta['study_date'][:8],'%Y%m%d').date()
            except Exception: pass
        row=ExternalPriorStudy(patient_id=patient.id,linked_order_id=request.form.get('linked_order_id',type=int),
          source_type=source,study_date=study_date,modality=(meta.get('modality') or request.form.get('modality') or '').upper(),
          study_description=(meta.get('study_description') or request.form.get('study_description') or '').strip(),
          external_patient_name=meta.get('patient_name',''),external_patient_id=meta.get('patient_id',''),
          external_dob=meta.get('dob',''),file_path=path,original_name=f.filename,
          dicom_metadata_json=json.dumps(meta,ensure_ascii=False),match_status=status,match_score=score,uploaded_by=current_user().id)
        db.session.add(row);db.session.commit()
        return redirect(url_for('patient_external_priors',patient_id=patient.id))
    return render_template('patient_external_priors.html',patient=patient,
      rows=ExternalPriorStudy.query.filter_by(patient_id=patient.id).order_by(ExternalPriorStudy.created_at.desc()).all(),
      orders=Order.query.filter_by(patient_id=patient.id).order_by(Order.id.desc()).limit(50).all())

