@app.get('/search')
@login_required
def universal_search():
    f=common_search_filters()
    q=f['q']
    patients=[]
    orders=[]
    if q:
        patients=Patient.query.filter(or_(
            Patient.name.ilike(f'%{q}%'),
            Patient.patient_id.ilike(f'%{q}%'),
            Patient.phone.ilike(f'%{q}%'),
            Patient.national_id.ilike(f'%{q}%')
        )).order_by(Patient.id.desc()).limit(100).all()

        oq=Order.query.join(Patient).filter(or_(
            Order.accession.ilike(f'%{q}%'),
            Order.procedure.ilike(f'%{q}%'),
            Patient.name.ilike(f'%{q}%'),
            Patient.patient_id.ilike(f'%{q}%'),
            Patient.phone.ilike(f'%{q}%')
        ))
        if f['branch_id']: oq=oq.filter(Order.branch_id==f['branch_id'])
        if f['modality']: oq=oq.filter(Order.modality==f['modality'])
        if f['priority']: oq=oq.filter(Order.priority==f['priority'])
        orders=oq.order_by(Order.id.desc()).limit(200).all()

        if f['has_priors']:
            orders=[o for o in orders if related_prior_orders(o,1) or external_priors_for_order(o)]
        if f['has_documents']:
            orders=[o for o in orders if PatientDocument.query.filter_by(patient_id=o.patient_id).first()]

    return render_template('universal_search.html',
        filters=f,patients=patients,orders=orders,
        branches=Branch.query.filter_by(active=True).order_by(Branch.name).all())



