@app.route('/patients/<int:patient_id>/communications',methods=['GET','POST'])
@login_required
def patient_communications(patient_id):
    patient=Patient.query.get_or_404(patient_id)
    if request.method=='POST':
        channel=(request.form.get('channel') or '').upper()
        order=Order.query.get(request.form.get('order_id',type=int)) if request.form.get('order_id',type=int) else None
        receipt=Receipt.query.get(request.form.get('receipt_id',type=int)) if request.form.get('receipt_id',type=int) else None
        code=(request.form.get('template_code') or '').strip().upper()
        tpl=CommunicationTemplate.query.filter_by(code=code,active=True).first() if code else None
        ctx=communication_context(patient,order,receipt,{'document_name':request.form.get('document_name','')})
        subject=render_comm_text(tpl.subject_template if tpl else request.form.get('subject',''),ctx)
        body=render_comm_text(tpl.body_template if tpl else request.form.get('body',''),ctx)
        recipient=(request.form.get('recipient') or patient_default_recipient(patient,channel)).strip()
        if not recipient or not body:
            flash('Recipient and message are required.','danger')
            return redirect(request.url)
        row=PatientCommunication(
            patient_id=patient.id,order_id=(order.id if order else None),
            receipt_id=(receipt.id if receipt else None),channel=channel,
            recipient=recipient,template_code=code,subject=subject,body=body,
            created_by=current_user().id,status='PENDING'
        )
        db.session.add(row);db.session.commit()
        ok,error=send_patient_communication(row)
        audit('PATIENT_COMMUNICATION','patient',patient.id,f'{channel}:{row.status}')
        flash('Message sent.' if ok else 'Message failed: '+error,'success' if ok else 'danger')
        return redirect(url_for('patient_communications',patient_id=patient.id))
