def imaging_ai_verify_demographics(order_id):
    order=Order.query.get_or_404(order_id)

    demographic_ok, demographic_reason = pacs_demographic_gate(order)

    if not demographic_ok:
        audit(
            'IMAGING_AI_BLOCKED_PACS_DEMOGRAPHICS',
            'order',
            order.id,
            demographic_reason
        )
        db.session.commit()
        flash(
            'Imaging AI blocked: PACS demographics require authorized reconciliation.',
            'danger'
        )
        return redirect(url_for('imaging_ai_workspace',order_id=order.id))

    pacs,error=pacs_study_lookup(order)
