@app.post('/reports/<int:order_id>/imaging-ai/<int:analysis_id>/analyze')
@require_perm('reports.edit')
def imaging_ai_analyze(order_id,analysis_id):
    order=Order.query.get_or_404(order_id)

    demographic_ok, demographic_reason = pacs_demographic_gate(order)

    if not demographic_ok:
        audit(
            'IMAGING_AI_BLOCKED_PACS_DEMOGRAPHICS',
            'order',
            order.id,
            demographic_reason
        )
        db.session.commit()
        flash(
            'Imaging AI blocked: PACS demographics require authorized reconciliation.',
            'danger'
        )
        return redirect(url_for('imaging_ai_workspace',order_id=order.id))

    row=ImagingAIAnalysis.query.filter_by(id=analysis_id,order_id=order.id).first_or_404()
    if row.demographic_status!='VERIFIED':
        flash('Image AI analysis blocked until demographics are VERIFIED.','danger')
        return redirect(url_for('imaging_ai_workspace',order_id=order.id))
    details=json.loads(row.demographic_details_json or '{}')
    pacs=details.get('pacs') or {}
    row.status='ANALYZING'
    db.session.commit()
    result,error=call_imaging_ai(order,pacs,row)
    if not result:
        row.status='FAILED';row.error_text=error;db.session.commit()
        flash('Imaging AI failed: '+error,'danger')
        return redirect(url_for('imaging_ai_workspace',order_id=order.id))
    row.structured_findings_json=json.dumps(result['structured_findings'],ensure_ascii=False)
    row.summary_text=result['summary']
    row.uncertainty_text=result['uncertainty']
    row.raw_response_json=json.dumps(result['raw'],ensure_ascii=False,default=str)
    row.status='AI_FINDINGS_READY'
    row.completed_at=datetime.utcnow()
    audit('IMAGING_AI_ANALYSIS_COMPLETE','order',order.id,f'analysis={row.id}')
    db.session.commit()
    return redirect(url_for('imaging_ai_workspace',order_id=order.id))

