@app.post('/admin/qa-control/run')
@require_perm('users.view')
def admin_qa_control_run():
    run_type=(request.form.get('run_type') or 'FULL').strip().upper()

    allowed={
        'FULL',
        'REGISTRATION',
        'APPROVAL',
        'PACS',
        'ASSIGNMENT',
        'OPEN_POOL',
        'OFFER',
        'DOCTOR',
        'COORDINATOR',
        'OHIF',
        'IMAGING_AI',
        'REPORTING',
        'SIGNATURE'
    }

    if run_type not in allowed:
        run_type='FULL'

    row=QARun(
        run_type=run_type,
        status='STARTING',
        release_name='v5.35',
        environment='PRODUCTION',
        started_by=current_user().id
    )

    db.session.add(row)
    db.session.commit()

    payload={
        'qa_run_id':row.id,
        'run_type':run_type,
        'callback_url':request.host_url.rstrip('/')+'/api/qa/callback',
        'callback_token':QA_CALLBACK_TOKEN
    }

    result,error=qa_n8n_call(
        QA_N8N_RUN_WEBHOOK,
        payload,
        timeout=20
    )

    if error:
        row.status='FAILED_TO_START'
        row.error_text=error
        row.finished_at=datetime.utcnow()
        db.session.commit()

        flash('QA workflow failed to start: '+error,'danger')
        return redirect(url_for('admin_qa_control'))

    row.status='RUNNING'

    if isinstance(result,dict):
        row.external_execution_id=str(
            result.get('execution_id')
            or result.get('executionId')
            or result.get('id')
            or ''
        )

    db.session.commit()

    audit(
        'QA_RUN_START',
        'qa_run',
        row.id,
        'type=%s' % run_type
    )
    db.session.commit()

    flash('QA run started.','success')
    return redirect(url_for('admin_qa_control'))


