@app.post('/api/qa/callback')
def api_qa_callback():
    expected=QA_CALLBACK_TOKEN

    supplied=(
        request.headers.get('X-RadBridge-QA-Token')
        or request.args.get('token')
        or ''
    )

    if expected and supplied != expected:
        return jsonify({
            'ok':False,
            'error':'QA_CALLBACK_UNAUTHORIZED'
        }),401

    data=request.get_json(silent=True) or {}

    run_id=data.get('qa_run_id')

    try:
        run_id=int(run_id)
    except Exception:
        return jsonify({
            'ok':False,
            'error':'INVALID_QA_RUN_ID'
        }),400

    row=QARun.query.get(run_id)

    if not row:
        return jsonify({
            'ok':False,
            'error':'QA_RUN_NOT_FOUND'
        }),404

    tests=data.get('tests') or []

    for item in tests:
        if not isinstance(item,dict):
            continue

        key=str(item.get('test') or item.get('test_key') or '').strip()

        if not key:
            continue

        tr=QATestResult.query.filter_by(
            run_id=row.id,
            test_key=key
        ).first()

        if not tr:
            tr=QATestResult(
                run_id=row.id,
                test_key=key
            )
            db.session.add(tr)

        tr.category=str(item.get('category') or '')
        tr.title=str(item.get('title') or key)
        tr.status=str(item.get('status') or 'UNKNOWN').upper()
        tr.severity=str(item.get('severity') or 'NORMAL').upper()
        tr.expected=str(item.get('expected') or '')
        tr.actual=str(item.get('actual') or '')
        tr.error_text=str(item.get('error') or '')
        tr.order_id=item.get('order_id') or None
        tr.details_json=json.dumps(
            item.get('details') or {},
            ensure_ascii=False,
            default=str
        )
        tr.finished_at=datetime.utcnow()

    db.session.flush()

    all_rows=QATestResult.query.filter_by(
        run_id=row.id
    ).all()

    row.total_tests=len(all_rows)
    row.passed_tests=sum(
        1 for x in all_rows if x.status=='PASS'
    )
    row.failed_tests=sum(
        1 for x in all_rows if x.status=='FAIL'
    )
    row.critical_tests=sum(
        1 for x in all_rows
        if x.status=='FAIL' and x.severity=='CRITICAL'
    )
    row.warning_tests=sum(
        1 for x in all_rows
        if x.status in ('WARN','WARNING')
    )

    callback_status=str(
        data.get('status')
        or ''
    ).upper()

    if callback_status in ('COMPLETE','COMPLETED','FINISHED'):
        row.status='COMPLETED'
        row.finished_at=datetime.utcnow()
    elif callback_status:
        row.status=callback_status
    else:
        row.status='RUNNING'

    row.summary_json=json.dumps(
        data.get('summary') or {},
        ensure_ascii=False,
        default=str
    )

    db.session.commit()

    return jsonify({
        'ok':True,
        'run':qa_run_summary(row)
    })


