def _open_pool_visible_to_doctor(order,user):
    if not user or not user.active:
        return False

    profile=DoctorAssignmentProfile.query.filter_by(
        user_id=user.id
    ).first()

    if not profile:
        return False

    if not profile.auto_assign or not profile.available:
        return False

    modalities=[
        x.strip().upper()
        for x in (profile.modalities or '').split(',')
        if x.strip()
    ]

    if modalities and str(order.modality or '').upper() not in modalities:
        return False

    branches=[
        x.strip()
        for x in (profile.branches or '').split(',')
        if x.strip()
    ]

    if branches and str(order.branch_id or '') not in branches:
        return False

    active_cases=CaseAssignment.query.filter_by(
        doctor_user_id=user.id,
        active=True
    ).count()

    max_cases=int(profile.max_active_cases or 20)

    if active_cases>=max_cases:
        return False

    return True


def order_is_open_pool(order):
    if order.assigned_doctor_id:
        return False

    strategy=assignment_strategy_for_order(order)

    if strategy and str(strategy.assignment_mode or '').upper()=='OPEN_POOL':
        return True

    last_event=AssignmentEscalationEvent.query.filter_by(
        order_id=order.id
    ).order_by(
        AssignmentEscalationEvent.id.desc()
    ).first()

    if last_event and last_event.event_type=='OPEN_POOL':
        return True

    return False


@app.get('/assignment/open-pool')
@login_required
def open_pool_cases():

    rows=[]

    for order in Order.query.filter(
        Order.assigned_doctor_id.is_(None)
    ).order_by(
        Order.id.desc()
    ).limit(300).all():

        if not order_is_open_pool(order):
            continue

        if not _open_pool_visible_to_doctor(
            order,
            current_user()
        ):
            continue

        decision=assignment_readiness_decision(order)

        if not decision.get('allowed'):
            continue

        rows.append(
            (
                order,
                decision
            )
        )

    return render_template(
        'open_pool_cases.html',
        rows=rows
    )


@app.post('/orders/<int:order_id>/assign-to-me')
@login_required
def assign_case_to_me(order_id):

    order=Order.query.get_or_404(order_id)

    if order.assigned_doctor_id:
        flash('Case is already assigned.','warning')
        return redirect(
            url_for('open_pool_cases')
        )

    if not order_is_open_pool(order):
        abort(403)

    if not _open_pool_visible_to_doctor(
        order,
        current_user()
    ):
        abort(403)

    decision=assignment_readiness_decision(
        order
    )

    if not decision.get('allowed'):
        flash(
            'Case is no longer eligible for assignment.',
            'warning'
        )
        return redirect(
            url_for('open_pool_cases')
        )

    try:
        doctor=manual_assign_order(
            order,
            current_user().id,
            assigned_by=current_user().id,
            notes='Doctor assigned case from Open Pool',
            assignment_type='OPEN_POOL',
            require_unassigned=True,
        )
    except Exception as exc:
        db.session.rollback()
        code=getattr(exc,'code',type(exc).__name__)
        flash('Case cannot be taken: '+str(code).replace('_',' ')+'.','warning')
        return redirect(url_for('open_pool_cases'))

    db.session.add(
        AssignmentEscalationEvent(
            order_id=order.id,
            event_type='OPEN_POOL_TAKEN',
            details=f'doctor={doctor.id}',
            created_by=current_user().id
        )
    )

    audit(
        'OPEN_POOL_ASSIGN_TO_ME',
        'order',
        order.id,
        f'doctor={doctor.id}'
    )

    db.session.commit()

    flash(
        'Case assigned to you.',
        'success'
    )

    return redirect(
        url_for(
            'order_detail',
            order_id=order.id
        )
    )


