@app.get('/operations/case-exceptions')
@require_perm('orders.view')
def case_exception_resolver():
    from case_exception_resolution_service import search_ris_orders

    q=(request.args.get('q') or '').strip()
    order_id=request.args.get('order_id',type=int)
    status_filter=(request.args.get('status') or 'BLOCKED').strip().upper()
    modality_filter=(request.args.get('modality') or '').strip().upper()
    branch_filter=request.args.get('branch_id',type=int)
    blocker_filter=(request.args.get('blocker') or '').strip().upper()
    scope_filter=(request.args.get('scope') or 'EDITABLE').strip().upper()
    page=max(1,request.args.get('page',1,type=int))
    per_page=25
    results=search_ris_orders(Order=Order,Patient=Patient,query=q,limit=50)
    queue_query=(db.session.query(CaseReadiness,Order)
                 .join(Order,Order.id==CaseReadiness.order_id))
    if status_filter in ('BLOCKED','WARNING','READY','NOT_CHECKED'):
        queue_query=queue_query.filter(CaseReadiness.status==status_filter)
    if modality_filter:
        queue_query=queue_query.filter(func.upper(Order.modality)==modality_filter)
    if branch_filter:
        queue_query=queue_query.filter(Order.branch_id==branch_filter)
    blocker_columns={
        'MISSING_PACS':CaseReadiness.missing_pacs,
        'INCOMPLETE_IMAGES':CaseReadiness.incomplete_images,
        'MISSING_SERIES':CaseReadiness.missing_series,
        'MISSING_HISTORY':CaseReadiness.missing_history,
        'MISSING_ATTACHMENTS':CaseReadiness.missing_attachments,
        'MISSING_DOCUMENTS':CaseReadiness.missing_documents,
        'MISSING_NOTES':CaseReadiness.missing_notes,
    }
    if blocker_filter in blocker_columns:
        queue_query=queue_query.filter(blocker_columns[blocker_filter].is_(True))
    if scope_filter=='EDITABLE':
        queue_query=(queue_query.outerjoin(Report,Report.order_id==Order.id)
                     .filter(func.upper(func.coalesce(Order.status,''))
                             .notin_(('FINAL','CANCELLED')),
                             func.upper(func.coalesce(Report.status,'UNREPORTED'))
                             .notin_(('VERIFIED','FINAL'))))
    queue_total=queue_query.count()
    queue_rows=(queue_query.order_by(CaseReadiness.checked_at.desc(),Order.id.desc())
                .offset((page-1)*per_page).limit(per_page).all())
    queue=[]
    for readiness_row,order_row in queue_rows:
        try: queue_details=json.loads(readiness_row.details_json or '{}')
        except Exception: queue_details={}
        queue.append({'order':order_row,'readiness':readiness_row,
                      'blockers':queue_details.get('blockers',[])})
    queue_pages=max(1,(queue_total+per_page-1)//per_page)
    branches=Branch.query.filter_by(active=True).order_by(Branch.name).all()
    modalities=[row[0] for row in db.session.query(Order.modality).distinct()
                .order_by(Order.modality).all() if row[0]]
    selected=Order.query.get_or_404(order_id) if order_id else None
    readiness=None;rule=None;series=[];details={};aliases=[];events=[];report=None;overrides=[]
    if selected:
        readiness=CaseReadiness.query.filter_by(order_id=selected.id).first()
        rule=quality_rule_for(selected)
        report=Report.query.filter_by(order_id=selected.id).order_by(Report.id.desc()).first()
        if readiness:
            try: series=json.loads(readiness.series_evidence_json or '[]')
            except Exception: series=[]
            try: details=json.loads(readiness.details_json or '{}')
            except Exception: details={}
        if rule:
            aliases=(ReadinessSeriesAlias.query.filter_by(rule_id=rule.id)
                     .order_by(ReadinessSeriesAlias.id.desc()).all())
        events=(CaseExceptionResolutionEvent.query.filter_by(order_id=selected.id)
                .order_by(CaseExceptionResolutionEvent.created_at.desc()).limit(30).all())
        overrides=(CaseReadinessOverride.query.filter_by(order_id=selected.id,active=True)
                   .order_by(CaseReadinessOverride.id.desc()).all())
    selected_editable=bool(
        selected
        and str(selected.status or '').upper() not in ('FINAL','CANCELLED')
        and str(getattr(report,'status','') or '').upper() not in ('VERIFIED','FINAL')
    )
    can_reconcile=has_perm('pacs.reconcile') and selected_editable
    can_add_history=selected_editable and any(has_perm(permission) for permission in (
        'orders.create','nursing.worklist','reports.coordinate','pacs.reconcile'))
    can_refresh=selected_editable and any(has_perm(permission) for permission in (
        'orders.status','nursing.worklist','reports.coordinate','assignment.manage',
        'pacs.reconcile'))
    can_override=selected_editable and has_perm('pacs.reconcile') and has_perm('workflow.override')
    return render_template(
        'case_exception_resolver.html',q=q,results=results,selected=selected,
        readiness=readiness,rule=rule,series=series,details=details,
        aliases=aliases,events=events,report=report,overrides=overrides,
        can_resolve=can_reconcile,can_reconcile=can_reconcile,
        can_map_series=can_reconcile and bool(rule) and bool(series),
        can_add_history=can_add_history,can_refresh=can_refresh,
        can_override=can_override,
        can_manage_quality_rules=has_perm('users.view'),
        can_view_resolution_history=has_perm('audit.view') or has_perm('pacs.reconcile'),
        focus_mode=bool(selected),
        selected_editable=selected_editable,queue=queue,
        queue_total=queue_total,queue_page=page,queue_pages=queue_pages,
        branches=branches,modalities=modalities,status_filter=status_filter,
        modality_filter=modality_filter,branch_filter=branch_filter,
        blocker_filter=blocker_filter,scope_filter=scope_filter,
    )


