@app.post('/orders/<int:order_id>/exceptions/refresh')
@require_perm('orders.view')
def case_exception_refresh(order_id):
    if not case_exception_refresh_allowed():
        abort(403)
    order=Order.query.get_or_404(order_id)
    report=Report.query.filter_by(order_id=order.id).order_by(Report.id.desc()).first()
    if str(order.status or '').upper() in ('FINAL','CANCELLED') or str(getattr(report,'status','') or '').upper() in ('VERIFIED','FINAL'):
        abort(409)
    before=CaseReadiness.query.filter_by(order_id=order.id).first()
    old_status=str(getattr(before,'status','NOT_CHECKED'))
    row=evaluate_case_readiness(order)
    db.session.add(CaseExceptionResolutionEvent(
        order_id=order.id,action='READINESS_REFRESH',blocker='',
        old_value=old_status,new_value=row.status,
        reason='Authorized resolver refresh',actor_user_id=current_user().id,
    ))
    audit('CASE_EXCEPTION_READINESS_REFRESH','order',order.id,
          f'{old_status}->{row.status}')
    db.session.commit()
    flash('Readiness refreshed from current RIS and PACS evidence.','success')
    return redirect(url_for('case_exception_resolver',order_id=order.id))

