# ============================================================
# REPORT SLA v1
# Reporting SLA is intentionally isolated from assignment
# offer timeouts / MWL / PACS / Order.status.
# ============================================================

REPORT_SLA_MINUTES = {
    'ROUTINE': 24 * 60,
    'VIP':       2 * 60,
    'URGENT':    4 * 60,
    'STAT':          60,
    'EMERGENCY':     60,
}

REPORT_SLA_NEAR_PERCENT = 80


def report_sla_snapshot(order, report=None, now=None):
    now = now or datetime.utcnow()

    priority=(order.priority or 'ROUTINE').strip().upper()

    # Unknown priorities safely fall back to ROUTINE.
    target_minutes=REPORT_SLA_MINUTES.get(
        priority,
        REPORT_SLA_MINUTES['ROUTINE']
    )

    # SLA starts when examination is completed.
    # Old imported cases may not have exam_completed_at.
    start_at=order.exam_completed_at or order.scheduled

    if not start_at:
        return {
            'priority':priority,
            'target_minutes':target_minutes,
            'elapsed_minutes':None,
            'remaining_minutes':None,
            'percent':0,
            'status':'NOT_STARTED',
            'start_at':None,
            'end_at':None,
        }

    is_final=bool(
        report and
        (report.status or '').upper()=='FINAL'
    )

    # Once FINAL, SLA clock stops permanently.
    end_at=(
        report.finalized_at
        if is_final and report.finalized_at
        else now
    )

    elapsed=max(
        0,
        int((end_at-start_at).total_seconds()/60)
    )

    remaining=target_minutes-elapsed

    percent=(
        round((elapsed/target_minutes)*100,1)
        if target_minutes else 0
    )

    if elapsed > target_minutes:
        status='BREACHED'
    elif percent >= REPORT_SLA_NEAR_PERCENT:
        status='NEAR_SLA'
    else:
        status='ON_TIME'

    return {
        'priority':priority,
        'target_minutes':target_minutes,
        'elapsed_minutes':elapsed,
        'remaining_minutes':remaining,
        'percent':percent,
        'status':status,
        'start_at':start_at,
        'end_at':end_at,
        'is_final':is_final,
    }


def format_sla_minutes(minutes):
    if minutes is None:
        return '—'

    minutes=abs(int(minutes))
    days,rem=divmod(minutes,1440)
    hours,mins=divmod(rem,60)

    parts=[]

    if days:
        parts.append(f'{days}d')

    if hours:
        parts.append(f'{hours}h')

    parts.append(f'{mins}m')

    return ' '.join(parts)

@app.get('/reports-portal')
@require_perm('reports.view')
def reports_portal():
    view=(request.args.get('view') or 'all').lower()
    q=(request.args.get('q') or '').strip()

    branch_id=request.args.get('branch_id',type=int)
    doctor_id=request.args.get('doctor_id',type=int)
    modality=(request.args.get('modality') or '').strip().upper()
    report_status=(request.args.get('report_status') or '').strip().upper()

    date_from=(request.args.get('date_from') or '').strip()
    date_to=(request.args.get('date_to') or '').strip()

    orders=Order.query.join(Patient)

    if q:
        like=f'%{q}%'
        orders=orders.filter(
            or_(
                Patient.name.ilike(like),
                Patient.patient_id.ilike(like),
                Order.accession.ilike(like),
                Order.procedure.ilike(like)
            )
        )

    if branch_id:
        orders=orders.filter(Order.branch_id==branch_id)

    if doctor_id:
        orders=orders.filter(Order.assigned_doctor_id==doctor_id)

    if modality:
        orders=orders.filter(Order.modality==modality)

    if date_from:
        try:
            dt=datetime.strptime(date_from,'%Y-%m-%d')
            orders=orders.filter(Order.scheduled>=dt)
        except Exception:
            pass

    if date_to:
        try:
            dt=datetime.strptime(date_to,'%Y-%m-%d')+timedelta(days=1)
            orders=orders.filter(Order.scheduled<dt)
        except Exception:
            pass

    # Keep portal responsive while allowing useful management reporting.
    source_rows=orders.order_by(
        Order.id.desc()
    ).limit(5000).all()

    all_result=[]

    for o in source_rows:
        report=o.report

        if report_status:
            current_report_status=(
                (report.status or 'UNREPORTED').upper()
                if report else 'UNREPORTED'
            )

            if current_report_status!=report_status:
                continue

        latest_return=CaseWorkflowEvent.query.filter_by(
            order_id=o.id,
            event_type='RETURNED'
        ).order_by(
            CaseWorkflowEvent.created_at.desc()
        ).first()

        latest_ready=CaseWorkflowEvent.query.filter_by(
            order_id=o.id,
            event_type='READY_FOR_REREVIEW'
        ).order_by(
            CaseWorkflowEvent.created_at.desc()
        ).first()

        state='WAITING'

        if latest_return and (
            not latest_ready or latest_ready.created_at < latest_return.created_at
        ):
            state='NEEDS_ACTION'

        elif latest_ready and (
            not latest_return or latest_ready.created_at >= latest_return.created_at
        ):
            state='READY_FOR_REREVIEW'

        elif report and (report.status or '').upper()=='FINAL':
            state='FINAL'

        elif report and (report.status or '').upper() not in ('','UNREPORTED'):
            state='REPORTING'

        elif report:
            state='WAITING'

        # Report TAT:
        # exam completion -> report finalization.
        # Fallback for old records: scheduled -> finalized.
        tat_minutes=None

        if report and report.finalized_at:
            start_at=o.exam_completed_at or o.scheduled

            if start_at:
                tat_minutes=max(
                    0,
                    int(
                        (report.finalized_at-start_at).total_seconds()/60
                    )
                )

        sla=report_sla_snapshot(o,report)

        all_result.append({
            'order':o,
            'report':report,
            'portal_state':state,
            'latest_return':latest_return,
            'latest_ready':latest_ready,
            'tat_minutes':tat_minutes,
            'sla':sla
        })

    # ------------------------------------------------------------
    # Statistics are calculated BEFORE the view tab filter.
    # They therefore represent all results matching search/date/etc.
    # ------------------------------------------------------------

    total=len(all_result)

    final_count=sum(
        1 for x in all_result
        if x['portal_state']=='FINAL'
    )

    reporting_count=sum(
        1 for x in all_result
        if x['portal_state']=='REPORTING'
    )

    needs_action_count=sum(
        1 for x in all_result
        if x['portal_state']=='NEEDS_ACTION'
    )

    rereview_count=sum(
        1 for x in all_result
        if x['portal_state']=='READY_FOR_REREVIEW'
    )

    waiting_count=sum(
        1 for x in all_result
        if x['portal_state']=='WAITING'
    )

    delivered_count=sum(
        1 for x in all_result
        if bool(x['order'].report_delivered)
    )

    tat_values=[
        x['tat_minutes']
        for x in all_result
        if x['tat_minutes'] is not None
    ]

    avg_tat_minutes=(
        round(sum(tat_values)/len(tat_values))
        if tat_values else None
    )

    finalization_rate=(
        round((final_count/total)*100,1)
        if total else 0
    )

    sla_on_time=sum(
        1 for x in all_result
        if x['sla']['status']=='ON_TIME'
    )

    sla_near=sum(
        1 for x in all_result
        if x['sla']['status']=='NEAR_SLA'
    )

    sla_breached=sum(
        1 for x in all_result
        if x['sla']['status']=='BREACHED'
    )

    urgent_open=sum(
        1 for x in all_result
        if x['sla']['priority']=='URGENT'
        and x['portal_state']!='FINAL'
    )

    stat_open=sum(
        1 for x in all_result
        if x['sla']['priority'] in ('STAT','EMERGENCY')
        and x['portal_state']!='FINAL'
    )

    vip_open=sum(
        1 for x in all_result
        if x['sla']['priority']=='VIP'
        and x['portal_state']!='FINAL'
    )

    stats={
        'sla_on_time':sla_on_time,
        'sla_near':sla_near,
        'sla_breached':sla_breached,
        'urgent_open':urgent_open,
        'stat_open':stat_open,
        'vip_open':vip_open,
        'total':total,
        'final':final_count,
        'reporting':reporting_count,
        'waiting':waiting_count,
        'needs_action':needs_action_count,
        'rereview':rereview_count,
        'delivered':delivered_count,
        'avg_tat_minutes':avg_tat_minutes,
        'finalization_rate':finalization_rate
    }

    result=all_result

    if view!='all':
        result=[
            x for x in all_result
            if x['portal_state'].lower()==view
        ]

    branches=Branch.query.filter_by(
        active=True
    ).order_by(Branch.name).all()

    doctors=User.query.join(Role).filter(
        Role.code.in_(['RADIOLOGIST','DOCTOR']),
        User.active.is_(True)
    ).order_by(User.full_name).all()

    modalities=sorted({
        (x['order'].modality or '').upper()
        for x in all_result
        if x['order'].modality
    })

    return render_template(
        'reports_portal.html',
        rows=result,
        stats=stats,
        branches=branches,
        doctors=doctors,
        modalities=modalities,
        view=view,
        q=q,
        branch_id=branch_id,
        doctor_id=doctor_id,
        modality=modality,
        report_status=report_status,
        date_from=date_from,
        date_to=date_to,
        format_sla_minutes=format_sla_minutes
    )


@app.get('/reports-portal.csv')
@require_perm('reports.view')
def reports_portal_csv():

    args=request.args.to_dict(flat=True)
    args['view']=args.get('view') or 'all'

    q=(args.get('q') or '').strip()
    branch_id=request.args.get('branch_id',type=int)
    doctor_id=request.args.get('doctor_id',type=int)
    modality=(args.get('modality') or '').strip().upper()
    report_status=(args.get('report_status') or '').strip().upper()
    view=(args.get('view') or 'all').lower()
    date_from=(args.get('date_from') or '').strip()
    date_to=(args.get('date_to') or '').strip()

    orders=Order.query.join(Patient)

    if q:
        like=f'%{q}%'
        orders=orders.filter(
            or_(
                Patient.name.ilike(like),
                Patient.patient_id.ilike(like),
                Order.accession.ilike(like),
                Order.procedure.ilike(like)
            )
        )

    if branch_id:
        orders=orders.filter(Order.branch_id==branch_id)

    if doctor_id:
        orders=orders.filter(Order.assigned_doctor_id==doctor_id)

    if modality:
        orders=orders.filter(Order.modality==modality)

    if date_from:
        try:
            orders=orders.filter(
                Order.scheduled>=datetime.strptime(date_from,'%Y-%m-%d')
            )
        except Exception:
            pass

    if date_to:
        try:
            orders=orders.filter(
                Order.scheduled<
                datetime.strptime(date_to,'%Y-%m-%d')+timedelta(days=1)
            )
        except Exception:
            pass

    rows=orders.order_by(Order.id.desc()).limit(5000).all()

    output=io.StringIO()
    writer=csv.writer(output)

    writer.writerow([
        'Patient ID',
        'Patient Name',
        'Accession',
        'Study Date',
        'Branch',
        'Modality',
        'Exam',
        'Doctor',
        'Report Status',
        'Case State',
        'Doctor Request',
        'Finalized At',
        'Report TAT Minutes',
        'Delivered'
    ])

    for o in rows:
        report=o.report

        current_status=(
            (report.status or 'UNREPORTED').upper()
            if report else 'UNREPORTED'
        )

        if report_status and current_status!=report_status:
            continue

        latest_return=CaseWorkflowEvent.query.filter_by(
            order_id=o.id,
            event_type='RETURNED'
        ).order_by(
            CaseWorkflowEvent.created_at.desc()
        ).first()

        latest_ready=CaseWorkflowEvent.query.filter_by(
            order_id=o.id,
            event_type='READY_FOR_REREVIEW'
        ).order_by(
            CaseWorkflowEvent.created_at.desc()
        ).first()

        state='WAITING'

        if latest_return and (
            not latest_ready or latest_ready.created_at<latest_return.created_at
        ):
            state='NEEDS_ACTION'

        elif latest_ready and (
            not latest_return or latest_ready.created_at>=latest_return.created_at
        ):
            state='READY_FOR_REREVIEW'

        elif current_status=='FINAL':
            state='FINAL'

        elif report and current_status not in ('','UNREPORTED'):
            state='REPORTING'

        if view!='all' and state.lower()!=view:
            continue

        tat_minutes=''

        if report and report.finalized_at:
            start_at=o.exam_completed_at or o.scheduled

            if start_at:
                tat_minutes=max(
                    0,
                    int(
                        (report.finalized_at-start_at).total_seconds()/60
                    )
                )

        doctor_request=''

        if state=='NEEDS_ACTION' and latest_return:
            doctor_request=(
                f'{latest_return.reason_code}: '
                f'{latest_return.note or ""}'
            )

        writer.writerow([
            o.patient.patient_id,
            o.patient.name,
            o.accession,
            o.scheduled.isoformat(sep=' ') if o.scheduled else '',
            o.branch.name if o.branch else '',
            o.modality,
            o.procedure,
            (
                o.assigned_doctor.full_name
                if o.assigned_doctor else ''
            ),
            current_status,
            state,
            doctor_request,
            (
                report.finalized_at.isoformat(sep=' ')
                if report and report.finalized_at else ''
            ),
            tat_minutes,
            'YES' if o.report_delivered else 'NO'
        ])

    data='\ufeff'+output.getvalue()

    return Response(
        data,
        mimetype='text/csv; charset=utf-8',
        headers={
            'Content-Disposition':
            'attachment; filename=radbridge-report-portal.csv'
        }
    )



# ============================================================
# RB_SLA_TAT_ADMIN_V1
# SLA / TAT policy administration.
#
# Existing TATPolicy schema only.
# No schema creation or migration is performed here.
# Resolution semantics:
#   priority + modality exact
#   -> fallback priority + "*"
# ============================================================

@app.route(
    '/admin/tat-policies',
    methods=['GET','POST']
)
@require_perm('assignment.manage')
def admin_tat_policies():

    priorities = (
        'STAT',
        'URGENT',
        'ROUTINE',
    )

    if request.method == 'POST':

        action = (
            request.form.get('action')
            or 'SAVE'
        ).strip().upper()

        row_id = request.form.get(
            'policy_id',
            type=int
        )

        row = (
            db.session.get(
                TATPolicy,
                row_id
            )
            if row_id
            else None
        )

        if action == 'DISABLE':

            if not row:
                abort(404)

            row.active = False

            audit(
                'TAT_POLICY_DISABLED',
                'tat_policy',
                row.id,
                (
                    f'priority={row.priority};'
                    f'modality={row.modality}'
                )
            )

            db.session.commit()

            flash(
                'SLA / TAT policy disabled.',
                'success'
            )

            return redirect(
                url_for(
                    'admin_tat_policies'
                )
            )

        priority = (
            request.form.get('priority')
            or ''
        ).strip().upper()

        modality = (
            request.form.get('modality')
            or '*'
        ).strip().upper()

        if not modality:
            modality = '*'

        if priority not in priorities:
            flash(
                'Invalid priority.',
                'danger'
            )
            return redirect(
                url_for(
                    'admin_tat_policies'
                )
            )

        def required_nonnegative_int(name):
            value = request.form.get(
                name,
                type=int
            )

            if value is None or value < 0:
                raise ValueError(name)

            return value

        try:
            ready_to_assign_min = (
                required_nonnegative_int(
                    'ready_to_assign_min'
                )
            )

            assign_to_accept_min = (
                required_nonnegative_int(
                    'assign_to_accept_min'
                )
            )

            accept_to_final_min = (
                required_nonnegative_int(
                    'accept_to_final_min'
                )
            )

            total_tat_min = (
                required_nonnegative_int(
                    'total_tat_min'
                )
            )

        except ValueError:
            flash(
                'All SLA values must be zero or positive minutes.',
                'danger'
            )
            return redirect(
                url_for(
                    'admin_tat_policies'
                )
            )

        active = (
            request.form.get('active')
            == '1'
        )

        duplicate_query = (
            TATPolicy.query
            .filter_by(
                priority=priority,
                modality=modality,
                active=True,
            )
        )

        if row:
            duplicate_query = (
                duplicate_query
                .filter(
                    TATPolicy.id != row.id
                )
            )

        duplicate = (
            duplicate_query
            .order_by(
                TATPolicy.id.asc()
            )
            .first()
        )

        if active and duplicate:
            flash(
                (
                    'An active SLA / TAT policy already exists '
                    f'for {priority} + {modality}.'
                ),
                'danger'
            )

            return redirect(
                url_for(
                    'admin_tat_policies'
                )
            )

        created = row is None

        if row is None:
            row = TATPolicy()
            db.session.add(row)

        row.priority = priority
        row.modality = modality

        row.ready_to_assign_min = (
            ready_to_assign_min
        )

        row.assign_to_accept_min = (
            assign_to_accept_min
        )

        row.accept_to_final_min = (
            accept_to_final_min
        )

        row.total_tat_min = (
            total_tat_min
        )

        row.active = active

        db.session.flush()

        audit(
            (
                'TAT_POLICY_CREATED'
                if created
                else 'TAT_POLICY_UPDATED'
            ),
            'tat_policy',
            row.id,
            (
                f'priority={row.priority};'
                f'modality={row.modality};'
                f'ready_to_assign_min={row.ready_to_assign_min};'
                f'assign_to_accept_min={row.assign_to_accept_min};'
                f'accept_to_final_min={row.accept_to_final_min};'
                f'total_tat_min={row.total_tat_min};'
                f'active={row.active}'
            )
        )

        db.session.commit()

        flash(
            (
                'SLA / TAT policy created.'
                if created
                else 'SLA / TAT policy updated.'
            ),
            'success'
        )

        return redirect(
            url_for(
                'admin_tat_policies'
            )
        )

    rows = (
        TATPolicy.query
        .order_by(
            TATPolicy.priority,
            TATPolicy.modality,
            TATPolicy.id
        )
        .all()
    )

    modalities = sorted({
        str(x[0]).strip().upper()
        for x in (
            db.session.query(
                Order.modality
            )
            .filter(
                Order.modality.isnot(None)
            )
            .distinct()
            .all()
        )
        if x[0]
    })

    return render_template(
        'admin_tat_policies.html',
        rows=rows,
        priorities=priorities,
        modalities=modalities,
    )


