    row=SmartIntakeSession.query.get_or_404(intake_id)
    docs=SmartIntakeDocument.query.filter_by(intake_id=row.id).order_by(SmartIntakeDocument.document_type,SmartIntakeDocument.created_at).all()
    if row.status!='COMPLETED':
        extracted,identity_validation,match_context=rebuild_intake_summary(row)
