@app.post('/intake/smart/<int:intake_id>/upload')
@require_perm('patients.create')
def smart_intake_upload(intake_id):
    intake=SmartIntakeSession.query.get_or_404(intake_id)
    if intake.status=='COMPLETED':
        abort(409)

    dtype=(request.form.get('document_type') or 'OTHER').upper()
    auto_ocr=request.form.get('auto_ocr')=='1'

    files=request.files.getlist('files')
    if not files:
        abort(400)

    allowed={x[0] for x in SMART_DOCUMENT_TYPES}
    if dtype not in allowed:
        abort(400)

    allowed_ext={'.pdf','.png','.jpg','.jpeg','.tif','.tiff','.webp','.bmp','.dcm'}
    folder=smart_intake_dir(intake.id)

    new_docs=[]
    uploaded_count=0
    duplicate_count=0

    for f in files:
        if not f or not f.filename:
            continue

        ext=os.path.splitext(f.filename)[1].lower()

        if ext not in allowed_ext:
            flash(f'Unsupported document type: {ext or "unknown"}.','danger')
            continue

        safe=re.sub(r'[^A-Za-z0-9._-]','_',f.filename)[:180]
        path=os.path.join(folder,f'{uuid.uuid4().hex}_{safe}')
        f.save(path)

        digest=_intake_file_sha256(path)

        if SmartIntakeDocument.query.filter_by(
                intake_id=intake.id,
                content_sha256=digest).first():
            os.remove(path)
            duplicate_count+=1
            continue

        doc=SmartIntakeDocument(
            intake_id=intake.id,
            document_type=dtype,
            original_name=f.filename,
            file_path=path,
            mime_type=f.mimetype or '',
            status='UPLOADED',
            content_sha256=digest
        )

        db.session.add(doc)
        db.session.flush()

        new_docs.append(doc)
        uploaded_count+=1

        audit(
            'SMART_INTAKE_DOCUMENT_UPLOAD',
            'smart_intake_session',
            intake.id,
            f'document_id={doc.id} document_type={dtype} '
            f'auto_ocr={1 if auto_ocr else 0} sha256={digest[:16]}'
        )

    intake.status='UPLOADING'
    db.session.commit()

    if duplicate_count:
        flash(f'{duplicate_count} duplicate document(s) skipped.','warning')

    # Unified intake: OCR each newly uploaded document immediately.
    if auto_ocr and new_docs:
        cfg=enabled_ocr_provider()

        provider_ready=bool(
            cfg and
            cfg.validation_status in ('READY','READY_WITH_WARNINGS') and
            cfg.validation_config_hash==ocr_configuration_hash(cfg)
        )

        if not provider_ready:
            flash(
                'Documents uploaded, but automatic OCR was not started because '
                'the OCR provider is not enabled and validated.',
                'warning'
            )
            return _intake_redirect(intake.id,'documents')

        success_count=0
        failed_count=0

        for doc in new_docs:
            result,error=call_ocr_provider(doc)

            if result:
                classification=_apply_smart_intake_ocr_result(doc,result)

                audit(
                    'SMART_INTAKE_OCR_EXTRACTED',
                    'smart_intake_document',
                    doc.id,
                    f'intake_id={intake.id} provider={doc.ocr_provider_key} '
                    f'confidence={doc.confidence:.3f} '
                    f'declared_type={doc.document_type} '
                    f'suggested_type={classification.get("suggested_type","OTHER")} '
                    f'classification_status={classification.get("status","UNCLASSIFIED")} '
                    f'auto_ocr=1'
                )

                success_count+=1

            else:
                doc.status='OCR_FAILED'
                doc.ocr_error=(error or 'OCR failed')[:500]

                audit(
                    'SMART_INTAKE_OCR_FAILED',
                    'smart_intake_document',
                    doc.id,
                    f'intake_id={intake.id} '
                    f'error_code={(error or "").split(":",1)[0][:80]} '
                    f'auto_ocr=1'
                )

                failed_count+=1

            db.session.flush()

        db.session.commit()
        rebuild_intake_summary(intake)

        if success_count:
            flash(
                f'{success_count} document(s) uploaded and read automatically. '
                'Review the detected types before approval.',
                'success'
            )

        if failed_count:
            flash(
                f'OCR failed for {failed_count} document(s). '
                'They remain available for manual review or retry.',
                'warning'
            )

    elif uploaded_count:
        flash(f'{uploaded_count} document(s) uploaded.','success')

    return _intake_redirect(intake.id,'documents')


def _apply_smart_intake_ocr_result(doc, result):
    """Apply OCR output and attach a non-authoritative document-type suggestion."""
    fields = dict(result.get('fields') or {})

    classification = classify_document_text(result.get('text') or '')

    fields['_document_classification'] = {
        'suggested_type': classification.get('suggested_type') or classification.get('type') or 'OTHER',
        'safe_type': classification.get('type') or 'OTHER',
        'confidence': float(classification.get('confidence') or 0),
        'status': classification.get('status') or 'UNCLASSIFIED',
        'hits': classification.get('hits') or [],
        'declared_type': doc.document_type,
    }

    doc.ocr_text = result.get('text') or ''
    doc.extracted_json = json.dumps(fields, ensure_ascii=False)
    doc.confidence = float(result.get('confidence') or 0)
    doc.status = 'REVIEW_REQUIRED'
    doc.ocr_error = ''

    cfg = enabled_ocr_provider()
    doc.ocr_provider_key = cfg.provider_key if cfg else ''
    doc.ocr_config_hash = ocr_configuration_hash(cfg) if cfg else ''

    # ========================================================
    # RB_SMART_INTAKE_OCR_FIELD_SYNC_V1
    #
    # Persist OCR suggestions into SmartIntakeFieldReview so
    # the identity-review / registration UI can consume them.
    #
    # OCR suggestions remain PENDING here. final_value and
    # ACCEPTED/CORRECTED status are set only by the explicit
    # review/save workflow.
    # ========================================================

    core_fields = {
        key: str(fields.get(key) or '').strip()
        for key in OCR_INTAKE_CORE_FIELDS
    }

    normalized = normalize_intake_identity(
        core_fields
    )

    validation = validate_intake_identity(
        normalized
    )

    validation_fields = (
        validation.get('fields')
        or {}
    )

    for field_key in OCR_INTAKE_CORE_FIELDS:

        extracted = str(
            core_fields.get(field_key)
            or ''
        )

        normalized_value = str(
            normalized.get(field_key)
            or ''
        )

        # Keep rows already reviewed by a user untouched.
        row = (
            SmartIntakeFieldReview.query
            .filter_by(
                intake_id=doc.intake_id,
                field_key=field_key
            )
            .first()
        )

        if not row:
            row = SmartIntakeFieldReview(
                intake_id=doc.intake_id,
                field_key=field_key
            )
            db.session.add(row)

        if row.review_status in (
            'ACCEPTED',
            'CORRECTED'
        ):
            continue

        if extracted or normalized_value:

            item = (
                validation_fields.get(
                    field_key
                )
                or {}
            )

            row.source_document_id = doc.id
            row.source_type = (
                doc.document_type
                or ''
            )

            row.extracted_value = extracted
            row.normalized_value = normalized_value

            row.confidence = float(
                result.get('confidence')
                or 0
            )

            row.validation_status = str(
                item.get('status')
                or 'warning'
            ).upper()

            row.validation_message = str(
                item.get('message')
                or ''
            )[:500]

            row.review_status = 'PENDING'

    return classification


@app.post('/intake/smart/<int:intake_id>/ocr/<int:doc_id>')
@require_perm('patients.create')
def smart_intake_run_ocr(intake_id,doc_id):
    intake=SmartIntakeSession.query.get_or_404(intake_id)
    if intake.status=='COMPLETED': abort(409)
    doc=SmartIntakeDocument.query.filter_by(id=doc_id,intake_id=intake.id).first_or_404()
    result,error=call_ocr_provider(doc)
    if not result:
        doc.status='OCR_FAILED';doc.ocr_error=(error or 'OCR failed')[:500]
        audit('SMART_INTAKE_OCR_FAILED','smart_intake_document',doc.id,
          f'intake_id={intake.id} error_code={(error or "").split(":",1)[0][:80]}')
        db.session.commit()
        flash('OCR failed: '+error,'danger')
        return _intake_redirect(intake.id,f'document-{doc.id}')
    classification=_apply_smart_intake_ocr_result(doc,result)
    audit('SMART_INTAKE_OCR_EXTRACTED','smart_intake_document',doc.id,
      f'intake_id={intake.id} provider={doc.ocr_provider_key} '
      f'confidence={doc.confidence:.3f} declared_type={doc.document_type} '
      f'suggested_type={classification.get("suggested_type","OTHER")} '
      f'classification_status={classification.get("status","UNCLASSIFIED")}')
    db.session.commit();rebuild_intake_summary(intake)
    return _intake_redirect(intake.id,f'document-{doc.id}')

@app.post('/intake/smart/<int:intake_id>/ocr-all')
@require_perm('patients.create')
def smart_intake_run_all_ocr(intake_id):
    intake=SmartIntakeSession.query.get_or_404(intake_id)
    if intake.status=='COMPLETED': abort(409)
    docs=SmartIntakeDocument.query.filter_by(intake_id=intake.id).all()
    for doc in docs:
        if doc.status in ('APPROVED','REJECTED'): continue
        result,error=call_ocr_provider(doc)
        if result:
            classification=_apply_smart_intake_ocr_result(doc,result)
            audit('SMART_INTAKE_OCR_EXTRACTED','smart_intake_document',doc.id,
              f'intake_id={intake.id} provider={doc.ocr_provider_key} '
              f'confidence={doc.confidence:.3f} declared_type={doc.document_type} '
              f'suggested_type={classification.get("suggested_type","OTHER")} '
              f'classification_status={classification.get("status","UNCLASSIFIED")}')
        else:
            doc.status='OCR_FAILED';doc.ocr_error=(error or 'OCR failed')[:500]
            audit('SMART_INTAKE_OCR_FAILED','smart_intake_document',doc.id,
              f'intake_id={intake.id} error_code={(error or "").split(":",1)[0][:80]}')
        db.session.flush()
    db.session.commit();rebuild_intake_summary(intake)
    return _intake_redirect(intake.id,'documents')

@app.post('/intake/smart/<int:intake_id>/document/<int:doc_id>/review')
@require_perm('patients.create')
def smart_intake_document_review(intake_id,doc_id):
    intake=SmartIntakeSession.query.get_or_404(intake_id)
    if intake.status=='COMPLETED': abort(409)
    doc=SmartIntakeDocument.query.filter_by(id=doc_id,intake_id=intake.id).first_or_404()
    action=(request.form.get('action') or '').upper()
    if action not in ('APPROVED','REJECTED','REVIEW_REQUIRED'): abort(400)
    notes=(request.form.get('review_notes') or '').strip()[:1000]

    submitted_type=(request.form.get('document_type') or doc.document_type or 'OTHER').upper()
    allowed_types={x[0] for x in SMART_DOCUMENT_TYPES}
    if submitted_type not in allowed_types:
        abort(400)

    old_type=doc.document_type
    if submitted_type != old_type:
        doc.document_type=submitted_type
        audit(
          'SMART_INTAKE_DOCUMENT_TYPE_CHANGED',
          'smart_intake_document',
          doc.id,
          f'intake_id={intake.id} old_type={old_type} new_type={submitted_type}'
        )

    if action=='APPROVED' and doc.status=='UPLOADED':
        flash('Run OCR or explicitly reject the unread document before continuing.','danger')
        return _intake_redirect(intake.id,f'document-{doc.id}')
    if action=='APPROVED' and doc.status=='OCR_FAILED' and len(notes)<3:
        flash('A review note is required to approve a document after OCR failure.','danger')
        return _intake_redirect(intake.id,f'document-{doc.id}')
    if action=='REJECTED' and len(notes)<3:
        flash('Enter a rejection reason.','danger')
        return _intake_redirect(intake.id,f'document-{doc.id}')
    doc.status=action;doc.reviewed_by=current_user().id;doc.reviewed_at=datetime.utcnow()
    doc.review_notes=notes
    audit('SMART_INTAKE_DOCUMENT_'+action,'smart_intake_document',doc.id,
      f'intake_id={intake.id} document_type={doc.document_type}')
    db.session.commit();rebuild_intake_summary(intake)
    return _intake_redirect(intake.id,f'document-{doc.id}')


def _save_intake_review_fields(intake,submitted,validation):
    clean=validation['normalized'];now=datetime.utcnow();uid=current_user().id
    for field_key in OCR_INTAKE_CORE_FIELDS:
        row=SmartIntakeFieldReview.query.filter_by(intake_id=intake.id,field_key=field_key).first()
        if not row:
            row=SmartIntakeFieldReview(intake_id=intake.id,field_key=field_key);db.session.add(row)
        final=str(clean.get(field_key) or '')
        row.final_value=final
        row.review_status='CORRECTED' if final!=str(row.normalized_value or '') else 'ACCEPTED'
        item=validation['fields'].get(field_key,{})
        row.validation_status=(item.get('status') or 'warning').upper()
        row.validation_message=(item.get('message') or '')[:500]
        row.reviewed_by=uid;row.reviewed_at=now
    intake.review_notes=(submitted.get('review_notes') or '').strip()[:2000]
    intake.reviewed_by=uid;intake.reviewed_at=now


def _save_intake_visit_review(intake,form):
    procedure_id=form.get('procedure_id',type=int)
    contract_id=form.get('contract_id',type=int)
    procedure=Procedure.query.filter_by(id=procedure_id,active=True).first() if procedure_id else None
    contract=Contract.query.filter_by(id=contract_id,active=True).first() if contract_id else None
    approval_no=(form.get('approval_no') or '').strip()[:120]
    if not (contract and contract.approval_required): approval_no=''
    try: summary=json.loads(intake.extracted_json or '{}')
    except Exception: summary={}
    if not isinstance(summary,dict): summary={}
    summary['visit_review']={
      'procedure_id':procedure.id if procedure else None,
      'procedure_name':procedure.name if procedure else '',
      'contract_id':contract.id if contract else None,
      'contract_name':contract.name if contract else '',
      'approval_required':bool(contract and contract.approval_required),
      'approval_no':approval_no,
      'reviewed':True,
      'reviewed_by':current_user().id,
      'reviewed_at':datetime.utcnow().isoformat()+'Z',
    }
    intake.suggested_procedure_id=procedure.id if procedure else None
    intake.suggested_contract_id=contract.id if contract else None
    intake.extracted_json=json.dumps(summary,ensure_ascii=False)
    return summary['visit_review']


def _attach_intake_documents(intake,patient):
    docs=SmartIntakeDocument.query.filter_by(intake_id=intake.id,status='APPROVED').all()
    for doc in docs:
        if doc.patient_document_id: continue
        attached=PatientDocument(
          patient_id=patient.id,document_type=doc.document_type,category='SMART_INTAKE',
          file_path=doc.file_path,original_name=doc.original_name,
          extracted_text=doc.ocr_text,extraction_status='COMPLETED',review_status='APPROVED',
          reviewer_id=doc.reviewed_by,review_notes=doc.review_notes,
          uploaded_by=intake.created_by,reviewed_at=doc.reviewed_at)
        db.session.add(attached);db.session.flush();doc.patient_document_id=attached.id


def _block_intake_registration(intake,status,message,reason_code):
    intake.status=status
    audit('SMART_INTAKE_COMMIT_BLOCKED','smart_intake_session',intake.id,
      f'reason={reason_code} status={status}')
    db.session.commit();flash(message,'danger')
    return _intake_redirect(intake.id,'commit')


@app.post('/intake/smart/<int:intake_id>/review-save')
@require_perm('patients.create')
def smart_intake_review_save(intake_id):
    intake=SmartIntakeSession.query.filter_by(id=intake_id).with_for_update().first_or_404()
    if intake.status=='COMPLETED' and intake.patient_id:
        return redirect(url_for('new_order',patient=intake.patient_id,intake=intake.id))
    action=(request.form.get('registration_action') or 'SAVE_DRAFT').upper()
    if action not in ('SAVE_DRAFT','LINK_EXISTING','CREATE_NEW'): abort(400)
    submitted={key:request.form.get(key,'') for key in OCR_INTAKE_CORE_FIELDS}
    submitted['review_notes']=request.form.get('review_notes','')
    validation=validate_intake_identity(submitted)
    _save_intake_review_fields(intake,submitted,validation)
    visit_review=_save_intake_visit_review(intake,request.form)

    if action=='SAVE_DRAFT':
        draft_match=_intake_match_context(validation['normalized'])
        if not validation['ok']: intake.status='IDENTITY_REVIEW'
        elif draft_match['resolution'] in ('CONFLICT','AMBIGUOUS'): intake.status='MATCH_REVIEW'
        else: intake.status='READY_TO_COMMIT'
        audit('SMART_INTAKE_REVIEW_DRAFT','smart_intake_session',intake.id,
          f'validation_ok={validation["ok"]} invalid_count={len(validation["invalid_fields"])} procedure_id={visit_review.get("procedure_id") or ""} contract_id={visit_review.get("contract_id") or ""}')
        db.session.commit();flash('Review draft saved. No patient or order was created.','success')
        return _intake_redirect(intake.id,'identity')

    docs=SmartIntakeDocument.query.filter_by(intake_id=intake.id).all()
    if not validation['ok']:
        return _block_intake_registration(intake,'IDENTITY_REVIEW',
          'Correct invalid identity fields and provide a reliable identifier before registration.','IDENTITY_INVALID')
    if request.form.get('identity_confirmed')!='1':
        return _block_intake_registration(intake,'IDENTITY_REVIEW',
          'Confirm that the final patient identity was checked against the available source or the patient.','IDENTITY_NOT_CONFIRMED')

    identity=validation['normalized'];match=_intake_match_context(identity)
    top=match.get('top')
    intake.match_resolution=match.get('resolution') or 'NO_MATCH'
    intake.matched_patient_score=float(top.get('score') if top else 0)
    patient=None
    if action=='LINK_EXISTING':
        selected_id=request.form.get('selected_patient_id',type=int)
        selected=next((item for item in match['candidates'] if item['patient_id']==selected_id),None)
        if not selected or selected['score']<85:
            return _block_intake_registration(intake,'MATCH_REVIEW',
              'Select a strong reviewed patient match before linking.','MATCH_NOT_SELECTED')
        if selected.get('hard_conflict') or match.get('resolution')=='AMBIGUOUS':
            reason=(request.form.get('override_reason') or '').strip()
            if not (has_perm('workflow.override') and len(reason)>=8):
                return _block_intake_registration(intake,'MATCH_REVIEW',
                  'Conflict or ambiguous duplicate requires supervisor override and a written reason.','MATCH_CONFLICT_OR_AMBIGUOUS')
            intake.review_notes=((intake.review_notes or '')+'\nSupervisor match override: '+reason).strip()[:2000]
        patient=Patient.query.get_or_404(selected_id)
        intake.matched_patient_id=patient.id
    else:
        exact=next((item for item in match['candidates'] if item['score']==100),None)
        if exact:
            return _block_intake_registration(intake,'MATCH_REVIEW',
              'A patient with this National ID already exists. Link the existing record.','EXACT_DUPLICATE')
        strong=next((item for item in match['candidates'] if item['score']>=85),None)
        if strong:
            reason=(request.form.get('override_reason') or '').strip()
            if not (has_perm('workflow.override') and request.form.get('confirm_create_new')=='1' and len(reason)>=8):
                return _block_intake_registration(intake,'MATCH_REVIEW',
                  'A strong possible duplicate exists. Supervisor override and reason are required to create a new patient.','STRONG_DUPLICATE')
            intake.review_notes=((intake.review_notes or '')+'\nSupervisor duplicate override: '+reason).strip()[:2000]

        lock_value=identity.get('national_id') or (identity.get('phone','')+identity.get('dob',''))
        if db.engine.dialect.name=='postgresql':
            db.session.execute(text('SELECT pg_advisory_xact_lock(hashtext(:key))'),{'key':'OCR_REG:'+lock_value})
        post_lock_match=_intake_match_context(identity)
        if any(item['score']==100 for item in post_lock_match['candidates']):
            return _block_intake_registration(intake,'MATCH_REVIEW',
              'Another registration created this patient. Link the existing record.','CONCURRENT_DUPLICATE')
        patient=Patient(
          patient_id=next_patient_id(),name=identity['name'],phone=identity['phone'],
          national_id=identity['national_id'],sex=identity['sex'],dob=identity['dob'],
          address=identity['address'])
        db.session.add(patient);db.session.flush()
        intake.matched_patient_id=None

    approved_docs=[doc for doc in docs if doc.status=='APPROVED']
    hashes=[doc.content_sha256 for doc in approved_docs if doc.content_sha256]
    commit_key=intake_registration_fingerprint(intake.id,identity,hashes)
    _attach_intake_documents(intake,patient)
    intake.patient_id=patient.id;intake.commit_key=commit_key;intake.commit_action=action
    intake.committed_by=current_user().id;intake.committed_at=datetime.utcnow()
    intake.completed_at=datetime.utcnow();intake.status='COMPLETED'
    audit('SMART_INTAKE_'+action,'smart_intake_session',intake.id,
      f'patient_id={patient.id} match_resolution={match["resolution"]} approved_documents={len(approved_docs)} excluded_documents={len(docs)-len(approved_docs)} procedure_id={visit_review.get("procedure_id") or ""} contract_id={visit_review.get("contract_id") or ""}')
    db.session.commit()
    flash('Patient registration completed. Review the order details before creating the order.','success')
    return redirect(url_for('new_order',patient=patient.id,intake=intake.id))

def _ocr_config_from_input(source):
    try:
        timeout=int(source.get('timeout_seconds',60) or 60)
    except (TypeError,ValueError):
        timeout=-1
    return {
      'enabled':source.get('enabled') in (True,1,'1','true','True','yes','on'),
      'provider_key':(source.get('provider_key') or 'GENERIC_OCR_REST').strip().upper(),
      'base_url':(source.get('base_url') or '').strip(),
      'model_name':(source.get('model_name') or '').strip(),
      'timeout_seconds':timeout,
      'secret_env_name':(source.get('secret_env_name') or 'RIS_OCR_API_KEY').strip(),
    }


def _ocr_saved_validation(row):
    if not row:
        return {'overall':'NOT_CONFIGURED','message':'Save OCR settings before provider validation.'}
    try:
        details=json.loads(row.validation_details or '{}')
        if not isinstance(details,dict): details={}
    except Exception:
        details={}
    current_hash=ocr_configuration_hash(row)
    if not row.validation_config_hash or row.validation_config_hash!=current_hash:
        return {
          'overall':'CONFIG_CHANGED',
          'message':'Configuration changed after the last validation.',
          'validated_at':row.validated_at.isoformat()+'Z' if row.validated_at else None,
        }
    details.setdefault('overall',row.validation_status or 'NOT_CHECKED')
    details.setdefault('latency_ms',row.validation_latency_ms)
    details.setdefault('validated_at',row.validated_at.isoformat()+'Z' if row.validated_at else None)
    return details


def _store_ocr_validation(row,result):
    if not row or result.get('config_hash')!=ocr_configuration_hash(row):
        return False
    row.validation_status=(result.get('overall') or 'NOT_CHECKED')[:40]
    row.validation_details=json.dumps(result,ensure_ascii=False)[:12000]
    row.validation_config_hash=result.get('config_hash') or ''
    row.validation_latency_ms=result.get('latency_ms')
    row.validated_by=current_user().id if current_user() else None
    row.validated_at=datetime.utcnow()
    return True


@app.route('/admin/ocr-settings',methods=['GET','POST'])
@require_perm('users.view')
def admin_ocr_settings():
    row=OCRProviderSetting.query.order_by(OCRProviderSetting.id).first()
    if request.method=='POST':
        config=_ocr_config_from_input(request.form)
        local=validate_ocr_local(config,os.environ)

        # Never allow an API key or token value to be persisted in a field that
        # is specifically intended to contain an environment-variable name.
        secret_check=local['fields'].get('secret_env_name',{})
        if secret_check.get('code')=='SECRET_ENV_NAME_INVALID':
            flash(secret_check.get('message') or 'Invalid secret environment variable name.','danger')
            return render_template('admin_ocr_settings.html',row=row,
              draft=config,initial_validation=local,saved_validation=_ocr_saved_validation(row),
              supported_providers=SUPPORTED_PROVIDERS),400

        if config['enabled'] and not local.get('ok'):
            bad=[x.get('message') for x in local.get('fields',{}).values() if x.get('status')=='invalid']
            flash('OCR settings were not saved: '+'; '.join([x for x in bad if x][:3]),'danger')
            return render_template('admin_ocr_settings.html',row=row,
              draft=config,initial_validation=local,saved_validation=_ocr_saved_validation(row),
              supported_providers=SUPPORTED_PROVIDERS),400

        if not row:
            row=OCRProviderSetting(provider_key=config['provider_key']);db.session.add(row)
        row.enabled=config['enabled']
        row.provider_key=config['provider_key']
        row.base_url=config['base_url']
        row.model_name=config['model_name']
        row.timeout_seconds=config['timeout_seconds']
        row.secret_env_name=config['secret_env_name']
        row.updated_by=current_user().id
        row.validation_status='NOT_CHECKED'
        row.validation_details='{}'
        row.validation_config_hash=''
        row.validation_latency_ms=None
        row.validated_by=None
        row.validated_at=None
        audit('OCR_SETTINGS_SAVE','ocr_provider_setting',row.id or '',
          f"provider={row.provider_key} enabled={row.enabled} base_host={urlparse(row.base_url).hostname or ''}")
        db.session.commit()

        if request.form.get('action')=='save_validate' and row.enabled:
            result=validate_ocr_remote(row,mode='connection',environ=os.environ)
            _store_ocr_validation(row,result)
            audit('OCR_SETTINGS_VALIDATE','ocr_provider_setting',row.id,
              f"provider={row.provider_key} status={result.get('overall')} error={result.get('error_code','')}")
            db.session.commit()
            flash(result.get('message') or result.get('overall'),
              'success' if result.get('ok') else 'danger')
        else:
            flash('OCR settings saved. Validation is required before clinical use.','success')
        return redirect(url_for('admin_ocr_settings'))

    config=row if row else {
      'enabled':False,'provider_key':'GENERIC_OCR_REST','base_url':'http://radbridge-ocr:7400',
      'model_name':'','timeout_seconds':60,'secret_env_name':'RIS_OCR_API_KEY'}
    return render_template('admin_ocr_settings.html',row=row,draft=(config if not row else None),
      initial_validation=validate_ocr_local(config,os.environ),
      saved_validation=_ocr_saved_validation(row),supported_providers=SUPPORTED_PROVIDERS)


@app.post('/admin/ocr-settings/validate')
@require_perm('users.view')
def admin_ocr_settings_validate():
    payload=request.get_json(silent=True) or request.form
    config=_ocr_config_from_input(payload)
    mode='ocr' if str(payload.get('mode') or '').lower()=='ocr' else 'connection'
    result=validate_ocr_remote(config,mode=mode,environ=os.environ)
    row=OCRProviderSetting.query.order_by(OCRProviderSetting.id).first()
    persisted=_store_ocr_validation(row,result)
    if persisted:
        audit('OCR_SETTINGS_TEST' if mode=='ocr' else 'OCR_SETTINGS_VALIDATE',
          'ocr_provider_setting',row.id,
          f"provider={config['provider_key']} status={result.get('overall')} error={result.get('error_code','')}")
        db.session.commit()
    result['saved_config_match']=persisted
    return jsonify(result)



@app.route('/doctor/case/<int:order_id>/workspace',methods=['GET','POST'])
@require_perm('reports.view')
def doctor_clinical_workspace(order_id):
    order=Order.query.get_or_404(order_id)
    assessment=ClinicalAssessment.query.filter_by(order_id=order.id).first()
    if not assessment:
        assessment=ClinicalAssessment(order_id=order.id,created_by=current_user().id)
        db.session.add(assessment);db.session.flush()

    if request.method=='POST':
        section=(request.form.get('section') or '').upper()

        if section=='CLINICAL':
            assessment.complaint=(request.form.get('complaint') or '').strip()
            assessment.history=(request.form.get('history') or '').strip()
            assessment.examination=(request.form.get('examination') or '').strip()
            assessment.clinical_indication=(request.form.get('clinical_indication') or '').strip()
            assessment.allergy_notes=(request.form.get('allergy_notes') or '').strip()
            assessment.updated_by=current_user().id

        elif section=='VITALS':
            db.session.add(VitalSign(
                order_id=order.id,
                temperature=request.form.get('temperature',type=float),
                pulse=request.form.get('pulse',type=int),
                systolic=request.form.get('systolic',type=int),
                diastolic=request.form.get('diastolic',type=int),
                spo2=request.form.get('spo2',type=int),
                respiratory_rate=request.form.get('respiratory_rate',type=int),
                weight_kg=request.form.get('weight_kg',type=float),
                height_cm=request.form.get('height_cm',type=float),
                recorded_by=current_user().id
            ))

        elif section=='DIAGNOSIS':
            txt=(request.form.get('diagnosis_text') or '').strip()
            if txt:
                db.session.add(ClinicalDiagnosis(
                    order_id=order.id,
                    diagnosis_text=txt,
                    diagnosis_type=(request.form.get('diagnosis_type') or 'WORKING').upper(),
                    code=(request.form.get('code') or '').strip(),
                    created_by=current_user().id
                ))

        elif section=='TREATMENT':
            assessment.treatment_plan=(request.form.get('treatment_plan') or '').strip()
            assessment.updated_by=current_user().id

        elif section=='MEDICATION':
            name=(request.form.get('medication_name') or '').strip()
            if name:
                db.session.add(ClinicalMedication(
                    order_id=order.id,
                    medication_name=name,
                    dose=(request.form.get('dose') or '').strip(),
                    route=(request.form.get('route') or '').strip(),
                    frequency=(request.form.get('frequency') or '').strip(),
                    duration=(request.form.get('duration') or '').strip(),
                    notes=(request.form.get('notes') or '').strip(),
                    created_by=current_user().id
                ))

        elif section=='LAB':
            test_name=(request.form.get('test_name') or '').strip()
            if test_name:
                db.session.add(ClinicalLabItem(
                    order_id=order.id,
                    test_name=test_name,
                    created_by=current_user().id
                ))

        db.session.commit()
        audit('CLINICAL_WORKSPACE_UPDATE','order',order.id,section)
        return redirect(url_for('doctor_clinical_workspace',order_id=order.id,tab=(request.form.get('return_tab') or '').lower()))

    attachments=Attachment.query.filter_by(order_id=order.id).order_by(Attachment.created_at.desc()).all()
    priors=related_prior_orders(order,20)
    ext_priors=external_priors_for_order(order)
    reports=Report.query.filter_by(order_id=order.id).order_by(Report.id.desc()).all()
    vitals=VitalSign.query.filter_by(order_id=order.id).order_by(VitalSign.recorded_at.desc()).all()
    diagnoses=ClinicalDiagnosis.query.filter_by(order_id=order.id).order_by(ClinicalDiagnosis.created_at.desc()).all()
    medications=ClinicalMedication.query.filter_by(order_id=order.id,active=True).order_by(ClinicalMedication.created_at.desc()).all()
    labs=ClinicalLabItem.query.filter_by(order_id=order.id).order_by(ClinicalLabItem.created_at.desc()).all()
    readiness=CaseReadiness.query.filter_by(order_id=order.id).first()
    assignment=CaseAssignment.query.filter_by(order_id=order.id,active=True).first()

    return render_template(
        'doctor_clinical_workspace.html',
        order=order,
        assessment=assessment,
        attachments=attachments,
        priors=priors,
        external_priors=ext_priors,
        reports=reports,
        vitals=vitals,
        diagnoses=diagnoses,
        medications=medications,
        labs=labs,
        readiness=readiness,
        assignment=assignment,
        tab=request.args.get('tab','overview')
    )



