        row.default_branch_id=request.form.get('default_branch_id',type=int)
        row.default_department=(request.form.get('default_department') or '').strip()
        row.default_procedure_id=request.form.get('default_procedure_id',type=int)
        row.default_contract_id=request.form.get('default_contract_id',type=int)
        row.default_referrer_id=request.form.get('default_referrer_id',type=int)
