        row.default_payment_method=(request.form.get('default_payment_method') or '').upper()
        row.default_patient_mode=(request.form.get('default_patient_mode') or 'existing').lower()
        row.updated_by=current_user().id
        db.session.commit()
        audit('REGISTRATION_DEFAULTS_UPDATE','user',user_id or 0,'GLOBAL' if is_global else 'USER')
