@app.route('/inventory/stock',methods=['GET','POST'])
@require_perm('inventory.view')
def inventory_stock():
    warehouse_id=request.args.get('warehouse_id',type=int) or request.form.get('warehouse_id',type=int)
    if request.method=='POST':
        if not has_perm('inventory.adjust_quantity'): abort(403)
        item_id=request.form.get('item_id',type=int); qty=request.form.get('qty',type=float) or 0
        movement=(request.form.get('movement_type') or 'RECEIPT').upper()
        reason=(request.form.get('reason') or '').strip()
        if not warehouse_id or not item_id or qty<=0 or not reason:
            flash('Warehouse, item, quantity and reason are required.','danger'); return redirect(url_for('inventory_stock',warehouse_id=warehouse_id))
        wh=Warehouse.query.get_or_404(warehouse_id);item=InventoryItem.query.get_or_404(item_id)
        lot_no=(request.form.get('lot_no') or '').strip()
        expiry=None
        if request.form.get('expiry_date'):
            try:expiry=datetime.strptime(request.form.get('expiry_date'),'%Y-%m-%d').date()
            except Exception:pass
        lot=InventoryLot.query.filter_by(item_id=item.id,warehouse_id=wh.id,lot_no=lot_no).first()
        if not lot:
            lot=InventoryLot(item_id=item.id,warehouse_id=wh.id,lot_no=lot_no,expiry_date=expiry,
                unit_cost=request.form.get('unit_cost',type=float) or item.default_cost,qty_on_hand=0)
            db.session.add(lot);db.session.flush()
        delta=qty if movement in ('RECEIPT','RETURN','ADJUSTMENT_IN') else -qty
        inventory_move(wh,item,delta,'RECEIPT' if delta>0 else 'ADJUSTMENT',lot=lot,
            unit_cost=request.form.get('unit_cost',type=float),reference_type='MANUAL',notes=reason)
        db.session.commit();audit('WAREHOUSE_STOCK_ADJUST','warehouse',wh.id,f'{item.code} {delta}')
        return redirect(url_for('inventory_stock',warehouse_id=wh.id))
    warehouses=Warehouse.query.filter_by(active=True).order_by(Warehouse.name).all()
    rows=[]
    if warehouse_id:
        wh=Warehouse.query.get(warehouse_id)
        for item in InventoryItem.query.filter_by(active=True).order_by(InventoryItem.name).all():
            qty=inventory_on_hand_qty(warehouse_id,item.id);avail=inventory_available_qty(warehouse_id,item.id)
            policy=WarehouseStockPolicy.query.filter_by(warehouse_id=warehouse_id,item_id=item.id,active=True).first()
            rows.append({'item':item,'qty':qty,'available':avail,'policy':policy})
    return render_template('inventory_stock.html',warehouses=warehouses,warehouse_id=warehouse_id,rows=rows,
        items=InventoryItem.query.filter_by(active=True).order_by(InventoryItem.name).all())

