@app.route('/inventory/transfers',methods=['GET','POST'])
@require_perm('inventory.view')
def inventory_transfers():
    if request.method=='POST':
        if not has_perm('inventory.transfer.request'): abort(403)
        source=request.form.get('source_warehouse_id',type=int);target=request.form.get('target_warehouse_id',type=int)
        if not source or not target or source==target:
            flash('Select different source and target warehouses.','danger');return redirect(url_for('inventory_transfers'))
        tr=StockTransfer(transfer_no=next_transfer_no(),source_warehouse_id=source,target_warehouse_id=target,
            status='REQUESTED',requested_by=current_user().id,notes=(request.form.get('notes') or '').strip())
        db.session.add(tr);db.session.flush()
        item_ids=request.form.getlist('item_id');qtys=request.form.getlist('qty')
        count=0
        for raw_item,raw_qty in zip(item_ids,qtys):
            try:item_id=int(raw_item);qty=float(raw_qty)
            except Exception:continue
            if qty<=0:continue
            db.session.add(StockTransferLine(transfer_id=tr.id,item_id=item_id,qty_requested=qty));count+=1
        if not count:
            db.session.rollback();flash('Add at least one transfer item.','danger');return redirect(url_for('inventory_transfers'))
        db.session.commit();audit('STOCK_TRANSFER_REQUEST','stock_transfer',tr.id,tr.transfer_no)
        return redirect(url_for('inventory_transfer_detail',transfer_id=tr.id))
    return render_template('inventory_transfers.html',
        rows=StockTransfer.query.order_by(StockTransfer.id.desc()).limit(300).all(),
        warehouses=Warehouse.query.filter_by(active=True).order_by(Warehouse.name).all(),
        items=InventoryItem.query.filter_by(active=True).order_by(InventoryItem.name).all())

