@app.post('/inventory/transfers/<int:transfer_id>/dispatch')
@require_perm('inventory.transfer.dispatch')
def inventory_transfer_dispatch(transfer_id):
    row=StockTransfer.query.get_or_404(transfer_id)
    if row.status!='APPROVED':
        flash('Transfer must be approved before dispatch.','danger');return redirect(url_for('inventory_transfer_detail',transfer_id=row.id))
    source=row.source_warehouse
    try:
        for line in StockTransferLine.query.filter_by(transfer_id=row.id).all():
            qty=float(line.qty_requested or 0)
            if inventory_available_qty(source.id,line.item_id)<qty-1e-9:
                raise ValueError(f'Insufficient stock for {line.item.name}')
        for line in StockTransferLine.query.filter_by(transfer_id=row.id).all():
            remaining=float(line.qty_requested or 0);dispatched=0
            for lot in stock_lots(source.id,line.item_id):
                take=min(max(0,float(lot.qty_on_hand or 0)-float(lot.qty_reserved or 0)),remaining)
                if take<=0:continue
                inventory_move(source,line.item,-take,'TRANSFER_OUT',lot=lot,reference_type='TRANSFER',reference_id=row.id,notes=row.transfer_no)
                dispatched+=take;remaining-=take
                if remaining<=1e-9:break
            line.qty_dispatched=dispatched
        row.status='DISPATCHED';row.dispatched_by=current_user().id;row.dispatched_at=datetime.utcnow()
        db.session.commit();audit('STOCK_TRANSFER_DISPATCHED','stock_transfer',row.id,row.transfer_no)
    except Exception as e:
        db.session.rollback();flash(str(e),'danger')
    return redirect(url_for('inventory_transfer_detail',transfer_id=row.id))

@app.post('/inventory/transfers/<int:transfer_id>/receive')
@require_perm('inventory.transfer.receive')
def inventory_transfer_receive(transfer_id):
    row=StockTransfer.query.get_or_404(transfer_id)
    if row.status!='DISPATCHED':
        flash('Only dispatched transfers can be received.','danger');return redirect(url_for('inventory_transfer_detail',transfer_id=row.id))
    target=row.target_warehouse
    for line in StockTransferLine.query.filter_by(transfer_id=row.id).all():
        qty=float(line.qty_dispatched or 0)
        if qty<=0:continue
        lot=InventoryLot.query.filter_by(item_id=line.item_id,warehouse_id=target.id,lot_no='').first()
        inventory_move(target,line.item,qty,'TRANSFER_IN',lot=lot,reference_type='TRANSFER',reference_id=row.id,notes=row.transfer_no)
        line.qty_received=qty
    row.status='RECEIVED';row.received_by=current_user().id;row.received_at=datetime.utcnow()
    db.session.commit();audit('STOCK_TRANSFER_RECEIVED','stock_transfer',row.id,row.transfer_no)
    return redirect(url_for('inventory_transfer_detail',transfer_id=row.id))


