@app.route('/orders/<int:order_id>/consumables',methods=['GET','POST'])
@require_perm('inventory.view')
def order_consumables(order_id):
    order=Order.query.get_or_404(order_id)
    warehouse=default_warehouse_for_order(order)
    if request.method=='POST':
        action=(request.form.get('action') or 'CONSUME').upper()
        item=InventoryItem.query.get_or_404(request.form.get('item_id',type=int))
        qty=request.form.get('qty',type=float) or 0
        reason=(request.form.get('reason') or '').strip()
        try:
            if action=='EXTRA':
                if not has_perm('inventory.add_extra_consumable'):abort(403)
                if not reason:raise ValueError('Extra consumable requires a reason.')
                consume_inventory(order,item,qty,usage_type='EXTRA',source='MANUAL',reason=reason,warehouse=warehouse)
            elif action=='WASTE':
                if not has_perm('inventory.waste'):abort(403)
                if not reason:raise ValueError('Waste requires a reason.')
                consume_inventory(order,item,qty,usage_type='WASTE',source='MANUAL',reason=reason,warehouse=warehouse)
            elif action=='RETURN':
                if not has_perm('inventory.return'):abort(403)
                if not reason:raise ValueError('Return requires a reason.')
                return_inventory(order,item,qty,warehouse=warehouse,reason=reason)
            else:
                if not has_perm('inventory.consume'):abort(403)
                consume_inventory(order,item,qty,usage_type='USED',source='MANUAL',reason=reason,warehouse=warehouse)
            db.session.commit();audit('ORDER_CONSUMABLE_'+action,'order',order.id,f'{item.code} x{qty} {reason}')
            flash('Consumable movement saved.','success')
        except Exception as e:
            db.session.rollback();flash(str(e),'danger')
        return redirect(url_for('order_consumables',order_id=order.id))
    usage=OrderConsumableUsage.query.filter_by(order_id=order.id).order_by(OrderConsumableUsage.id.desc()).all()
    return render_template('order_consumables.html',order=order,warehouse=warehouse,defaults=order_default_consumables(order),
        usage=usage,items=InventoryItem.query.filter_by(active=True).order_by(InventoryItem.name).all(),
        total_cost=order_consumable_cost(order))

@app.post('/orders/<int:order_id>/consumables/apply-defaults')
@require_perm('inventory.consume')
def order_consumables_apply_defaults(order_id):
    order=Order.query.get_or_404(order_id);warehouse=default_warehouse_for_order(order)
    if not warehouse:
        flash('No branch warehouse configured.','danger');return redirect(url_for('order_consumables',order_id=order.id))
    try:
        for x in order_default_consumables(order):
            needed=max(0,float(x['rule'].qty or 0)-float(x['used'] or 0))
            if needed>1e-9:
                consume_inventory(order,x['rule'].item,needed,usage_type='USED',source='DEFAULT',
                    reason='Procedure default consumable',warehouse=warehouse)
        db.session.commit();audit('ORDER_DEFAULT_CONSUMABLES_APPLIED','order',order.id,warehouse.name)
        flash('Default consumables applied.','success')
    except Exception as e:
        db.session.rollback();flash(str(e),'danger')
    return redirect(url_for('order_consumables',order_id=order.id))

