@app.post('/inventory/warehouses/create-for-branch/<int:branch_id>')
@require_perm('inventory.manage')
def inventory_create_for_branch(branch_id):
    branch=Branch.query.get_or_404(branch_id)
    main,_=ensure_main_warehouse()

    existing=Warehouse.query.filter_by(
        branch_id=branch.id,
        warehouse_type='BRANCH',
        active=True
    ).order_by(Warehouse.id).first()

    if existing:
        if not existing.parent_id:
            existing.parent_id=main.id
            db.session.commit()
        flash(f'{branch.name} already has warehouse: {existing.name}','info')
        return redirect(request.referrer or url_for('inventory_warehouses'))

    base='BR-'+_warehouse_code_part(getattr(branch,'code',None) or branch.name or str(branch.id))
    code=base
    n=1
    while Warehouse.query.filter_by(code=code).first():
        n+=1
        code=f'{base[:25]}-{n}'

    wh=Warehouse(
        code=code,
        name=f'{branch.name} Warehouse',
        warehouse_type='BRANCH',
        branch_id=branch.id,
        parent_id=main.id,
        active=True
    )
    db.session.add(wh)
    db.session.commit()
    audit('WAREHOUSE_CREATE_FOR_BRANCH','warehouse',wh.id,f'branch={branch.id}')
    flash(f'Warehouse created for {branch.name}: {wh.name}','success')
    return redirect(request.referrer or url_for('inventory_warehouses'))



