def external_reporting_setting():
    row=ExternalReportingSetting.query.order_by(ExternalReportingSetting.id).first()
    if not row:
        row=ExternalReportingSetting(enabled=False)
        db.session.add(row);db.session.flush()
    return row


def _external_intake_generated_accession(row):
    """Return a stable local reference without pretending it came from DICOM."""
    center_code=(re.sub(r'[^A-Z0-9_-]','',str(row.center.code or '').upper()) or 'CENTER')[:20]
    return f'EXT-{center_code}-{row.id}'[:40]


def _external_intake_local_patient_id(row):
    """Create a unique RIS identity while preserving the external ID separately."""
    center_code=(re.sub(r'[^A-Z0-9_-]','',str(row.center.code or '').upper()) or 'CENTER')[:12]
    external_id=(
        str(row.expected_patient_id or '').strip()
        or str(row.dicom_patient_id or '').strip()
        or str(row.inbox.pacs_patient_id or '').strip()
        or 'UNKNOWN'
    )
    external_id=re.sub(r'[^A-Z0-9_-]','-',external_id.upper()).strip('-') or 'UNKNOWN'
    suffix=f'-{row.id}'
    prefix=f'EXT-{center_code}-'
    available=max(1,40-len(prefix)-len(suffix))
    return (prefix+external_id[:available]+suffix)[:40]


def external_intake_autofill(row,tags=None):
    """Prefill empty referral fields but never mark them independently verified."""
    # RB_EXTERNAL_INTAKE_AUTOFILL_V1
    tags=tags or {}
    inbox=row.inbox
    proposed={
        'expected_patient_id':str(tags.get('patient_id') or inbox.pacs_patient_id or '').strip(),
        'expected_patient_name':str(tags.get('patient_name') or inbox.pacs_patient_name or '').replace('^',' ').strip(),
        'expected_dob':normalize_date(tags.get('dob')),
        'expected_sex':str(tags.get('sex') or '').strip().upper()[:1],
        'expected_accession':str(tags.get('accession') or inbox.accession or '').strip(),
    }
    if not proposed['expected_accession']:
        proposed['expected_accession']=_external_intake_generated_accession(row)
    for field,value in proposed.items():
        if not str(getattr(row,field) or '').strip() and value:
            setattr(row,field,value)
    return proposed


def capture_external_pacs_studies():
    """Mirror eligible PACS inbox rows into the isolated external intake.

    This function never creates an Order, offer or assignment. An exact,
    enabled source AE mapping is mandatory; unknown sources remain untouched.
    """
    setting=external_reporting_setting()
    if not setting.enabled:
        return 0
    created=0
    centers={
        row.ae_title.strip().upper():row
        for row in ExternalReportingCenter.query.filter_by(active=True,receiving_enabled=True).all()
    }
    # RB_EXTERNAL_INTAKE_REMOTE_AET_DISCOVERY_V1
    # Scan Orthanc here instead of requiring the internal auto-intake job to
    # populate PacsStudyInbox first. Only exact known external AEs are mirrored;
    # unknown sources remain untouched and no Patient/Order is ever created.
    for study in _orthanc_recent_studies(500):
        tags=_study_tags_extended(study)
        study_id=str(tags.get('study_id') or '').strip()
        source_ae=str(tags.get('source_ae') or '').strip().upper()
        center=centers.get(source_ae)
        if not study_id or not center:
            continue
        inbox=PacsStudyInbox.query.filter_by(orthanc_study_id=study_id).first()
        if not inbox:
            inbox=PacsStudyInbox(
                orthanc_study_id=study_id,
                study_instance_uid=(tags.get('study_instance_uid') or None),
                pacs_patient_id=tags.get('patient_id',''),
                pacs_patient_name=tags.get('patient_name',''),
                accession=tags.get('accession',''),
                modality=tags.get('modality',''),
                study_description=tags.get('study_description',''),
                source_ae=source_ae,
                image_count=int(tags.get('instances') or 0),
                state='EXTERNAL_INTAKE'
            )
            db.session.add(inbox);db.session.flush()
        else:
            inbox.source_ae=source_ae
            inbox.last_seen_at=datetime.utcnow()
            inbox.image_count=int(tags.get('instances') or inbox.image_count or 0)
        if inbox.order_id is not None:
            continue
        intake=ExternalIntakeCase.query.filter_by(inbox_id=inbox.id).first()
        if not intake:
            intake=ExternalIntakeCase(
                center_id=center.id,inbox_id=inbox.id,status='RECEIVED'
            )
            db.session.add(intake);db.session.flush()
            created+=1
        external_intake_autofill(intake,tags)
        inbox.state='EXTERNAL_INTAKE'

    # Preserve capture of eligible inbox rows created by older discovery jobs.
    for inbox in PacsStudyInbox.query.filter(PacsStudyInbox.order_id.is_(None)).all():
        center=centers.get(str(inbox.source_ae or '').strip().upper())
        if not center or ExternalIntakeCase.query.filter_by(inbox_id=inbox.id).first():
            continue
        intake=ExternalIntakeCase(center_id=center.id,inbox_id=inbox.id,status='RECEIVED')
        db.session.add(intake);db.session.flush()
        external_intake_autofill(intake)
        created+=1
    return created


def external_intake_dicom_demographics(row):
    """Read the authoritative patient/study identity from linked Orthanc data."""
    study_id=str(row.inbox.orthanc_study_id or '').strip()
    if not study_id:
        return {},'ORTHANC_STUDY_ID_MISSING'
    try:
        response=requests.get(
            f'{PACS_ORTHANC_URL}/studies/{study_id}',
            auth=_orthanc_auth(),timeout=15
        )
        response.raise_for_status()
        study=response.json() or {}
        patient=study.get('PatientMainDicomTags') or {}
        tags=study.get('MainDicomTags') or {}
        return {
            'patient_id':str(patient.get('PatientID') or '').strip(),
            'patient_name':str(patient.get('PatientName') or '').strip(),
            'dob':normalize_date(patient.get('PatientBirthDate')),
            'sex':str(patient.get('PatientSex') or '').strip().upper()[:1],
            'accession':str(tags.get('AccessionNumber') or row.inbox.accession or '').strip(),
        },''
    except Exception as exc:
        return {},'ORTHANC_DEMOGRAPHICS_FAILED: '+str(exc)[:300]


def external_intake_demographic_verification(row,persist=False,actor_user_id=None):
    """Fail-closed comparison of referral identity against live DICOM identity."""
    dicom,error=external_intake_dicom_demographics(row)
    expected={
        'patient_id':str(row.expected_patient_id or '').strip(),
        'patient_name':str(row.expected_patient_name or '').strip(),
        'dob':normalize_date(row.expected_dob),
        'sex':str(row.expected_sex or '').strip().upper()[:1],
        'accession':str(row.expected_accession or '').strip(),
    }
    normalizers={
        'patient_id':lambda value:str(value or '').strip().upper(),
        'patient_name':lambda value:normalize_person_name(value),
        'dob':lambda value:normalize_date(value),
        'sex':lambda value:str(value or '').strip().upper()[:1],
        'accession':lambda value:str(value or '').strip().upper(),
    }
    labels={
        'patient_id':'Patient ID','patient_name':'Patient Name','dob':'DOB',
        'sex':'Sex','accession':'Accession'
    }
    critical={'patient_id','dob','accession'}
    checks=[]
    matches=0
    comparable=0
    hard_mismatch=False
    review_required=bool(error)
    for key in ('patient_id','patient_name','dob','sex','accession'):
        left=normalizers[key](expected.get(key))
        right=normalizers[key](dicom.get(key))
        if not left or not right:
            state='MISSING'
            review_required=True
        elif left==right:
            state='MATCH'
            matches+=1
            comparable+=1
        else:
            state='MISMATCH'
            comparable+=1
            if key in critical:
                hard_mismatch=True
            else:
                review_required=True
        checks.append({
            'field':labels[key],'expected':expected.get(key) or '',
            'dicom':dicom.get(key) or '','status':state,'critical':key in critical
        })
    if hard_mismatch:
        status='BLOCKED'
    elif review_required:
        status='REVIEW_REQUIRED'
    else:
        status='MATCHED'
    score=round((matches/comparable)*100,2) if comparable else 0.0
    facts={
        'expected':expected,'dicom':dicom,'checks':checks,'source_error':error
    }
    facts_sha256=hashlib.sha256(
        json.dumps(facts,sort_keys=True,ensure_ascii=False).encode('utf-8')
    ).hexdigest()
    result={
        'status':status,'score':score,'checks':checks,'facts_sha256':facts_sha256,
        'source_error':error,'expected':expected,'dicom':dicom
    }
    if persist:
        row.dicom_patient_id=dicom.get('patient_id') or ''
        row.dicom_patient_name=dicom.get('patient_name') or ''
        row.dicom_dob=dicom.get('dob') or ''
        row.dicom_sex=dicom.get('sex') or ''
        row.dicom_accession=dicom.get('accession') or ''
        row.demographic_status=status
        row.demographic_score=score
        row.demographic_checks_json=json.dumps(checks,ensure_ascii=False)
        row.demographic_facts_sha256=facts_sha256
        row.demographic_verified_by=actor_user_id
        row.demographic_verified_at=datetime.utcnow()
        if row.demographic_override_facts_sha256!=facts_sha256:
            row.demographic_override_approved=False
            row.demographic_override_reason=''
            row.demographic_override_by=None
            row.demographic_override_at=None
            row.demographic_override_facts_sha256=''
    return result


def queue_external_intake(row,actor_user_id):
    if row.status not in ('RECEIVED','HOLD'):
        return None,'INTAKE_NOT_REVIEWABLE'
    setting=external_reporting_setting()
    center=row.center
    inbox=row.inbox
    if not setting.enabled:
        return None,'EXTERNAL_REPORTING_DISABLED'
    if not center.active or not center.receiving_enabled or not center.assignment_enabled:
        return None,'CENTER_NOT_ENABLED'
    pool=ExternalCenterDoctor.query.filter_by(center_id=center.id,active=True).count()
    if pool<1:
        return None,'DOCTOR_POOL_EMPTY'
    if not inbox.study_instance_uid or not inbox.orthanc_study_id or int(inbox.image_count or 0)<1:
        return None,'STUDY_NOT_READY'
    verification=external_intake_demographic_verification(row)
    if verification['status']=='BLOCKED':
        return None,'DEMOGRAPHICS_BLOCKED'
    if verification['status']=='REVIEW_REQUIRED' and not (
        not verification['source_error'] and
        row.demographic_override_approved and
        row.demographic_override_facts_sha256==verification['facts_sha256']
    ):
        return None,'DEMOGRAPHICS_REVIEW_REQUIRED'
    if verification['status'] not in ('MATCHED','REVIEW_REQUIRED'):
        return None,'DEMOGRAPHICS_NOT_VERIFIED'
    intake_attachments=Attachment.query.filter_by(external_intake_id=row.id).all()
    if center.required_documents and not intake_attachments:
        return None,'REQUIRED_DOCUMENTS_MISSING'
    if center.billing_enabled and not center.billing_contract_id:
        return None,'CENTER_BILLING_CONTRACT_REQUIRED'

    branch=Branch.query.filter_by(active=True).order_by(Branch.id).first()
    if not branch:
        return None,'ACTIVE_BRANCH_REQUIRED'
    patient=Patient(
        patient_id=_external_intake_local_patient_id(row),
        name=(str(row.expected_patient_name or '').strip()
              or (inbox.pacs_patient_name or '').replace('^',' ').strip()
              or 'External patient')[:120],
        dob=normalize_date(row.expected_dob),sex=(row.expected_sex or '')[:1],phone='',
        worklist_name=f'EXTERNAL:{center.code}:{center.name}'[:180]
    )
    db.session.add(patient);db.session.flush()
    local_accession=_external_intake_generated_accession(row)
    description=(
        f'External - {center.name} - '
        f'{inbox.study_description or "Reporting study"}'
    )[:120]
    report_fee=max(0.0,float(center.default_report_fee or 0)) if center.billing_enabled else 0.0
    order=Order(
        accession=local_accession,patient_id=patient.id,
        modality=(inbox.modality or 'OT').split('\\')[0].strip().upper()[:8] or 'OT',
        procedure=description,
        station_ae=(inbox.source_ae or '')[:40],scheduled=inbox.first_seen_at or datetime.utcnow(),
        status='IMAGES_RECEIVED',branch_id=branch.id,priority=center.default_priority,
        contract_id=(center.billing_contract_id if center.billing_enabled else None),
        gross_price=report_fee,contract_price=report_fee,
        patient_share=0,company_share=report_fee,paid_amount=0,
        created_by=actor_user_id,created_at=datetime.utcnow(),exam_status='EXAM_COMPLETED',
        exam_completed_at=datetime.utcnow(),pacs_image_count=int(inbox.image_count or 0),
        pacs_status='IMAGES_COMPLETE',pacs_last_seen_at=inbox.last_seen_at or datetime.utcnow(),
        pacs_last_change_at=inbox.last_seen_at or datetime.utcnow(),
        pacs_study_id=inbox.orthanc_study_id,study_instance_uid=inbox.study_instance_uid
    )
    db.session.add(order);db.session.flush()
    for attachment in intake_attachments:
        attachment.patient_id=patient.id
        attachment.order_id=order.id
    row.order_id=order.id;row.status='QUEUED';row.reviewed_by=actor_user_id
    row.reviewed_at=datetime.utcnow();row.queued_at=row.reviewed_at
    inbox.order_id=order.id;inbox.state='EXTERNAL_QUEUED'
    db.session.add(AuditLog(
        user_id=actor_user_id,username=current_user().username,
        action='EXTERNAL_INTAKE_QUEUE',entity='external_intake_case',entity_id=str(row.id),
        details=(f'center={center.code};order={order.id};study={inbox.orthanc_study_id};'
                 f'billing={center.billing_enabled};fee={report_fee};documents={len(intake_attachments)}'),
        ip=request.remote_addr or ''
    ))
    db.session.commit()
    offer,status=offer_next_doctor(order,created_by=actor_user_id)
    return offer,status


@app.route('/admin/external-intake',methods=['GET','POST'])
@require_perm('assignment.manage')
def admin_external_intake():
    setting=external_reporting_setting()
    if request.method=='POST':
        action=(request.form.get('action') or '').upper()
        if action=='MASTER':
            setting.enabled=request.form.get('enabled')=='1'
            setting.updated_by=current_user().id
            audit('EXTERNAL_REPORTING_MASTER','external_reporting_setting',setting.id,
                  f'enabled={setting.enabled}')
        elif action=='CENTER':
            code=re.sub(r'[^A-Z0-9_-]','',(request.form.get('code') or '').upper())[:40]
            ae=(request.form.get('ae_title') or '').strip().upper()[:80]
            name=(request.form.get('name') or '').strip()[:160]
            if not code or not ae or not name: abort(400)
            center=ExternalReportingCenter.query.filter_by(code=code).first()
            if not center:
                center=ExternalReportingCenter(code=code,name=name,ae_title=ae,created_by=current_user().id)
                db.session.add(center)
            center.name=name;center.ae_title=ae
            center.receiving_enabled=request.form.get('receiving_enabled')=='1'
            center.assignment_enabled=request.form.get('assignment_enabled')=='1'
            center.auto_queue=False # Phase one remains explicit-admin queue only.
            center.required_documents=request.form.get('required_documents')=='1'
            center.billing_enabled=request.form.get('billing_enabled')=='1'
            center.billing_contract_id=request.form.get('billing_contract_id',type=int) or None
            try:
                center.default_report_fee=max(0.0,float(request.form.get('default_report_fee') or 0))
            except (TypeError,ValueError):
                abort(400)
            if center.billing_enabled:
                contract=Contract.query.filter_by(id=center.billing_contract_id,active=True).first()
                if not contract: abort(400)
            center.default_priority=(request.form.get('default_priority') or 'ROUTINE').upper()
            center.active=request.form.get('active')=='1'
            db.session.flush()
            wanted={int(x) for x in request.form.getlist('doctor_ids') if x.isdigit()}
            existing={x.doctor_user_id:x for x in ExternalCenterDoctor.query.filter_by(center_id=center.id).all()}
            for doctor_id,item in existing.items(): item.active=doctor_id in wanted
            for doctor_id in wanted-existing.keys():
                db.session.add(ExternalCenterDoctor(center_id=center.id,doctor_user_id=doctor_id,active=True))
            audit('EXTERNAL_CENTER_SAVE','external_reporting_center',center.id,
                  f'code={code};receiving={center.receiving_enabled};assignment={center.assignment_enabled};'
                  f'billing={center.billing_enabled};contract={center.billing_contract_id};'
                  f'fee={center.default_report_fee};pool={sorted(wanted)}')
        elif action=='SYNC':
            count=capture_external_pacs_studies()
            audit('EXTERNAL_INTAKE_SYNC','external_intake_case','',f'created={count}')
        else:
            abort(400)
        db.session.commit()
        return redirect(url_for('admin_external_intake'))
    doctors=User.query.join(Role).filter(User.active.is_(True),Role.code.in_(['RADIOLOGIST','DOCTOR'])).all()
    centers=ExternalReportingCenter.query.order_by(ExternalReportingCenter.name).all()
    pools={c.id:{x.doctor_user_id for x in ExternalCenterDoctor.query.filter_by(center_id=c.id,active=True)} for c in centers}
    rows=ExternalIntakeCase.query.order_by(ExternalIntakeCase.created_at.desc()).limit(500).all()
    demographic_checks={}
    for row in rows:
        try: demographic_checks[row.id]=json.loads(row.demographic_checks_json or '[]')
        except Exception: demographic_checks[row.id]=[]
    return render_template('admin_external_intake.html',setting=setting,centers=centers,
                           doctors=doctors,pools=pools,rows=rows,
                           demographic_checks=demographic_checks,
                           contracts=Contract.query.filter_by(active=True).order_by(Contract.name).all(),
                           intake_attachments={row.id:Attachment.query.filter_by(
                               external_intake_id=row.id).order_by(Attachment.created_at.desc()).all()
                               for row in rows})


@app.post('/admin/external-intake/<int:intake_id>/attachments')
@require_perm('assignment.manage')
def admin_external_intake_attachment_upload(intake_id):
    row=ExternalIntakeCase.query.get_or_404(intake_id)
    if row.status not in ('RECEIVED','HOLD'): abort(409)
    files=[item for item in request.files.getlist('files') if item and item.filename]
    if not files:
        flash('Choose one or more referral or approval documents.','danger')
        return redirect(url_for('admin_external_intake'))
    category=(request.form.get('category') or 'REFERRAL').strip().upper()
    if category not in ('REFERRAL','APPROVAL','CLINICAL','IDENTITY','OTHER'): abort(400)
    notes=(request.form.get('notes') or '').strip()[:500]
    folder=os.path.join(ATTACHMENT_DIR,'external-intake',str(row.id))
    os.makedirs(folder,exist_ok=True)
    allowed_exts=('.pdf','.jpg','.jpeg','.png','.doc','.docx','.odt','.dcm','.dicom','.zip')
    saved=0
    for uploaded in files:
        ext=os.path.splitext(uploaded.filename)[1].lower()
        if ext not in allowed_exts:
            continue
        stored_name=generated_attachment_filename(row.id,category,uploaded.filename)
        path=os.path.join(folder,stored_name)
        uploaded.save(path)
        db.session.add(Attachment(
            external_intake_id=row.id,category=category,
            original_name=uploaded.filename[:255],stored_path=path,
            mime_type=(uploaded.mimetype or '')[:120],notes=notes,
            uploaded_by=current_user().id
        ))
        saved+=1
    if saved<1:
        flash('No supported documents were uploaded.','danger')
        return redirect(url_for('admin_external_intake'))
    audit('EXTERNAL_INTAKE_ATTACHMENT_UPLOAD','external_intake_case',row.id,
          f'category={category};count={saved}')
    db.session.commit()
    flash(f'{saved} external intake document(s) uploaded.','success')
    return redirect(url_for('admin_external_intake'))


@app.post('/admin/external-intake/<int:intake_id>/decision')
@require_perm('assignment.manage')
def admin_external_intake_decision(intake_id):
    row=ExternalIntakeCase.query.get_or_404(intake_id)
    action=(request.form.get('action') or '').upper()
    note=(request.form.get('note') or '').strip()[:500]
    if action=='VERIFY':
        row.expected_patient_id=(request.form.get('expected_patient_id') or '').strip()[:80]
        row.expected_patient_name=(request.form.get('expected_patient_name') or '').strip()[:180]
        row.expected_dob=normalize_date(request.form.get('expected_dob'))
        row.expected_sex=(request.form.get('expected_sex') or '').strip().upper()[:1]
        row.expected_accession=(request.form.get('expected_accession') or '').strip()[:120]
        if not (row.expected_patient_id and row.expected_patient_name and
                row.expected_dob and row.expected_accession):
            abort(400)
        result=external_intake_demographic_verification(
            row,persist=True,actor_user_id=current_user().id
        )
        audit('EXTERNAL_DEMOGRAPHICS_VERIFY','external_intake_case',row.id,
              f"status={result['status']};score={result['score']};facts={result['facts_sha256']}")
        db.session.commit()
        flash('Demographic verification: '+result['status'],
              'success' if result['status']=='MATCHED' else 'warning')
        return redirect(url_for('admin_external_intake'))
    if action=='APPROVE_REVIEW':
        result=external_intake_demographic_verification(row,persist=True,
                                                        actor_user_id=current_user().id)
        if result['status']!='REVIEW_REQUIRED': abort(409)
        if result['source_error']: abort(409)
        if not note: abort(400)
        row.demographic_override_approved=True
        row.demographic_override_reason=note
        row.demographic_override_by=current_user().id
        row.demographic_override_at=datetime.utcnow()
        row.demographic_override_facts_sha256=result['facts_sha256']
        audit('EXTERNAL_DEMOGRAPHICS_APPROVE_REVIEW','external_intake_case',row.id,
              f"reason={note};facts={result['facts_sha256']}")
        db.session.commit()
        flash('Demographic review approved for the current DICOM facts.','success')
        return redirect(url_for('admin_external_intake'))
    if action=='QUEUE':
        _,status=queue_external_intake(row,current_user().id)
        flash('External case queued.' if status in ('OFFERED','DIRECT_ASSIGNED') else f'Queue result: {status}',
              'success' if status in ('OFFERED','DIRECT_ASSIGNED') else 'warning')
        return redirect(url_for('admin_external_intake'))
    if row.status not in ('RECEIVED','HOLD'): abort(409)
    if action not in ('HOLD','REJECT'): abort(400)
    row.status='HOLD' if action=='HOLD' else 'REJECTED'
    row.review_note=note;row.reviewed_by=current_user().id;row.reviewed_at=datetime.utcnow()
    audit('EXTERNAL_INTAKE_'+action,'external_intake_case',row.id,note)
    db.session.commit()
    return redirect(url_for('admin_external_intake'))

