# ============================================================
# OHIF Integrated Reporting API - TEST
# ============================================================


OHIF_REPORTING_TOKEN = os.getenv("OHIF_REPORTING_TOKEN", "").strip()

def require_ohif_token(fn):
    from functools import wraps

    @wraps(fn)
    def wrapper(*args, **kwargs):
        supplied = (request.headers.get("X-RadBridge-OHIF-Token") or "").strip()

        if not OHIF_REPORTING_TOKEN or supplied != OHIF_REPORTING_TOKEN:
            return jsonify({
                "ok": False,
                "error": "OHIF_AUTH_REQUIRED"
            }), 401

        return fn(*args, **kwargs)

    return wrapper




def _normalize_case_uid(value):
    return str(value or '').strip()


def validate_ohif_case_context(order, requested_study_uid=None):
    """
    Critical patient-safety gate.

    The study displayed by OHIF must be the exact PACS study
    attached to the RIS Order.

    Never trust radbridgeOrderId and StudyInstanceUIDs as two
    independent client-side values.
    """

    expected_uid = _normalize_case_uid(
        ohif_study_uid(order)
    )

    received_uid = _normalize_case_uid(
        requested_study_uid
        or request.args.get('studyInstanceUID')
        or request.args.get('StudyInstanceUIDs')
    )

    if not expected_uid:
        return False, {
            'error': 'RIS_ORDER_HAS_NO_STUDY_UID',
            'message': (
                'Reporting is blocked because this RIS order '
                'is not linked to a PACS study.'
            ),
            'expected_study_uid': '',
            'received_study_uid': received_uid,
        }

    if not received_uid:
        return False, {
            'error': 'OHIF_STUDY_UID_REQUIRED',
            'message': (
                'Reporting is blocked because the displayed '
                'PACS Study UID was not supplied.'
            ),
            'expected_study_uid': expected_uid,
            'received_study_uid': '',
        }

    if received_uid != expected_uid:
        return False, {
            'error': 'OHIF_STUDY_ORDER_MISMATCH',
            'message': (
                'Patient safety block: the PACS study displayed '
                'in OHIF does not belong to the selected RIS order.'
            ),
            'expected_study_uid': expected_uid,
            'received_study_uid': received_uid,
            'order_id': order.id,
            'accession': order.accession,
            'patient_id': (
                order.patient.patient_id
                if order.patient else ''
            ),
            'modality': order.modality or '',
            'procedure': order.procedure or '',
        }

    return True, {
        'error': '',
        'expected_study_uid': expected_uid,
        'received_study_uid': received_uid,
    }


def require_valid_ohif_case_context(order):
    ok, result = validate_ohif_case_context(order)

    if ok:
        return None

    audit(
        'CASE_CONTEXT_MISMATCH_BLOCKED',
        'order',
        order.id,
        (
            f"error={result.get('error')} "
            f"expected_uid={result.get('expected_study_uid')} "
            f"received_uid={result.get('received_study_uid')}"
        )
    )

    db.session.commit()

    payload = {
        'ok': False,
        **result
    }

    return jsonify(payload), 409



def _ohif_report_json(order, report):
    return {
        'ok': True,
        'order': {
            'id': order.id,
            'accession': order.accession,
            'status': order.status,
            'modality': order.modality,
            'procedure': order.procedure,
            'study_instance_uid': ohif_study_uid(order),
        },
        'patient': {
            'id': order.patient.patient_id if order.patient else '',
            'name': order.patient.name if order.patient else '',
            'dob': str(order.patient.dob or '') if order.patient else '',
            'sex': order.patient.sex if order.patient else '',
        },
        'report': {
            'id': report.id,
            'status': report.status or 'DRAFT',
            'findings': report.findings or '',
            'impression': report.impression or '',
            'radiologist': report.radiologist or '',
            'updated_at': report.updated_at.isoformat() if report.updated_at else None,
            'allowed_transitions': allowed_report_transitions(report),
        }
    }


def _ohif_json_body():
    data = request.get_json(silent=True)
    return data if isinstance(data, dict) else {}


@app.get('/api/ohif/report/<int:order_id>')
@require_ohif_token
def api_ohif_report_get(order_id):
    order = Order.query.get_or_404(order_id)

    context_block = require_valid_ohif_case_context(order)
    if context_block:
        return context_block

    doctor_user, identity_block = require_ohif_doctor_user(order.id)
    if identity_block:
        return identity_block

    # Record a real reporting-panel open, but suppress refresh/reload noise
    # for the same doctor and order for five minutes.
    opened_since = datetime.utcnow() - timedelta(minutes=5)

    recent_open = (
        AuditLog.query
        .filter_by(
            user_id=doctor_user.id,
            action='OHIF_REPORT_OPENED',
            entity='order',
            entity_id=str(order.id)
        )
        .filter(AuditLog.created_at >= opened_since)
        .first()
    )

    if recent_open is None:
        audit_as_user(
            doctor_user,
            'OHIF_REPORT_OPENED',
            'order',
            order.id,
            'OHIF reporting panel opened'
        )
        db.session.commit()

    report = get_report(order)
    return jsonify(_ohif_report_json(order, report))


