@app.get('/api/ohif/report/<int:order_id>/word')
@require_ohif_token
def api_ohif_report_word(order_id):
    order = Order.query.get_or_404(order_id)

    context_block = require_valid_ohif_case_context(order)
    if context_block:
        return context_block
    report = get_report(order)

    authoritative = _rb_authoritative_docx_download(
        order,
        report,
    )

    if authoritative:
        return send_file(
            authoritative['path'],
            as_attachment=True,
            download_name=build_report_filename(
                order,
                authoritative['version_no'],
                authoritative['status'],
                'docx',
            ),
            mimetype=(
                'application/vnd.openxmlformats-officedocument.'
                'wordprocessingml.document'
            ),
        )

    version_no = _next_report_version(report)

    doc = Document()
    section = doc.sections[0]
    header = section.header

    table = header.add_table(
        rows=5,
        cols=4,
        width=Inches(7.0)
    )
    table.style = 'Table Grid'

    patient = order.patient
    proc_name = (
        order.proc.name
        if order.proc
        else order.procedure
    ) or ''

    ref_name = (
        order.referring_doctor.name
        if getattr(order, 'referring_doctor', None)
        else ''
    )

    values = [
        (
            'Patient Name',
            patient.name or '',
            'Patient ID',
            patient.patient_id or ''
        ),
        (
            'DOB',
            str(patient.dob or ''),
            'Sex',
            patient.sex or ''
        ),
        (
            'Accession',
            order.accession or '',
            'Modality',
            order.modality or ''
        ),
        (
            'Exam',
            proc_name,
            'Study Date',
            str(order.scheduled or '')
        ),
        (
            'Referring Doctor',
            ref_name,
            'Report Status',
            report.status or 'DRAFT'
        ),
    ]

    for r, row in enumerate(values):
        for c, val in enumerate(row):
            table.cell(r, c).text = str(val)

    doc.add_paragraph(
        f'RIS_ACCESSION: {order.accession}'
    )

    doc.add_heading(
        proc_name or 'Radiology Report',
        level=1
    )

    doc.add_heading('FINDINGS', level=2)
    doc.add_paragraph(report.findings or '')

    doc.add_heading('IMPRESSION', level=2)
    doc.add_paragraph(report.impression or '')

    if report.radiologist:
        doc.add_paragraph(
            f'RADIOLOGIST: {report.radiologist}'
        )

    out = io.BytesIO()
    doc.save(out)
    out.seek(0)

    return send_file(
        out,
        as_attachment=True,
        download_name=build_report_filename(
            order,
            version_no,
            'DRAFT',
            'docx'
        ),
        mimetype=(
            'application/vnd.openxmlformats-officedocument.'
            'wordprocessingml.document'
        )
    )


def _ohif_validate_word_upload(order, document, final=False):
    if not document or not document.filename:
        return None, {
            'ok': False,
            'error': 'DOCUMENT_REQUIRED'
        }, 400

    if not document.filename.lower().endswith('.docx'):
        return None, {
            'ok': False,
            'error': 'DOCX_REQUIRED'
        }, 400

    tmpdir = tempfile.mkdtemp(prefix='ohif-word-identity-')
    tmppath = os.path.join(tmpdir, 'report.docx')

    document.save(tmppath)

    doc = Document(tmppath)
    values = []

    def add_text(value):
        value = str(value or '').strip()
        if value:
            values.append(value)

    # Main body
    for para in doc.paragraphs:
        add_text(para.text)

    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                add_text(cell.text)

    # Header -- RadBridge template stores patient demographics here
    for section in doc.sections:
        header = section.header

        for para in header.paragraphs:
            add_text(para.text)

        for table in header.tables:
            for row in table.rows:
                for cell in row.cells:
                    add_text(cell.text)

    text_blob = '\n'.join(values)

    expected_pid = str(
        order.patient.patient_id if order.patient else ''
    ).strip()

    expected_acc = str(order.accession or '').strip()

    # --------------------------------------------------------
    # Find RIS Accession
    # --------------------------------------------------------

    found_acc = ''

    m = re.search(
        r'RIS_ACCESSION\s*:\s*([A-Za-z0-9_.-]+)',
        text_blob,
        re.I
    )

    if m:
        found_acc = m.group(1).strip()

    if not found_acc:
        for i, value in enumerate(values):

            if re.fullmatch(
                r'\s*accession(?:\s+number)?\s*:?\s*',
                value,
                re.I
            ):
                if i + 1 < len(values):
                    found_acc = values[i + 1].strip()
                    break

            m = re.match(
                r'^accession(?:\s+number)?\s*:\s*(.+)$',
                value,
                re.I
            )

            if m:
                found_acc = m.group(1).strip()
                break

    # --------------------------------------------------------
    # Find Patient ID
    # --------------------------------------------------------

    found_pid = ''

    for i, value in enumerate(values):

        if re.fullmatch(
            r'\s*patient\s*id\s*:?\s*',
            value,
            re.I
        ):
            if i + 1 < len(values):
                found_pid = values[i + 1].strip()
                break

        m = re.match(
            r'^patient\s*id\s*:\s*(.+)$',
            value,
            re.I
        )

        if m:
            found_pid = m.group(1).strip()
            break

    # --------------------------------------------------------
    # STRICT DECISION
    # --------------------------------------------------------

    if not found_pid or not found_acc:
        result = 'IDENTITY_NOT_FOUND'

    elif found_pid != expected_pid:
        result = 'PATIENT_ID_MISMATCH'

    elif found_acc != expected_acc:
        result = 'ACCESSION_MISMATCH'

    else:
        result = 'MATCH'

    safety = {
        'result': result,
        'expected_patient_id': expected_pid,
        'found_patient_id': found_pid,
        'expected_accession': expected_acc,
        'found_accession': found_acc,
    }

    audit(
        'REPORT_PATIENT_SAFETY',
        'order',
        order.id,
        (
            f"OHIF_WORD result={result} "
            f"expected_pid={expected_pid} "
            f"found_pid={found_pid} "
            f"expected_acc={expected_acc} "
            f"found_acc={found_acc}"
        )
    )

    db.session.commit()

    # HARD BLOCK FOR BOTH DRAFT AND FINAL
    if result != 'MATCH':
        return None, {
            'ok': False,
            'error': 'WORD_PATIENT_IDENTITY_MISMATCH',
            'reason': result,
            'safety': safety,
            'message': (
                'Upload blocked: Patient ID and Accession '
                'inside this Word document do not match '
                'the currently opened RIS case.'
            )
        }, 409

    return tmppath, {
        'ok': True,
        'safety': safety
    }, 200


@app.post('/api/ohif/report/<int:order_id>/word/draft')
@require_ohif_token
def api_ohif_report_word_draft(order_id):
    import os
    import uuid

    from report_transaction_writer import (
        commit_report_version,
        TransactionalReportCommitError,
    )

    order = Order.query.get_or_404(order_id)

    context_block = require_valid_ohif_case_context(order)
    if context_block:
        return context_block

    doctor_user, identity_block = \
        require_ohif_doctor_user(order.id)

    if identity_block:
        return identity_block

    try:
        report=get_report(order)
        assert_not_final(report)
        assert_role_allowed(doctor_user,'DRAFT')

        lease_token=str(
            request.headers.get('X-RadBridge-Report-Lease') or
            (request.get_json(silent=True) or {}).get('lease_token') or
            request.form.get('lease_token') or
            ''
        ).strip()

        assert_lease_owner(
            db=db,
            order=order,
            report=report,
            user=doctor_user,
            lease_token=lease_token,
        )

    except ReportEditControlError as exc:
        code=getattr(exc,'code',type(exc).__name__)

        try:
            audit(
                'REPORT_EDIT_DENIED',
                'order',
                order.id,
                f'action=DRAFT; editor=WORD; code={code}; user={doctor_user.id}'
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        return jsonify({
            'ok':False,
            'error':code,
        }), 409 if code in (
            'FINAL_REPORT_LOCKED',
            'REPORT_EDIT_LOCKED',
        ) else 403

    report = get_report(order)

    if (report.status or '').upper() == 'FINAL':
        return jsonify({
            'ok': False,
            'error': 'FINAL_REPORT_LOCKED'
        }), 409

    if 'base_version_no' not in request.form:
        return jsonify({
            'ok': False,
            'error': 'BASE_VERSION_REQUIRED'
        }), 400

    commit_id = str(
        request.form.get('commit_id')
        or uuid.uuid4()
    )

    document = request.files.get('document')

    tmppath, validation, status_code = \
        _ohif_validate_word_upload(
            order,
            document,
            final=False
        )

    if not tmppath:
        return jsonify(validation), status_code

    owned_artifact = None

    try:
        findings, impression, radiologist = \
            extract_docx_sections(tmppath)

        radiologist = str(
            (
                radiologist
                if radiologist
                and radiologist != '____________________'
                else (
                    doctor_user.full_name
                    or doctor_user.username
                    or ''
                )
            )
        ).strip()

        result = commit_report_version(
            db=db,
            Report=Report,
            ReportVersion=ReportVersion,
            report_root=REPORT_DIR,
            order=order,
            patient=order.patient,
            user=doctor_user,
            editor_type='WORD',
            requested_status='DRAFT',
            source_file=tmppath,
            base_version_no=int(
                request.form['base_version_no']
            ),
            commit_id=commit_id,
            findings=findings or '',
            impression=impression or '',
            radiologist=radiologist,
            change_summary='OHIF Word Upload Draft',
        )

        version = result.get('version')

        if version is not None and not result.get('retry'):
            owned_artifact = version.docx_path

        audit_as_user(
            doctor_user,
            'REPORT_VERSION_COMMITTED',
            'order',
            order.id,
            (
                f"version={(version.version_no if version is not None else None)}; "
                "editor=WORD; status=DRAFT; "
                "patient_safety=MATCH"
            )
        )

        db.session.commit()

        payload = _ohif_report_json(order, report)

        payload.update({
            'ok': True,
            'patient_safety': validation['safety'],
            'version_no': (version.version_no if version is not None else None),
            'commit_id': (
                result.get('commit_id')
                or commit_id
            ),
            'editor_type': 'WORD',
            'status': 'DRAFT',
        })

        return jsonify(payload)

    except TransactionalReportCommitError as exc:
        db.session.rollback()

        if owned_artifact:
            try:
                os.unlink(owned_artifact)
            except FileNotFoundError:
                pass

        return jsonify({
            'ok': False,
            'error': getattr(
                exc,
                'code',
                type(exc).__name__
            ),
            'message': str(exc)
        }), 409

    except Exception as exc:
        db.session.rollback()

        if owned_artifact:
            try:
                os.unlink(owned_artifact)
            except FileNotFoundError:
                pass

        return jsonify({
            'ok': False,
            'error': type(exc).__name__,
            'message': str(exc)
        }), 400

    finally:
        if tmppath:
            try:
                os.unlink(tmppath)
            except FileNotFoundError:
                pass

            try:
                os.rmdir(os.path.dirname(tmppath))
            except OSError:
                pass



@app.post('/api/ohif/report/<int:order_id>/word/verify')
@require_ohif_token
def api_ohif_report_word_verify(order_id):
    order = Order.query.get_or_404(order_id)

    context_block = require_valid_ohif_case_context(order)
    if context_block:
        return context_block

    doctor_user, identity_block = \
        require_ohif_doctor_user(order.id)

    if identity_block:
        return identity_block

    try:
        report=get_report(order)
        assert_not_final(report)
        assert_role_allowed(doctor_user,'VERIFY')
        assert_no_foreign_active_lease(
            db=db,
            order_id=order.id,
            user=doctor_user,
        )

    except ReportEditControlError as exc:
        code=getattr(exc,'code',type(exc).__name__)

        try:
            audit(
                'REPORT_EDIT_DENIED',
                'order',
                order.id,
                f'action=VERIFY; editor=WORD; code={code}; user={doctor_user.id}'
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        return jsonify({
            'ok':False,
            'error':code,
        }), 409 if code in (
            'FINAL_REPORT_LOCKED',
            'REPORT_EDIT_LOCKED',
        ) else 403

    demographic_ok, demographic_reason = \
        pacs_demographic_gate(order)

    if not demographic_ok:
        return jsonify({
            'ok': False,
            'error': 'PACS_DEMOGRAPHIC_REVIEW_REQUIRED',
            'reason': demographic_reason
        }), 409

    data = request.get_json(silent=True) or {}

    if 'base_version_no' not in data:
        return jsonify({
            'ok': False,
            'error': 'BASE_VERSION_REQUIRED'
        }), 400

    try:
        from report_commit_core import (
            validate_base_version,
        )

        from onlyoffice_report_bridge import (
            onlyoffice_verify_latest,
        )

        report = get_report(order)

        latest = _rb_latest_report_version(report)

        if latest is None:
            raise ValueError('NO_REPORT_VERSION')

        if str(latest.editor_type or '').upper() != 'WORD':
            return jsonify({
                'ok': False,
                'error': 'LATEST_VERSION_NOT_WORD',
                'version_no': latest.version_no,
                'editor_type': latest.editor_type
            }), 409

        validate_base_version(
            current_version_no=int(latest.version_no),
            base_version_no=int(data['base_version_no']),
        )

        before_count = (
            ReportVersion.query
            .filter_by(report_id=report.id)
            .count()
        )

        version = onlyoffice_verify_latest(
            db=db,
            Report=Report,
            ReportVersion=ReportVersion,
            order=order,
            user=doctor_user,
        )

        after_count = (
            ReportVersion.query
            .filter_by(report_id=report.id)
            .count()
        )

        if after_count != before_count:
            db.session.rollback()
            raise RuntimeError(
                'VERIFY_CREATED_EXTRA_VERSION'
            )

        audit_as_user(
            doctor_user,
            'REPORT_VERSION_VERIFIED',
            'order',
            order.id,
            (
                f'version={version.version_no}; '
                'editor=WORD'
            )
        )

        db.session.commit()

        return jsonify({
            'ok': True,
            'status': 'VERIFIED',
            'version_no': version.version_no,
            'authoritative': True,
            'editor_type': 'WORD'
        })

    except Exception as exc:
        db.session.rollback()

        code = getattr(
            exc,
            'code',
            type(exc).__name__
        )

        status = 409 if code in (
            'REPORT_VERSION_CONFLICT',
            'REPORT_VERSION_DUPLICATE',
            'REPORT_VERIFY_CONFLICT',
        ) else 400

        return jsonify({
            'ok': False,
            'error': code,
            'message': str(exc)
        }), status


@app.post('/api/ohif/report/<int:order_id>/word/finalize')
@require_ohif_token
def api_ohif_report_word_finalize(order_id):
    order = Order.query.get_or_404(order_id)

    context_block = require_valid_ohif_case_context(order)
    if context_block:
        return context_block

    doctor_user, identity_block = \
        require_ohif_doctor_user(order.id)

    if identity_block:
        return identity_block

    try:
        report=get_report(order)
        assert_not_final(report)
        assert_role_allowed(doctor_user,'FINALIZE')
        assert_no_foreign_active_lease(
            db=db,
            order_id=order.id,
            user=doctor_user,
        )

    except ReportEditControlError as exc:
        code=getattr(exc,'code',type(exc).__name__)

        try:
            audit(
                'REPORT_EDIT_DENIED',
                'order',
                order.id,
                f'action=FINALIZE; editor=WORD; code={code}; user={doctor_user.id}'
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        return jsonify({
            'ok':False,
            'error':code,
        }), 409 if code in (
            'FINAL_REPORT_LOCKED',
            'REPORT_EDIT_LOCKED',
        ) else 403

    demographic_ok, demographic_reason = \
        pacs_demographic_gate(order)

    if not demographic_ok:
        return jsonify({
            'ok': False,
            'error': 'PACS_DEMOGRAPHIC_REVIEW_REQUIRED',
            'reason': demographic_reason
        }), 409

    data = request.get_json(silent=True) or {}

    if 'base_version_no' not in data:
        return jsonify({
            'ok': False,
            'error': 'BASE_VERSION_REQUIRED'
        }), 400

    try:
        from report_commit_core import (
            validate_base_version,
        )

        from onlyoffice_report_bridge import (
            onlyoffice_finalize_latest,
        )

        report = get_report(order)

        latest = _rb_latest_report_version(report)

        if latest is None:
            return jsonify({
                'ok': False,
                'error': 'NO_REPORT_VERSION'
            }), 409

        if str(latest.editor_type or '').upper() != 'WORD':
            return jsonify({
                'ok': False,
                'error': 'LATEST_VERSION_NOT_WORD',
                'version_no': latest.version_no,
                'editor_type': latest.editor_type
            }), 409

        if (
            (report.status or '').upper() == 'FINAL'
            or latest.finalized_at is not None
        ):
            return jsonify({
                'ok': False,
                'error': 'FINAL_REPORT_LOCKED'
            }), 409

        if (latest.status or '').upper() != 'VERIFIED':
            return jsonify({
                'ok': False,
                'error': 'LATEST_VERSION_NOT_VERIFIED',
                'version_no': latest.version_no,
                'status': latest.status
            }), 409

        validate_base_version(
            current_version_no=int(latest.version_no),
            base_version_no=int(data['base_version_no']),
        )

        before_count = (
            ReportVersion.query
            .filter_by(report_id=report.id)
            .count()
        )

        version = onlyoffice_finalize_latest(
            db=db,
            Report=Report,
            ReportVersion=ReportVersion,
            order=order,
            user=doctor_user,
        )

        after_count = (
            ReportVersion.query
            .filter_by(report_id=report.id)
            .count()
        )

        if after_count != before_count:
            db.session.rollback()
            raise RuntimeError(
                'FINALIZE_CREATED_EXTRA_VERSION'
            )

        audit_as_user(
            doctor_user,
            'REPORT_FINALIZED',
            'order',
            order.id,
            (
                f'version={version.version_no}; '
                'editor=WORD; '
                'content_immutable=YES'
            )
        )

        db.session.commit()

        queue_final_delivery(order)

        enqueue_event(
            'REPORT_FINALIZED',
            'order',
            order.id,
            {
                'accession': order.accession,
                'version_no': version.version_no,
                'source': 'OHIF_WORD'
            }
        )

        db.session.commit()

        return jsonify({
            'ok': True,
            'status': 'FINALIZED',
            'version_no': version.version_no,
            'authoritative': True,
            'editor_type': 'WORD'
        })

    except Exception as exc:
        db.session.rollback()

        code = getattr(
            exc,
            'code',
            type(exc).__name__
        )

        status = 409 if code in (
            'REPORT_VERSION_CONFLICT',
            'REPORT_VERSION_DUPLICATE',
            'REPORT_FINALIZE_CONFLICT',
        ) else 400

        return jsonify({
            'ok': False,
            'error': code,
            'message': str(exc)
        }), status



