@app.post('/api/ohif/report/<int:order_id>/draft')
@require_ohif_token
def api_ohif_report_draft(order_id):
    import os
    import tempfile
    import uuid

    from report_transaction_writer import (
        commit_report_version,
        TransactionalReportCommitError,
    )

    order = Order.query.get_or_404(order_id)

    context_block = require_valid_ohif_case_context(order)
    if context_block:
        return context_block

    doctor_user, identity_block = \
        require_ohif_doctor_user(order.id)

    if identity_block:
        return identity_block

    try:
        report=get_report(order)
        assert_not_final(report)
        assert_role_allowed(doctor_user,'DRAFT')

        lease_token=str(
            request.headers.get('X-RadBridge-Report-Lease') or
            (request.get_json(silent=True) or {}).get('lease_token') or
            request.form.get('lease_token') or
            ''
        ).strip()

        assert_lease_owner(
            db=db,
            order=order,
            report=report,
            user=doctor_user,
            lease_token=lease_token,
        )

    except ReportEditControlError as exc:
        code=getattr(exc,'code',type(exc).__name__)

        try:
            audit(
                'REPORT_EDIT_DENIED',
                'order',
                order.id,
                f'action=DRAFT; editor=OHIF; code={code}; user={doctor_user.id}'
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        return jsonify({
            'ok':False,
            'error':code,
        }), 409 if code in (
            'FINAL_REPORT_LOCKED',
            'REPORT_EDIT_LOCKED',
        ) else 403

    report = get_report(order)

    if (report.status or '').upper() == 'FINAL':
        return jsonify({
            'ok': False,
            'error': 'FINAL_REPORT_LOCKED'
        }), 409

    data = request.get_json(silent=True) or {}

    if 'base_version_no' not in data:
        return jsonify({
            'ok': False,
            'error': 'BASE_VERSION_REQUIRED'
        }), 400

    findings = str(data.get('findings') or '').strip()
    impression = str(data.get('impression') or '').strip()

    radiologist = str(
        data.get('radiologist')
        or doctor_user.full_name
        or doctor_user.username
        or ''
    ).strip()

    commit_id = str(
        data.get('commit_id')
        or uuid.uuid4()
    )

    old_findings = report.findings
    old_impression = report.impression
    old_radiologist = report.radiologist

    tmp_path = None

    try:
        # Build browser content into a DOCX source artifact
        # without committing legacy Report state.
        report.findings = findings
        report.impression = impression
        report.radiologist = radiologist

        buf = make_docx(order, report)

        fd, tmp_path = tempfile.mkstemp(
            prefix='radbridge-browser-',
            suffix='.docx'
        )

        with os.fdopen(fd, 'wb') as fh:
            fh.write(buf.getvalue())

        # Restore mutable Report fields BEFORE transactional commit.
        report.findings = old_findings
        report.impression = old_impression
        report.radiologist = old_radiologist

        result = commit_report_version(
            db=db,
            Report=Report,
            ReportVersion=ReportVersion,
            report_root=REPORT_DIR,
            order=order,
            patient=order.patient,
            user=doctor_user,
            editor_type='BROWSER',
            requested_status='DRAFT',
            source_file=tmp_path,
            base_version_no=int(data['base_version_no']),
            commit_id=commit_id,
            findings=findings,
            impression=impression,
            radiologist=radiologist,
            change_summary='OHIF Browser Editor Draft',
        )

        version = result.get('version')

        # The unified writer flushes but intentionally does not commit.
        # This HTTP route owns the transaction boundary.
        created_artifact = None

        if (
            version is not None
            and not result.get('retry', False)
        ):
            created_artifact = version.docx_path

        try:
            db.session.commit()
        except Exception:
            db.session.rollback()

            if (
                created_artifact
                and os.path.isfile(created_artifact)
            ):
                try:
                    os.unlink(created_artifact)
                except Exception:
                    pass

            raise

        payload = _ohif_report_json(order, report)

        payload.update({
            'ok': True,
            'version_no': (
                version.version_no
                if version is not None
                else result.get('version_no')
            ),
            'commit_id': result.get('commit_id') or commit_id,
            'editor_type': 'BROWSER',
            'status': 'DRAFT',
        })

        return jsonify(payload)

    except TransactionalReportCommitError as exc:
        db.session.rollback()

        report.findings = old_findings
        report.impression = old_impression
        report.radiologist = old_radiologist

        return jsonify({
            'ok': False,
            'error': getattr(exc, 'code', type(exc).__name__),
            'message': str(exc)
        }), 409

    except Exception as exc:
        db.session.rollback()

        report.findings = old_findings
        report.impression = old_impression
        report.radiologist = old_radiologist

        return jsonify({
            'ok': False,
            'error': type(exc).__name__,
            'message': str(exc)
        }), 400

    finally:
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except FileNotFoundError:
                pass



