# ============================================================
# RADBRIDGE ONLYOFFICE INTEGRATION - PHASE 1
# ============================================================

ONLYOFFICE_INTERNAL_URL = (
    os.getenv('ONLYOFFICE_INTERNAL_URL', 'http://radbridge-onlyoffice')
    .rstrip('/')
)

ONLYOFFICE_RIS_INTERNAL_URL = (
    os.getenv('ONLYOFFICE_RIS_INTERNAL_URL', 'http://ris-web:8000')
    .rstrip('/')
)

ONLYOFFICE_JWT_SECRET = (
    os.getenv('ONLYOFFICE_JWT_SECRET', '').strip()
)

ONLYOFFICE_LINK_TTL = int(
    os.getenv('ONLYOFFICE_LINK_TTL', '7200') or 7200
)


ONLYOFFICE_KEY_REV = (
    os.getenv('ONLYOFFICE_KEY_REV', '1')
    .strip()
    or '1'
)


def _onlyoffice_serializer():
    return URLSafeTimedSerializer(
        app.secret_key,
        salt='radbridge-onlyoffice-v1'
    )


def _onlyoffice_link_token(order_id, purpose):
    return _onlyoffice_serializer().dumps({
        'order_id': int(order_id),
        'purpose': str(purpose)
    })


def _onlyoffice_check_link_token(token, order_id, purpose):
    if not token:
        return False

    try:
        data = _onlyoffice_serializer().loads(
            token,
            max_age=max(60, ONLYOFFICE_LINK_TTL)
        )
    except Exception:
        return False

    return (
        int(data.get('order_id', -1)) == int(order_id)
        and str(data.get('purpose') or '') == str(purpose)
    )


def _onlyoffice_b64url(raw):
    import base64
    return (
        base64.urlsafe_b64encode(raw)
        .decode('ascii')
        .rstrip('=')
    )


def _onlyoffice_jwt_encode(payload):
    import json
    import hashlib

    if not ONLYOFFICE_JWT_SECRET:
        raise RuntimeError('ONLYOFFICE_JWT_SECRET is not configured')

    header = {
        'alg': 'HS256',
        'typ': 'JWT'
    }

    h = _onlyoffice_b64url(
        json.dumps(
            header,
            separators=(',', ':')
        ).encode()
    )

    b = _onlyoffice_b64url(
        json.dumps(
            payload,
            separators=(',', ':'),
            default=str
        ).encode()
    )

    signing_input = f'{h}.{b}'.encode()

    sig = hmac.new(
        ONLYOFFICE_JWT_SECRET.encode(),
        signing_input,
        hashlib.sha256
    ).digest()

    return f'{h}.{b}.{_onlyoffice_b64url(sig)}'


def _onlyoffice_jwt_valid(token):
    import base64
    import hashlib

    if not token or not ONLYOFFICE_JWT_SECRET:
        return False

    try:
        parts = token.split('.')
        if len(parts) != 3:
            return False

        signing_input = f'{parts[0]}.{parts[1]}'.encode()

        expected = hmac.new(
            ONLYOFFICE_JWT_SECRET.encode(),
            signing_input,
            hashlib.sha256
        ).digest()

        pad = '=' * (-len(parts[2]) % 4)

        supplied = base64.urlsafe_b64decode(
            parts[2] + pad
        )

        return hmac.compare_digest(
            supplied,
            expected
        )
    except Exception:
        return False


def _onlyoffice_working_dir():
    path = os.path.join(
        REPORT_DIR,
        '_onlyoffice_working'
    )
    os.makedirs(path, exist_ok=True)
    return path


def _onlyoffice_working_path(order):
    safe_acc = re.sub(
        r'[^A-Za-z0-9_.-]+',
        '_',
        str(order.accession or order.id)
    )

    return os.path.join(
        _onlyoffice_working_dir(),
        f'{safe_acc}.docx'
    )


def _onlyoffice_prepare_document(order, report):
    path = _onlyoffice_working_path(order)

    if os.path.exists(path):
        return path

    # Patient-safety boundary:
    # Never reconstruct a missing ONLYOFFICE working document from a
    # previously committed clinical artifact.  Existing reports must fail
    # closed and require an explicit doctor-controlled action.
    existing_version = (
        ReportVersion.query
        .filter_by(report_id=report.id)
        .order_by(ReportVersion.version_no.desc())
        .first()
    )

    if existing_version is not None:
        raise ValueError('ONLYOFFICE_WORKING_COPY_NOT_FOUND')

    # First document for a report with no committed versions.
    buf = make_docx(order, report)

    with open(path, 'wb') as fh:
        fh.write(buf.getvalue())

    return path


