def api_ohif_onlyoffice_health():
    result = {
        'ok': False,
        'service': 'RadBridge ONLYOFFICE Integration',
        'jwt_configured': bool(ONLYOFFICE_JWT_SECRET),
        'document_server': ONLYOFFICE_INTERNAL_URL
    }

    try:
        r = requests.get(
            ONLYOFFICE_INTERNAL_URL + '/healthcheck',
            timeout=5
        )

        result['onlyoffice_http'] = r.status_code
        result['onlyoffice_body'] = r.text[:100]
        result['ok'] = (
            r.status_code == 200
            and r.text.strip().lower() == 'true'
            and bool(ONLYOFFICE_JWT_SECRET)
        )

    except Exception as exc:
        result['error'] = str(exc)

    return jsonify(result), (200 if result['ok'] else 503)


@app.get('/api/ohif/report/<int:order_id>/onlyoffice/config')
@require_ohif_token
def api_ohif_onlyoffice_config(order_id):
    order = Order.query.get_or_404(order_id)

    context_block = require_valid_ohif_case_context(order)
    if context_block:
        return context_block

    doctor_user, identity_block = \
        require_ohif_doctor_user(order.id)

    if identity_block:
        return identity_block

    report = get_report(order)

    report_status = str(
        report.status or 'DRAFT'
    ).upper()

    is_final = report_status == 'FINAL'

    # RB_VERIFIED_READONLY_CONFIG_V1
    is_locked = report_status in (
        'VERIFIED',
        'FINAL',
    )

    # Locked reports must always use their committed authoritative
    # document. Never require or reconstruct an editable working copy
    # for VERIFIED or FINAL reports.
    authoritative = (
        _rb_authoritative_docx_download(
            order,
            report,
        )
        if is_locked
        else None
    )

    if is_locked:
        if not authoritative:
            return jsonify({
                'ok': False,
                'error': (
                    'FINAL_REPORT_DOCUMENT_NOT_FOUND'
                    if is_final
                    else 'VERIFIED_REPORT_DOCUMENT_NOT_FOUND'
                )
            }), 404

        path = authoritative['path']
    else:
        path = _onlyoffice_prepare_document(
            order,
            report
        )

    doc_token = _onlyoffice_link_token(
        order.id,
        'document'
    )

    callback_token = _onlyoffice_link_token(
        order.id,
        'callback'
    )

    document_url = (
        f'{ONLYOFFICE_RIS_INTERNAL_URL}'
        f'/api/ohif/report/{order.id}/onlyoffice/document'
        f'?token={quote(doc_token)}'
    )

    callback_url = (
        f'{ONLYOFFICE_RIS_INTERNAL_URL}'
        f'/api/ohif/report/{order.id}/onlyoffice/callback'
        f'?token={quote(callback_token)}'
    )

    st = os.stat(path)

    key = (
        f'rb-oo{ONLYOFFICE_KEY_REV}-'
        f'{order.id}-{report.id}-'
        f'{int(st.st_mtime)}-{st.st_size}'
    )

    user_name = (
        doctor_user.full_name
        or doctor_user.username
        or f'Doctor {doctor_user.id}'
    )

    if is_final:
        document_version_no = int(
            authoritative['version_no']
        )
        document_status = 'FINAL'
    elif is_locked:
        locked_version = _rb_latest_report_version(
            report
        )

        if not locked_version:
            return jsonify({
                'ok': False,
                'error': 'VERIFIED_REPORT_VERSION_NOT_FOUND'
            }), 404

        document_version_no = int(
            locked_version.version_no
        )
        document_status = 'VERIFIED'
    else:
        document_version_no = _next_report_version(
            report
        )
        document_status = 'DRAFT'

    config = {
        'document': {
            'fileType': 'docx',
            'key': key[:128],
            'title': build_report_filename(
                order,
                document_version_no,
                document_status,
                'docx'
            ),
            'url': document_url,
            'permissions': {
                'edit': not is_locked,
                'download': True,
                'print': True
            }
        },
        'documentType': 'word',
        'editorConfig': {
            'callbackUrl': callback_url,
            'lang': 'en',
            'mode': (
                'view'
                if is_locked
                else 'edit'
            ),
            'user': {
                'id': str(doctor_user.id),
                'name': user_name
            },
            'customization': {
                # RB_ONLYOFFICE_AUTOSAVE_WORKING_COPY_V1
                'autosave': not is_locked,
                'forcesave': not is_locked,
                'compactHeader': False
            }
        }
    }

    config['token'] = _onlyoffice_jwt_encode(
        config
    )

    audit_as_user(
        doctor_user,
        'ONLYOFFICE_EDITOR_OPENED',
        'order',
        order.id,
        f'key={key[:128]}'
    )

    db.session.commit()

    latest_version = _rb_latest_report_version(report)

    return jsonify({
        'ok': True,
        'config': config,
        'base_version_no': (
            int(latest_version.version_no)
            if latest_version
            else 0
        ),
        'report_status': (
            'FINAL'
            if is_final
            else (
                str(
                    latest_version.status
                    or 'DRAFT'
                ).upper()
                if latest_version
                else 'DRAFT'
            )
        ),
        'api_path': (
            '/onlyoffice/'
            'web-apps/apps/api/documents/api.js'
        )
    })



def _onlyoffice_forcesave_ack_path(order_id):
    return os.path.join(
        _onlyoffice_working_dir(),
        f'order-{int(order_id)}.forcesave-ack'
    )


def _onlyoffice_write_forcesave_ack(order_id, nonce):
    nonce = str(nonce or '').strip()

    if not nonce:
        return

    path = _onlyoffice_forcesave_ack_path(order_id)
    tmp = path + '.tmp'

    with open(tmp, 'w', encoding='utf-8') as fh:
        fh.write(nonce)

    os.replace(tmp, path)


def _onlyoffice_read_forcesave_ack(order_id):
    path = _onlyoffice_forcesave_ack_path(order_id)

    try:
        with open(path, 'r', encoding='utf-8') as fh:
            return fh.read().strip()
    except FileNotFoundError:
        return ''


@app.post('/api/ohif/report/<int:order_id>/onlyoffice/forcesave')
@require_ohif_token
def api_ohif_onlyoffice_forcesave(order_id):
    import time

    order = Order.query.get_or_404(order_id)

    context_block = require_valid_ohif_case_context(order)
    if context_block:
        return context_block

    doctor_user, identity_block = \
        require_ohif_doctor_user(order.id)

    if identity_block:
        return identity_block

    report = get_report(order)

    try:
        assert_not_final(report)

        assert_role_allowed(
            doctor_user,
            'DRAFT'
        )

        lease_token = str(
            request.headers.get(
                'X-RadBridge-Report-Lease'
            ) or ''
        ).strip()

        assert_lease_owner(
            db=db,
            order=order,
            report=report,
            user=doctor_user,
            lease_token=lease_token,
        )

    except ReportEditControlError as exc:
        code = getattr(
            exc,
            'code',
            type(exc).__name__
        )

        return jsonify({
            'ok': False,
            'error': code,
        }), 409 if code in (
            'FINAL_REPORT_LOCKED',
            'REPORT_EDIT_LOCKED',
        ) else 403

    path = _onlyoffice_working_path(order)

    if not path or not os.path.isfile(path):
        return jsonify({
            'ok': False,
            'error': 'ONLYOFFICE_WORKING_COPY_NOT_FOUND',
        }), 409

    # RB_ONLYOFFICE_DIRTY_FORCESAVE_V1
    forcesave_data = request.get_json(silent=True) or {}

    key = str(
        forcesave_data.get('document_key') or ''
    ).strip()

    document_dirty = bool(
        forcesave_data.get('document_dirty', False)
    )

    if not key:
        return jsonify({
            'ok': False,
            'error': 'ONLYOFFICE_DOCUMENT_KEY_REQUIRED',
        }), 400

    import uuid

    nonce = str(uuid.uuid4())

    command = {
        'c': 'forcesave',
        'key': key,
        'userdata': nonce,
    }

    try:
        token = _onlyoffice_jwt_encode(command)

        r = requests.post(
            ONLYOFFICE_INTERNAL_URL
            + '/coauthoring/CommandService.ashx',
            json=command,
            headers={
                'Authorization': f'Bearer {token}'
            },
            timeout=10,
        )

        r.raise_for_status()

        result = r.json() or {}

        onlyoffice_error = int(
            result.get('error') or 0
        )

        # A dirty browser must never convert error 4 into
        # a successful clinical save. Retry briefly, then require
        # a real callback acknowledgement.
        if onlyoffice_error == 4 and document_dirty:
            for _attempt in range(4):
                time.sleep(0.75)

                r = requests.post(
                    ONLYOFFICE_INTERNAL_URL
                    + '/coauthoring/CommandService.ashx',
                    json=command,
                    headers={
                        'Authorization': f'Bearer {token}'
                    },
                    timeout=10,
                )

                r.raise_for_status()
                result = r.json() or {}
                onlyoffice_error = int(
                    result.get('error') or 0
                )

                if onlyoffice_error != 4:
                    break

        if onlyoffice_error == 4:
            if document_dirty:
                return jsonify({
                    'ok': False,
                    'forcesaved': False,
                    'error': (
                        'ONLYOFFICE_CHANGES_NOT_SYNCHRONIZED'
                    ),
                    'message': (
                        'The document is still synchronizing. '
                        'Wait a moment and save again.'
                    ),
                    'onlyoffice_error': 4,
                }), 409

            return jsonify({
                'ok': True,
                'forcesaved': True,
                'no_changes': True,
                'onlyoffice_error': 4,
            })

        if onlyoffice_error != 0:
            return jsonify({
                'ok': False,
                'error': 'ONLYOFFICE_FORCESAVE_REJECTED',
                'onlyoffice_error': onlyoffice_error,
            }), 409

        deadline = time.monotonic() + 12.0

        while time.monotonic() < deadline:
            time.sleep(0.25)

            if (
                _onlyoffice_read_forcesave_ack(
                    order.id
                )
                == nonce
            ):
                return jsonify({
                    'ok': True,
                    'forcesaved': True,
                })

        return jsonify({
            'ok': False,
            'error': 'ONLYOFFICE_FORCESAVE_CALLBACK_TIMEOUT',
        }), 504

    except Exception as exc:
        return jsonify({
            'ok': False,
            'error': 'ONLYOFFICE_FORCESAVE_FAILED',
            'message': str(exc),
        }), 502


@app.get('/api/ohif/report/<int:order_id>/onlyoffice/document')
def api_ohif_onlyoffice_document(order_id):
    order = Order.query.get_or_404(order_id)

    token = str(
        request.args.get('token') or ''
    )

    if not _onlyoffice_check_link_token(
        token,
        order.id,
        'document'
    ):
        return jsonify({
            'ok': False,
            'error': 'ONLYOFFICE_DOCUMENT_TOKEN_INVALID'
        }), 403

    report = get_report(order)

    report_status = str(
        report.status or 'DRAFT'
    ).upper()

    is_final = report_status == 'FINAL'
    is_locked = report_status in (
        'VERIFIED',
        'FINAL',
    )

    # VERIFIED and FINAL documents are immutable committed artifacts.
    # Serve their authoritative version and never require or recreate
    # an editable ONLYOFFICE working copy.
    if is_locked:
        authoritative = (
            _rb_authoritative_docx_download(
                order,
                report,
            )
        )

        if not authoritative:
            return jsonify({
                'ok': False,
                'error': (
                    'FINAL_REPORT_DOCUMENT_NOT_FOUND'
                    if is_final
                    else 'VERIFIED_REPORT_DOCUMENT_NOT_FOUND'
                )
            }), 404

        path = authoritative['path']
    else:
        path = _onlyoffice_prepare_document(
            order,
            report
        )

    return send_file(
        path,
        as_attachment=False,
        download_name=os.path.basename(path),
        mimetype=(
            'application/vnd.openxmlformats-officedocument.'
            'wordprocessingml.document'
        )
    )




# ============================================================
# RadBridge Unified Clinical Report Versioning
# ONLYOFFICE explicit commit layer.
#
# IMPORTANT:
# ONLYOFFICE callback remains WORKING COPY ONLY.
# Clinical versions are created only by explicit doctor action.
# ============================================================

def _rb_latest_report_version(report):
    return (
        ReportVersion.query
        .filter_by(report_id=report.id)
        .order_by(ReportVersion.version_no.desc())
        .first()
    )


def _rb_authoritative_docx_download(order, report):
    version = _rb_latest_report_version(report)

    if not version:
        return None

    path = version.docx_path or version.source_path

    if not path or not os.path.isfile(path):
        return None

    status = (
        'FINAL'
        if (report.status or '').upper() == 'FINAL'
        else (version.status or report.status or 'REPORT').upper()
    )

    return {
        'path': path,
        'version_no': version.version_no,
        'status': status,
    }


def _rb_latest_authoritative_version(report):
    return (
        ReportVersion.query
        .filter(
            ReportVersion.report_id == report.id,
            ReportVersion.status.in_([
                'VERIFIED',
                'SECOND_VERIFIED',
                'FINALIZED'
            ])
        )
        .order_by(ReportVersion.version_no.desc())
        .first()
    )


def _rb_onlyoffice_working_bytes(order):
    path = _onlyoffice_working_path(order)

    if not path or not os.path.isfile(path):
        raise ValueError('ONLYOFFICE_WORKING_COPY_NOT_FOUND')

    with open(path, 'rb') as fh:
        return path, fh.read()


def _rb_commit_onlyoffice_version(
    order,
    doctor_user,
    requested_status,
    base_version_no,
):
    """
    Compatibility bridge for existing ONLYOFFICE routes.

    ONLYOFFICE owns no clinical report storage.

    DRAFT:
        working copy -> unified commit writer

    VERIFIED:
        verify the existing latest DRAFT only
        no new ReportVersion

    FINAL / FINALIZED:
        finalize the existing latest VERIFIED only
        no new ReportVersion

    The ONLYOFFICE callback remains working-copy only.
    """

    import uuid

    from report_commit_core import (
        validate_base_version,
    )

    from report_version_safety import (
        validate_docx_bytes,
    )

    from onlyoffice_report_bridge import (
        onlyoffice_save_draft,
        onlyoffice_verify_latest,
        onlyoffice_finalize_latest,
    )

    requested_status = str(
        requested_status or ''
    ).strip().upper()

    if requested_status not in (
        'DRAFT',
        'VERIFIED',
        'FINAL',
        'FINALIZED',
    ):
        raise ValueError(
            'INVALID_ONLYOFFICE_COMMIT_STATUS'
        )

    report = get_report(order)

    if (
        (report.status or '').upper()
        == 'FINAL'
    ):
        raise ValueError(
            'FINAL_REPORT_LOCKED'
        )

    working_path, raw = \
        _rb_onlyoffice_working_bytes(order)

    # --------------------------------------------------
    # Structural DOCX validation.
    # --------------------------------------------------

    meta = validate_docx_bytes(raw)

    incoming_hash = str(
        meta['sha256'] or ''
    ).strip().lower()

    # --------------------------------------------------
    # Patient / Accession identity gate.
    # --------------------------------------------------

    safety = validate_report_patient_file(
        order,
        working_path,
        '.docx'
    )

    if safety.get('result') != 'MATCH':
        raise ValueError(
            'REPORT_PATIENT_IDENTITY_MISMATCH'
        )

    # --------------------------------------------------
    # Latest version is re-read before explicit action.
    # --------------------------------------------------

    latest = _rb_latest_report_version(
        report
    )

    current_no = (
        int(latest.version_no)
        if latest
        else 0
    )

    # DRAFT idempotency and stale-base ordering is owned by
    # commit_report_version() under the Report row lock:
    #
    #   existing commit_id -> return existing version
    #   otherwise          -> validate base version
    #
    # Running the base gate here for DRAFT would reject a
    # legitimate network retry before the idempotency lookup.
    #
    # VERIFY / FINALIZE remain non-content state transitions
    # and keep their helper-level base-version protection.
    if requested_status != 'DRAFT':
        validate_base_version(
            current_version_no=current_no,
            base_version_no=base_version_no,
        )

    current_hash = (
        str(latest.sha256 or '')
        .strip()
        .lower()
        if latest
        else ''
    )

    # --------------------------------------------------
    # DRAFT = the only content-creating action.
    # --------------------------------------------------

    # RB_DRAFT_SERIES_POLICY_V1
    # Repeating the latest identical DRAFT is an idempotent
    # success and must not allocate another version.
    if (
        requested_status == 'DRAFT'
        and latest is not None
        and str(latest.status or '').upper() == 'DRAFT'
        and incoming_hash == current_hash
    ):
        return latest

    if requested_status == 'DRAFT':
        try:
            draft_limit = max(
                1,
                int(os.getenv(
                    'REPORT_MAX_DRAFT_VERSIONS',
                    '10'
                ))
            )
        except (TypeError, ValueError):
            draft_limit = 10

        draft_count = (
            ReportVersion.query
            .filter_by(
                report_id=report.id,
                status='DRAFT'
            )
            .count()
        )

        if draft_count >= draft_limit:
            limit_error = RuntimeError(
                'DRAFT_VERSION_LIMIT_REACHED'
            )
            limit_error.code = (
                'DRAFT_VERSION_LIMIT_REACHED'
            )
            raise limit_error

    if requested_status == 'DRAFT':

        findings, impression, radiologist = \
            extract_docx_sections(
                working_path
            )

        #
        # Stable commit UUID:
        #
        # If the browser retries the same save request
        # with the same base version + same document,
        # the DB idempotency constraint resolves it to
        # the same clinical version.
        #

        commit_key = (
            'radbridge-onlyoffice:'
            f'order={order.id}:'
            f'base={int(base_version_no)}:'
            f'sha256={incoming_hash}'
        )

        commit_id = str(
            uuid.uuid5(
                uuid.NAMESPACE_URL,
                commit_key
            )
        )

        result = onlyoffice_save_draft(
            db=db,
            Report=Report,
            ReportVersion=ReportVersion,
            report_root=REPORT_DIR,
            order=order,
            patient=order.patient,
            user=doctor_user,
            source_file=working_path,
            base_version_no=base_version_no,
            commit_id=commit_id,
            findings=findings or '',
            impression=impression or '',
            radiologist=(
                radiologist
                if radiologist
                and radiologist
                != '____________________'
                else (
                    doctor_user.full_name
                    or doctor_user.username
                    or 'Unknown'
                )
            ),
        )

        version = result['version']

        try:
            audit_as_user(
                doctor_user,
                (
                    'REPORT_VERSION_RETRY'
                    if result.get('retry')
                    else 'REPORT_VERSION_COMMITTED'
                ),
                'order',
                order.id,
                (
                    f'version={version.version_no}; '
                    'status=DRAFT; '
                    'editor=ONLYOFFICE; '
                    f'commit_id={commit_id}; '
                    f'sha256={incoming_hash[:12]}'
                )
            )

            db.session.commit()

        except Exception:

            artifact = (
                getattr(
                    version,
                    'source_path',
                    None
                )
                if not result.get('retry')
                else None
            )

            db.session.rollback()

            #
            # If DB commit failed after the unified
            # writer published the new immutable file,
            # remove only that uncommitted artifact.
            #

            if (
                artifact
                and
                os.path.isfile(artifact)
            ):
                try:
                    os.unlink(artifact)
                except Exception:
                    pass

            raise

        return version

    # --------------------------------------------------
    # VERIFY / FINALIZE never create content versions.
    # --------------------------------------------------

    if latest is None:
        raise ValueError(
            'NO_REPORT_VERSION'
        )

    #
    # Clinical protection:
    #
    # The working document must exactly equal the latest
    # committed version before Verify or Finalize.
    #
    # Otherwise the doctor must Save Draft first.
    #

    if (
        not current_hash
        or incoming_hash != current_hash
    ):
        raise ValueError(
            'ONLYOFFICE_CHANGES_NOT_SAVED_AS_DRAFT'
        )

    if requested_status == 'VERIFIED':

        before_count = (
            ReportVersion.query
            .filter_by(
                report_id=report.id
            )
            .count()
        )

        version = onlyoffice_verify_latest(
            db=db,
            Report=Report,
            ReportVersion=ReportVersion,
            order=order,
            user=doctor_user,
        )

        after_count = (
            ReportVersion.query
            .filter_by(
                report_id=report.id
            )
            .count()
        )

        if after_count != before_count:
            db.session.rollback()

            raise RuntimeError(
                'VERIFY_CREATED_EXTRA_VERSION'
            )

        audit_as_user(
            doctor_user,
            'REPORT_VERSION_VERIFIED',
            'order',
            order.id,
            (
                f'version={version.version_no}; '
                'editor=ONLYOFFICE'
            )
        )

        db.session.commit()

        return version

    # --------------------------------------------------
    # FINAL / FINALIZED
    # --------------------------------------------------

    before_count = (
        ReportVersion.query
        .filter_by(
            report_id=report.id
        )
        .count()
    )

    version = onlyoffice_finalize_latest(
        db=db,
        Report=Report,
        ReportVersion=ReportVersion,
        order=order,
        user=doctor_user,
    )

    after_count = (
        ReportVersion.query
        .filter_by(
            report_id=report.id
        )
        .count()
    )

    if after_count != before_count:
        db.session.rollback()

        raise RuntimeError(
            'FINALIZE_CREATED_EXTRA_VERSION'
        )

    audit_as_user(
        doctor_user,
        'REPORT_VERSION_FINALIZED',
        'order',
        order.id,
        (
            f'version={version.version_no}; '
            'editor=ONLYOFFICE'
        )
    )

    db.session.commit()

    return version


@app.post(
    '/api/ohif/report/<int:order_id>/onlyoffice/commit-draft'
)
@require_ohif_token
def api_ohif_onlyoffice_commit_draft(order_id):
    order = Order.query.get_or_404(order_id)

    context_block = require_valid_ohif_case_context(order)
    if context_block:
        return context_block

    doctor_user, identity_block = \
        require_ohif_doctor_user(order.id)

    if identity_block:
        return identity_block

    try:
        report=get_report(order)

        assert_not_final(report)

        assert_role_allowed(
            doctor_user,
            'DRAFT'
        )

        lease_token=str(
            request.headers.get('X-RadBridge-Report-Lease') or
            (request.get_json(silent=True) or {}).get('lease_token') or
            request.form.get('lease_token') or
            ''
        ).strip()

        assert_lease_owner(
            db=db,
            order=order,
            report=report,
            user=doctor_user,
            lease_token=lease_token,
        )

    except ReportEditControlError as exc:

        code=getattr(
            exc,
            'code',
            type(exc).__name__
        )

        try:
            audit(
                'REPORT_EDIT_DENIED',
                'order',
                order.id,
                f'action=DRAFT; editor=ONLYOFFICE; code={code}; user={doctor_user.id}'
            )

            db.session.commit()

        except Exception:
            db.session.rollback()

        return jsonify({
            'ok':False,
            'error':code,
        }), 409 if code in (
            'FINAL_REPORT_LOCKED',
            'REPORT_EDIT_LOCKED',
        ) else 403

    data = request.get_json(silent=True) or {}

    if 'base_version_no' not in data:
        return jsonify({
            'ok': False,
            'error': 'BASE_VERSION_REQUIRED'
        }), 400

    try:
        version = _rb_commit_onlyoffice_version(
            order,
            doctor_user,
            'DRAFT',
            int(data['base_version_no'])
        )

        return jsonify({
            'ok': True,
            'status': 'DRAFT',
            'version_no': version.version_no,
            'editor_type': 'ONLYOFFICE'
        })

    except Exception as exc:
        db.session.rollback()

        code = getattr(
            exc,
            'code',
            None
        )

        if not code:
            message_code = str(exc).strip()

            if message_code == 'FINAL_REPORT_LOCKED':
                code = message_code
            else:
                code = type(exc).__name__

        status = 409 if code in (
            'REPORT_VERSION_CONFLICT',
            'REPORT_VERSION_DUPLICATE',
            'FINAL_REPORT_LOCKED'
            'DRAFT_VERSION_LIMIT_REACHED',
        ) else 400

        return jsonify({
            'ok': False,
            'error': code,
            'message': str(exc)
        }), status


@app.post(
    '/api/ohif/report/<int:order_id>/onlyoffice/verify'
)
@require_ohif_token
def api_ohif_onlyoffice_verify(order_id):
    order = Order.query.get_or_404(order_id)

    context_block = require_valid_ohif_case_context(order)
    if context_block:
        return context_block

    doctor_user, identity_block = \
        require_ohif_doctor_user(order.id)

    if identity_block:
        return identity_block

    try:
        report=get_report(order)

        assert_not_final(report)

        assert_role_allowed(
            doctor_user,
            'VERIFY'
        )
        assert_no_foreign_active_lease(
            db=db,
            order_id=order.id,
            user=doctor_user,
        )

    except ReportEditControlError as exc:

        code=getattr(
            exc,
            'code',
            type(exc).__name__
        )

        try:
            audit(
                'REPORT_EDIT_DENIED',
                'order',
                order.id,
                f'action=VERIFY; editor=ONLYOFFICE; code={code}; user={doctor_user.id}'
            )

            db.session.commit()

        except Exception:
            db.session.rollback()

        return jsonify({
            'ok':False,
            'error':code,
        }), 409 if code in (
            'FINAL_REPORT_LOCKED',
            'REPORT_EDIT_LOCKED',
        ) else 403

    demographic_ok, demographic_reason = \
        pacs_demographic_gate(order)

    if not demographic_ok:
        return jsonify({
            'ok': False,
            'error': 'PACS_DEMOGRAPHIC_REVIEW_REQUIRED',
            'reason': demographic_reason
        }), 409

    data = request.get_json(silent=True) or {}

    if 'base_version_no' not in data:
        return jsonify({
            'ok': False,
            'error': 'BASE_VERSION_REQUIRED'
        }), 400

    try:
        version = _rb_commit_onlyoffice_version(
            order,
            doctor_user,
            'VERIFIED',
            int(data['base_version_no'])
        )

        return jsonify({
            'ok': True,
            'status': 'VERIFIED',
            'version_no': version.version_no,
            'authoritative': True,
            'editor_type': 'ONLYOFFICE'
        })

    except Exception as exc:
        db.session.rollback()

        code = getattr(
            exc,
            'code',
            type(exc).__name__
        )

        status = 409 if code in (
            'REPORT_VERSION_CONFLICT',
            'REPORT_VERSION_DUPLICATE'
        ) else 400

        return jsonify({
            'ok': False,
            'error': code,
            'message': str(exc)
        }), status


@app.post('/api/ohif/report/<int:order_id>/onlyoffice/finalize')
@require_ohif_token
def api_ohif_onlyoffice_finalize(order_id):
    order = Order.query.get_or_404(order_id)

    context_block = require_valid_ohif_case_context(order)
    if context_block:
        return context_block

    doctor_user, identity_block = require_ohif_doctor_user(order.id)
    if identity_block:
        return identity_block

    try:
        report=get_report(order)

        assert_not_final(report)

        assert_role_allowed(
            doctor_user,
            'FINALIZE'
        )
        assert_no_foreign_active_lease(
            db=db,
            order_id=order.id,
            user=doctor_user,
        )

    except ReportEditControlError as exc:

        code=getattr(
            exc,
            'code',
            type(exc).__name__
        )

        try:
            audit(
                'REPORT_EDIT_DENIED',
                'order',
                order.id,
                f'action=FINALIZE; editor=ONLYOFFICE; code={code}; user={doctor_user.id}'
            )

            db.session.commit()

        except Exception:
            db.session.rollback()

        return jsonify({
            'ok':False,
            'error':code,
        }), 409 if code in (
            'FINAL_REPORT_LOCKED',
            'REPORT_EDIT_LOCKED',
        ) else 403

    gate_ok, gate_reason = pacs_demographic_gate(order)
    if not gate_ok:
        return jsonify({
            'ok': False,
            'error': gate_reason,
        }), 409

    report = get_report(order)

    from onlyoffice_report_bridge import onlyoffice_finalize_latest

    try:
        version = onlyoffice_finalize_latest(
            db=db,
            Report=Report,
            ReportVersion=ReportVersion,
            order=order,
            user=doctor_user,
        )

        db.session.commit()

        try:
            audit(
                'REPORT_FINALIZED',
                'report',
                report.id,
                f'ONLYOFFICE version={version.version_no}'
            )
            db.session.commit()
        except Exception:
            db.session.rollback()

        return jsonify({
            'ok': True,
            'version_no': int(version.version_no),
            'status': 'FINALIZED',
        })

    except Exception as exc:
        db.session.rollback()

        code = getattr(exc, 'code', '') or type(exc).__name__

        status = 409 if code in (
            'FINAL_REPORT_LOCKED',
            'FINAL_REPORT_REQUIRES_ADDENDUM',
            'FINALIZE_CONFLICT',
            'REPORT_VERSION_CONFLICT',
            'NO_REPORT_VERSION',
        ) else 400

        return jsonify({
            'ok': False,
            'error': code,
        }), status

@app.post('/api/ohif/report/<int:order_id>/onlyoffice/callback')
def api_ohif_onlyoffice_callback(order_id):
    order = Order.query.get_or_404(order_id)

    link_token = str(
        request.args.get('token') or ''
    )

    if not _onlyoffice_check_link_token(
        link_token,
        order.id,
        'callback'
    ):
        return jsonify({'error': 1}), 403

    auth = str(
        request.headers.get('Authorization') or ''
    ).strip()

    jwt_token = (
        auth[7:].strip()
        if auth.lower().startswith('bearer ')
        else ''
    )

    if not _onlyoffice_jwt_valid(jwt_token):
        audit(
            'ONLYOFFICE_CALLBACK_REJECTED',
            'order',
            order.id,
            'invalid JWT'
        )
        db.session.commit()
        return jsonify({'error': 1}), 403

    data = request.get_json(silent=True) or {}
    status = int(data.get('status') or 0)

    # 1 = editing, 4 = closed without changes
    if status in (1, 4):
        return jsonify({'error': 0})

    # 2 = ready for save
    # 6 = forcesave
    if status not in (2, 6):
        return jsonify({'error': 0})

    edited_url = str(
        data.get('url') or ''
    ).strip()

    if not edited_url:
        return jsonify({'error': 1})

    try:
        r = requests.get(
            edited_url,
            timeout=60
        )
        r.raise_for_status()

        from werkzeug.datastructures import FileStorage
        import io as _io

        fs = FileStorage(
            stream=_io.BytesIO(r.content),
            filename='onlyoffice.docx',
            content_type=(
                'application/vnd.openxmlformats-officedocument.'
                'wordprocessingml.document'
            )
        )

        tmppath, validation, code = \
            _ohif_validate_word_upload(
                order,
                fs,
                final=False
            )

        if not tmppath:
            audit(
                'ONLYOFFICE_SAVE_BLOCKED',
                'order',
                order.id,
                str(validation)
            )
            db.session.commit()
            return jsonify({'error': 1}), 409

        target = _onlyoffice_working_path(order)
        shutil.copy2(tmppath, target)

        audit(
            'ONLYOFFICE_WORKING_COPY_SAVED',
            'order',
            order.id,
            (
                f'status={status}; '
                f'patient_safety=MATCH; '
                f'bytes={os.path.getsize(target)}'
            )
        )

        db.session.commit()

        if status == 6:
            _onlyoffice_write_forcesave_ack(
                order.id,
                data.get('userdata')
            )

        return jsonify({'error': 0})

    except Exception as exc:
        db.session.rollback()
        app.logger.exception(
            'ONLYOFFICE_CALLBACK_FAILED order=%s',
            order.id
        )

        return jsonify({
            'error': 1,
            'message': str(exc)
        }), 500


