# ===== RADBRIDGE VOICE BOOKING API V5.37 =====

def _voice_api_authorized():
    expected = (os.getenv("VOICE_API_TOKEN") or "").strip()
    auth = (request.headers.get("Authorization") or "").strip()

    return bool(
        expected and
        auth == "Bearer " + expected
    )


def _voice_api_unauthorized():
    return jsonify(
        ok=False,
        error="VOICE_API_UNAUTHORIZED"
    ), 401


def voice_api_branches():
    if not _voice_api_authorized():
        return _voice_api_unauthorized()

    rows = (
        Branch.query
        .filter_by(active=True)
        .order_by(Branch.name)
        .all()
    )

    return jsonify(
        ok=True,
        branches=[
            {
                "id": x.id,
                "name": x.name,
                "working_hours": (
                    lambda devices: (
                        (
                            min(
                                str(d.workday_start or "08:00")
                                for d in devices
                            )
                            + " - " +
                            max(
                                str(d.workday_end or "22:00")
                                for d in devices
                            )
                        )
                        if devices
                        else None
                    )
                )(
                    Device.query.filter_by(
                        branch_id=x.id,
                        active=True
                    ).all()
                ),
            }
            for x in rows
        ]
    )


def voice_api_procedures():
    if not _voice_api_authorized():
        return _voice_api_unauthorized()

    branch_id = request.args.get("branch_id", type=int)
    search = (request.args.get("q") or "").strip().lower()

    rows = (
        Procedure.query
        .filter_by(active=True)
        .order_by(
            Procedure.modality,
            Procedure.name
        )
        .all()
    )

    if branch_id:
        rows = [
            x for x in rows
            if procedure_available_in_branch(
                x.id,
                branch_id
            )
        ]

    if search:
        def matches(x):
            haystack = " ".join([
                str(x.code or ""),
                str(x.name or ""),
                str(x.name_ar or ""),
                str(x.modality or ""),
                str(x.body_part or ""),
            ]).lower()

            return search in haystack

        rows = [x for x in rows if matches(x)]

    return jsonify(
        ok=True,
        procedures=[
            {
                "id": x.id,
                "code": x.code,
                "name": x.name,
                "name_ar": x.name_ar,
                "modality": x.modality,
                "body_part": x.body_part,
                "duration_min": x.duration_min,
                "base_price": x.base_price,
                "contrast": x.contrast,
            }
            for x in rows[:100]
        ]
    )


