@app.route("/api/voice/patient", methods=["POST"])
def voice_api_patient_create():
    if not _voice_api_authorized():
        return _voice_api_unauthorized()

    data = request.get_json(silent=True) or {}

    name = str(data.get("name") or "").strip()
    phone = str(data.get("phone") or "").strip()

    if not name:
        return jsonify(
            ok=False,
            error="PATIENT_NAME_REQUIRED"
        ), 400

    if not phone:
        return jsonify(
            ok=False,
            error="PHONE_REQUIRED"
        ), 400

    existing = patient_by_phone(phone)

    if existing:
        return jsonify(
            ok=True,
            created=False,
            duplicate=True,
            patient={
                "id": existing.id,
                "patient_id": existing.patient_id,
                "name": existing.name,
                "phone": existing.phone,
            }
        )

    patient = Patient(
        patient_id="TMP-" + secrets.token_hex(8),
        name=name,
        dob=str(data.get("dob") or "")
            .replace("-", ""),
        sex=str(data.get("sex") or "").strip(),
        phone=phone,
        national_id=str(
            data.get("national_id") or ""
        ).strip(),
        address=str(
            data.get("address") or ""
        ).strip(),
        email=str(
            data.get("email") or ""
        ).strip(),
        worklist_name=arabic_to_latin_name(name),
    )

    db.session.add(patient)
    db.session.flush()

    patient.patient_id = generate_patient_id(patient)

    audit(
        "PATIENT_CREATE_FROM_VOICE",
        "patient",
        patient.id,
        patient.patient_id
    )

    db.session.commit()

    return jsonify(
        ok=True,
        created=True,
        patient={
            "id": patient.id,
            "patient_id": patient.patient_id,
            "name": patient.name,
            "phone": patient.phone,
        }
    ), 201



