@app.route("/api/voice/inquiry", methods=["GET"])
def voice_api_inquiry():

    if not _voice_api_authorized():
        return _voice_api_unauthorized()

    phone = (request.args.get("phone") or "").strip()

    if not phone:
        return jsonify(
            ok=False,
            error="PHONE_REQUIRED"
        ), 400

    patient = patient_by_phone(phone)

    if not patient:
        return jsonify(
            ok=True,
            found=False,
            patient=None,
            orders=[]
        )

    orders = (
        Order.query
        .filter_by(patient_id=patient.id)
        .order_by(
            Order.scheduled.desc(),
            Order.id.desc()
        )
        .limit(10)
        .all()
    )

    result = []

    for order in orders:

        report = (
            Report.query
            .filter_by(order_id=order.id)
            .order_by(Report.id.desc())
            .first()
        )

        exam_status = (
            order.exam_status or
            order.status or
            "UNKNOWN"
        ).upper()

        pacs_status = (
            order.pacs_status or
            "WAITING"
        ).upper()

        report_status = (
            report.status
            if report else "UNREPORTED"
        )

        report_status = (
            report_status or "UNREPORTED"
        ).upper()

        exam_complete = bool(
            order.exam_completed_at
            or exam_status in (
                "EXAM_COMPLETED",
                "COMPLETED",
                "DONE",
                "FINAL",
                "REPORTED"
            )
        )

        images_received = bool(
            (order.pacs_image_count or 0) > 0
            or pacs_status in (
                "RECEIVED",
                "COMPLETE",
                "COMPLETED"
            )
        )

        report_ready = bool(
            report and
            report_status == "FINAL"
        )

        result.append({
            "order_id": order.id,
            "accession": order.accession,

            "procedure": order.procedure,
            "modality": order.modality,

            "scheduled": (
                order.scheduled.isoformat(sep=" ")
                if order.scheduled else None
            ),

            "branch": (
                order.branch.name
                if order.branch else None
            ),

            "exam_status": exam_status,

            "exam_complete": exam_complete,

            "exam_completed_at": (
                order.exam_completed_at.isoformat(sep=" ")
                if order.exam_completed_at else None
            ),

            "pacs_status": pacs_status,

            "pacs_image_count":
                order.pacs_image_count or 0,

            "images_received": images_received,

            "report_status": report_status,

            "report_ready": report_ready,

            "report_finalized_at": (
                report.finalized_at.isoformat(sep=" ")
                if report and report.finalized_at
                else None
            ),

            "report_delivered":
                bool(order.report_delivered),

            "images_delivered":
                bool(order.images_delivered)
        })

    return jsonify(
        ok=True,
        found=True,
        patient={
            "id": patient.id,
            "patient_id": patient.patient_id,
            "name": patient.name,
            "phone": patient.phone
        },
        orders=result
    )


def voice_api_slots():
    if not _voice_api_authorized():
        return _voice_api_unauthorized()

    branch_id = request.args.get(
        "branch_id",
        type=int
    )

    procedure_id = request.args.get(
        "procedure_id",
        type=int
    )

    date_text = (
        request.args.get("date") or ""
    ).strip()

    if not all([
        branch_id,
        procedure_id,
        date_text
    ]):
        return jsonify(
            ok=False,
            error="BRANCH_PROCEDURE_DATE_REQUIRED"
        ), 400

    try:
        selected_date = datetime.fromisoformat(
            date_text
        ).date()
    except ValueError:
        return jsonify(
            ok=False,
            error="INVALID_DATE"
        ), 400

    branch = db.session.get(
        Branch,
        branch_id
    )

    procedure = db.session.get(
        Procedure,
        procedure_id
    )

    if not branch or not procedure:
        return jsonify(
            ok=False,
            error="BRANCH_OR_PROCEDURE_NOT_FOUND"
        ), 404

    if not branch.active or not procedure.active:
        return jsonify(
            ok=False,
            error="BRANCH_OR_PROCEDURE_INACTIVE"
        ), 409

    if not procedure_available_in_branch(
        procedure.id,
        branch.id
    ):
        return jsonify(
            ok=False,
            error="PROCEDURE_NOT_AVAILABLE_IN_BRANCH"
        ), 409

    devices = (
        Device.query
        .filter_by(
            branch_id=branch.id,
            active=True
        )
        .filter(
            Device.modality == procedure.modality
        )
        .order_by(Device.name)
        .all()
    )

    duration = max(
        5,
        int(procedure.duration_min or 20)
    )

    slots = []

    for device in devices:
        for slot in booking_v2_slots(
            selected_date,
            device
        ):
            reason = booking_restriction_reason(
                branch,
                procedure,
                device,
                slot,
                duration
            )

            if not reason:
                slots.append({
                    "device_id": device.id,
                    "device_name": device.name,
                    "scheduled": slot.isoformat(),
                    "duration_min": duration,
                })

    slots.sort(
        key=lambda x: x["scheduled"]
    )

    return jsonify(
        ok=True,
        branch_id=branch.id,
        procedure_id=procedure.id,
        date=selected_date.isoformat(),
        slots=slots[:50]
    )


@app.route("/api/voice/book", methods=["POST"])
def voice_api_book():
    if not _voice_api_authorized():
        return _voice_api_unauthorized()

    data = request.get_json(silent=True) or {}

    # The gateway must obtain explicit caller
    # confirmation before sending confirmed=true.
    if data.get("confirmed") is not True:
        return jsonify(
            ok=False,
            error="EXPLICIT_CONFIRMATION_REQUIRED"
        ), 409

    try:
        patient_id = int(data["patient_id"])
        branch_id = int(data["branch_id"])
        procedure_id = int(data["procedure_id"])
        device_id = int(data["device_id"])

        scheduled = datetime.fromisoformat(
            str(data["scheduled"])
        )
    except (
        KeyError,
        TypeError,
        ValueError
    ):
        return jsonify(
            ok=False,
            error="INVALID_BOOKING_DATA"
        ), 400

    patient = db.session.get(
        Patient,
        patient_id
    )

    branch = db.session.get(
        Branch,
        branch_id
    )

    procedure = db.session.get(
        Procedure,
        procedure_id
    )

    device = db.session.get(
        Device,
        device_id
    )

    if not all([
        patient,
        branch,
        procedure,
        device
    ]):
        return jsonify(
            ok=False,
            error="BOOKING_REFERENCE_NOT_FOUND"
        ), 404

    duration = max(
        5,
        int(procedure.duration_min or 20)
    )

    reason = booking_restriction_reason(
        branch,
        procedure,
        device,
        scheduled,
        duration
    )

    if reason:
        return jsonify(
            ok=False,
            error="BOOKING_NOT_AVAILABLE",
            reason=reason
        ), 409

    duplicate = (
        Appointment.query
        .filter_by(
            patient_id=patient.id,
            procedure_id=procedure.id,
            scheduled=scheduled
        )
        .filter(
            Appointment.status != "CANCELLED"
        )
        .first()
    )

    if duplicate:
        return jsonify(
            ok=False,
            error="DUPLICATE_APPOINTMENT",
            appointment_id=duplicate.id
        ), 409

    appointment = Appointment(
        patient_id=patient.id,
        branch_id=branch.id,
        procedure_id=procedure.id,
        device_id=device.id,
        scheduled=scheduled,
        status="BOOKED",
        source="VOICE_AI",
        duration_min=duration,
        priority="NORMAL",
        waiting_list=False,
        notes=str(
            data.get("notes") or ""
        ).strip(),
        created_by=None,
    )

    db.session.add(appointment)
    db.session.flush()

    audit(
        "APPOINTMENT_CREATE_VOICE",
        "appointment",
        appointment.id,
        (
            f"{patient.patient_id} "
            f"{procedure.code} "
            f"{scheduled.isoformat()}"
        )
    )

    db.session.commit()

    return jsonify(
        ok=True,
        appointment={
            "id": appointment.id,
            "patient_id": patient.patient_id,
            "patient": patient.name,
            "procedure_id": procedure.id,
            "procedure":
                procedure.name_ar
                or procedure.name,
            "branch_id": branch.id,
            "branch": branch.name,
            "device_id": device.id,
            "device": device.name,
            "scheduled":
                appointment.scheduled.isoformat(),
            "duration_min": duration,
            "status": appointment.status,
            "source": appointment.source,
        }
    ), 201


