@app.get("/voice-intake/review")
@login_required
def voice_intake_review():

    selected_status = (
        request.args.get("status")
        or "PENDING"
    ).upper()

    allowed = {
        "PENDING",
        "REVIEWED",
        "CONVERTED",
        "CANCELLED",
    }

    if selected_status not in allowed:
        selected_status = "PENDING"

    rows = db.session.execute(
        db.text("""
            SELECT
                v.id,
                v.reference,
                v.status,
                v.branch_id,
                v.source,
                v.reason,
                v.phone_text,
                v.patient_name_text,
                v.procedure_text,
                v.notes,
                v.transcript,
                v.audio_path,
                v.audio_mime,
                v.created_at,
                b.name AS branch_name
            FROM voice_intake_review v
            LEFT JOIN branch b
                ON b.id = v.branch_id
            WHERE v.status = :status
            ORDER BY v.created_at ASC
            LIMIT 500
        """),
        {"status": selected_status}
    ).mappings().all()

    return render_template(
        "voice_intake_review.html",
        rows=rows,
        selected_status=selected_status
    )


@app.get("/voice-intake/<int:intake_id>/audio")
@login_required
def voice_intake_audio(intake_id):

    row = db.session.execute(
        db.text("""
            SELECT
                reference,
                audio_path,
                audio_mime
            FROM voice_intake_review
            WHERE id = :id
        """),
        {"id": intake_id}
    ).mappings().first()

    if not row:
        abort(404)

    stored_path = row["audio_path"] or ""

    prefix = "/data/voice-intake/"

    if stored_path.startswith(prefix):
        stored_path = os.path.join(
            VOICE_INTAKE_STORAGE,
            stored_path[len(prefix):]
        )

    root = os.path.realpath(
        VOICE_INTAKE_STORAGE
    )

    real_path = os.path.realpath(
        stored_path
    )

    if not real_path.startswith(
        root + os.sep
    ):
        abort(403)

    if not os.path.isfile(real_path):
        abort(404)

    return send_file(
        real_path,
        mimetype=row["audio_mime"] or "audio/wav",
        as_attachment=False,
        conditional=True
    )


