import secrets as _rb_secrets
import re as _rb_re


def _rb_public_reference():

    from datetime import datetime

    return (
        "WEB-"
        + datetime.utcnow().strftime("%Y%m%d")
        + "-"
        + _rb_secrets.token_hex(4).upper()
    )


def _rb_normalize_public_text(value, limit=1000):

    value = str(
        value or ""
    ).strip()

    return value[:limit]


def _rb_human_requested(text):

    q = str(
        text or ""
    ).strip().lower()

    words = (
        "موظف",
        "الاستقبال",
        "استقبال",
        "حد يرد",
        "شخص",
        "انسان",
        "إنسان",
        "human",
        "agent",
        "reception",
        "call center",
    )

    return any(
        word in q
        for word in words
    )


def _rb_public_bot_answer(text):

    q = str(
        text or ""
    ).strip().lower()

    if any(
        x in q
        for x in (
            "موعد",
            "مواعيد",
            "الفرع",
            "الفرع",
            "ساعات العمل",
        )
    ):
        return (
            True,
            "أقدر أساعدك في مواعيد الفروع. "
            "اكتب اسم الفرع أو المنطقة، "
            "ولو تحب التحدث مع موظف اكتب: موظف."
        )

    if any(
        x in q
        for x in (
            "سعر",
            "الأسعار",
            "الاسعار",
            "تكلفة",
            "كام",
        )
    ):
        return (
            True,
            "اكتب اسم الفحص المطلوب، "
            "وسنراجع السعر المتاح. "
            "ويمكنك طلب موظف في أي وقت."
        )

    if any(
        x in q
        for x in (
            "تقرير",
            "النتيجة",
            "نتيجة",
        )
    ):
        return (
            True,
            "للاستفسار عن التقرير، "
            "يفضل كتابة رقم الموبايل المسجل "
            "أو رقم الحجز في النموذج."
        )

    if any(
        x in q
        for x in (
            "حجز",
            "احجز",
            "تعديل الحجز",
            "الغاء",
            "إلغاء",
        )
    ):
        return (
            True,
            "أقدر أساعدك في طلبات الحجز. "
            "املأ الاسم ورقم الموبايل، "
            "وسيظهر الطلب لموظف الاستقبال."
        )

    if any(
        x in q
        for x in (
            "تحضير",
            "صيام",
            "تجهيز",
            "استعداد",
        )
    ):
        return (
            True,
            "اكتب اسم الفحص المطلوب، "
            "وسنراجع تعليمات التحضير المناسبة."
        )

    return (
        False,
        "لم أتمكن من تحديد طلبك بدقة. "
        "يمكنك توضيح السؤال أو اختيار التحدث مع موظف."
    )


def _rb_staff_role_allowed():

    try:
        u = current_user()

        code = (
            u.role.code
            if u and u.role
            else ""
        )

        # Canonical production roles plus legacy aliases kept for backwards compatibility.
        return code in {
            "SUPER_ADMIN",
            "RECEPTION",
            "CALL_CENTER",
            "CASE_COORDINATOR",
            "ADMIN",
            "COORDINATOR",
        }

    except Exception:
        return False


@app.post("/api/public-call/request")
def public_contact_request_create():

    data = request.get_json(
        silent=True
    ) or {}

    patient_name = _rb_normalize_public_text(
        data.get("patient_name"),
        160
    )

    phone = _rb_normalize_public_text(
        data.get("phone"),
        40
    )

    booking_reference = _rb_normalize_public_text(
        data.get("booking_reference"),
        100
    )

    request_type = (
        _rb_normalize_public_text(
            data.get("request_type"),
            40
        ).upper()
        or "OTHER"
    )

    message = _rb_normalize_public_text(
        data.get("message"),
        2000
    )

    if not patient_name:
        return jsonify(
            ok=False,
            error="PATIENT_NAME_REQUIRED"
        ),400

    if not phone:
        return jsonify(
            ok=False,
            error="PHONE_REQUIRED"
        ),400

    reference = _rb_public_reference()

    row = db.session.execute(
        db.text("""
            INSERT INTO public_contact_request
            (
                reference,
                patient_name,
                phone,
                booking_reference,
                request_type,
                message,
                status,
                source
            )
            VALUES
            (
                :reference,
                :patient_name,
                :phone,
                :booking_reference,
                :request_type,
                :message,
                'NEW',
                'WEB'
            )
            RETURNING id
        """),
        {
            "reference": reference,
            "patient_name": patient_name,
            "phone": phone,
            "booking_reference": booking_reference,
            "request_type": request_type,
            "message": message,
        }
    ).mappings().first()

    db.session.commit()

    return jsonify(
        ok=True,
        request_id=row["id"],
        reference=reference
    )


@app.post("/api/public-chat/start")
def public_chat_start():

    data = request.get_json(
        silent=True
    ) or {}

    request_id = data.get(
        "request_id"
    )

    if not request_id:
        return jsonify(
            ok=False,
            error="REQUEST_ID_REQUIRED"
        ),400

    exists = db.session.execute(
        db.text("""
            SELECT id
            FROM public_contact_request
            WHERE id=:id
        """),
        {
            "id": request_id
        }
    ).mappings().first()

    if not exists:
        return jsonify(
            ok=False,
            error="REQUEST_NOT_FOUND"
        ),404

    token = _rb_secrets.token_urlsafe(
        32
    )

    row = db.session.execute(
        db.text("""
            INSERT INTO public_chat_session
            (
                public_token,
                contact_request_id,
                state
            )
            VALUES
            (
                :token,
                :request_id,
                'BOT'
            )
            RETURNING id
        """),
        {
            "token": token,
            "request_id": request_id,
        }
    ).mappings().first()

    db.session.execute(
        db.text("""
            INSERT INTO public_chat_message
            (
                session_id,
                sender_type,
                message
            )
            VALUES
            (
                :session_id,
                'BOT',
                :message
            )
        """),
        {
            "session_id": row["id"],
            "message":
                "أهلاً بك. كيف يمكنني مساعدتك؟ "
                "يمكنك أيضاً كتابة: موظف، "
                "للتحويل إلى الاستقبال."
        }
    )

    db.session.commit()

    return jsonify(
        ok=True,
        token=token,
        state="BOT"
    )


