@app.post("/api/public-chat/<token>/message")
def public_chat_message(token):

    data = request.get_json(
        silent=True
    ) or {}

    message = _rb_normalize_public_text(
        data.get("message"),
        2000
    )

    if not message:
        return jsonify(
            ok=False,
            error="MESSAGE_REQUIRED"
        ),400

    chat = db.session.execute(
        db.text("""
            SELECT
                id,
                contact_request_id,
                state,
                bot_failures
            FROM public_chat_session
            WHERE public_token=:token
        """),
        {
            "token": token
        }
    ).mappings().first()

    if not chat:
        return jsonify(
            ok=False,
            error="CHAT_NOT_FOUND"
        ),404

    db.session.execute(
        db.text("""
            INSERT INTO public_chat_message
            (
                session_id,
                sender_type,
                message
            )
            VALUES
            (
                :session_id,
                'PATIENT',
                :message
            )
        """),
        {
            "session_id": chat["id"],
            "message": message,
        }
    )

    state = chat["state"]

    if (
        state == "BOT"
        and _rb_human_requested(message)
    ):

        state = "WAITING_HUMAN"

        db.session.execute(
            db.text("""
                UPDATE public_chat_session
                SET
                    state='WAITING_HUMAN',
                    updated_at=NOW()
                WHERE id=:id
            """),
            {
                "id": chat["id"]
            }
        )

        db.session.execute(
            db.text("""
                UPDATE public_contact_request
                SET
                    status='WAITING_HUMAN',
                    updated_at=NOW()
                WHERE id=:id
            """),
            {
                "id":
                    chat["contact_request_id"]
            }
        )

        reply = (
            "تم تحويل المحادثة إلى موظف. "
            "سيتم الرد عليك من الاستقبال عند توفر موظف."
        )

        db.session.execute(
            db.text("""
                INSERT INTO public_chat_message
                (
                    session_id,
                    sender_type,
                    message
                )
                VALUES
                (
                    :session_id,
                    'SYSTEM',
                    :message
                )
            """),
            {
                "session_id": chat["id"],
                "message": reply,
            }
        )

    elif state == "BOT":

        understood, reply = (
            _rb_public_bot_answer(
                message
            )
        )

        failures = (
            0
            if understood
            else int(
                chat["bot_failures"] or 0
            ) + 1
        )

        if failures >= 2:

            state = "WAITING_HUMAN"

            reply = (
                "سأحول المحادثة إلى موظف "
                "ليساعدك بشكل أفضل."
            )

            db.session.execute(
                db.text("""
                    UPDATE public_chat_session
                    SET
                        state='WAITING_HUMAN',
                        bot_failures=:failures,
                        updated_at=NOW()
                    WHERE id=:id
                """),
                {
                    "id": chat["id"],
                    "failures": failures,
                }
            )

            db.session.execute(
                db.text("""
                    UPDATE public_contact_request
                    SET
                        status='WAITING_HUMAN',
                        updated_at=NOW()
                    WHERE id=:id
                """),
                {
                    "id":
                        chat["contact_request_id"]
                }
            )

        else:

            db.session.execute(
                db.text("""
                    UPDATE public_chat_session
                    SET
                        bot_failures=:failures,
                        updated_at=NOW()
                    WHERE id=:id
                """),
                {
                    "id": chat["id"],
                    "failures": failures,
                }
            )

        db.session.execute(
            db.text("""
                INSERT INTO public_chat_message
                (
                    session_id,
                    sender_type,
                    message
                )
                VALUES
                (
                    :session_id,
                    'BOT',
                    :message
                )
            """),
            {
                "session_id": chat["id"],
                "message": reply,
            }
        )

    db.session.commit()

    return jsonify(
        ok=True,
        state=state
    )


