@login_required
def staff_communications_queue():

    if not _rb_staff_role_allowed():
        abort(403)

    rows = db.session.execute(
        db.text("""
            SELECT
                r.id,
                r.reference,
                r.patient_name,
                r.phone,
                r.booking_reference,
                r.request_type,
                r.message,
                r.status,
                r.assigned_user_id,
                r.confirmed,
                r.created_at,

                c.id AS chat_session_id,
                c.state AS chat_state,
                c.assigned_user_id
                    AS chat_assigned_user_id

            FROM public_contact_request r

            LEFT JOIN public_chat_session c
                ON c.contact_request_id=r.id

            WHERE r.status NOT IN (
                'REJECTED',
                'CLOSED'
            )

            ORDER BY
                CASE
                    WHEN r.status='WAITING_HUMAN'
                    THEN 0
                    ELSE 1
                END,
                r.id DESC

            LIMIT 100
        """)
    ).mappings().all()

    return jsonify(
        ok=True,
        items=[
            {
                **dict(x),
                "created_at":
                    x["created_at"].isoformat()
                    if x["created_at"]
                    else None,
            }
            for x in rows
        ]
    )


