import os as _rb_os
import uuid as _rb_uuid
from datetime import datetime as _rb_datetime


_RB_PUBLIC_ATTACHMENT_TYPES = {
    "INSURANCE_CARD",
    "MEDICAL_APPROVAL",
    "OLD_REPORT",
    "OLD_IMAGE",
    "PRESCRIPTION",
    "LAB_RESULT",
    "REFERRAL",
    "OTHER",
}


_RB_ALLOWED_UPLOAD_EXTENSIONS = {
    ".pdf",
    ".jpg",
    ".jpeg",
    ".png",
}


_RB_ALLOWED_UPLOAD_MIMES = {
    "application/pdf",
    "image/jpeg",
    "image/png",
}


def _rb_public_attachment_root():

    root = os.environ.get(
        "ATTACHMENT_DIR",
        "/app/attachments"
    )

    root = _rb_os.path.join(
        root,
        "public-contact"
    )

    _rb_os.makedirs(
        root,
        exist_ok=True
    )

    return root


def _rb_safe_upload_extension(filename):

    _, ext = _rb_os.path.splitext(
        str(filename or "")
    )

    return ext.lower()


@app.post("/api/public-call/request/<int:request_id>/details")
def public_contact_request_details(request_id):

    data = request.get_json(
        silent=True
    ) or {}

    date_of_birth = (
        str(data.get("date_of_birth") or "").strip()
        or None
    )

    age_years = data.get("age_years")

    try:
        age_years = (
            int(age_years)
            if age_years not in (None, "")
            else None
        )
    except Exception:
        age_years = None

    exam_name = _rb_normalize_public_text(
        data.get("exam_name"),
        240
    )

    insurance_company = _rb_normalize_public_text(
        data.get("insurance_company"),
        200
    )

    insurance_member_no = _rb_normalize_public_text(
        data.get("insurance_member_no"),
        120
    )

    medical_approval_no = _rb_normalize_public_text(
        data.get("medical_approval_no"),
        160
    )

    medical_approval_status = (
        _rb_normalize_public_text(
            data.get("medical_approval_status"),
            40
        ).upper()
        or "NOT_DECLARED"
    )

    allowed_approval = {
        "NOT_DECLARED",
        "NOT_REQUIRED",
        "REQUIRED",
        "PENDING",
        "PATIENT_HAS_APPROVAL",
    }

    if medical_approval_status not in allowed_approval:
        medical_approval_status = "NOT_DECLARED"

    payment_preference = (
        _rb_normalize_public_text(
            data.get("payment_preference"),
            50
        ).upper()
        or None
    )

    notification_email_address = (
        _rb_normalize_public_text(
            data.get("notification_email_address"),
            240
        )
        or None
    )

    db.session.execute(
        db.text("""
            UPDATE public_contact_request
            SET
                date_of_birth=:date_of_birth,
                age_years=:age_years,
                exam_name=:exam_name,

                insurance_company=:insurance_company,
                insurance_member_no=:insurance_member_no,

                medical_approval_no=:medical_approval_no,
                medical_approval_status=:medical_approval_status,

                payment_preference=:payment_preference,

                notification_whatsapp=:notification_whatsapp,
                notification_sms=:notification_sms,
                notification_email=:notification_email,
                notification_web_chat=:notification_web_chat,
                notification_email_address=:notification_email_address,

                updated_at=NOW()

            WHERE id=:request_id
        """),
        {
            "request_id": request_id,

            "date_of_birth": date_of_birth,
            "age_years": age_years,
            "exam_name": exam_name,

            "insurance_company": insurance_company,
            "insurance_member_no": insurance_member_no,

            "medical_approval_no": medical_approval_no,
            "medical_approval_status":
                medical_approval_status,

            "payment_preference":
                payment_preference,

            "notification_whatsapp":
                bool(data.get("notification_whatsapp")),

            "notification_sms":
                bool(data.get("notification_sms")),

            "notification_email":
                bool(data.get("notification_email")),

            "notification_web_chat":
                bool(data.get(
                    "notification_web_chat",
                    True
                )),

            "notification_email_address":
                notification_email_address,
        }
    )

    db.session.commit()

    return jsonify(
        ok=True
    )


@app.post(
    "/api/public-call/request/"
    "<int:request_id>/attachments"
)
def public_contact_attachment_upload(request_id):

    exists = db.session.execute(
        db.text("""
            SELECT id
            FROM public_contact_request
            WHERE id=:id
        """),
        {"id": request_id}
    ).mappings().first()

    if not exists:
        return jsonify(
            ok=False,
            error="REQUEST_NOT_FOUND"
        ),404

    files = request.files.getlist(
        "files"
    )

    if not files:
        return jsonify(
            ok=False,
            error="NO_FILES"
        ),400

    if len(files) > 10:
        return jsonify(
            ok=False,
            error="TOO_MANY_FILES"
        ),400

    attachment_type = (
        str(
            request.form.get(
                "attachment_type",
                "OTHER"
            )
        )
        .strip()
        .upper()
    )

    if attachment_type not in _RB_PUBLIC_ATTACHMENT_TYPES:
        attachment_type = "OTHER"

    description = _rb_normalize_public_text(
        request.form.get("description"),
        300
    )

    root = _rb_public_attachment_root()

    request_dir = _rb_os.path.join(
        root,
        str(request_id)
    )

    _rb_os.makedirs(
        request_dir,
        exist_ok=True
    )

    uploaded = []

    for f in files:

        original = str(
            f.filename or ""
        ).strip()

        if not original:
            continue

        ext = _rb_safe_upload_extension(
            original
        )

        if ext not in _RB_ALLOWED_UPLOAD_EXTENSIONS:
            return jsonify(
                ok=False,
                error="FILE_TYPE_NOT_ALLOWED",
                filename=original
            ),400

        mime = str(
            f.mimetype or ""
        ).lower()

        if (
            mime
            and mime not in
            _RB_ALLOWED_UPLOAD_MIMES
        ):
            return jsonify(
                ok=False,
                error="MIME_NOT_ALLOWED",
                filename=original
            ),400

        blob = f.read(
            10 * 1024 * 1024 + 1
        )

        if len(blob) > 10 * 1024 * 1024:
            return jsonify(
                ok=False,
                error="FILE_TOO_LARGE",
                filename=original
            ),413

        stored = (
            _rb_uuid.uuid4().hex
            + ext
        )

        destination = _rb_os.path.join(
            request_dir,
            stored
        )

        with open(
            destination,
            "wb"
        ) as out:
            out.write(blob)

        row = db.session.execute(
            db.text("""
                INSERT INTO public_contact_attachment
                (
                    contact_request_id,
                    attachment_type,
                    description,
                    original_filename,
                    stored_filename,
                    mime_type,
                    size_bytes
                )
                VALUES
                (
                    :request_id,
                    :attachment_type,
                    :description,
                    :original_filename,
                    :stored_filename,
                    :mime_type,
                    :size_bytes
                )
                RETURNING id
            """),
            {
                "request_id":
                    request_id,

                "attachment_type":
                    attachment_type,

                "description":
                    description,

                "original_filename":
                    original,

                "stored_filename":
                    stored,

                "mime_type":
                    mime,

                "size_bytes":
                    len(blob),
            }
        ).mappings().first()

        uploaded.append({
            "id": row["id"],
            "filename": original,
        })

    db.session.commit()

    return jsonify(
        ok=True,
        uploaded=uploaded
    )


@login_required
def staff_contact_attachments(request_id):

    if not _rb_staff_role_allowed():
        abort(403)

    rows = db.session.execute(
        db.text("""
            SELECT
                id,
                attachment_type,
                description,
                original_filename,
                mime_type,
                size_bytes,
                verification_status,
                created_at

            FROM public_contact_attachment

            WHERE contact_request_id=:id

            ORDER BY id
        """),
        {"id": request_id}
    ).mappings().all()

    return jsonify(
        ok=True,
        attachments=[
            {
                **dict(x),
                "created_at":
                    x["created_at"].isoformat()
                    if x["created_at"]
                    else None,

                "view_url":
                    (
                        "/staff/public-attachment/"
                        + str(x["id"])
                    )
            }
            for x in rows
        ]
    )


@app.get(
    "/staff/public-attachment/"
    "<int:attachment_id>"
)
@login_required
def staff_public_attachment_view(attachment_id):

    if not _rb_staff_role_allowed():
        abort(403)

    row = db.session.execute(
        db.text("""
            SELECT
                contact_request_id,
                stored_filename,
                original_filename,
                mime_type

            FROM public_contact_attachment

            WHERE id=:id
        """),
        {"id": attachment_id}
    ).mappings().first()

    if not row:
        abort(404)

    root = _rb_public_attachment_root()

    path = _rb_os.path.realpath(
        _rb_os.path.join(
            root,
            str(row["contact_request_id"]),
            row["stored_filename"]
        )
    )

    safe_root = _rb_os.path.realpath(
        root
    )

    if not path.startswith(
        safe_root + _rb_os.sep
    ):
        abort(403)

    if not _rb_os.path.isfile(path):
        abort(404)

    return send_file(
        path,
        mimetype=(
            row["mime_type"]
            or "application/octet-stream"
        ),
        download_name=
            row["original_filename"],
        as_attachment=False
    )


@app.post(
    "/api/staff/attachments/"
    "<int:attachment_id>/verify"
)
@login_required
def staff_attachment_verify(attachment_id):

    if not _rb_staff_role_allowed():
        abort(403)

    u = current_user()

    db.session.execute(
        db.text("""
            UPDATE public_contact_attachment
            SET
                verification_status='VERIFIED',
                verified_by_user_id=:uid,
                verified_at=NOW()
            WHERE id=:id
        """),
        {
            "id": attachment_id,
            "uid": u.id,
        }
    )

    db.session.commit()

    return jsonify(ok=True)


