@app.route("/admin/ivr")
@login_required
def admin_ivr():
    uid = session.get("uid")
    user = db.session.get(User, uid) if uid else None

    if not user:
        return redirect(url_for("login"))

    extension_count = TelephonyExtension.query.filter_by(
        active=True
    ).count()

    return render_template(
        "admin_ivr.html",
        extension_count=extension_count
    )


